  "properties" jsonb DEFAULT '{}'::jsonb NOT NULL,
  "occurred_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE OR REPLACE FUNCTION private.validate_household_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if NEW.status='active' and (OLD.status is distinct from NEW.status or OLD.household_type is distinct from NEW.household_type) then
    perform private.assert_household_composition(NEW.id);
  end if;
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.validate_active_household_after_member_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_id uuid;
begin
  v_id := coalesce(NEW.household_id,OLD.household_id);
  perform private.assert_household_composition(v_id);
  return coalesce(NEW,OLD);
end;
$function$
;

CREATE OR REPLACE FUNCTION private.provision_client_foundation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_household_id uuid;
  v_membership_id uuid;
  v_user_id uuid;
  v_sex text;
  v_full_name text;
  v_program text;
  v_membership_status text;
  v_household_status text;
begin
  if NEW.payment_status <> 'paid' or NEW.agreement_status <> 'signed'
     or NEW.access_status not in ('ready','active') then
    return NEW;
  end if;

  v_program := coalesce(NEW.program_code,'');
  if not exists(select 1 from public.program_catalog where program_code=v_program and active) then
    return NEW;
  end if;

  select concat_ws(' ',first_name,last_name)
  into v_full_name
  from public.contacts
  where id=NEW.contact_id;

  select lower(wa.answer #>> '{}')
  into v_sex
  from public.workflow_records wr
  join public.workflow_answers wa on wa.workflow_id=wr.id and wa.question_key='sex'
  where wr.contact_id=NEW.contact_id
    and wr.workflow_type='enrollment'
  order by wr.created_at desc
  limit 1;

  if v_sex not in ('male','female') then
    v_sex := null;
  end if;

  v_household_status := case when v_sex is not null then 'active' else 'draft' end;

  insert into public.households(
    household_type,status,primary_contact_id,household_name,created_by,updated_at
  )
  values(
    'individual',v_household_status,NEW.contact_id,
    nullif(trim(v_full_name),'') || ' Household',
    NEW.created_by,now()
  )
  on conflict (primary_contact_id) do update
  set updated_at=now()
  returning id into v_household_id;

  insert into public.household_members(
    household_id,contact_id,relationship_type,sex,is_primary,status,updated_at
  )
  values(
    v_household_id,NEW.contact_id,'self',v_sex,true,'active',now()
  )
  on conflict (contact_id) do update
  set household_id=excluded.household_id,
      relationship_type='self',
      sex=coalesce(excluded.sex,public.household_members.sex),
      is_primary=true,
      status='active',
      updated_at=now();

  v_membership_status := case when NEW.access_status='active' then 'active' else 'pending' end;

  insert into public.client_memberships(
    household_id,primary_contact_id,activation_id,program_code,status,
    billing_choice,amount_cents,currency,commitment_months,starts_at,commitment_ends_at,
    assigned_coach_id,created_by,metadata,updated_at
  )
  values(
    v_household_id,NEW.contact_id,NEW.id,v_program,v_membership_status,
    NEW.billing_choice,NEW.amount_cents,NEW.currency,NEW.commitment_months,
    coalesce(NEW.paid_at,now()),
    case
      when NEW.commitment_months is not null
        then coalesce(NEW.paid_at,now()) + make_interval(months=>NEW.commitment_months)
      else null
    end,
    (select assigned_to from public.contact_journeys where id=NEW.journey_id),
    NEW.created_by,
    jsonb_build_object('journey_id',NEW.journey_id),
    now()
  )
  on conflict (activation_id) do update
  set status=excluded.status,
      billing_choice=excluded.billing_choice,
      amount_cents=excluded.amount_cents,
      currency=excluded.currency,
      commitment_months=excluded.commitment_months,
      assigned_coach_id=coalesce(excluded.assigned_coach_id,public.client_memberships.assigned_coach_id),
      updated_at=now()
  returning id into v_membership_id;

  insert into public.membership_entitlements(
    membership_id,entitlement_key,label,limit_value,reset_cadence,metadata
  )
  select
    v_membership_id,t.entitlement_key,t.label,t.limit_value,t.reset_cadence,t.metadata
  from public.program_entitlement_templates t
  where t.program_code=v_program and t.active
  on conflict (membership_id,entitlement_key) do update
  set label=excluded.label,
      limit_value=excluded.limit_value,
      reset_cadence=excluded.reset_cadence,
      metadata=excluded.metadata,
      status='active',
      updated_at=now();

  select user_id into v_user_id
  from public.profiles
  where contact_id=NEW.contact_id
  limit 1;

  insert into public.client_access(
    contact_id,household_id,membership_id,user_id,status,ready_at,activated_at,updated_at
  )
  values(
    NEW.contact_id,v_household_id,v_membership_id,v_user_id,
    case when NEW.access_status='active' and v_user_id is not null then 'active' else 'ready' end,
    now(),
    case when NEW.access_status='active' and v_user_id is not null then now() else null end,
    now()
  )
  on conflict (contact_id) do update
  set household_id=excluded.household_id,
      membership_id=excluded.membership_id,
      user_id=coalesce(public.client_access.user_id,excluded.user_id),
      status=case
        when NEW.access_status='active' and coalesce(public.client_access.user_id,excluded.user_id) is not null then 'active'
        when public.client_access.status='active' then 'active'
        else 'ready'
      end,
      ready_at=coalesce(public.client_access.ready_at,now()),
      activated_at=case
        when NEW.access_status='active' and coalesce(public.client_access.user_id,excluded.user_id) is not null
          then coalesce(public.client_access.activated_at,now())
        else public.client_access.activated_at
      end,
      updated_at=now();

  insert into public.contact_activity(contact_id,activity_type,title,detail,metadata)
  values(
    NEW.contact_id,'client_foundation_ready','Client membership foundation ready',
    (select name from public.program_catalog where program_code=v_program),
    jsonb_build_object(
      'membership_id',v_membership_id,
      'household_id',v_household_id,
      'activation_id',NEW.id,
      'access_status',NEW.access_status
    )
  );

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.link_profile_to_client_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_activation_active boolean;
begin
  select exists(
    select 1
    from public.client_access ca
    join public.client_memberships cm on cm.id=ca.membership_id
    join public.journey_enrollment_activations ea on ea.id=cm.activation_id
    where ca.contact_id=NEW.contact_id
      and ea.access_status='active'
  ) into v_activation_active;

  update public.client_access
  set user_id=NEW.user_id,
      status=case when v_activation_active then 'active' else 'invited' end,
      invited_at=coalesce(invited_at,now()),
      activated_at=case when v_activation_active then coalesce(activated_at,now()) else activated_at end,
      updated_at=now()
  where contact_id=NEW.contact_id;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.activate_household(p_household_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists (
    select 1 from public.staff_access s where s.user_id=(select auth.uid())
  ) then
    raise exception 'Staff access required';
  end if;

  update public.households
  set status='active',updated_at=now()
  where id=p_household_id;

  if not found then
    raise exception 'Household not found';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.match_coach_companion_chunks(query_embedding vector, match_threshold double precision, match_count integer)
 RETURNS TABLE(chunk_id uuid, source_id uuid, source_title text, source_type text, heading text, content text, similarity double precision)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions'
AS $function$
  select
    ch.id,
    ch.source_id,
    s.title,
    s.source_type,
    ch.heading,
    ch.content,
    (ch.embedding <#> query_embedding) * -1 as similarity
  from public.coach_companion_knowledge_chunks ch
  join public.coach_companion_knowledge_sources s on s.id=ch.source_id
  where ch.active
    and ch.embedding is not null
    and s.status='approved'
    and (ch.embedding <#> query_embedding) < -match_threshold
  order by ch.embedding <#> query_embedding
  limit least(match_count,20);
$function$
;

CREATE OR REPLACE FUNCTION public.record_journey_event(p_contact_id uuid, p_journey_id uuid, p_event_type text, p_source text DEFAULT 'system'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id uuid;
begin
  insert into public.journey_events(contact_id,journey_id,event_type,source,metadata)
  values(p_contact_id,p_journey_id,p_event_type,coalesce(p_source,'system'),coalesce(p_metadata,'{}'::jsonb))
  returning id into v_id;

  update public.contact_journeys
  set last_activity_at=now(),updated_at=now()
  where id=p_journey_id;

  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.emit_current_step_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_step public.contact_journey_steps%rowtype;
begin
  if NEW.current_step_key is distinct from OLD.current_step_key
     and NEW.current_step_key is not null then
    select * into v_step
    from public.contact_journey_steps
    where journey_id=NEW.id and step_key=NEW.current_step_key
    limit 1;

    if v_step.id is not null then
      insert into public.journey_events(
        contact_id,journey_id,step_id,event_type,source,metadata
      )
      values(
        NEW.contact_id,NEW.id,v_step.id,'step_became_current','system',
        jsonb_build_object(
          'step_key',v_step.step_key,
          'step_name',v_step.name,
          'due_at',v_step.due_at
        )
      );
    end if;
  end if;
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_health_observation_to_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_supported boolean;
begin
  select exists(
    select 1 from public.progress_metric_catalog
    where metric_key=NEW.metric_key and active
  ) into v_supported;

  if not v_supported then
    return NEW;
  end if;

  insert into public.progress_entries(
    contact_id,membership_id,metric_key,value_numeric,value_boolean,
    recorded_at,source,note,metadata
  )
  values(
    NEW.contact_id,NEW.membership_id,NEW.metric_key,NEW.value_numeric,NEW.value_boolean,
    NEW.observed_at,'integration',null,
    jsonb_build_object(
      'health_observation_id',NEW.id,
      'provider_key',NEW.provider_key,
      'external_record_id',NEW.external_record_id
    )
  );

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_contact_id uuid;
  v_email text;
begin
  v_email := lower(nullif(new.email, ''));
  if v_email is not null then
    select id into v_contact_id from public.contacts where lower(email) = v_email limit 1;
  end if;

  if v_contact_id is null then
    insert into public.contacts(first_name,last_name,email,phone,first_source,last_source)
    values (
      new.raw_user_meta_data->>'first_name',
      new.raw_user_meta_data->>'last_name',
      new.email,
      new.raw_user_meta_data->>'phone',
      'account',
      'account'
    )
    returning id into v_contact_id;
  else
    update public.contacts
    set first_name = coalesce(first_name, new.raw_user_meta_data->>'first_name'),
        last_name = coalesce(last_name, new.raw_user_meta_data->>'last_name'),
        phone = coalesce(phone, new.raw_user_meta_data->>'phone'),
        last_source = 'account'
    where id = v_contact_id;
  end if;

  insert into public.profiles(user_id, contact_id)
  values (new.id, v_contact_id)
  on conflict (user_id) do update set contact_id = excluded.contact_id;

  update public.workflow_records set user_id = new.id where contact_id = v_contact_id and user_id is null;
  update public.webinar_registrations set user_id = new.id where contact_id = v_contact_id and user_id is null;

  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.staff_can_manage_document_category(p_category text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
  select case p_category
    when 'general' then private.staff_has_permission((select auth.uid()),'crm.manage')
    when 'coaching' then private.staff_has_permission((select auth.uid()),'coaching.manage')
    when 'health' then private.staff_has_permission((select auth.uid()),'health.progress.manage')
    when 'progress' then private.staff_has_permission((select auth.uid()),'health.progress.manage')
    when 'financial' then private.staff_has_permission((select auth.uid()),'finance.manage')
    when 'agreement' then private.staff_has_permission((select auth.uid()),'finance.manage')
    else false
  end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_my_member_email_impl()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_email text;
begin
  select p.contact_id into v_contact_id
  from public.profiles p
  where p.user_id=(select auth.uid());

  if v_contact_id is null then
    raise exception 'Member profile not found';
  end if;

  select u.email into v_email
  from auth.users u
  where u.id=(select auth.uid());

  if v_email is null then
    raise exception 'Authenticated email not found';
  end if;

  update public.contacts
  set email=lower(v_email), updated_at=now()
  where id=v_contact_id
    and lower(coalesce(email,'')) is distinct from lower(v_email);

  return v_email;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_my_member_email()
 RETURNS text
 LANGUAGE sql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
  select private.sync_my_member_email_impl();
$function$
;

CREATE OR REPLACE FUNCTION public.ensure_my_workflow(p_workflow_type text, p_current_step text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_contact uuid;
  v_workflow uuid;
begin
  if v_user is null then raise exception 'Authentication required'; end if;
  if p_workflow_type not in ('vitality_assessment','enrollment') then raise exception 'Invalid workflow'; end if;

  select contact_id into v_contact from public.profiles where user_id = v_user;
  if v_contact is null then raise exception 'Profile not found'; end if;

  select id into v_workflow
  from public.workflow_records
  where contact_id = v_contact and workflow_type = p_workflow_type and status <> 'abandoned'
  order by created_at desc limit 1;

  if v_workflow is null then
    insert into public.workflow_records(contact_id,user_id,workflow_type,status,current_step,completion_percent,started_at)
    values(v_contact,v_user,p_workflow_type,'in_progress',p_current_step,0,now())
    returning id into v_workflow;
  else
    update public.workflow_records
    set user_id = v_user,
        current_step = coalesce(p_current_step,current_step),
        status = case when status='completed' then status else 'in_progress' end,
        last_activity_at = now()
    where id = v_workflow;
  end if;

  return v_workflow;
end $function$
;

CREATE OR REPLACE FUNCTION private.sync_journey_from_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if NEW.payment_status='paid' and NEW.paid_at is null then
    update public.journey_enrollment_activations
    set paid_at=now(),updated_at=now()
    where id=NEW.id;
    NEW.paid_at := now();
  end if;

  if NEW.payment_status in ('paid','waived')
     and NEW.agreement_status in ('signed','waived') then
    update public.contact_journey_steps
    set status='completed',
        completion_source=case
          when NEW.payment_status='waived' or NEW.agreement_status='waived'
            then 'manual_financial_override'
          else 'payment_and_agreement'
        end,
        completed_at=coalesce(completed_at,now()),
        updated_at=now()
    where journey_id=NEW.journey_id
      and step_key='payment_agreement'
      and status not in ('completed','skipped','waived');
  end if;

  if NEW.access_status='active' then
    update public.contact_journey_steps
    set status='completed',
        completion_source=coalesce(NEW.access_completion_method,'member_access_activated'),
        completed_at=coalesce(completed_at,now()),
        updated_at=now()
    where journey_id=NEW.journey_id
      and step_key='backend_activation'
      and status not in ('completed','skipped','waived');
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.backfill_published_agreement_template()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  r record;
begin
  if NEW.status<>'published'
     or (TG_OP='UPDATE' and OLD.status is not distinct from NEW.status) then
    return NEW;
  end if;

  for r in
    select *
    from public.program_agreement_requirements par
    where par.agreement_template_id=NEW.id
      and par.active
      and par.required
  loop
    perform private.backfill_agreement_requirement_record(r.id);
  end loop;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.complete_my_workflow(p_workflow_type text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then raise exception 'Authentication required'; end if;
  update public.workflow_records
  set status='completed',completion_percent=100,completed_at=now(),last_activity_at=now()
  where workflow_type=p_workflow_type
    and status <> 'abandoned'
    and (user_id=v_user or contact_id in (select contact_id from public.profiles where user_id=v_user));
end $function$
;

CREATE OR REPLACE FUNCTION public.save_my_workflow_answer(p_workflow_type text, p_question_key text, p_answer jsonb, p_current_step text DEFAULT NULL::text, p_completion_percent integer DEFAULT NULL::integer, p_confirmed boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_contact uuid;
  v_workflow uuid;
  v_answer_id uuid;
  v_map public.question_mappings%rowtype;
begin
  if v_user is null then raise exception 'Authentication required'; end if;
  if nullif(trim(p_question_key),'') is null then raise exception 'Question key required'; end if;

  v_workflow := public.ensure_my_workflow(p_workflow_type,p_current_step);
  select contact_id into v_contact from public.profiles where user_id = v_user;

  insert into public.workflow_answers(workflow_id,question_key,answer,source,confirmed_at)
  values(v_workflow,p_question_key,p_answer,'user',case when p_confirmed then now() else null end)
  on conflict(workflow_id,question_key)
  do update set answer=excluded.answer, source='user',
    confirmed_at=case when p_confirmed then now() else public.workflow_answers.confirmed_at end,
    updated_at=now()
  returning id into v_answer_id;

  update public.workflow_records
  set current_step = coalesce(p_current_step,current_step),
      completion_percent = coalesce(greatest(0,least(100,p_completion_percent)),completion_percent),
      last_activity_at=now()
  where id=v_workflow;

  select * into v_map from public.question_mappings
  where workflow_type=p_workflow_type and question_key=p_question_key limit 1;

  if found then
    insert into public.canonical_facts(contact_id,field_key,value,source_workflow,source_question_key,last_confirmed_at)
    values(v_contact,v_map.canonical_key,p_answer,p_workflow_type,p_question_key,case when p_confirmed then now() else null end)
    on conflict(contact_id,field_key)
    do update set value=excluded.value,source_workflow=excluded.source_workflow,
      source_question_key=excluded.source_question_key,
      last_confirmed_at=coalesce(excluded.last_confirmed_at,public.canonical_facts.last_confirmed_at),
      updated_at=now();
  end if;

  return v_answer_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.log_contact_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if TG_TABLE_NAME='webinar_registrations' then
    if TG_OP='INSERT' then
      insert into public.contact_activity(contact_id,activity_type,title,detail,metadata)
      values(new.contact_id,'webinar_registration','Registered for Founders Webinar',
             'Priority webinar registration received.',
             jsonb_build_object('registration_id',new.id,'status',new.status));
    elsif TG_OP='UPDATE' and (new.status is distinct from old.status or new.payment_status is distinct from old.payment_status) then
      insert into public.contact_activity(contact_id,activity_type,title,detail,metadata)
      values(new.contact_id,'webinar_update','Webinar status updated',
             concat('Registration: ',new.status,' • Payment: ',new.payment_status),
             jsonb_build_object('registration_id',new.id,'status',new.status,'payment_status',new.payment_status));
    end if;
    return new;
  end if;

  if TG_TABLE_NAME='workflow_records' then
    if TG_OP='INSERT' then
      insert into public.contact_activity(contact_id,activity_type,title,detail,metadata)
      values(new.contact_id,'workflow_started',
             case new.workflow_type when 'vitality_assessment' then 'Started Vitality Assessment' else 'Started Enrollment' end,
             concat('Status: ',new.status),
             jsonb_build_object('workflow_id',new.id,'workflow_type',new.workflow_type));
    elsif TG_OP='UPDATE' and new.status is distinct from old.status then
      insert into public.contact_activity(contact_id,activity_type,title,detail,metadata)
      values(new.contact_id,'workflow_status',
             case new.workflow_type when 'vitality_assessment' then 'Vitality Assessment updated' else 'Enrollment updated' end,
             concat('Status changed to ',new.status),
             jsonb_build_object('workflow_id',new.id,'workflow_type',new.workflow_type,'status',new.status));
    end if;
    return new;
  end if;

  return new;
end $function$
;

CREATE OR REPLACE FUNCTION private.sync_staff_directory()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if tg_op = 'DELETE' then
    delete from public.staff_directory where user_id = old.user_id;
    return old;
  end if;

  insert into public.staff_directory (user_id, display_name, role, updated_at)
  values (new.user_id, new.display_name, new.role, now())
  on conflict (user_id) do update
  set display_name = excluded.display_name,
      role = excluded.role,
      updated_at = now();

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.mark_report_sent_from_journey()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if NEW.event_type='report_sent' then
    update public.vitality_reports
    set status='sent',
        sent_at=coalesce(sent_at,now()),
        updated_at=now()
    where id=(
      select id
      from public.vitality_reports
      where journey_id=NEW.journey_id
        and status in ('approved','sent')
      order by created_at desc
      limit 1
    );
  end if;
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.log_sms_consent_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if tg_op = 'INSERT'
     or old.status is distinct from new.status
     or old.opt_in_source is distinct from new.opt_in_source
     or old.consent_version is distinct from new.consent_version
     or old.notes is distinct from new.notes then
    insert into public.sms_consent_events
      (contact_id,status,source,consent_version,notes,changed_by,occurred_at)
    values
      (new.contact_id,new.status,new.opt_in_source,new.consent_version,new.notes,new.updated_by,now());
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_my_notification(p_notification_id uuid, p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if p_action not in ('read','unread','dismissed') then
    raise exception 'Unsupported notification action';
  end if;

  update public.member_notifications
  set
    status = p_action,
    read_at = case
      when p_action='read' then coalesce(read_at,now())
      when p_action='unread' then null
      else read_at
    end
  where id=p_notification_id
    and user_id=(select auth.uid());

  return found;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ensure_contact_journey(p_contact_id uuid, p_journey_key text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_existing public.contact_journeys%rowtype;
  v_journey_id uuid;
  v_first_step text;
  v_vitality_completed boolean := false;
begin
  if p_journey_key not in ('coaching_application','direct_membership','assessment_first') then
    raise exception 'Unsupported journey key';
  end if;

  select * into v_existing
  from public.contact_journeys
  where contact_id=p_contact_id
    and status in ('active','paused','nurture')
  order by created_at desc
  limit 1
  for update;

  if found and v_existing.journey_key = p_journey_key then
    update public.contact_journeys
      set metadata = coalesce(metadata,'{}'::jsonb) || coalesce(p_metadata,'{}'::jsonb),
          last_activity_at=now(),
          updated_at=now()
    where id=v_existing.id;
    return v_existing.id;
  elsif found then
    update public.contact_journeys
      set status='converted',
          completed_at=now(),
          updated_at=now(),
          metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object('converted_to',p_journey_key)
    where id=v_existing.id;
  end if;

  select exists(
    select 1
    from public.workflow_records
    where contact_id=p_contact_id
      and workflow_type='vitality_assessment'
      and status='completed'
  ) into v_vitality_completed;

  insert into public.contact_journeys(contact_id,journey_key,metadata)
  values(p_contact_id,p_journey_key,coalesce(p_metadata,'{}'::jsonb))
  returning id into v_journey_id;

  insert into public.contact_journey_steps(
    journey_id,step_key,step_order,name,step_type,required,status,due_at,metadata
  )
  select
    v_journey_id,d.step_key,d.step_order,d.name,d.step_type,d.required,
    case
      when d.step_key='vitality_assessment' and v_vitality_completed then 'completed'
      when p_journey_key in ('coaching_application','direct_membership') and d.step_key='application_capture' then 'completed'
      when p_journey_key='assessment_first' and d.step_key='vitality_assessment' then 'in_progress'
      else 'pending'
    end,
    case
      when p_journey_key='assessment_first' and d.step_key='vitality_assessment' and d.default_due_hours is not null
        then now() + make_interval(hours => d.default_due_hours)
      else null
    end,
    d.metadata
  from public.journey_step_definitions d
  where d.journey_key=p_journey_key
  order by d.step_order;

  select s.step_key into v_first_step
  from public.contact_journey_steps s
  where s.journey_id=v_journey_id
    and s.required
    and s.status not in ('completed','skipped')
  order by s.step_order
  limit 1;

  if v_first_step is null then
    select s.step_key into v_first_step
    from public.contact_journey_steps s
    where s.journey_id=v_journey_id
      and s.status not in ('completed','skipped')
    order by s.step_order
    limit 1;
  end if;

  update public.contact_journey_steps s
  set status='in_progress',
      started_at=coalesce(started_at,now()),
      due_at=case
        when due_at is null and d.default_due_hours is not null
          then now() + make_interval(hours => d.default_due_hours)
        else due_at
      end,
      updated_at=now()
  from public.journey_step_definitions d
  where s.journey_id=v_journey_id
    and s.step_key=v_first_step
    and d.journey_key=p_journey_key
    and d.step_key=s.step_key;

  update public.contact_journeys
  set current_step_key=v_first_step,
      progress_percent=(
        select round(100.0 * count(*) filter (where status in ('completed','skipped')) / nullif(count(*),0))::int
        from public.contact_journey_steps
        where journey_id=v_journey_id
      ),
      next_action_at=(
        select due_at from public.contact_journey_steps
        where journey_id=v_journey_id and step_key=v_first_step
      ),
      updated_at=now()
  where id=v_journey_id;

  return v_journey_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.apply_journey_event_intelligence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  r record;
  v_text text;
  v_match boolean;
  v_points integer := 0;
  v_bonus integer := 0;
  v_score integer;
  v_reason jsonb;
begin
  for r in
    select *
    from public.automatic_tag_rules
    where active and event_type=NEW.event_type
    order by priority,id
  loop
    v_match := false;
    if r.match_type='always' then
      v_match := true;
    else
      v_text := coalesce(NEW.metadata->>r.metadata_key,'');
      if r.match_type='exact' then
        v_match := lower(v_text)=lower(coalesce(r.match_value,''));
      elsif r.match_type='contains' then
        v_match := position(lower(coalesce(r.match_value,'')) in lower(v_text)) > 0;
      elsif r.match_type='regex' then
        v_match := v_text ~* coalesce(r.match_value,'');
      end if;
    end if;

    if v_match then
      insert into public.contact_tags(contact_id,tag,source,rule_key,updated_at)
      values(NEW.contact_id,r.tag,'automatic',r.rule_key,now())
      on conflict (contact_id,tag) do update
      set source=case when public.contact_tags.source='manual' then 'manual' else 'automatic' end,
          rule_key=case when public.contact_tags.source='manual' then public.contact_tags.rule_key else excluded.rule_key end,
          updated_at=now();
    end if;
  end loop;

  select points into v_points
  from public.engagement_event_weights
  where event_type=NEW.event_type and active;

  v_points := coalesce(v_points,0);

  if NEW.event_type='enrollment_started' then
    if lower(coalesce(NEW.metadata->>'start_timeline',''))='as soon as possible' then
      v_bonus := v_bonus + 15;
    elsif lower(coalesce(NEW.metadata->>'start_timeline','')) like 'within the next 30 days%' then
      v_bonus := v_bonus + 8;
    end if;
    if lower(coalesce(NEW.metadata->>'program_interest','')) not like '%not sure%' then
      v_bonus := v_bonus + 5;
    end if;
  end if;

  if v_points <> 0 or v_bonus <> 0 then
    insert into public.contact_engagement(contact_id,intent_score,temperature,last_engagement_at,last_scored_at,score_reasons)
    values(
      NEW.contact_id,
      greatest(0,least(100,v_points+v_bonus)),
      case
        when greatest(0,least(100,v_points+v_bonus)) >= 60 then 'hot'
        when greatest(0,least(100,v_points+v_bonus)) >= 25 then 'warm'
        else 'cold'
      end,
      NEW.occurred_at,
      now(),
      jsonb_build_array(jsonb_build_object(
        'event',NEW.event_type,'points',v_points,'bonus',v_bonus,'at',NEW.occurred_at
      ))
    )
    on conflict (contact_id) do update
    set intent_score=greatest(0,least(100,public.contact_engagement.intent_score + v_points + v_bonus)),
        temperature=case
          when greatest(0,least(100,public.contact_engagement.intent_score + v_points + v_bonus)) >= 60 then 'hot'
          when greatest(0,least(100,public.contact_engagement.intent_score + v_points + v_bonus)) >= 25 then 'warm'
          else 'cold'
        end,
        last_engagement_at=NEW.occurred_at,
        last_scored_at=now(),
        score_reasons=(
          select coalesce(jsonb_agg(x),'[]'::jsonb)
          from (
            select x
            from jsonb_array_elements(
              coalesce(public.contact_engagement.score_reasons,'[]'::jsonb) ||
              jsonb_build_array(jsonb_build_object(
                'event',NEW.event_type,'points',v_points,'bonus',v_bonus,'at',NEW.occurred_at
              ))
            ) with ordinality as t(x,ord)
            order by ord desc
            limit 20
          ) q
        );
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.enqueue_journey_automation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  r record;
  v_journey_key text;
  v_step_key text;
  v_dedupe text;
begin
  if NEW.journey_id is not null then
    select journey_key into v_journey_key
    from public.contact_journeys
    where id=NEW.journey_id;
  end if;

  v_step_key := NEW.metadata->>'step_key';

  for r in
    select *
    from public.journey_automation_rules
    where active
      and trigger_event=NEW.event_type
      and (journey_key is null or journey_key=v_journey_key)
  loop
    if r.config ? 'required_step_key'
       and coalesce(r.config->>'required_step_key','') <> coalesce(v_step_key,'') then
      continue;
    end if;

    v_dedupe := concat(
      r.rule_key,':',NEW.contact_id::text,':',
      coalesce(NEW.journey_id::text,'none'),':',
      coalesce(v_step_key,'none'),':',
      to_char(NEW.occurred_at,'YYYYMMDDHH24MISS')
    );

    insert into public.journey_automation_jobs(
      contact_id,journey_id,rule_id,action_type,status,scheduled_for,dedupe_key,payload
    )
    values(
      NEW.contact_id,NEW.journey_id,r.id,r.action_type,'queued',
      NEW.occurred_at + make_interval(mins => r.delay_minutes),
      v_dedupe,
      coalesce(r.config,'{}'::jsonb) || jsonb_build_object(
        'trigger_event',NEW.event_type,
        'step_key',v_step_key
      )
    )
    on conflict (dedupe_key) do nothing;
  end loop;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.expand_completed_journey_step()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_step_key text;
  v_semantic_event text;
begin
  if NEW.event_type <> 'step_completed' then
    return NEW;
  end if;

  v_step_key := NEW.metadata->>'step_key';

  v_semantic_event := case v_step_key
    when 'application_interview_schedule' then 'application_interview_scheduled'
    when 'application_interview' then 'application_interview_completed'
    when 'consultation_schedule' then 'consultation_scheduled'
    when 'consultation' then 'consultation_completed'
    when 'payment_agreement' then 'payment_completed'
    when 'report_send' then 'report_sent'
    when 'onboarding_health_questionnaire' then 'onboarding_completed'
    when 'backend_activation' then 'member_access_activated'
    else null
  end;

  if v_semantic_event is not null then
    insert into public.journey_events(
      contact_id,journey_id,step_id,event_type,source,actor_user_id,metadata,dedupe_key
    )
    values(
      NEW.contact_id,NEW.journey_id,NEW.step_id,v_semantic_event,
      NEW.source,NEW.actor_user_id,
      NEW.metadata || jsonb_build_object('derived_from','step_completed'),
      'semantic:' || NEW.step_id::text || ':' || v_semantic_event
    )
    on conflict (dedupe_key) do nothing;
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_contact_state_from_journey_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if NEW.event_type='consultation_scheduled' then
    update public.contacts
    set consultation_status='scheduled',
        follow_up_status='consultation_scheduled',
        updated_at=now()
    where id=NEW.contact_id;

  elsif NEW.event_type='consultation_completed' then
    update public.contacts
    set consultation_status='completed',
        follow_up_status='consultation_completed',
        updated_at=now()
    where id=NEW.contact_id;

  elsif NEW.event_type='payment_completed' then
    update public.contacts
    set lifecycle_stage='client',
        updated_at=now()
    where id=NEW.contact_id;
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.create_appointment_reminder_actions()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  a record;
  v_email_template uuid;
  v_sms_template uuid;
  v_step_id uuid;
  v_email_exists boolean;
  v_sms_exists boolean;
  v_sms_allowed boolean;
  v_count integer := 0;
  v_step_key text;
begin
  for a in
    select
      ja.*,
      c.email,
      c.phone,
      cj.current_step_key
    from public.journey_appointments ja
    join public.contacts c on c.id=ja.contact_id
    join public.contact_journeys cj on cj.id=ja.journey_id
    where ja.status='scheduled'
      and ja.scheduled_start is not null
      and ja.scheduled_start > now()
      and ja.scheduled_start <= now() + interval '24 hours'
  loop
    v_step_key := case
      when a.appointment_type='consultation' then 'consultation'
      else 'application_interview'
    end;

    select id into v_step_id
    from public.contact_journey_steps
    where journey_id=a.journey_id and step_key=v_step_key
    limit 1;

    select id into v_email_template
    from public.journey_action_templates
    where template_key=case
      when a.appointment_type='consultation' then 'consult-reminder-email'
      else 'appointment-reminder-email'
    end
    limit 1;

    select id into v_sms_template
    from public.journey_action_templates
    where template_key=case
      when a.appointment_type='consultation' then 'consult-reminder-sms'
      else 'appointment-reminder-sms'
    end
    limit 1;

    select exists(
      select 1
      from public.journey_step_actions x
      where x.journey_id=a.journey_id
        and x.action_type='email'
        and x.template_id=v_email_template
        and x.metadata->>'appointment_id'=a.id::text
        and x.status not in ('cancelled')
    ) into v_email_exists;

    if a.email is not null and not v_email_exists then
      insert into public.journey_step_actions(
        contact_id,journey_id,journey_step_id,action_type,status,assigned_to,due_at,
        template_id,subject,body,created_by,metadata
      )
      select
        a.contact_id,a.journey_id,v_step_id,'email','assigned',a.assigned_to,
        greatest(now(),a.scheduled_start-interval '24 hours'),
        t.id,t.subject,t.body,null,
        jsonb_build_object('appointment_id',a.id,'reminder','24_hour')
      from public.journey_action_templates t
      where t.id=v_email_template;

      v_count := v_count + 1;
    end if;

    select exists(
      select 1 from public.contact_sms_preferences p
      where p.contact_id=a.contact_id and p.status='opted_in'
    ) into v_sms_allowed;

    select exists(
      select 1
      from public.journey_step_actions x
      where x.journey_id=a.journey_id
        and x.action_type='sms'
        and x.template_id=v_sms_template
        and x.metadata->>'appointment_id'=a.id::text
        and x.status not in ('cancelled')
    ) into v_sms_exists;

    if a.phone is not null and v_sms_allowed and not v_sms_exists then
      insert into public.journey_step_actions(
        contact_id,journey_id,journey_step_id,action_type,status,assigned_to,due_at,
        template_id,body,created_by,metadata
      )
      select
        a.contact_id,a.journey_id,v_step_id,'sms','assigned',a.assigned_to,
        greatest(now(),a.scheduled_start-interval '24 hours'),
        t.id,t.body,null,
        jsonb_build_object('appointment_id',a.id,'reminder','24_hour')
      from public.journey_action_templates t
      where t.id=v_sms_template;

      v_count := v_count + 1;
    end if;
  end loop;

  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_journey_from_appointment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_schedule_step text;
  v_event_step text;
begin
  if NEW.appointment_type='application_interview' then
    v_schedule_step := 'application_interview_schedule';
    v_event_step := 'application_interview';
  elsif NEW.appointment_type='consultation' then
    v_schedule_step := 'consultation_schedule';
    v_event_step := 'consultation';
  else
    return NEW;
  end if;

  if NEW.status='scheduled'
     and (TG_OP='INSERT' or OLD.status is distinct from NEW.status or OLD.scheduled_start is distinct from NEW.scheduled_start) then
    update public.contact_journey_steps
    set status='completed',
        completion_source='appointment_scheduled',
        completed_at=coalesce(completed_at,now()),
        updated_at=now()
    where journey_id=NEW.journey_id
      and step_key=v_schedule_step
      and status not in ('completed','skipped');

    update public.follow_up_tasks
    set status='completed',completed_at=coalesce(completed_at,now())
    where journey_id=NEW.journey_id
      and journey_step_id=NEW.journey_step_id
      and status='open'
      and task_type in ('scheduling','journey','task');

    insert into public.contact_activity(contact_id,activity_type,title,detail,metadata)
    values(
      NEW.contact_id,'appointment_scheduled',
      case when NEW.appointment_type='application_interview' then 'Application interview scheduled' else 'Consultation scheduled' end,
      case when NEW.scheduled_start is not null then 'Scheduled for ' || NEW.scheduled_start::text else null end,
      jsonb_build_object('appointment_id',NEW.id,'journey_id',NEW.journey_id,'assigned_to',NEW.assigned_to)
    );
  end if;

  if NEW.status='completed'
     and (TG_OP='INSERT' or OLD.status is distinct from NEW.status) then
    update public.contact_journey_steps
    set status='completed',
        completion_source='appointment_completed',
        completed_at=coalesce(completed_at,now()),
        updated_at=now()
    where journey_id=NEW.journey_id
      and step_key=v_event_step
      and status not in ('completed','skipped');

    update public.follow_up_tasks
    set status='completed',completed_at=coalesce(completed_at,now())
    where journey_id=NEW.journey_id
      and status='open'
      and (
        journey_step_id=NEW.journey_step_id
        or lower(title) like '%' || lower(case when NEW.appointment_type='consultation' then 'consultation' else 'application interview' end) || '%'
      );

    update public.journey_appointments
    set completed_at=coalesce(completed_at,now()),updated_at=now()
    where id=NEW.id and completed_at is null;
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.create_followup_for_journey_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_step_name text;
  v_title text;
  v_existing uuid;
  v_is_reminder boolean := false;
begin
  if NEW.status not in ('assigned','in_progress') then
    return NEW;
  end if;

  select name into v_step_name
  from public.contact_journey_steps
  where id=NEW.journey_step_id;

  v_title := case NEW.action_type
    when 'email' then 'Email: ' || coalesce(v_step_name,'Journey next step')
    when 'sms' then 'Text: ' || coalesce(v_step_name,'Journey next step')
    when 'call' then 'Call: ' || coalesce(v_step_name,'Journey next step')
    when 'review' then 'Review: ' || coalesce(v_step_name,'Journey next step')
    else coalesce(v_step_name,'Journey next step')
  end;

  v_is_reminder := coalesce(NEW.metadata->>'reminder','') <> '';

  select id into v_existing
  from public.follow_up_tasks
  where contact_id=NEW.contact_id
    and journey_step_id=NEW.journey_step_id
    and status='open'
    and (
      journey_action_id=NEW.id
      or (
        not v_is_reminder
        and (
          task_type=NEW.action_type
          or (
            NEW.action_type in ('review','call','task')
            and task_type='journey'
          )
        )
      )
    )
  order by created_at
  limit 1;

  if v_existing is not null then
    update public.follow_up_tasks
    set assigned_to=coalesce(NEW.assigned_to,assigned_to),
        due_at=coalesce(NEW.due_at,due_at),
        title=v_title,
        task_type=NEW.action_type,
        journey_action_id=NEW.id,
        instructions=coalesce(NEW.instructions,NEW.body,instructions)
    where id=v_existing;
  else
    insert into public.follow_up_tasks(
      contact_id,assigned_to,title,due_at,status,priority,created_by,
      task_type,journey_id,journey_step_id,journey_action_id,instructions
    )
    values(
      NEW.contact_id,NEW.assigned_to,v_title,NEW.due_at,'open',
      case when NEW.due_at is not null and NEW.due_at <= now() + interval '24 hours' then 'high' else 'normal' end,
      NEW.created_by,NEW.action_type,NEW.journey_id,NEW.journey_step_id,NEW.id,
      coalesce(NEW.instructions,NEW.body)
    );
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.complete_journey_action_from_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if NEW.status='completed'
     and OLD.status is distinct from NEW.status
     and NEW.journey_action_id is not null then
    update public.journey_step_actions
    set status='completed',
        completed_by=(select auth.uid()),
        completed_at=coalesce(completed_at,now()),
        updated_at=now()
    where id=NEW.journey_action_id
      and status not in ('completed','cancelled');
  end if;
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.process_journey_automation_jobs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  j record;
  v_count integer := 0;
  v_step_status text;
  v_step_id uuid;
  v_assigned uuid;
  v_title text;
  v_priority text;
begin
  for j in
    select *
    from public.journey_automation_jobs
    where status='queued' and scheduled_for <= now()
    order by scheduled_for
    limit 100
    for update skip locked
  loop
    update public.journey_automation_jobs set status='processing' where id=j.id;

    v_step_status := null;
    v_step_id := null;

    if j.payload ? 'required_step_key' and j.journey_id is not null then
      select id,status into v_step_id,v_step_status
      from public.contact_journey_steps
      where journey_id=j.journey_id
        and step_key=j.payload->>'required_step_key'
      limit 1;

      if v_step_status in ('completed','skipped','waived') then
        update public.journey_automation_jobs
        set status='cancelled',processed_at=now(),
            result=jsonb_build_object('reason','required_step_already_complete')
        where id=j.id;
        continue;
      end if;
    end if;

    if j.action_type='create_task' then
      select coalesce(cj.assigned_to,c.assigned_to)
      into v_assigned
      from public.contacts c
      left join public.contact_journeys cj on cj.id=j.journey_id
      where c.id=j.contact_id;

      v_title := coalesce(j.payload->>'task_title','Journey follow-up');
      v_priority := coalesce(j.payload->>'priority','normal');

      if not exists (
        select 1 from public.follow_up_tasks
        where contact_id=j.contact_id
          and title=v_title
          and status='open'
      ) then
        insert into public.follow_up_tasks(
          contact_id,assigned_to,title,due_at,status,priority,
          task_type,journey_id,journey_step_id,instructions
        )
        values(
          j.contact_id,v_assigned,v_title,now(),'open',v_priority,
          'journey',j.journey_id,v_step_id,
          coalesce(j.payload->>'instructions',v_title)
        );
      else
        update public.follow_up_tasks
        set journey_id=coalesce(journey_id,j.journey_id),
            journey_step_id=coalesce(journey_step_id,v_step_id),
            task_type=case when task_type='general' then 'journey' else task_type end
        where contact_id=j.contact_id
          and title=v_title
          and status='open';
      end if;

      update public.contacts
      set follow_up_status=case when follow_up_status='closed' then follow_up_status else 'needs_follow_up' end,
          next_follow_up_at=coalesce(next_follow_up_at,now()),
          updated_at=now()
      where id=j.contact_id;

      insert into public.contact_activity(contact_id,activity_type,title,detail,metadata)
      values(
        j.contact_id,'journey_automation','Follow-up task created',
        v_title,jsonb_build_object('automation_job_id',j.id,'journey_id',j.journey_id,'journey_step_id',v_step_id)
      );

      update public.journey_automation_jobs
      set status='completed',processed_at=now(),
          result=jsonb_build_object('task_title',v_title,'journey_step_id',v_step_id)
      where id=j.id;

      v_count := v_count + 1;

    elsif j.action_type='set_follow_up' then
      update public.contacts
      set follow_up_status='needs_follow_up',
          next_follow_up_at=coalesce((j.payload->>'follow_up_at')::timestamptz,now()),
          updated_at=now()
      where id=j.contact_id;

      update public.journey_automation_jobs
      set status='completed',processed_at=now()
      where id=j.id;
      v_count := v_count + 1;

    elsif j.action_type='add_tag' then
      insert into public.contact_tags(contact_id,tag,source,rule_key,updated_at)
      values(j.contact_id,j.payload->>'tag','automatic','automation:' || coalesce((select rule_key from public.journey_automation_rules where id=j.rule_id),'unknown'),now())
      on conflict (contact_id,tag) do update set updated_at=now();

      update public.journey_automation_jobs
      set status='completed',processed_at=now()
      where id=j.id;
      v_count := v_count + 1;

    else
      update public.journey_automation_jobs
      set status='blocked',processed_at=now(),
          result=jsonb_build_object('reason','delivery_provider_not_enabled')
      where id=j.id;
    end if;
  end loop;

  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_household_type(p_household_id uuid, p_household_type text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_primary_member public.household_members%rowtype;
  v_member_count integer;
begin
  if not exists (
    select 1 from public.staff_access s where s.user_id=(select auth.uid())
  ) then
    raise exception 'Staff access required';
  end if;

  if p_household_type not in ('individual','couple','family') then
    raise exception 'Invalid household type';
  end if;

  select count(*) into v_member_count
  from public.household_members
  where household_id=p_household_id and status='active';

  if p_household_type='individual' and v_member_count > 1 then
    raise exception 'Remove additional household members before changing to individual';
  end if;

  select * into v_primary_member
  from public.household_members
  where household_id=p_household_id and is_primary and status='active'
  limit 1;

  if v_primary_member.id is null then
    raise exception 'Primary household member not found';
  end if;

  update public.households
  set status='draft',
      household_type=p_household_type,
      updated_at=now()
  where id=p_household_id;

  if p_household_type='individual' then
    update public.household_members
    set relationship_type='self',updated_at=now()
    where id=v_primary_member.id;
  else
    if v_primary_member.sex='male' then
      update public.household_members
      set relationship_type='husband',updated_at=now()
      where id=v_primary_member.id;
    elsif v_primary_member.sex='female' then
      update public.household_members
      set relationship_type='wife',updated_at=now()
      where id=v_primary_member.id;
    else
      raise exception 'Primary member sex must be male or female before creating a couple or family';
    end if;
  end if;

  if p_household_type='individual' then
    update public.households
    set status='active',updated_at=now()
    where id=p_household_id;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.ensure_vitality_report_after_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_workflow_id uuid;
begin
  if NEW.event_type <> 'vitality_completed' then
    return NEW;
  end if;

  v_workflow_id := nullif(NEW.metadata->>'workflow_id','')::uuid;

  if v_workflow_id is null then
    select id into v_workflow_id
    from public.workflow_records
    where contact_id=NEW.contact_id
      and workflow_type='vitality_assessment'
      and status='completed'
    order by completed_at desc nulls last,created_at desc
    limit 1;
  end if;

  insert into public.vitality_reports(
    contact_id,workflow_id,journey_id,status,updated_at
  )
  values(
    NEW.contact_id,v_workflow_id,NEW.journey_id,'awaiting_review',now()
  )
  on conflict (workflow_id) where workflow_id is not null do update
  set journey_id=coalesce(public.vitality_reports.journey_id,excluded.journey_id),
      updated_at=now();

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_report_review_to_journey()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if NEW.status='approved'
     and (TG_OP='INSERT' or OLD.status is distinct from NEW.status) then
    update public.contact_journey_steps
    set status='completed',
        completion_source='vitality_report_approved',
        completed_at=coalesce(completed_at,now()),
        updated_at=now()
    where journey_id=NEW.journey_id
      and step_key='report_review'
      and status not in ('completed','skipped');

    insert into public.contact_activity(contact_id,activity_type,title,detail,actor_user_id,metadata)
    values(
      NEW.contact_id,'vitality_report_approved','Vitality report approved',
      coalesce(NEW.original_filename,'Report approved for client delivery'),
      NEW.approved_by,
      jsonb_build_object('report_id',NEW.id,'journey_id',NEW.journey_id)
    );
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.advance_journey_step_from_completed_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_step_key text;
begin
  if NEW.status <> 'completed' or OLD.status is not distinct from NEW.status then
    return NEW;
  end if;

  select step_key into v_step_key
  from public.contact_journey_steps
  where id=NEW.journey_step_id;

  if (
    v_step_key='report_send'
    and NEW.action_type in ('email','sms')
  ) or (
    v_step_key='preconsultation_doc'
    and NEW.action_type='email'
  ) then
    update public.contact_journey_steps
    set status='completed',
        completion_source='completed_journey_action',
        completed_at=coalesce(completed_at,now()),
        updated_at=now()
    where id=NEW.journey_step_id
      and status not in ('completed','skipped');
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.handle_enrollment_activation_exception()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_event_type text;
  v_title text;
  v_detail text;
  v_assigned uuid;
begin
  if TG_OP <> 'UPDATE' then
    return NEW;
  end if;

  select coalesce(cj.assigned_to,c.assigned_to)
  into v_assigned
  from public.contacts c
  left join public.contact_journeys cj on cj.id=NEW.journey_id
  where c.id=NEW.contact_id;

  if OLD.payment_status is distinct from NEW.payment_status
     and NEW.payment_status='failed' then
    v_event_type := 'payment_failed';
    v_title := 'Personal follow-up: enrollment payment needs attention';
    v_detail := 'Payment did not complete. Reach out personally, answer questions, and help them retry without pressure.';

    insert into public.journey_events(
      contact_id,journey_id,step_id,event_type,source,actor_user_id,metadata,dedupe_key
    )
    values(
      NEW.contact_id,NEW.journey_id,NEW.journey_step_id,v_event_type,'enrollment',
      (select auth.uid()),
      jsonb_build_object('activation_id',NEW.id,'program_code',NEW.program_code),
      v_event_type || ':' || NEW.id::text || ':' || to_char(now(),'YYYYMMDDHH24MI')
    )
    on conflict (dedupe_key) do nothing;

    insert into public.follow_up_tasks(
      contact_id,assigned_to,title,due_at,status,priority,task_type,journey_id,journey_step_id,instructions
    )
    select
      NEW.contact_id,v_assigned,v_title,now()+interval '1 day','open','high','call',
      NEW.journey_id,NEW.journey_step_id,v_detail
    where not exists (
      select 1 from public.follow_up_tasks
      where contact_id=NEW.contact_id and title=v_title and status='open'
    );

    update public.contacts
    set follow_up_status='needs_follow_up',
        next_follow_up_at=now()+interval '1 day',
        updated_at=now()
    where id=NEW.contact_id;
  end if;

  if OLD.agreement_status is distinct from NEW.agreement_status
     and NEW.agreement_status='declined' then
    v_event_type := 'agreement_declined';
    v_title := 'Personal follow-up: enrollment agreement declined';
    v_detail := 'Reach out personally to understand the concern or question. Do not pressure the client.';

    insert into public.journey_events(
      contact_id,journey_id,step_id,event_type,source,actor_user_id,metadata,dedupe_key
    )
    values(
      NEW.contact_id,NEW.journey_id,NEW.journey_step_id,v_event_type,'enrollment',
      (select auth.uid()),
      jsonb_build_object('activation_id',NEW.id,'program_code',NEW.program_code),
      v_event_type || ':' || NEW.id::text
    )
    on conflict (dedupe_key) do nothing;

    insert into public.follow_up_tasks(
      contact_id,assigned_to,title,due_at,status,priority,task_type,journey_id,journey_step_id,instructions
    )
    select
      NEW.contact_id,v_assigned,v_title,now()+interval '1 day','open','high','call',
      NEW.journey_id,NEW.journey_step_id,v_detail
    where not exists (
      select 1 from public.follow_up_tasks
      where contact_id=NEW.contact_id and title=v_title and status='open'
    );

    update public.contacts
    set follow_up_status='needs_follow_up',
        next_follow_up_at=now()+interval '1 day',
        updated_at=now()
    where id=NEW.contact_id;
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.add_household_member(p_household_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_relationship_type text, p_sex text, p_date_of_birth date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_household public.households%rowtype;
  v_contact_id uuid;
  v_primary_contact uuid;
  v_limit integer;
  v_current_count integer;
begin
  if not exists (
    select 1 from public.staff_access s where s.user_id=(select auth.uid())
  ) then
    raise exception 'Staff access required';
  end if;

  select * into v_household
  from public.households
  where id=p_household_id
  for update;

  if v_household.id is null then
    raise exception 'Household not found';
  end if;

  if trim(coalesce(p_first_name,''))='' or trim(coalesce(p_last_name,''))='' then
    raise exception 'First and last name are required';
  end if;

  if p_sex not in ('male','female') then
    raise exception 'Sex must be male or female';
  end if;

  if v_household.household_type='individual' then
    raise exception 'Change the household to Couple or Family before adding members';
  end if;

  if v_household.household_type='couple'
     and p_relationship_type not in ('husband','wife') then
    raise exception 'Couple households are husband and wife only';
  end if;

  if v_household.household_type='family'
     and p_relationship_type not in ('husband','wife','child','dependent') then
    raise exception 'Family households are husband, wife, children and dependents only';
  end if;

  if p_relationship_type='husband' and p_sex <> 'male' then
    raise exception 'A husband must be male';
  end if;

  if p_relationship_type='wife' and p_sex <> 'female' then
    raise exception 'A wife must be female';
  end if;

  select hm.contact_id into v_primary_contact
  from public.household_members hm
  where hm.household_id=p_household_id and hm.is_primary and hm.status='active'
  limit 1;

  select me.limit_value into v_limit
  from public.client_access ca
  join public.membership_entitlements me on me.membership_id=ca.membership_id
  where ca.household_id=p_household_id
    and me.entitlement_key='family_profiles'
    and me.status='active'
  order by me.created_at desc
  limit 1;

  select count(*) into v_current_count
  from public.household_members
  where household_id=p_household_id and status='active';

  if v_limit is not null and v_current_count >= v_limit then
    raise exception 'This membership has reached its included household profile limit';
  end if;

  insert into public.contacts(
    first_name,last_name,email,phone,lifecycle_stage,first_source,last_source
  )
  values(
    trim(p_first_name),trim(p_last_name),
    nullif(lower(trim(coalesce(p_email,''))),''),
    nullif(trim(coalesce(p_phone,'')),''),
    'client','family_household','family_household'
  )
  returning id into v_contact_id;

  insert into public.household_members(
    household_id,contact_id,relationship_type,sex,is_primary,date_of_birth,guardian_contact_id,status
  )
  values(
    p_household_id,v_contact_id,p_relationship_type,p_sex,false,p_date_of_birth,
    case when p_relationship_type in ('child','dependent') then v_primary_contact else null end,
    'active'
  );

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    v_household.primary_contact_id,'household_member_added','Household member added',
    trim(p_first_name) || ' ' || trim(p_last_name),
    (select auth.uid()),
    jsonb_build_object(
      'household_id',p_household_id,
      'new_contact_id',v_contact_id,
      'relationship_type',p_relationship_type,
      'sex',p_sex
    )
  );

  return v_contact_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.validate_household_member()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_type text;
begin
  select household_type into v_type
  from public.households
  where id=NEW.household_id;

  if v_type is null then
    raise exception 'Household not found';
  end if;

  if NEW.relationship_type='husband' and NEW.sex is distinct from 'male' then
    raise exception 'A husband must be recorded as male';
  end if;

  if NEW.relationship_type='wife' and NEW.sex is distinct from 'female' then
    raise exception 'A wife must be recorded as female';
  end if;

  if v_type='individual' and NEW.relationship_type <> 'self' then
    raise exception 'Individual households can contain only the individual';
  end if;

  if v_type='couple' and NEW.relationship_type not in ('husband','wife') then
    raise exception 'Couple households are husband and wife only';
  end if;

  if v_type='family' and NEW.relationship_type not in ('husband','wife','child','dependent') then
    raise exception 'Family households are husband, wife, children and dependents only';
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.handle_appointment_exception()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_schedule_step text;
  v_event_step text;
  v_event_type text;
  v_task_title text;
begin
  if TG_OP <> 'UPDATE' or OLD.status is not distinct from NEW.status then
    return NEW;
  end if;

  if NEW.status not in ('cancelled','no_show') then
    return NEW;
  end if;

  if NEW.appointment_type='application_interview' then
    v_schedule_step := 'application_interview_schedule';
    v_event_step := 'application_interview';
  elsif NEW.appointment_type='consultation' then
    v_schedule_step := 'consultation_schedule';
    v_event_step := 'consultation';
  else
    return NEW;
  end if;

  v_event_type := case when NEW.status='no_show' then 'appointment_no_show' else 'appointment_cancelled' end;
  v_task_title := case
    when NEW.status='no_show' then
      case when NEW.appointment_type='consultation'
        then 'Personal follow-up after missed consultation'
        else 'Personal follow-up after missed application interview'
      end
    else
      case when NEW.appointment_type='consultation'
        then 'Help reschedule cancelled consultation'
        else 'Help reschedule cancelled application interview'
      end
  end;

  update public.contact_journey_steps
  set status='in_progress',
      completed_at=null,
      completion_source=null,
      started_at=coalesce(started_at,now()),
      due_at=now()+interval '48 hours',
      updated_at=now()
  where journey_id=NEW.journey_id
    and step_key=v_schedule_step;

  update public.contact_journey_steps
  set status='pending',
      completed_at=null,
      completion_source=null,
      updated_at=now()
  where journey_id=NEW.journey_id
    and step_key=v_event_step
    and status <> 'completed';

  update public.contact_journeys
  set current_step_key=v_schedule_step,
      next_action_at=now()+interval '48 hours',
      last_activity_at=now(),
      updated_at=now()
  where id=NEW.journey_id;

  insert into public.journey_events(
    contact_id,journey_id,step_id,event_type,source,actor_user_id,metadata,dedupe_key
  )
  values(
    NEW.contact_id,NEW.journey_id,NEW.journey_step_id,v_event_type,'appointment',
    (select auth.uid()),
    jsonb_build_object('appointment_id',NEW.id,'appointment_type',NEW.appointment_type),
    v_event_type || ':' || NEW.id::text
  )
  on conflict (dedupe_key) do nothing;

  insert into public.follow_up_tasks(
    contact_id,assigned_to,title,due_at,status,priority,task_type,
    journey_id,journey_step_id,instructions
  )
  select
    NEW.contact_id,
    coalesce(NEW.assigned_to,cj.assigned_to,c.assigned_to),
    v_task_title,
    now()+interval '1 day',
    'open',
    case when NEW.status='no_show' then 'high' else 'normal' end,
    'call',
    NEW.journey_id,
    s.id,
    case
      when NEW.status='no_show'
        then 'Reach out personally and gently. Check that everything is okay, answer questions, and offer to reschedule without pressure.'
      else 'Reach out personally and help them find a new time that works.'
    end
  from public.contact_journeys cj
  join public.contacts c on c.id=NEW.contact_id
  join public.contact_journey_steps s
    on s.journey_id=NEW.journey_id and s.step_key=v_schedule_step
  where cj.id=NEW.journey_id
    and not exists (
      select 1 from public.follow_up_tasks t
      where t.contact_id=NEW.contact_id
        and t.title=v_task_title
        and t.status='open'
    );

  update public.contacts
  set follow_up_status='needs_follow_up',
      next_follow_up_at=now()+interval '1 day',
      consultation_status=case
        when NEW.appointment_type='consultation' then 'cancelled'
        else consultation_status
      end,
      updated_at=now()
  where id=NEW.contact_id;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.assert_household_composition(p_household_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_type text;
  v_status text;
  v_total integer;
  v_self integer;
  v_husbands integer;
  v_wives integer;
  v_children integer;
  v_missing_sex integer;
begin
  select household_type,status into v_type,v_status
  from public.households
  where id=p_household_id;

  if v_status is distinct from 'active' then
    return;
  end if;

  select
    count(*) filter (where status='active'),
    count(*) filter (where status='active' and relationship_type='self'),
    count(*) filter (where status='active' and relationship_type='husband'),
    count(*) filter (where status='active' and relationship_type='wife'),
    count(*) filter (where status='active' and relationship_type in ('child','dependent')),
    count(*) filter (where status='active' and sex is null)
  into v_total,v_self,v_husbands,v_wives,v_children,v_missing_sex
  from public.household_members
  where household_id=p_household_id;

  if v_missing_sex > 0 then
    raise exception 'Every active ReVitalized household member must be recorded as male or female';
  end if;

  if v_type='individual' and not (v_total=1 and v_self=1) then
    raise exception 'An active individual household must contain exactly one self member';
  end if;

  if v_type='couple' and not (v_total=2 and v_husbands=1 and v_wives=1) then
    raise exception 'An active couple household must contain one husband and one wife';
  end if;

  if v_type='family' and not (v_husbands=1 and v_wives=1 and v_children>=1 and v_total>=3) then
    raise exception 'An active family household must contain one husband, one wife, and at least one child or dependent';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.process_submitted_client_checkin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_coach uuid;
  v_value numeric;
  v_key text;
begin
  if NEW.status <> 'submitted'
     or (TG_OP='UPDATE' and OLD.status is not distinct from NEW.status) then
    return NEW;
  end if;

  foreach v_key in array array['energy','mood','stress','sleep_hours']
  loop
    begin
      v_value := nullif(NEW.responses->>v_key,'')::numeric;
    exception when others then
      v_value := null;
    end;

    if v_value is not null then
      insert into public.progress_entries(
        contact_id,membership_id,metric_key,value_numeric,recorded_at,source,created_by,metadata
      )
      values(
        NEW.contact_id,NEW.membership_id,v_key,v_value,coalesce(NEW.submitted_at,now()),
        'member',NEW.created_by,jsonb_build_object('checkin_id',NEW.id)
      );
    end if;
  end loop;

  select coach_user_id into v_coach
  from public.client_coach_assignments
  where contact_id=NEW.contact_id
    and role='primary'
    and status='active'
  limit 1;

  insert into public.follow_up_tasks(
    contact_id,assigned_to,title,due_at,status,priority,task_type,instructions
  )
  select
    NEW.contact_id,v_coach,'Review client weekly check-in',
    now()+interval '1 day','open','normal','review',
    'Review the client’s submitted weekly check-in, note wins/challenges/questions, and determine whether a personal response or coaching adjustment is needed.'
  where not exists (
    select 1 from public.follow_up_tasks
    where contact_id=NEW.contact_id
      and title='Review client weekly check-in'
      and status='open'
  );

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    NEW.contact_id,'weekly_checkin_submitted','Weekly ReVitalized check-in submitted',
    null,NEW.created_by,jsonb_build_object('checkin_id',NEW.id)
  );

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.create_coaching_session_prep_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_due timestamptz;
begin
  if NEW.status <> 'scheduled' or NEW.scheduled_start is null then
    return NEW;
  end if;

  v_due := greatest(now(),NEW.scheduled_start - interval '24 hours');

  insert into public.follow_up_tasks(
    contact_id,assigned_to,title,due_at,status,priority,task_type,instructions
  )
  select
    NEW.contact_id,
    NEW.coach_user_id,
    'Prepare for coaching session',
    v_due,
    'open',
    case when NEW.scheduled_start <= now()+interval '24 hours' then 'high' else 'normal' end,
    'coaching',
    'Review the client’s latest goals, habits, progress entries, weekly check-in, open assignments and prior coaching notes before the session.'
  where not exists (
    select 1
    from public.follow_up_tasks t
    where t.contact_id=NEW.contact_id
      and t.title='Prepare for coaching session'
      and t.status='open'
      and t.assigned_to=NEW.coach_user_id
      and abs(extract(epoch from (coalesce(t.due_at,v_due)-v_due))) < 300
  );

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_primary_coach_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if NEW.assigned_coach_id is null then
    update public.client_coach_assignments
    set status='inactive',ended_at=now()
    where contact_id=NEW.primary_contact_id
      and role='primary'
      and status='active';
    return NEW;
  end if;

  update public.client_coach_assignments
  set status='inactive',ended_at=now()
  where contact_id=NEW.primary_contact_id
    and role='primary'
    and status='active'
    and coach_user_id <> NEW.assigned_coach_id;

  insert into public.client_coach_assignments(
    contact_id,membership_id,coach_user_id,role,status,assigned_at,assigned_by
  )
  values(
    NEW.primary_contact_id,NEW.id,NEW.assigned_coach_id,'primary','active',now(),NEW.created_by
  )
  on conflict (contact_id,coach_user_id,role) do update
  set membership_id=excluded.membership_id,
      status='active',
      ended_at=null,
      assigned_at=now();

  update public.contacts
  set assigned_to=NEW.assigned_coach_id,updated_at=now()
  where id=NEW.primary_contact_id;

  update public.contact_journeys
  set assigned_to=NEW.assigned_coach_id,updated_at=now()
  where contact_id=NEW.primary_contact_id
    and status in ('active','paused','nurture');

  update public.follow_up_tasks
  set assigned_to=NEW.assigned_coach_id
  where contact_id=NEW.primary_contact_id
    and status='open'
    and assigned_to is null;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_all_my_notifications_read()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_count integer;
begin
  update public.member_notifications
  set status='read',
      read_at=coalesce(read_at,now())
  where user_id=(select auth.uid())
    and status='unread';

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.update_my_staff_profile_impl(p_display_name text, p_phone text)
 RETURNS TABLE(display_name text, phone text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  update public.staff_access
  set
    display_name = nullif(trim(p_display_name),''),
    phone = nullif(trim(p_phone),''),
    updated_at = now(),
    updated_by = auth.uid()
  where user_id = auth.uid();

  return query
  select sa.display_name, sa.phone
  from public.staff_access sa
  where sa.user_id = auth.uid();
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_coaching_session_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if TG_OP='UPDATE' and OLD.status is distinct from NEW.status
     and NEW.status in ('completed','cancelled','no_show') then

    update public.follow_up_tasks
    set status='completed',
        completed_at=coalesce(completed_at,now())
    where contact_id=NEW.contact_id
      and assigned_to=NEW.coach_user_id
      and title='Prepare for coaching session'
      and status='open';

    if NEW.status='completed' and NEW.completed_at is null then
      update public.coaching_sessions
      set completed_at=now(),updated_at=now()
      where id=NEW.id;
    end if;

    insert into public.contact_activity(
      contact_id,activity_type,title,detail,actor_user_id,metadata
    )
    values(
      NEW.contact_id,
      case
        when NEW.status='completed' then 'coaching_session_completed'
        when NEW.status='no_show' then 'coaching_session_no_show'
        else 'coaching_session_cancelled'
      end,
      case
        when NEW.status='completed' then 'Coaching session completed'
        when NEW.status='no_show' then 'Coaching session missed'
        else 'Coaching session cancelled'
      end,
      case when NEW.scheduled_start is not null then NEW.scheduled_start::text else null end,
      NEW.coach_user_id,
      jsonb_build_object('session_id',NEW.id,'status',NEW.status)
    );
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.assign_meal_plan_template(p_contact_id uuid, p_template_id uuid, p_starts_on date, p_title text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_membership_id uuid;
  v_plan_id uuid;
  v_title text;
begin
  if not exists (
    select 1 from public.staff_access s where s.user_id=(select auth.uid())
  ) then
    raise exception 'Staff access required';
  end if;

  select ca.membership_id into v_membership_id
  from public.client_access ca
  where ca.contact_id=p_contact_id
  limit 1;

  if v_membership_id is null then
    raise exception 'Active client membership not found';
  end if;

  select coalesce(p_title,t.title) into v_title
  from public.meal_plan_templates t
  where t.id=p_template_id and t.status='published';

  if v_title is null then
    raise exception 'Published meal plan template not found';
  end if;

  update public.client_meal_plans
  set status='completed',updated_at=now()
  where contact_id=p_contact_id and status='active';

  insert into public.client_meal_plans(
    contact_id,membership_id,template_id,assigned_by,title,starts_on,ends_on,status,notes
  )
  select
    p_contact_id,
    v_membership_id,
    t.id,
    (select auth.uid()),
    v_title,
    p_starts_on,
    p_starts_on + (t.days_count - 1),
    'active',
    p_notes
  from public.meal_plan_templates t
  where t.id=p_template_id
  returning id into v_plan_id;

  insert into public.client_meal_plan_items(
    meal_plan_id,contact_id,scheduled_date,meal_slot,recipe_id,custom_title,notes,status,sort_order
  )
  select
    v_plan_id,
    p_contact_id,
    p_starts_on + (i.day_number - 1),
    i.meal_slot,
    i.recipe_id,
    i.custom_title,
    i.notes,
    'planned',
    i.sort_order
  from public.meal_plan_template_items i
  where i.template_id=p_template_id
  order by i.day_number,i.sort_order;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    p_contact_id,'meal_plan_assigned','Meal plan assigned',v_title,(select auth.uid()),
    jsonb_build_object('meal_plan_id',v_plan_id,'template_id',p_template_id,'starts_on',p_starts_on)
  );

  return v_plan_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_grocery_list_for_meal_plan(p_meal_plan_id uuid, p_title text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_contact_id uuid;
  v_list_id uuid;
  v_title text;
begin
  select contact_id,title into v_contact_id,v_title
  from public.client_meal_plans
  where id=p_meal_plan_id;

  if v_contact_id is null then
    raise exception 'Meal plan not found';
  end if;

  if not exists (
    select 1 from public.staff_access s where s.user_id=(select auth.uid())
  ) and not exists (
    select 1 from public.client_access ca
    where ca.contact_id=v_contact_id
      and ca.user_id=(select auth.uid())
      and ca.status='active'
  ) then
    raise exception 'Not authorized';
  end if;

  update public.client_grocery_lists
  set status='archived',updated_at=now()
  where contact_id=v_contact_id and status='active';

  insert into public.client_grocery_lists(
    contact_id,meal_plan_id,title,status,created_by
  )
  values(
    v_contact_id,p_meal_plan_id,
    coalesce(p_title,v_title || ' Grocery List'),
    'active',
    (select auth.uid())
  )
  returning id into v_list_id;

  insert into public.grocery_list_items(
    grocery_list_id,item,quantity,unit,category,checked,sort_order
  )
  select
    v_list_id,
    ri.ingredient,
    sum(coalesce(ri.quantity,0)),
    ri.unit,
    null,
    false,
    min(ri.sort_order)
  from public.client_meal_plan_items mi
  join public.recipe_ingredients ri on ri.recipe_id=mi.recipe_id
  where mi.meal_plan_id=p_meal_plan_id
  group by ri.ingredient,ri.unit
  order by min(ri.sort_order),ri.ingredient;

  return v_list_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.assign_fitness_program(p_contact_id uuid, p_program_id uuid, p_starts_on date, p_title text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_membership_id uuid;
  v_plan_id uuid;
  v_title text;
begin
  if not exists (
    select 1 from public.staff_access s where s.user_id=(select auth.uid())
  ) then
    raise exception 'Staff access required';
  end if;

  select ca.membership_id into v_membership_id
  from public.client_access ca
  where ca.contact_id=p_contact_id
  limit 1;

  if v_membership_id is null then
    raise exception 'Active client membership not found';
  end if;

  select coalesce(p_title,p.title) into v_title
  from public.fitness_programs p
  where p.id=p_program_id and p.status='published';

  if v_title is null then
    raise exception 'Published fitness program not found';
  end if;

  update public.client_fitness_plans
  set status='completed',updated_at=now()
  where contact_id=p_contact_id and status='active';

  insert into public.client_fitness_plans(
    contact_id,membership_id,program_id,assigned_by,title,starts_on,status,notes
  )
  values(
    p_contact_id,v_membership_id,p_program_id,(select auth.uid()),
    v_title,p_starts_on,'active',p_notes
  )
  returning id into v_plan_id;

  insert into public.client_workout_assignments(
    fitness_plan_id,contact_id,workout_id,scheduled_date,status,assigned_by,notes
  )
  select
    v_plan_id,
    p_contact_id,
    pw.workout_id,
    p_starts_on + ((pw.week_number-1)*7 + (pw.day_number-1)),
    'assigned',
    (select auth.uid()),
    pw.notes
  from public.fitness_program_workouts pw
  where pw.program_id=p_program_id
  order by pw.week_number,pw.day_number;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    p_contact_id,'fitness_program_assigned','Fitness program assigned',v_title,(select auth.uid()),
    jsonb_build_object('fitness_plan_id',v_plan_id,'program_id',p_program_id,'starts_on',p_starts_on)
  );

  return v_plan_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_workout_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_membership uuid;
begin
  update public.client_workout_assignments
  set status='completed',updated_at=now()
  where id=NEW.assignment_id;

  select fp.membership_id into v_membership
  from public.client_workout_assignments wa
  join public.client_fitness_plans fp on fp.id=wa.fitness_plan_id
  where wa.id=NEW.assignment_id;

  insert into public.progress_entries(
    contact_id,membership_id,metric_key,value_numeric,recorded_at,source,created_by,metadata
  )
  values(
    NEW.contact_id,v_membership,'workouts',1,NEW.completed_at,NEW.source,NEW.created_by,
    jsonb_build_object('workout_completion_id',NEW.id,'assignment_id',NEW.assignment_id)
  );

  if NEW.duration_minutes is not null then
    insert into public.progress_entries(
      contact_id,membership_id,metric_key,value_numeric,recorded_at,source,created_by,metadata
    )
    values(
      NEW.contact_id,v_membership,'exercise_minutes',NEW.duration_minutes,NEW.completed_at,NEW.source,NEW.created_by,
      jsonb_build_object('workout_completion_id',NEW.id,'assignment_id',NEW.assignment_id)
    );
  end if;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    NEW.contact_id,'workout_completed','Workout completed',
    case when NEW.duration_minutes is not null then NEW.duration_minutes::text || ' minutes' else null end,
    NEW.created_by,
    jsonb_build_object('workout_completion_id',NEW.id,'assignment_id',NEW.assignment_id)
  );

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.update_direct_membership_access_readiness()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_journey_key text;
  v_payment_done boolean;
  v_vitality_done boolean;
begin
  if NEW.event_type not in ('payment_completed','vitality_completed','step_completed') then
    return NEW;
  end if;

  select journey_key into v_journey_key
  from public.contact_journeys
  where id=NEW.journey_id;

  if v_journey_key <> 'direct_membership' then
    return NEW;
  end if;

  select exists(
    select 1 from public.contact_journey_steps
    where journey_id=NEW.journey_id
      and step_key='payment_agreement'
      and status in ('completed','skipped','waived')
  ) into v_payment_done;

  select exists(
    select 1 from public.contact_journey_steps
    where journey_id=NEW.journey_id
      and step_key='vitality_assessment'
      and status in ('completed','skipped','waived')
  ) into v_vitality_done;

  if v_payment_done and v_vitality_done then
    update public.journey_enrollment_activations
    set access_status='active',
        updated_at=now()
    where journey_id=NEW.journey_id
      and access_status <> 'active';
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.repair_coach_conversation_participants()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_conversation_id uuid;
  v_member_user uuid;
  v_old_coach uuid;
begin
  if NEW.assigned_coach_id is null then
    return NEW;
  end if;

  select user_id into v_member_user
  from public.client_access
  where contact_id=NEW.primary_contact_id
    and status='active'
  limit 1;

  v_conversation_id := private.ensure_coach_client_conversation(
    NEW.primary_contact_id,NEW.id,v_member_user,NEW.assigned_coach_id
  );

  if v_conversation_id is null then
    return NEW;
  end if;

  if TG_OP='UPDATE' and OLD.assigned_coach_id is distinct from NEW.assigned_coach_id and OLD.assigned_coach_id is not null then
    v_old_coach := OLD.assigned_coach_id;

    update public.member_conversation_participants
    set left_at=now()
    where conversation_id=v_conversation_id
      and user_id=v_old_coach
      and left_at is null;
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_meal_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_membership uuid;
begin
  if TG_OP='UPDATE'
     and OLD.status is distinct from NEW.status
     and NEW.status='completed' then

    if NEW.completed_at is null then
      update public.client_meal_plan_items
      set completed_at=now()
      where id=NEW.id;
    end if;

    select mp.membership_id into v_membership
    from public.client_meal_plans mp
    where mp.id=NEW.meal_plan_id;

    insert into public.nutrition_logs(
      contact_id,membership_id,log_date,meal_slot,description,adherence_percent,note,source,created_by
    )
    values(
      NEW.contact_id,v_membership,NEW.scheduled_date,NEW.meal_slot,
      coalesce((select title from public.recipes where id=NEW.recipe_id),NEW.custom_title),
      coalesce(NEW.adherence_percent,100),
      NEW.notes,
      case when (select auth.uid()) is null then 'staff' else 'member' end,
      (select auth.uid())
    );

    insert into public.progress_entries(
      contact_id,membership_id,metric_key,value_numeric,recorded_at,source,created_by,metadata
    )
    values(
      NEW.contact_id,v_membership,'nutrition_adherence',
      coalesce(NEW.adherence_percent,100),
      coalesce(NEW.completed_at,now()),
      case when (select auth.uid()) is null then 'staff' else 'member' end,
      (select auth.uid()),
      jsonb_build_object('meal_plan_item_id',NEW.id)
    );
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_journey_after_step_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_journey public.contact_journeys%rowtype;
  v_next public.contact_journey_steps%rowtype;
  v_progress integer;
begin
  select * into v_journey
  from public.contact_journeys
  where id=NEW.journey_id;

  if TG_OP='UPDATE' and OLD.status is distinct from NEW.status then
    if NEW.status in ('completed','waived') and NEW.completed_at is null then
      update public.contact_journey_steps
      set completed_at=now(),updated_at=now()
      where id=NEW.id;
      NEW.completed_at := now();
    end if;

    if NEW.status in ('completed','skipped','waived') then
      insert into public.journey_events(
        contact_id,journey_id,step_id,event_type,source,actor_user_id,metadata,dedupe_key
      )
      values(
        v_journey.contact_id,NEW.journey_id,NEW.id,'step_completed',
        coalesce(NEW.completion_source,'staff'),
        (select auth.uid()),
        jsonb_build_object('step_key',NEW.step_key,'step_name',NEW.name,'status',NEW.status),
        'step-completed:' || NEW.id::text || ':' || NEW.status
      )
      on conflict (dedupe_key) do nothing;

      update public.journey_automation_jobs
      set status='cancelled',processed_at=now(),
          result=jsonb_build_object('reason','step_completed_before_job_ran')
      where journey_id=NEW.journey_id
        and status='queued'
        and payload->>'required_step_key'=NEW.step_key;
    end if;
  end if;

  select round(
    100.0 * count(*) filter (where status in ('completed','skipped','waived'))
    / nullif(count(*),0)
  )::int
  into v_progress
  from public.contact_journey_steps
  where journey_id=NEW.journey_id;

  select * into v_next
  from public.contact_journey_steps
  where journey_id=NEW.journey_id
    and required
    and status not in ('completed','skipped','waived')
  order by step_order
  limit 1;

  if not found then
    select * into v_next
    from public.contact_journey_steps
    where journey_id=NEW.journey_id
      and status not in ('completed','skipped','waived')
    order by step_order
    limit 1;
  end if;

  if v_next.id is null then
    update public.contact_journeys
    set current_step_key=null,progress_percent=100,status='completed',
        completed_at=coalesce(completed_at,now()),next_action_at=null,
        last_activity_at=now(),updated_at=now()
    where id=NEW.journey_id;
  else
    if v_next.status='pending' then
      update public.contact_journey_steps s
      set status='in_progress',
          started_at=coalesce(s.started_at,now()),
          due_at=case
            when s.due_at is null and d.default_due_hours is not null
              then now() + make_interval(hours => d.default_due_hours)
            else s.due_at
          end,
          updated_at=now()
      from public.contact_journeys j
      join public.journey_step_definitions d
        on d.journey_key=j.journey_key
       and d.step_key=v_next.step_key
      where s.id=v_next.id
        and j.id=NEW.journey_id;

      select * into v_next
      from public.contact_journey_steps
      where id=v_next.id;
    end if;

    update public.contact_journeys
    set current_step_key=v_next.step_key,
        progress_percent=coalesce(v_progress,0),
        next_action_at=v_next.due_at,
        last_activity_at=now(),
        updated_at=now()
    where id=NEW.journey_id;
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_coach_client_conversation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user_id uuid;
  v_coach_id uuid;
  v_membership_id uuid;
begin
  if TG_TABLE_NAME='client_access' then
    if NEW.status <> 'active' or NEW.user_id is null then return NEW; end if;
    v_user_id := NEW.user_id;
    v_membership_id := NEW.membership_id;
    select assigned_coach_id into v_coach_id
    from public.client_memberships where id=NEW.membership_id;
    perform private.ensure_coach_client_conversation(
      NEW.contact_id,v_membership_id,v_user_id,v_coach_id
    );
    return NEW;
  end if;

  if TG_TABLE_NAME='client_memberships' then
    if NEW.assigned_coach_id is null then return NEW; end if;
    select user_id into v_user_id
    from public.client_access
    where contact_id=NEW.primary_contact_id and status='active';
    perform private.ensure_coach_client_conversation(
      NEW.primary_contact_id,NEW.id,v_user_id,NEW.assigned_coach_id
    );
    return NEW;
  end if;

  return NEW;
end;
$function$
;

