 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  perform private.reconcile_membership_course_access(NEW.id);
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_course_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_course_id uuid;
  v_total integer;
  v_completed integer;
  v_percent integer;
begin
  select course_id into v_course_id
  from public.client_course_enrollments
  where id=NEW.enrollment_id;

  select count(*)
  into v_total
  from public.learning_lessons l
  join public.learning_modules m on m.id=l.module_id
  where m.course_id=v_course_id
    and m.active
    and l.status='published'
    and l.requires_completion;

  select count(*)
  into v_completed
  from public.lesson_progress lp
  join public.learning_lessons l on l.id=lp.lesson_id
  join public.learning_modules m on m.id=l.module_id
  where lp.enrollment_id=NEW.enrollment_id
    and m.course_id=v_course_id
    and l.requires_completion
    and lp.status='completed';

  v_percent := case
    when v_total=0 then 0
    else round(100.0*v_completed/v_total)::int
  end;

  update public.client_course_enrollments
  set progress_percent=v_percent,
      last_lesson_id=NEW.lesson_id,
      last_activity_at=coalesce(NEW.last_activity_at,now()),
      started_at=coalesce(started_at,NEW.first_started_at,now()),
      status=case when v_total>0 and v_completed>=v_total then 'completed' else status end,
      completed_at=case when v_total>0 and v_completed>=v_total then coalesce(completed_at,now()) else completed_at end,
      updated_at=now()
  where id=NEW.enrollment_id;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_published_course_to_existing_members()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if NEW.status <> 'published'
     or (TG_OP='UPDATE' and OLD.status is not distinct from NEW.status) then
    return NEW;
  end if;

  insert into public.client_course_enrollments(
    contact_id,membership_id,course_id,source,status,assigned_by
  )
  select
    cm.primary_contact_id,
    cm.id,
    NEW.id,
    'program',
    'active',
    cm.created_by
  from public.program_course_access pca
  join public.client_memberships cm
    on cm.program_code=pca.program_code
   and cm.status='active'
  where pca.course_id=NEW.id
    and pca.active
  on conflict (contact_id,course_id) do update
  set membership_id=excluded.membership_id,
      status=case when public.client_course_enrollments.status='completed' then 'completed' else 'active' end,
      updated_at=now();

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.ensure_coach_client_conversation(p_contact_id uuid, p_membership_id uuid, p_member_user_id uuid, p_coach_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_conversation_id uuid;
  v_staff_role text;
begin
  if p_contact_id is null or p_member_user_id is null or p_coach_user_id is null then
    return null;
  end if;

  select id into v_conversation_id
  from public.member_conversations
  where contact_id=p_contact_id
    and conversation_type='coach_client'
    and status='active'
  order by created_at desc
  limit 1;

  if v_conversation_id is null then
    insert into public.member_conversations(
      conversation_type,contact_id,membership_id,title,status,created_by
    )
    values(
      'coach_client',p_contact_id,p_membership_id,'Your ReVitalized Coaching Conversation',
      'active',p_coach_user_id
    )
    returning id into v_conversation_id;
  else
    update public.member_conversations
    set membership_id=coalesce(p_membership_id,membership_id),updated_at=now()
    where id=v_conversation_id;
  end if;

  insert into public.member_conversation_participants(
    conversation_id,user_id,participant_type,contact_id
  )
  values(
    v_conversation_id,p_member_user_id,'member',p_contact_id
  )
  on conflict (conversation_id,user_id) do update
  set left_at=null,participant_type='member',contact_id=p_contact_id;

  select role into v_staff_role
  from public.staff_access
  where user_id=p_coach_user_id;

  insert into public.member_conversation_participants(
    conversation_id,user_id,participant_type,contact_id
  )
  values(
    v_conversation_id,p_coach_user_id,
    case
      when v_staff_role='owner' then 'owner'
      when v_staff_role='admin' then 'admin'
      when v_staff_role='support' then 'support'
      else 'coach'
    end,
    null
  )
  on conflict (conversation_id,user_id) do update
  set left_at=null,
      participant_type=excluded.participant_type;

  return v_conversation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_program_course_to_existing_members()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_program_code text;
  v_membership_id uuid;
begin
  v_program_code := coalesce(NEW.program_code, OLD.program_code);

  for v_membership_id in
    select cm.id
    from public.client_memberships cm
    where cm.program_code = v_program_code
  loop
    perform private.reconcile_membership_course_access(v_membership_id);
  end loop;

  if TG_OP = 'UPDATE' and OLD.program_code is distinct from NEW.program_code then
    for v_membership_id in
      select cm.id
      from public.client_memberships cm
      where cm.program_code = OLD.program_code
    loop
      perform private.reconcile_membership_course_access(v_membership_id);
    end loop;
  end if;

  return coalesce(NEW, OLD);
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_member_message_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  p record;
  v_sender_name text;
begin
  update public.member_conversations
  set last_message_at=NEW.created_at,updated_at=NEW.created_at
  where id=NEW.conversation_id;

  select coalesce(sa.display_name,c.first_name,'ReVitalized Member')
  into v_sender_name
  from auth.users u
  left join public.staff_access sa on sa.user_id=u.id
  left join public.profiles pr on pr.user_id=u.id
  left join public.contacts c on c.id=pr.contact_id
  where u.id=NEW.sender_user_id;

  for p in
    select *
    from public.member_conversation_participants
    where conversation_id=NEW.conversation_id
      and user_id<>NEW.sender_user_id
      and left_at is null
      and not muted
  loop
    insert into public.member_notifications(
      user_id,contact_id,notification_type,title,body,link_url,
      source_type,source_id
    )
    values(
      p.user_id,
      p.contact_id,
      'new_message',
      'New message from ' || coalesce(v_sender_name,'ReVitalized Academy'),
      left(NEW.body,240),
      case when p.participant_type='member' then '/member/' else '/portal/' end,
      'member_message',
      NEW.id
    );
  end loop;

  return NEW;
end;
$function$
;

