CREATE OR REPLACE FUNCTION private.ensure_household_conversation(p_household_id uuid, p_membership_id uuid, p_created_by uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_conversation_id uuid;
  r record;
begin
  if p_household_id is null then
    return null;
  end if;

  select id into v_conversation_id
  from public.member_conversations
  where household_id=p_household_id
    and conversation_type='family'
    and status='active'
  order by created_at desc
  limit 1;

  if v_conversation_id is null then
    insert into public.member_conversations(
      conversation_type,household_id,membership_id,title,status,created_by
    )
    values(
      'family',p_household_id,p_membership_id,
      'Your ReVitalized Family Conversation','active',p_created_by
    )
    returning id into v_conversation_id;
  end if;

  for r in
    select distinct ca.user_id,hm.contact_id
    from public.household_members hm
    join public.client_access ca on ca.contact_id=hm.contact_id
    where hm.household_id=p_household_id
      and hm.status='active'
      and ca.user_id is not null
      and ca.status='active'
  loop
    insert into public.member_conversation_participants(
      conversation_id,user_id,participant_type,contact_id
    )
    values(v_conversation_id,r.user_id,'member',r.contact_id)
    on conflict (conversation_id,user_id) do update
    set left_at=null,participant_type='member',contact_id=excluded.contact_id;
  end loop;

  return v_conversation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_household_conversation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_household_id uuid;
  v_membership_id uuid;
begin
  if TG_TABLE_NAME='client_access' then
    if NEW.status='active' and NEW.user_id is not null and NEW.household_id is not null then
      perform private.ensure_household_conversation(
        NEW.household_id,NEW.membership_id,NEW.user_id
      );
    end if;
    return NEW;
  end if;

  if TG_TABLE_NAME='household_members' then
    v_household_id := coalesce(NEW.household_id,OLD.household_id);

    select ca.membership_id into v_membership_id
    from public.client_access ca
    where ca.household_id=v_household_id
      and ca.membership_id is not null
    order by ca.created_at
    limit 1;

    perform private.ensure_household_conversation(
      v_household_id,v_membership_id,(select auth.uid())
    );
    return coalesce(NEW,OLD);
  end if;

  return coalesce(NEW,OLD);
end;
$function$
;

CREATE OR REPLACE FUNCTION private.create_companion_review(p_request_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_request public.coach_companion_requests%rowtype;
  v_review_id uuid;
  v_coach uuid;
begin
  select * into v_request
  from public.coach_companion_requests
  where id=p_request_id;

  if v_request.id is null then
    return null;
  end if;

  select coach_user_id into v_coach
  from public.client_coach_assignments
  where contact_id=v_request.contact_id
    and role='primary'
    and status='active'
  limit 1;

  insert into public.coach_companion_reviews(
    request_id,contact_id,assigned_to,status,review_reason
  )
  values(
    v_request.id,v_request.contact_id,coalesce(v_request.assigned_coach_id,v_coach),'open',p_reason
  )
  on conflict (request_id) do update
  set assigned_to=coalesce(public.coach_companion_reviews.assigned_to,excluded.assigned_to),
      status=case when public.coach_companion_reviews.status='resolved' then 'resolved' else 'open' end,
      review_reason=excluded.review_reason,
      updated_at=now()
  returning id into v_review_id;

  update public.coach_companion_requests
  set status='coach_review',
      assigned_coach_id=coalesce(assigned_coach_id,v_coach),
      escalation_reason=p_reason,
      updated_at=now()
  where id=v_request.id;

  insert into public.follow_up_tasks(
    contact_id,assigned_to,title,due_at,status,priority,task_type,instructions
  )
  select
    v_request.contact_id,
    coalesce(v_request.assigned_coach_id,v_coach),
    'Coach Companion review needed',
    now()+interval '1 day',
    'open',
    case
      when v_request.handling_mode='block_and_escalate' then 'high'
      else 'normal'
    end,
    'review',
    'Review the member’s Coach Companion question and provide or approve an appropriate response. The AI layer did not send an autonomous answer.'
  where not exists (
    select 1 from public.follow_up_tasks t
    where t.contact_id=v_request.contact_id
      and t.title='Coach Companion review needed'
      and t.status='open'
  );

  return v_review_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.coach_companion_match_chunks(query_embedding vector, match_threshold double precision, match_count integer)
 RETURNS TABLE(chunk_id uuid, source_id uuid, source_title text, source_type text, heading text, content text, similarity double precision)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions'
AS $function$
  select *
  from private.match_coach_companion_chunks(query_embedding,match_threshold,match_count);
$function$
;

CREATE OR REPLACE FUNCTION private.recalculate_challenge_enrollment(p_enrollment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_enrollment public.challenge_enrollments%rowtype;
  v_challenge public.wellness_challenges%rowtype;
  v_value numeric := 0;
  v_percent integer := 0;
  v_points integer := 0;
  v_was_completed boolean := false;
begin
  select * into v_enrollment
  from public.challenge_enrollments
  where id=p_enrollment_id;

  if v_enrollment.id is null then return; end if;

  select * into v_challenge
  from public.wellness_challenges
  where id=v_enrollment.challenge_id;

  if v_challenge.id is null or v_challenge.goal_type<>'metric' then return; end if;

  v_was_completed := v_enrollment.status='completed';

  if v_challenge.aggregation='sum' then
    select coalesce(sum(pe.value_numeric),0) into v_value
    from public.progress_entries pe
    where pe.metric_key=v_challenge.target_key
      and pe.value_numeric is not null
      and pe.recorded_at::date between v_challenge.starts_on and v_challenge.ends_on
      and (
        (v_enrollment.scope='individual' and pe.contact_id=v_enrollment.contact_id)
        or
        (v_enrollment.scope='household' and pe.contact_id in (
          select hm.contact_id from public.household_members hm
          where hm.household_id=v_enrollment.household_id and hm.status='active'
        ))
      );
  elsif v_challenge.aggregation='count' then
    select count(*)::numeric into v_value
    from public.progress_entries pe
    where pe.metric_key=v_challenge.target_key
      and pe.recorded_at::date between v_challenge.starts_on and v_challenge.ends_on
      and (
        (v_enrollment.scope='individual' and pe.contact_id=v_enrollment.contact_id)
        or
        (v_enrollment.scope='household' and pe.contact_id in (
          select hm.contact_id from public.household_members hm
          where hm.household_id=v_enrollment.household_id and hm.status='active'
        ))
      );
  elsif v_challenge.aggregation='average' then
    select coalesce(avg(pe.value_numeric),0) into v_value
    from public.progress_entries pe
    where pe.metric_key=v_challenge.target_key
      and pe.value_numeric is not null
      and pe.recorded_at::date between v_challenge.starts_on and v_challenge.ends_on
      and (
        (v_enrollment.scope='individual' and pe.contact_id=v_enrollment.contact_id)
        or
        (v_enrollment.scope='household' and pe.contact_id in (
          select hm.contact_id from public.household_members hm
          where hm.household_id=v_enrollment.household_id and hm.status='active'
        ))
      );
  else
    select coalesce((
      select pe.value_numeric
      from public.progress_entries pe
      where pe.metric_key=v_challenge.target_key
        and pe.value_numeric is not null
        and pe.recorded_at::date between v_challenge.starts_on and v_challenge.ends_on
        and (
          (v_enrollment.scope='individual' and pe.contact_id=v_enrollment.contact_id)
          or
          (v_enrollment.scope='household' and pe.contact_id in (
            select hm.contact_id from public.household_members hm
            where hm.household_id=v_enrollment.household_id and hm.status='active'
          ))
        )
      order by pe.recorded_at desc
      limit 1
    ),0) into v_value;
  end if;

  v_percent := case
    when coalesce(v_challenge.target_value,0)<=0 then 0
    else least(100,greatest(0,round(100.0*v_value/v_challenge.target_value)::int))
  end;

  v_points := round(v_challenge.points_available * v_percent / 100.0)::int;

  update public.challenge_enrollments
  set current_value=v_value,
      completion_percent=v_percent,
      points_earned=v_points,
      status=case when v_percent>=100 then 'completed' else status end,
      completed_at=case when v_percent>=100 then coalesce(completed_at,now()) else completed_at end,
      updated_at=now()
  where id=v_enrollment.id;

  if v_percent>=100 and not v_was_completed then
    insert into public.challenge_activity(
      enrollment_id,contact_id,activity_type,value_delta,resulting_value,points_delta,source_type
    )
    values(
      v_enrollment.id,v_enrollment.contact_id,'challenge_completed',null,v_value,
      greatest(0,v_challenge.points_available-v_enrollment.points_earned),'progress_engine'
    );
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_progress_to_challenges()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  r record;
begin
  for r in
    select ce.id
    from public.challenge_enrollments ce
    join public.wellness_challenges wc on wc.id=ce.challenge_id
    where ce.status in ('active','completed')
      and wc.goal_type='metric'
      and wc.target_key=NEW.metric_key
      and NEW.recorded_at::date between wc.starts_on and wc.ends_on
      and (
        (ce.scope='individual' and ce.contact_id=NEW.contact_id)
        or
        (ce.scope='household' and ce.household_id in (
          select hm.household_id from public.household_members hm
          where hm.contact_id=NEW.contact_id and hm.status='active'
        ))
      )
  loop
    perform private.recalculate_challenge_enrollment(r.id);
  end loop;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.ensure_program_community_space(p_program_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_space_id uuid;
  v_name text;
begin
  select name into v_name
  from public.program_catalog
  where program_code=p_program_code;

  if v_name is null then return null; end if;

  insert into public.community_spaces(
    space_key,name,description,space_type,program_code,status,posting_mode
  )
  values(
    'program:'||p_program_code,
    v_name||' Community',
    'Private ReVitalized community for active '||v_name||' members.',
    'program',p_program_code,'active','staff_and_members'
  )
  on conflict (space_key) do update
  set name=excluded.name,description=excluded.description,status='active',updated_at=now()
  returning id into v_space_id;

  return v_space_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enroll_client_in_challenge(p_challenge_id uuid, p_contact_id uuid, p_scope text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_challenge public.wellness_challenges%rowtype;
  v_access public.client_access%rowtype;
  v_enrollment_id uuid;
begin
  if not exists (
    select 1 from public.staff_access s where s.user_id=(select auth.uid())
  ) then
    raise exception 'Staff access required';
  end if;

  select * into v_challenge
  from public.wellness_challenges
  where id=p_challenge_id
    and status in ('published','active');

  if v_challenge.id is null then
    raise exception 'Published challenge not found';
  end if;

  select * into v_access
  from public.client_access
  where contact_id=p_contact_id
  limit 1;

  if v_access.contact_id is null then
    raise exception 'Client access record not found';
  end if;

  if p_scope='individual' then
    if v_challenge.scope not in ('individual','both') then
      raise exception 'This challenge is not available for individual enrollment';
    end if;

    insert into public.challenge_enrollments(
      challenge_id,contact_id,household_id,membership_id,scope,status,enrolled_by
    )
    values(
      v_challenge.id,p_contact_id,null,v_access.membership_id,'individual','active',(select auth.uid())
    )
    on conflict (challenge_id,contact_id) where scope='individual' and contact_id is not null
    do update set
      status='active',
      membership_id=excluded.membership_id,
      updated_at=now()
    returning id into v_enrollment_id;

  elsif p_scope='household' then
    if v_challenge.scope not in ('household','both') then
      raise exception 'This challenge is not available for household enrollment';
    end if;

    if v_access.household_id is null then
      raise exception 'This client does not have a ReVitalized household yet';
    end if;

    insert into public.challenge_enrollments(
      challenge_id,contact_id,household_id,membership_id,scope,status,enrolled_by
    )
    values(
      v_challenge.id,null,v_access.household_id,v_access.membership_id,'household','active',(select auth.uid())
    )
    on conflict (challenge_id,household_id) where scope='household' and household_id is not null
    do update set
      status='active',
      membership_id=excluded.membership_id,
      updated_at=now()
    returning id into v_enrollment_id;
  else
    raise exception 'Challenge enrollment scope must be individual or household';
  end if;

  perform private.recalculate_challenge_enrollment(v_enrollment_id);

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    p_contact_id,'challenge_enrolled','Challenge enrolled',v_challenge.title,(select auth.uid()),
    jsonb_build_object('challenge_id',v_challenge.id,'enrollment_id',v_enrollment_id,'scope',p_scope)
  );

  return v_enrollment_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_member_community_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user uuid;
  v_space uuid;
  v_household_space uuid;
begin
  if NEW.status<>'active' then return NEW; end if;

  select ca.user_id into v_user
  from public.client_access ca
  where ca.contact_id=NEW.primary_contact_id and ca.status='active';

  if v_user is null then return NEW; end if;

  v_space := private.ensure_program_community_space(NEW.program_code);

  if v_space is not null then
    insert into public.community_memberships(space_id,user_id,contact_id,membership_role,status)
    values(v_space,v_user,NEW.primary_contact_id,'member','active')
    on conflict (space_id,user_id) do update set
      contact_id=excluded.contact_id,status='active',left_at=null;
  end if;

  if NEW.household_id is not null then
    insert into public.community_spaces(
      space_key,name,description,space_type,household_id,status,posting_mode,created_by
    )
    select
      'household:'||NEW.household_id::text,
      coalesce(h.household_name,'ReVitalized Household'),
      'Private ReVitalized family space.',
      'household',NEW.household_id,'active','members',NEW.created_by
    from public.households h
    where h.id=NEW.household_id
    on conflict (space_key) do update set status='active',updated_at=now()
    returning id into v_household_space;

    insert into public.community_memberships(space_id,user_id,contact_id,membership_role,status)
    values(v_household_space,v_user,NEW.primary_contact_id,'owner','active')
    on conflict (space_id,user_id) do update set
      contact_id=excluded.contact_id,membership_role='owner',status='active',left_at=null;
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_member_community_access_record(p_membership_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  m public.client_memberships%rowtype;
  v_user uuid;
  v_space uuid;
  v_household_space uuid;
begin
  select * into m from public.client_memberships where id=p_membership_id;
  if m.id is null or m.status<>'active' then return; end if;

  select ca.user_id into v_user
  from public.client_access ca
  where ca.contact_id=m.primary_contact_id and ca.status='active';

  if v_user is null then return; end if;

  v_space := private.ensure_program_community_space(m.program_code);
  if v_space is not null then
    insert into public.community_memberships(space_id,user_id,contact_id,membership_role,status)
    values(v_space,v_user,m.primary_contact_id,'member','active')
    on conflict (space_id,user_id) do update set contact_id=excluded.contact_id,status='active',left_at=null;
  end if;

  if m.household_id is not null then
    insert into public.community_spaces(
      space_key,name,description,space_type,household_id,status,posting_mode,created_by
    )
    select
      'household:'||m.household_id::text,
      coalesce(h.household_name,'ReVitalized Household'),
      'Private ReVitalized family space.',
      'household',m.household_id,'active','members',m.created_by
    from public.households h where h.id=m.household_id
    on conflict (space_key) do update set status='active',updated_at=now()
    returning id into v_household_space;

    insert into public.community_memberships(space_id,user_id,contact_id,membership_role,status)
    values(v_household_space,v_user,m.primary_contact_id,'owner','active')
    on conflict (space_id,user_id) do update set contact_id=excluded.contact_id,membership_role='owner',status='active',left_at=null;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_access_to_community()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if NEW.status='active' and NEW.user_id is not null and NEW.membership_id is not null then
    perform private.sync_member_community_access_record(NEW.membership_id);
  end if;
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.moderate_community_post(p_post_id uuid, p_action text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_post public.community_posts%rowtype;
  v_status text;
begin
  if not exists (
    select 1 from public.staff_access s
    where s.user_id=(select auth.uid())
      and s.role in ('owner','admin','coach')
  ) then
    raise exception 'Owner/Admin/Coach access required';
  end if;

  if p_action not in ('hide_post','remove_post','restore_post') then
    raise exception 'Invalid moderation action';
  end if;

  if trim(coalesce(p_reason,''))='' then
    raise exception 'Moderation reason is required';
  end if;

  select * into v_post from public.community_posts where id=p_post_id;
  if v_post.id is null then raise exception 'Post not found'; end if;

  v_status := case
    when p_action='hide_post' then 'hidden'
    when p_action='remove_post' then 'removed'
    else 'published'
  end;

  update public.community_posts
  set status=v_status,updated_at=now()
  where id=p_post_id;

  insert into public.community_moderation_events(
    space_id,post_id,action,reason,actor_user_id
  )
  values(v_post.space_id,v_post.id,p_action,trim(p_reason),(select auth.uid()));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.toggle_community_post_pin(p_post_id uuid, p_pinned boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists (
    select 1 from public.staff_access s
    where s.user_id=(select auth.uid())
      and s.role in ('owner','admin','coach')
  ) then
    raise exception 'Owner/Admin/Coach access required';
  end if;

  update public.community_posts
  set pinned=p_pinned,updated_at=now()
  where id=p_post_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.invite_contact_to_refuel(p_contact_id uuid, p_offer_id uuid, p_channel text, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_invitation_id uuid;
  v_offer public.refuel_offers%rowtype;
begin
  if not exists (
    select 1 from public.staff_access s where s.user_id=(select auth.uid())
  ) then
    raise exception 'Staff access required';
  end if;

  if p_channel not in ('email','sms','in_app','manual') then
    raise exception 'Invalid invitation channel';
  end if;

  select * into v_offer
  from public.refuel_offers
  where id=p_offer_id and status='published';

  if v_offer.id is null then
    raise exception 'Published ReFuel offer not found';
  end if;

  insert into public.refuel_invitations(
    contact_id,offer_id,status,invitation_channel,invited_by,invited_at,note
  )
  values(
    p_contact_id,p_offer_id,
    case when p_channel='manual' then 'sent' else 'queued' end,
    p_channel,(select auth.uid()),
    case when p_channel='manual' then now() else null end,
    p_note
  )
  on conflict (contact_id,offer_id) do update
  set status=case
        when public.refuel_invitations.status in ('accepted','declined') then public.refuel_invitations.status
        else excluded.status
      end,
      invitation_channel=excluded.invitation_channel,
      invited_by=excluded.invited_by,
      invited_at=coalesce(public.refuel_invitations.invited_at,excluded.invited_at),
      note=excluded.note,
      updated_at=now()
  returning id into v_invitation_id;

  update public.refuel_interest
  set status='notified',updated_at=now()
  where contact_id=p_contact_id
    and status='interested';

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    p_contact_id,'refuel_invited','ReFuel invitation created',v_offer.name,
    (select auth.uid()),
    jsonb_build_object('offer_id',p_offer_id,'invitation_id',v_invitation_id,'channel',p_channel)
  );

  return v_invitation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enroll_contact_in_refuel(p_contact_id uuid, p_offer_id uuid, p_payment_status text DEFAULT 'pending'::text, p_amount_cents integer DEFAULT NULL::integer, p_currency text DEFAULT 'USD'::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_offer public.refuel_offers%rowtype;
  v_access public.client_access%rowtype;
  v_invitation_id uuid;
  v_enrollment_id uuid;
  v_status text;
begin
  if not exists (
    select 1 from public.staff_access s
    where s.user_id=(select auth.uid())
      and s.role in ('owner','admin')
  ) then
    raise exception 'Owner/Admin access required';
  end if;

  if p_payment_status not in ('pending','paid','included','waived','failed','refunded') then
    raise exception 'Invalid ReFuel payment status';
  end if;

  select * into v_offer
  from public.refuel_offers
  where id=p_offer_id and status='published';

  if v_offer.id is null then
    raise exception 'Published ReFuel offer not found';
  end if;

  select * into v_access
  from public.client_access
  where contact_id=p_contact_id
  limit 1;

  select id into v_invitation_id
  from public.refuel_invitations
  where contact_id=p_contact_id and offer_id=p_offer_id
  limit 1;

  v_status := case
    when p_payment_status in ('paid','included','waived') then 'active'
    else 'pending'
  end;

  insert into public.refuel_enrollments(
    contact_id,membership_id,offer_id,invitation_id,status,payment_status,
    amount_cents,currency,enrolled_by,activated_at,notes
  )
  values(
    p_contact_id,v_access.membership_id,p_offer_id,v_invitation_id,v_status,p_payment_status,
    coalesce(p_amount_cents,v_offer.price_cents),coalesce(p_currency,v_offer.currency),
    (select auth.uid()),
    case when v_status='active' then now() else null end,
    p_notes
  )
  on conflict (contact_id,offer_id) do update
  set membership_id=excluded.membership_id,
      invitation_id=coalesce(excluded.invitation_id,public.refuel_enrollments.invitation_id),
      status=excluded.status,
      payment_status=excluded.payment_status,
      amount_cents=excluded.amount_cents,
      currency=excluded.currency,
      enrolled_by=excluded.enrolled_by,
      activated_at=case
        when excluded.status='active' then coalesce(public.refuel_enrollments.activated_at,now())
        else public.refuel_enrollments.activated_at
      end,
      notes=excluded.notes
  returning id into v_enrollment_id;

  if v_invitation_id is not null then
    update public.refuel_invitations
    set status='accepted',responded_at=coalesce(responded_at,now()),updated_at=now()
    where id=v_invitation_id;
  end if;

  update public.refuel_interest
  set status='converted',updated_at=now()
  where contact_id=p_contact_id;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    p_contact_id,'refuel_enrolled','ReFuel enrollment updated',v_offer.name,
    (select auth.uid()),
    jsonb_build_object(
      'offer_id',p_offer_id,'enrollment_id',v_enrollment_id,
      'payment_status',p_payment_status,'status',v_status
    )
  );

  return v_enrollment_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.notify_refuel_invitation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user uuid;
  v_offer_name text;
begin
  if NEW.status not in ('queued','sent') then return NEW; end if;

  select ca.user_id into v_user
  from public.client_access ca
  where ca.contact_id=NEW.contact_id and ca.status='active'
  limit 1;

  select name into v_offer_name
  from public.refuel_offers where id=NEW.offer_id;

  if v_user is not null and NEW.invitation_channel='in_app' then
    insert into public.member_notifications(
      user_id,contact_id,notification_type,title,body,link_url,source_type,source_id
    )
    values(
      v_user,NEW.contact_id,'program_update',
      'You have a ReFuel invitation',
      'A ReFuel opportunity is available for you inside ReVitalized Academy.',
      '/member/','refuel_invitation',NEW.id
    );
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.trg_evaluate_engagement_achievements()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
begin
  v_contact_id := coalesce(new.contact_id,old.contact_id);
  perform private.evaluate_engagement_achievements(v_contact_id);
  return coalesce(new,old);
end;
$function$
;

CREATE OR REPLACE FUNCTION private.staff_has_permission(p_user_id uuid, p_permission_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
  select case
    when exists(
      select 1
      from public.staff_access sa
      where sa.user_id=p_user_id
        and sa.status='active'
        and sa.role='coach'
        and sa.onboarding_status='pending'
    ) then false
    else coalesce(
      (
        select spo.allowed
        from public.staff_permission_overrides spo
        where spo.user_id=p_user_id
          and spo.permission_key=p_permission_key
      ),
      (
        select srpd.allowed
        from public.staff_access sa
        join public.staff_role_permission_defaults srpd
          on srpd.role=sa.role
         and srpd.permission_key=p_permission_key
        where sa.user_id=p_user_id
          and sa.status='active'
      ),
      false
    )
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.my_staff_permissions()
 RETURNS TABLE(permission_key text, allowed boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
  select pc.permission_key,
         private.staff_has_permission((select auth.uid()),pc.permission_key)
  from public.staff_permission_catalog pc
  where pc.active
  order by pc.sort_order;
$function$
;

CREATE OR REPLACE FUNCTION private.evaluate_engagement_achievements(p_contact_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_membership_id uuid;
  v_checkins integer;
  v_challenges integer;
  v_courses integer;
begin
  select ca.membership_id
    into v_membership_id
  from public.client_access ca
  where ca.contact_id=p_contact_id
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  select count(*)::integer
    into v_checkins
  from public.habit_checkins hc
  where hc.contact_id=p_contact_id;

  select count(*)::integer
    into v_challenges
  from public.challenge_enrollments ce
  where ce.contact_id=p_contact_id
    and ce.status='completed';

  select count(*)::integer
    into v_courses
  from public.client_course_enrollments cce
  where cce.contact_id=p_contact_id
    and cce.status='completed';

  if v_checkins >= 1 then
    insert into public.member_achievements(contact_id,membership_id,achievement_key,source_type)
    values(p_contact_id,v_membership_id,'first_checkin','habit_checkin')
    on conflict(contact_id,achievement_key) do nothing;
  end if;

  if v_checkins >= 7 then
    insert into public.member_achievements(contact_id,membership_id,achievement_key,source_type)
    values(p_contact_id,v_membership_id,'seven_checkins','habit_checkin')
    on conflict(contact_id,achievement_key) do nothing;
  end if;

  if v_checkins >= 30 then
    insert into public.member_achievements(contact_id,membership_id,achievement_key,source_type)
    values(p_contact_id,v_membership_id,'thirty_checkins','habit_checkin')
    on conflict(contact_id,achievement_key) do nothing;
  end if;

  if v_challenges >= 1 then
    insert into public.member_achievements(contact_id,membership_id,achievement_key,source_type)
    values(p_contact_id,v_membership_id,'first_challenge_complete','challenge')
    on conflict(contact_id,achievement_key) do nothing;
  end if;

  if v_courses >= 1 then
    insert into public.member_achievements(contact_id,membership_id,achievement_key,source_type)
    values(p_contact_id,v_membership_id,'first_course_complete','course')
    on conflict(contact_id,achievement_key) do nothing;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.ensure_referral_profile(p_contact_id uuid, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_id uuid;
  v_code text;
  v_name text;
begin
  select id into v_id
  from public.referral_profiles
  where contact_id=p_contact_id;

  if v_id is not null then
    update public.referral_profiles
    set user_id=coalesce(p_user_id,user_id),updated_at=now()
    where id=v_id;
    return v_id;
  end if;

  select trim(concat_ws(' ',first_name,last_name)) into v_name
  from public.contacts where id=p_contact_id;

  v_code := 'RVA-' || upper(substr(replace(p_contact_id::text,'-',''),1,10));

  insert into public.referral_profiles(
    contact_id,user_id,referral_code,status,display_name
  )
  values(p_contact_id,p_user_id,v_code,'active',nullif(v_name,''))
  returning id into v_id;

  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_referral_profile_from_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if NEW.status='active' and NEW.user_id is not null then
    perform private.ensure_referral_profile(NEW.contact_id,NEW.user_id);
  end if;
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_referral_status_from_contact()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  r record;
  p public.referral_programs%rowtype;
begin
  if TG_OP='UPDATE' and OLD.lifecycle_stage is not distinct from NEW.lifecycle_stage then
    return NEW;
  end if;

  if NEW.lifecycle_stage='applicant' then
    update public.referrals
    set status='applicant',updated_at=now()
    where referred_contact_id=NEW.id
      and status in ('referred','engaged');
  elsif NEW.lifecycle_stage='client' then
    update public.referrals
    set status='converted',
        converted_at=coalesce(converted_at,now()),
        updated_at=now()
    where referred_contact_id=NEW.id
      and status not in ('converted','cancelled','ineligible');

    for r in
      select *
      from public.referrals
      where referred_contact_id=NEW.id
        and status='converted'
        and referrer_contact_id is not null
    loop
      if r.referral_program_id is not null then
        select * into p
        from public.referral_programs
        where id=r.referral_program_id
          and status='published';

        if p.id is not null and coalesce(p.reward_type,'none')<>'none' then
          insert into public.referral_rewards(
            referral_id,referrer_contact_id,reward_type,reward_value,currency,status
          )
          select
            r.id,r.referrer_contact_id,p.reward_type,p.reward_value,p.currency,'pending'
          where not exists(
            select 1 from public.referral_rewards rr where rr.referral_id=r.id
          );
        end if;
      end if;
    end loop;
  elsif NEW.lifecycle_stage in ('assessment_lead','webinar_lead') then
    update public.referrals
    set status='engaged',updated_at=now()
    where referred_contact_id=NEW.id
      and status='referred';
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_referral_reward_status(p_reward_id uuid, p_status text, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not private.staff_has_permission((select auth.uid()),'referrals.manage') then
    raise exception 'Referral management permission required';
  end if;

  if p_status not in ('pending','approved','issued','cancelled') then
    raise exception 'Invalid reward status';
  end if;

  update public.referral_rewards
  set
    status=p_status,
    approved_by=case when p_status in ('approved','issued') then (select auth.uid()) else approved_by end,
    approved_at=case when p_status in ('approved','issued') then coalesce(approved_at,now()) else approved_at end,
    issued_at=case when p_status='issued' then coalesce(issued_at,now()) else issued_at end,
    notes=coalesce(nullif(trim(p_notes),''),notes)
  where id=p_reward_id;

  if not found then raise exception 'Referral reward not found'; end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.bulk_update_people(p_contact_ids uuid[], p_action text, p_value text, p_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_count integer := 0;
  v_id uuid;
  v_staff uuid;
begin
  if not private.staff_has_permission((select auth.uid()),'crm.manage') then
    raise exception 'CRM management permission required';
  end if;

  if p_contact_ids is null or array_length(p_contact_ids,1) is null then
    return 0;
  end if;

  if p_action='assign_staff' then
    v_staff := nullif(p_value,'')::uuid;
    update public.contacts
    set assigned_to=v_staff,updated_at=now()
    where id=any(p_contact_ids);
    get diagnostics v_count=row_count;

  elsif p_action='set_stage' then
    if p_value not in ('lead','assessment_lead','webinar_lead','applicant','client','inactive') then
      raise exception 'Invalid lifecycle stage';
    end if;
    update public.contacts
    set lifecycle_stage=p_value,updated_at=now()
    where id=any(p_contact_ids);
    get diagnostics v_count=row_count;

  elsif p_action='set_followup_status' then
    if p_value not in ('new','needs_follow_up','contacted','consultation_scheduled','consultation_completed','nurture','not_ready','closed') then
      raise exception 'Invalid follow-up status';
    end if;
    update public.contacts
    set follow_up_status=p_value,updated_at=now()
    where id=any(p_contact_ids);
    get diagnostics v_count=row_count;

  elsif p_action='add_tag' then
    if nullif(trim(p_value),'') is null then raise exception 'Tag is required'; end if;
    foreach v_id in array p_contact_ids loop
      insert into public.contact_tags(contact_id,tag,source,rule_key,updated_at)
      values(v_id,lower(trim(p_value)),'manual','bulk-people',now())
      on conflict (contact_id,tag) do update set updated_at=now();
      v_count:=v_count+1;
    end loop;

  else
    raise exception 'Invalid bulk People action';
  end if;

  foreach v_id in array p_contact_ids loop
    insert into public.contact_activity(
      contact_id,activity_type,title,detail,actor_user_id,metadata
    )
    values(
      v_id,'bulk_people_update','People record updated in bulk',
      coalesce(nullif(trim(p_reason),''),'Bulk People Directory action'),
      (select auth.uid()),
      jsonb_build_object('action',p_action,'value',p_value)
    );
  end loop;

  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_team_calendar_item(p_item_type text, p_item_id uuid, p_status text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_contact_id uuid;
  v_title text;
begin
  if p_status not in ('scheduled','completed','cancelled','no_show') then
    raise exception 'Invalid schedule status';
  end if;

  if p_item_type='journey_appointment' then
    if not private.staff_has_permission((select auth.uid()),'crm.manage') then
      raise exception 'CRM management permission required';
    end if;

    update public.journey_appointments
    set status=p_status,
        completed_at=case when p_status='completed' then coalesce(completed_at,now()) else completed_at end,
        updated_at=now()
    where id=p_item_id
    returning contact_id,appointment_type into v_contact_id,v_title;

  elsif p_item_type='coaching_session' then
    if not private.staff_has_permission((select auth.uid()),'coaching.manage') then
      raise exception 'Coaching management permission required';
    end if;

    update public.coaching_sessions
    set status=p_status,
        completed_at=case when p_status='completed' then coalesce(completed_at,now()) else completed_at end,
        updated_at=now()
    where id=p_item_id
    returning contact_id,'coaching_session' into v_contact_id,v_title;

  else
    raise exception 'Invalid calendar item type';
  end if;

  if v_contact_id is null then raise exception 'Calendar item not found'; end if;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    v_contact_id,
    'schedule_status_updated',
    'Schedule status updated',
    coalesce(nullif(trim(p_reason),''),initcap(replace(v_title,'_',' '))||' → '||initcap(replace(p_status,'_',' '))),
    (select auth.uid()),
    jsonb_build_object('item_type',p_item_type,'item_id',p_item_id,'status',p_status)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION private.queue_upcoming_appointment_reminders()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  r record;
  v_count integer:=0;
  v_title text;
  v_body text;
  v_source_type text;
begin
  -- Journey appointments: 24-hour reminders.
  for r in
    select
      ja.id as source_id,
      ja.contact_id,
      ca.user_id,
      ja.appointment_type,
      ja.scheduled_start,
      ja.format
    from public.journey_appointments ja
    join public.client_access ca on ca.contact_id=ja.contact_id
    where ca.status='active'
      and ca.user_id is not null
      and ja.status='scheduled'
      and ja.scheduled_start between now()+interval '23 hours 45 minutes'
                                 and now()+interval '24 hours 15 minutes'
  loop
    v_title:='ReVitalized appointment reminder';
    v_body:='Your '||initcap(replace(r.appointment_type,'_',' '))||
      ' is scheduled for '||to_char(r.scheduled_start at time zone 'UTC','Mon DD at HH12:MI AM')||
      ' UTC'||
      case when r.format is not null then ' · '||initcap(r.format) else '' end||'.';
    v_source_type:='journey_appointment_24h';

    insert into public.member_notifications(
      user_id,contact_id,notification_type,title,body,link_url,source_type,source_id
    )
    values(
      r.user_id,r.contact_id,'appointment_reminder',v_title,v_body,
      '/member/',v_source_type,r.source_id
    )
    on conflict (user_id,notification_type,source_type,source_id)
      where source_id is not null
    do nothing;

    if found then v_count:=v_count+1; end if;
  end loop;

  -- Journey appointments: 2-hour reminders.
  for r in
    select
      ja.id as source_id,
      ja.contact_id,
      ca.user_id,
      ja.appointment_type,
      ja.scheduled_start,
      ja.format
    from public.journey_appointments ja
    join public.client_access ca on ca.contact_id=ja.contact_id
    where ca.status='active'
      and ca.user_id is not null
      and ja.status='scheduled'
      and ja.scheduled_start between now()+interval '1 hour 45 minutes'
                                 and now()+interval '2 hours 15 minutes'
  loop
    v_title:='Your ReVitalized appointment is coming up';
    v_body:='Your '||initcap(replace(r.appointment_type,'_',' '))||
      ' starts in about 2 hours.';
    v_source_type:='journey_appointment_2h';

    insert into public.member_notifications(
      user_id,contact_id,notification_type,title,body,link_url,source_type,source_id
    )
    values(
      r.user_id,r.contact_id,'appointment_reminder',v_title,v_body,
      '/member/',v_source_type,r.source_id
    )
    on conflict (user_id,notification_type,source_type,source_id)
      where source_id is not null
    do nothing;

    if found then v_count:=v_count+1; end if;
  end loop;

  -- Coaching sessions: 24-hour and 2-hour reminders.
  for r in
    select
      cs.id as source_id,
      cs.contact_id,
      ca.user_id,
      cs.scheduled_start,
      cs.format,
      '24h'::text as reminder_window
    from public.coaching_sessions cs
    join public.client_access ca on ca.contact_id=cs.contact_id
    where ca.status='active'
      and ca.user_id is not null
      and cs.status='scheduled'
      and cs.scheduled_start between now()+interval '23 hours 45 minutes'
                                 and now()+interval '24 hours 15 minutes'
    union all
    select
      cs.id,cs.contact_id,ca.user_id,cs.scheduled_start,cs.format,'2h'
    from public.coaching_sessions cs
    join public.client_access ca on ca.contact_id=cs.contact_id
    where ca.status='active'
      and ca.user_id is not null
      and cs.status='scheduled'
      and cs.scheduled_start between now()+interval '1 hour 45 minutes'
                                 and now()+interval '2 hours 15 minutes'
  loop
    if r.reminder_window='24h' then
      v_title:='ReVitalized coaching reminder';
      v_body:='Your coaching session is scheduled for '||
        to_char(r.scheduled_start at time zone 'UTC','Mon DD at HH12:MI AM')||
        ' UTC'||
        case when r.format is not null then ' · '||initcap(r.format) else '' end||'.';
      v_source_type:='coaching_session_24h';
    else
      v_title:='Your ReVitalized coaching session is coming up';
      v_body:='Your coaching session starts in about 2 hours.';
      v_source_type:='coaching_session_2h';
    end if;

    insert into public.member_notifications(
      user_id,contact_id,notification_type,title,body,link_url,source_type,source_id
    )
    values(
      r.user_id,r.contact_id,'coaching_reminder',v_title,v_body,
      '/member/',v_source_type,r.source_id
    )
    on conflict (user_id,notification_type,source_type,source_id)
      where source_id is not null
    do nothing;

    if found then v_count:=v_count+1; end if;
  end loop;

  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.apply_billing_event_to_subscription()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  s public.membership_subscriptions%rowtype;
  p public.billing_plans%rowtype;
begin
  select * into s from public.membership_subscriptions where id=NEW.subscription_id;
  if s.id is null then return NEW; end if;

  select * into p from public.billing_plans where id=s.billing_plan_id;

  if NEW.event_type='payment_succeeded' then
    update public.membership_subscriptions
    set status='active',
        failed_payment_count=0,
        grace_period_ends_at=null,
        last_payment_at=NEW.occurred_at,
        last_payment_amount_cents=NEW.amount_cents,
        next_charge_at=case
          when p.billing_interval='weekly' then NEW.occurred_at + (p.interval_count||' week')::interval
          when p.billing_interval='monthly' then NEW.occurred_at + (p.interval_count||' month')::interval
          else next_charge_at
        end,
        updated_at=now()
    where id=s.id;

  elsif NEW.event_type='payment_failed' then
    update public.membership_subscriptions
    set status='past_due',
        failed_payment_count=failed_payment_count+1,
        last_failure_at=NEW.occurred_at,
        grace_period_ends_at=coalesce(grace_period_ends_at,NEW.occurred_at + coalesce(p.grace_days,3)*interval '1 day'),
        updated_at=now()
    where id=s.id;

  elsif NEW.event_type='subscription_cancelled' then
    update public.membership_subscriptions
    set status='cancelled',
        cancelled_at=coalesce(cancelled_at,NEW.occurred_at),
        updated_at=now()
    where id=s.id;

  elsif NEW.event_type='subscription_completed' then
    update public.membership_subscriptions
    set status='completed',
        ended_at=coalesce(ended_at,NEW.occurred_at),
        next_charge_at=null,
        updated_at=now()
    where id=s.id;

  elsif NEW.event_type='subscription_paused' then
    update public.membership_subscriptions
    set status='paused',updated_at=now()
    where id=s.id;

  elsif NEW.event_type='subscription_resumed' then
    update public.membership_subscriptions
    set status='active',updated_at=now()
    where id=s.id;
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.staff_can_view_document_category(p_category text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
  select case p_category
    when 'general' then private.staff_has_permission((select auth.uid()),'crm.view')
    when 'coaching' then private.staff_has_permission((select auth.uid()),'coaching.view')
    when 'health' then private.staff_has_permission((select auth.uid()),'health.private.view')
    when 'progress' then private.staff_has_permission((select auth.uid()),'health.private.view')
    when 'financial' then private.staff_has_permission((select auth.uid()),'finance.view')
    when 'agreement' then private.staff_has_permission((select auth.uid()),'finance.view')
    else false
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_membership_subscription(p_membership_id uuid, p_billing_plan_id uuid, p_provider text DEFAULT NULL::text, p_provider_customer_id text DEFAULT NULL::text, p_provider_subscription_id text DEFAULT NULL::text, p_status text DEFAULT 'pending'::text, p_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_next_charge_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  m public.client_memberships%rowtype;
  p public.billing_plans%rowtype;
  v_id uuid;
  v_start timestamptz;
  v_commit_end timestamptz;
begin
  if not private.staff_has_permission((select auth.uid()),'finance.manage') then
    raise exception 'Financial management permission required';
  end if;

  if p_status not in ('pending','trialing','active','past_due','paused','cancelled','completed') then
    raise exception 'Invalid subscription status';
  end if;

  select * into m from public.client_memberships where id=p_membership_id;
  if m.id is null then raise exception 'Membership not found'; end if;

  select * into p from public.billing_plans where id=p_billing_plan_id and active;
  if p.id is null then raise exception 'Active billing plan not found'; end if;

  v_start:=coalesce(p_started_at,m.starts_at,now());
  v_commit_end:=case
    when p.commitment_months is not null then v_start+(p.commitment_months||' month')::interval
    else m.commitment_ends_at
  end;

  insert into public.membership_subscriptions(
    membership_id,contact_id,billing_plan_id,provider,provider_customer_id,
    provider_subscription_id,status,started_at,next_charge_at,
    commitment_ends_at,created_by
  )
  values(
    m.id,m.primary_contact_id,p.id,nullif(trim(p_provider),''),
    nullif(trim(p_provider_customer_id),''),
    nullif(trim(p_provider_subscription_id),''),
    p_status,v_start,p_next_charge_at,v_commit_end,(select auth.uid())
  )
  on conflict (membership_id) do update
  set billing_plan_id=excluded.billing_plan_id,
      provider=coalesce(excluded.provider,public.membership_subscriptions.provider),
      provider_customer_id=coalesce(excluded.provider_customer_id,public.membership_subscriptions.provider_customer_id),
      provider_subscription_id=coalesce(excluded.provider_subscription_id,public.membership_subscriptions.provider_subscription_id),
      status=excluded.status,
      started_at=coalesce(public.membership_subscriptions.started_at,excluded.started_at),
      next_charge_at=excluded.next_charge_at,
      commitment_ends_at=excluded.commitment_ends_at,
      updated_at=now()
  returning id into v_id;

  update public.client_memberships
  set billing_choice=p.billing_interval,
      amount_cents=p.amount_cents,
      currency=p.currency,
      commitment_months=coalesce(p.commitment_months,commitment_months),
      commitment_ends_at=coalesce(v_commit_end,commitment_ends_at),
      updated_at=now()
  where id=m.id;

  insert into public.billing_events(
    subscription_id,membership_id,contact_id,event_type,provider,status,occurred_at,recorded_by
  )
  values(
    v_id,m.id,m.primary_contact_id,'subscription_created',
    nullif(trim(p_provider),''),p_status,now(),(select auth.uid())
  );

  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.handle_billing_failure_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user uuid;
  v_assignee uuid;
  v_sub public.membership_subscriptions%rowtype;
  v_plan public.billing_plans%rowtype;
  v_due timestamptz;
begin
  if NEW.event_type<>'payment_failed' then return NEW; end if;

  select * into v_sub from public.membership_subscriptions where id=NEW.subscription_id;
  select * into v_plan from public.billing_plans where id=v_sub.billing_plan_id;

  v_due:=coalesce(v_sub.grace_period_ends_at,NEW.occurred_at+coalesce(v_plan.grace_days,3)*interval '1 day');

  select ca.user_id into v_user
  from public.client_access ca
  where ca.contact_id=NEW.contact_id
    and ca.status='active'
    and ca.user_id is not null
  limit 1;

  if v_user is not null then
    insert into public.member_notifications(
      user_id,contact_id,notification_type,title,body,link_url,source_type,source_id
    )
    values(
      v_user,NEW.contact_id,'billing_alert',
      'Membership payment needs attention',
      'We were unable to process your ReVitalized membership payment. Please review your billing information or contact the ReVitalized team before the grace period ends.',
      '/member/','billing_payment_failure',NEW.id
    )
    on conflict (user_id,notification_type,source_type,source_id)
      where source_id is not null
    do nothing;
  end if;

  select sa.user_id into v_assignee
  from public.staff_access sa
  where sa.status='active'
    and private.staff_has_permission(sa.user_id,'finance.manage')
  order by
    case sa.role when 'financial' then 1 when 'owner' then 2 when 'admin' then 3 else 4 end,
    sa.created_at
  limit 1;

  if not exists(
    select 1 from public.follow_up_tasks t
    where t.contact_id=NEW.contact_id
      and t.title='Resolve past-due membership payment'
      and t.status='open'
  ) then
    insert into public.follow_up_tasks(
      contact_id,assigned_to,title,due_at,status,priority,task_type,instructions
    )
    values(
      NEW.contact_id,v_assignee,'Resolve past-due membership payment',
      v_due,'open','high','billing',
      'Review the failed membership payment, contact the client if needed, and resolve billing before the grace period ends.'
    );
  end if;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,metadata
  )
  values(
    NEW.contact_id,'billing_payment_failed','Membership payment failed',
    'Billing recovery workflow started.',
    jsonb_build_object('billing_event_id',NEW.id,'subscription_id',NEW.subscription_id,'grace_period_ends_at',v_due)
  );

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.hash_agreement_template()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions'
AS $function$
begin
  NEW.content_hash:=encode(digest(convert_to(NEW.content_text,'UTF8'),'sha256'),'hex');
  NEW.updated_at:=now();
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.prevent_published_agreement_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if OLD.status='published'
     and (
       OLD.content_text is distinct from NEW.content_text
       or OLD.version is distinct from NEW.version
       or OLD.agreement_key is distinct from NEW.agreement_key
     ) then
    raise exception 'Published agreement content/version is immutable. Create a new version instead.';
  end if;
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.issue_required_agreements_for_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  r record;
begin
  if NEW.status not in ('pending','active') then return NEW; end if;

  for r in
    select at.id,at.agreement_key,at.version,at.content_hash
    from public.program_agreement_requirements par
    join public.agreement_templates at on at.id=par.agreement_template_id
    where par.program_code=NEW.program_code
      and par.active
      and par.required
      and at.status='published'
    order by par.sort_order
  loop
    insert into public.client_agreements(
      contact_id,membership_id,activation_id,agreement_template_id,
      agreement_key,template_version,content_hash,status,created_by
    )
    values(
      NEW.primary_contact_id,NEW.id,NEW.activation_id,r.id,
      r.agreement_key,r.version,r.content_hash,'not_sent',NEW.created_by
    )
    on conflict (contact_id,agreement_template_id) do update
    set membership_id=excluded.membership_id,
        activation_id=coalesce(excluded.activation_id,public.client_agreements.activation_id),
        updated_at=now();
  end loop;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_client_agreement_to_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_pending integer;
  v_declined integer;
begin
  if NEW.activation_id is null then return NEW; end if;

  select
    count(*) filter (where ca.status not in ('signed','waived')),
    count(*) filter (where ca.status='declined')
  into v_pending,v_declined
  from public.client_agreements ca
  where ca.activation_id=NEW.activation_id;

  if v_declined>0 then
    update public.journey_enrollment_activations
    set agreement_status='declined',updated_at=now()
    where id=NEW.activation_id;
  elsif v_pending=0 then
    update public.journey_enrollment_activations
    set agreement_status='signed',
        agreement_signed_at=coalesce(agreement_signed_at,now()),
        agreement_completion_method=coalesce(agreement_completion_method,'revitalized_esign'),
        updated_at=now()
    where id=NEW.activation_id;
  else
    update public.journey_enrollment_activations
    set agreement_status=case
      when exists(select 1 from public.client_agreements x where x.activation_id=NEW.activation_id and x.status in ('sent','viewed')) then 'sent'
      else 'not_sent'
    end,
    updated_at=now()
    where id=NEW.activation_id;
  end if;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.backfill_program_agreement_requirement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  m record;
  t public.agreement_templates%rowtype;
begin
  if not NEW.active or not NEW.required then return NEW; end if;

  select * into t
  from public.agreement_templates
  where id=NEW.agreement_template_id
    and status='published';

  if t.id is null then return NEW; end if;

  for m in
    select cm.*
    from public.client_memberships cm
    where cm.program_code=NEW.program_code
      and cm.status in ('pending','active')
  loop
    insert into public.client_agreements(
      contact_id,membership_id,activation_id,agreement_template_id,
      agreement_key,template_version,content_hash,status,created_by
    )
    values(
      m.primary_contact_id,m.id,m.activation_id,t.id,
      t.agreement_key,t.version,t.content_hash,'not_sent',m.created_by
    )
    on conflict (contact_id,agreement_template_id) do update
    set membership_id=excluded.membership_id,
        activation_id=coalesce(excluded.activation_id,public.client_agreements.activation_id),
        updated_at=now();
  end loop;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.backfill_agreement_requirement_record(p_requirement_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  r public.program_agreement_requirements%rowtype;
  t public.agreement_templates%rowtype;
  m record;
begin
  select * into r from public.program_agreement_requirements where id=p_requirement_id;
  if r.id is null or not r.active or not r.required then return; end if;

  select * into t from public.agreement_templates where id=r.agreement_template_id and status='published';
  if t.id is null then return; end if;

  for m in
    select cm.*
    from public.client_memberships cm
    where cm.program_code=r.program_code
      and cm.status in ('pending','active')
  loop
    insert into public.client_agreements(
      contact_id,membership_id,activation_id,agreement_template_id,
      agreement_key,template_version,content_hash,status,created_by
    )
    values(
      m.primary_contact_id,m.id,m.activation_id,t.id,
      t.agreement_key,t.version,t.content_hash,'not_sent',m.created_by
    )
    on conflict (contact_id,agreement_template_id) do update
    set membership_id=excluded.membership_id,
        activation_id=coalesce(excluded.activation_id,public.client_agreements.activation_id),
        updated_at=now();
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.issue_client_agreement(p_contact_id uuid, p_agreement_template_id uuid, p_send boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t public.agreement_templates%rowtype;
  m public.client_memberships%rowtype;
  a public.client_agreements%rowtype;
  v_user uuid;
begin
  if not private.staff_has_permission((select auth.uid()),'finance.manage') then
    raise exception 'Financial management permission required';
  end if;

  select * into t
  from public.agreement_templates
  where id=p_agreement_template_id
    and status='published';

  if t.id is null then raise exception 'Published agreement template not found'; end if;

  select * into m
  from public.client_memberships
  where primary_contact_id=p_contact_id
  order by created_at desc
  limit 1;

  if m.id is null then raise exception 'Client membership not found'; end if;

  insert into public.client_agreements(
    contact_id,membership_id,activation_id,agreement_template_id,
    agreement_key,template_version,content_hash,status,sent_at,created_by
  )
  values(
    p_contact_id,m.id,m.activation_id,t.id,t.agreement_key,t.version,t.content_hash,
    case when p_send then 'sent' else 'not_sent' end,
    case when p_send then now() else null end,
    (select auth.uid())
  )
  on conflict (contact_id,agreement_template_id) do update
  set membership_id=excluded.membership_id,
      activation_id=coalesce(excluded.activation_id,public.client_agreements.activation_id),
      status=case
        when public.client_agreements.status in ('signed','waived') then public.client_agreements.status
        when p_send then 'sent'
        else public.client_agreements.status
      end,
      sent_at=case
        when public.client_agreements.status in ('signed','waived') then public.client_agreements.sent_at
        when p_send then now()
        else public.client_agreements.sent_at
      end,
      updated_at=now()
  returning * into a;

  if p_send and a.status='sent' then
    select ca.user_id into v_user
    from public.client_access ca
    where ca.contact_id=p_contact_id and ca.status='active' and ca.user_id is not null
    limit 1;

    if v_user is not null then
      insert into public.member_notifications(
        user_id,contact_id,notification_type,title,body,link_url,source_type,source_id
      )
      values(
        v_user,p_contact_id,'program_update',
        'Agreement ready for your review',
        t.name||' is ready to review and sign in your ReVitalized member dashboard.',
        '/member/','client_agreement',a.id
      )
      on conflict (user_id,notification_type,source_type,source_id)
        where source_id is not null
      do nothing;
    end if;
  end if;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    p_contact_id,
    case when p_send then 'agreement_sent' else 'agreement_assigned' end,
    case when p_send then 'Agreement sent' else 'Agreement assigned' end,
    t.name||' · v'||t.version,
    (select auth.uid()),
    jsonb_build_object('client_agreement_id',a.id,'template_id',t.id)
  );

  return a.id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_my_notification_preferences(p_preferences jsonb)
 RETURNS notification_preferences
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_tz text;
  v_result public.notification_preferences%rowtype;
begin
  if p_preferences is null or jsonb_typeof(p_preferences) <> 'object' then
    raise exception 'Preferences must be a JSON object';
  end if;

  v_tz := nullif(trim(p_preferences->>'time_zone'),'');
  if v_tz is not null
     and not exists(select 1 from pg_timezone_names where name=v_tz) then
    raise exception 'Invalid time zone';
  end if;

  insert into public.notification_preferences(user_id)
  values((select auth.uid()))
  on conflict (user_id) do nothing;

  update public.notification_preferences np
  set
    in_app_messages = coalesce((p_preferences->>'in_app_messages')::boolean,np.in_app_messages),
    email_messages = coalesce((p_preferences->>'email_messages')::boolean,np.email_messages),
    sms_messages = coalesce((p_preferences->>'sms_messages')::boolean,np.sms_messages),
    email_coaching_reminders = coalesce((p_preferences->>'email_coaching_reminders')::boolean,np.email_coaching_reminders),
    sms_coaching_reminders = coalesce((p_preferences->>'sms_coaching_reminders')::boolean,np.sms_coaching_reminders),
    email_program_updates = coalesce((p_preferences->>'email_program_updates')::boolean,np.email_program_updates),
    sms_program_updates = coalesce((p_preferences->>'sms_program_updates')::boolean,np.sms_program_updates),
    email_billing_alerts = coalesce((p_preferences->>'email_billing_alerts')::boolean,np.email_billing_alerts),
    sms_billing_alerts = coalesce((p_preferences->>'sms_billing_alerts')::boolean,np.sms_billing_alerts),
    quiet_hours_enabled = coalesce((p_preferences->>'quiet_hours_enabled')::boolean,np.quiet_hours_enabled),
    quiet_hours_start = case
      when p_preferences ? 'quiet_hours_start'
      then nullif(p_preferences->>'quiet_hours_start','')::time
      else np.quiet_hours_start
    end,
    quiet_hours_end = case
      when p_preferences ? 'quiet_hours_end'
      then nullif(p_preferences->>'quiet_hours_end','')::time
      else np.quiet_hours_end
    end,
    time_zone = case
      when p_preferences ? 'time_zone' then v_tz
      else np.time_zone
    end,
    updated_at = now()
  where np.user_id=(select auth.uid())
  returning * into v_result;

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_my_meal_item(p_item_id uuid, p_status text, p_adherence_percent numeric DEFAULT NULL::numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if p_status not in ('planned','completed','skipped','substituted') then
    raise exception 'Unsupported meal status';
  end if;

  if p_adherence_percent is not null
     and (p_adherence_percent<0 or p_adherence_percent>100) then
    raise exception 'Adherence must be between 0 and 100';
  end if;

  update public.client_meal_plan_items mi
  set status=p_status,
      adherence_percent=p_adherence_percent,
      completed_at=case
        when p_status='completed' then coalesce(mi.completed_at,now())
        when p_status in ('planned','skipped','substituted') then null
        else mi.completed_at
      end
  where mi.id=p_item_id
    and mi.contact_id in (
      select ca.contact_id
      from public.client_access ca
      where ca.user_id=(select auth.uid())
    );

  return found;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_my_workout_status(p_assignment_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if p_status not in ('assigned','completed','skipped','cancelled') then
    raise exception 'Unsupported workout status';
  end if;

  update public.client_workout_assignments wa
  set status=p_status,
      notes=case when p_note is not null then nullif(trim(p_note),'') else wa.notes end,
      updated_at=now()
  where wa.id=p_assignment_id
    and wa.contact_id in (
      select ca.contact_id
      from public.client_access ca
      where ca.user_id=(select auth.uid())
    );

  return found;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_my_assignment(p_assignment_id uuid, p_status text, p_member_note text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if p_status not in ('assigned','in_progress','completed') then
    raise exception 'Unsupported assignment status';
  end if;

  update public.client_assignments a
  set status=p_status,
      member_note=case
        when p_member_note is not null then nullif(trim(p_member_note),'')
        else a.member_note
      end,
      completed_at=case
        when p_status='completed' then coalesce(a.completed_at,now())
        else null
      end,
      updated_at=now()
  where a.id=p_assignment_id
    and a.contact_id in (
      select ca.contact_id
      from public.client_access ca
      where ca.user_id=(select auth.uid())
    );

  return found;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.waive_client_agreement(p_client_agreement_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  a public.client_agreements%rowtype;
  v_role text;
begin
  select role into v_role
  from public.staff_access
  where user_id=(select auth.uid())
    and status='active';

  if v_role not in ('owner','admin') then
    raise exception 'Only Owner/Admin can waive a client agreement';
  end if;

  if nullif(trim(p_reason),'') is null then
    raise exception 'Waiver reason is required';
  end if;

  select * into a from public.client_agreements where id=p_client_agreement_id;
  if a.id is null then raise exception 'Client agreement not found'; end if;
  if a.status='signed' then raise exception 'Signed agreements cannot be waived'; end if;

  update public.client_agreements
  set status='waived',
      waived_at=now(),
      waived_by=(select auth.uid()),
      waiver_reason=trim(p_reason),
      updated_at=now()
  where id=a.id;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    a.contact_id,'agreement_waived','Agreement requirement waived',
    trim(p_reason),(select auth.uid()),
    jsonb_build_object('client_agreement_id',a.id)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION private.recalculate_coaching_entitlement_used_value(p_membership_id uuid, p_entitlement_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  update public.membership_entitlements me
  set used_value=coalesce((
        select sum(ceu.usage_units)
        from public.coaching_entitlement_usage ceu
        where ceu.membership_id=p_membership_id
          and ceu.entitlement_key=p_entitlement_key
          and ceu.status='consumed'
      ),0),
      updated_at=now()
  where me.membership_id=p_membership_id
    and me.entitlement_key=p_entitlement_key;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_coaching_session_entitlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_entitlement_id uuid;
  v_new_status text;
  v_review_reason text;
begin
  if NEW.membership_id is null then
    return NEW;
  end if;

  select id into v_entitlement_id
  from public.membership_entitlements
  where membership_id=NEW.membership_id
    and entitlement_key='private_coaching'
    and status='active'
  limit 1;

  -- The ledger can still track a session when there is not yet a numeric limit.
  if NEW.status='scheduled' then
    v_new_status:='reserved';
  elsif NEW.status='completed' then
    v_new_status:='consumed';
  elsif NEW.status='cancelled' then
    v_new_status:='released';
  elsif NEW.status='no_show' then
    v_new_status:='review';
    v_review_reason:='No-show requires staff determination before consuming or releasing an entitlement.';
  else
    return NEW;
  end if;

  insert into public.coaching_entitlement_usage(
    membership_id,entitlement_id,coaching_session_id,contact_id,
    entitlement_key,usage_units,status,reserved_at,consumed_at,released_at,review_reason
  )
  values(
    NEW.membership_id,v_entitlement_id,NEW.id,NEW.contact_id,
    'private_coaching',1,v_new_status,
    case when v_new_status='reserved' then coalesce(NEW.created_at,now()) else null end,
    case when v_new_status='consumed' then coalesce(NEW.completed_at,now()) else null end,
    case when v_new_status='released' then now() else null end,
    v_review_reason
  )
  on conflict (coaching_session_id) do update
  set entitlement_id=coalesce(excluded.entitlement_id,public.coaching_entitlement_usage.entitlement_id),
      status=excluded.status,
      reserved_at=case
        when excluded.status='reserved' then coalesce(public.coaching_entitlement_usage.reserved_at,now())
        else public.coaching_entitlement_usage.reserved_at
      end,
      consumed_at=case when excluded.status='consumed' then coalesce(public.coaching_entitlement_usage.consumed_at,now()) else null end,
      released_at=case when excluded.status='released' then coalesce(public.coaching_entitlement_usage.released_at,now()) else null end,
      review_reason=excluded.review_reason,
      updated_at=now();

  perform private.recalculate_coaching_entitlement_used_value(NEW.membership_id,'private_coaching');

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.notify_member_challenge_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user_id uuid;
  v_title text;
begin
  if NEW.status<>'completed' or NEW.contact_id is null then
    return NEW;
  end if;

  if TG_OP='UPDATE' and OLD.status='completed' then
    return NEW;
  end if;

  select ca.user_id
  into v_user_id
  from public.client_access ca
  where ca.contact_id=NEW.contact_id
    and ca.user_id is not null
  limit 1;

  if v_user_id is null then
    return NEW;
  end if;

  select wc.title
  into v_title
  from public.wellness_challenges wc
  where wc.id=NEW.challenge_id;

  insert into public.member_notifications(
    user_id,contact_id,notification_type,title,body,status,source_type,source_id
  )
  values(
    v_user_id,
    NEW.contact_id,
    'challenge_completed',
    'Challenge completed',
    coalesce(v_title,'You completed a ReVitalized challenge.'),
    'unread',
    'challenge',
    NEW.challenge_id
  )
  on conflict (user_id,notification_type,source_type,source_id)
    where source_id is not null
  do nothing;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.send_my_message(p_conversation_id uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_id uuid;
begin
  if coalesce(length(trim(p_body)),0)<1 or length(trim(p_body))>8000 then
    raise exception 'Message must be between 1 and 8000 characters';
  end if;

  if not private.current_user_is_conversation_participant(p_conversation_id) then
    raise exception 'Conversation is not available';
  end if;

  select ca.contact_id
  into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
  limit 1;

  insert into public.member_messages(
    conversation_id,sender_user_id,sender_contact_id,body,message_type
  )
  values(
    p_conversation_id,(select auth.uid()),v_contact_id,trim(p_body),'text'
  )
  returning id into v_id;

  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.resolve_coaching_entitlement_review(p_usage_id uuid, p_resolution text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  u public.coaching_entitlement_usage%rowtype;
begin
  if not private.staff_has_permission((select auth.uid()),'coaching.manage') then
    raise exception 'Coaching management permission required';
  end if;

  if p_resolution not in ('consumed','released') then
    raise exception 'Resolution must be consumed or released';
  end if;

  if nullif(trim(p_reason),'') is null then
    raise exception 'Resolution reason is required';
  end if;

  select * into u from public.coaching_entitlement_usage where id=p_usage_id;
  if u.id is null then raise exception 'Entitlement usage record not found'; end if;

  update public.coaching_entitlement_usage
  set status=p_resolution,
      consumed_at=case when p_resolution='consumed' then now() else null end,
      released_at=case when p_resolution='released' then now() else null end,
      review_reason=trim(p_reason),
      updated_by=(select auth.uid()),
      updated_at=now()
  where id=u.id;

  perform private.recalculate_coaching_entitlement_used_value(u.membership_id,u.entitlement_key);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.import_people_batch(p_rows jsonb, p_filename text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_batch_id uuid;
  v_row jsonb;
  v_index integer:=0;
  v_total integer:=0;
  v_created integer:=0;
  v_updated integer:=0;
  v_skipped integer:=0;
  v_errors integer:=0;
  v_error_list jsonb:='[]'::jsonb;
  v_contact_id uuid;
  v_email text;
  v_phone text;
  v_phone_digits text;
  v_stage text;
  v_source text;
  v_first text;
  v_last text;
  v_city text;
  v_state text;
  v_country text;
  v_tags text[];
  v_tag text;
begin
  if not private.staff_has_permission((select auth.uid()),'people.import') then
    raise exception 'People import permission required';
  end if;

  if jsonb_typeof(p_rows)<>'array' then
    raise exception 'Import rows must be a JSON array';
  end if;

  v_total:=jsonb_array_length(p_rows);
  if v_total>5000 then
    raise exception 'A single import is limited to 5,000 rows';
  end if;

  insert into public.people_import_batches(uploaded_by,filename,total_rows)
  values((select auth.uid()),nullif(trim(p_filename),''),v_total)
  returning id into v_batch_id;

  for v_row in select * from jsonb_array_elements(p_rows)
  loop
    v_index:=v_index+1;
    begin
      v_first:=nullif(trim(coalesce(v_row->>'first_name','')),'');
      v_last:=nullif(trim(coalesce(v_row->>'last_name','')),'');
      v_email:=nullif(lower(trim(coalesce(v_row->>'email',''))),'');
      v_phone:=nullif(trim(coalesce(v_row->>'phone','')),'');
      v_city:=nullif(trim(coalesce(v_row->>'city','')),'');
      v_state:=nullif(trim(coalesce(v_row->>'state','')),'');
      v_country:=nullif(trim(coalesce(v_row->>'country','')),'');
      v_stage:=coalesce(nullif(trim(v_row->>'lifecycle_stage'),''),'lead');
      v_source:=coalesce(nullif(trim(v_row->>'source'),''),'csv_import');

      if v_first is null and v_last is null then
        raise exception 'First name or last name is required';
      end if;
      if v_email is null and v_phone is null then
        raise exception 'Email or phone is required';
      end if;
      if v_stage not in ('lead','assessment_lead','webinar_lead','applicant','client','inactive') then
        raise exception 'Invalid lifecycle stage: %',v_stage;
      end if;

      v_contact_id:=null;

      if v_email is not null then
        select id into v_contact_id
        from public.contacts
        where lower(email)=v_email
        limit 1;
      end if;

      if v_contact_id is null and v_phone is not null then
        v_phone_digits:=regexp_replace(v_phone,'[^0-9]','','g');
        select id into v_contact_id
        from public.contacts
        where phone is not null
          and regexp_replace(phone,'[^0-9]','','g')=v_phone_digits
        limit 1;
      end if;

      if v_contact_id is null then
        insert into public.contacts(
          first_name,last_name,email,phone,city,state,country,lifecycle_stage,
          first_source,last_source,follow_up_status,consultation_status,record_kind
        )
        values(
          v_first,v_last,v_email,v_phone,v_city,v_state,v_country,v_stage,
          v_source,v_source,'new','not_scheduled','crm'
        )
        returning id into v_contact_id;
        v_created:=v_created+1;
      else
        update public.contacts
        set first_name=coalesce(v_first,first_name),
            last_name=coalesce(v_last,last_name),
            email=coalesce(v_email,email),
            phone=coalesce(v_phone,phone),
            city=coalesce(v_city,city),
            state=coalesce(v_state,state),
            country=coalesce(v_country,country),
            lifecycle_stage=case when record_kind='crm' then v_stage else lifecycle_stage end,
            last_source=v_source,
            updated_at=now()
        where id=v_contact_id;
        v_updated:=v_updated+1;
      end if;

      if jsonb_typeof(v_row->'tags')='array' then
        select array_agg(value) into v_tags
        from jsonb_array_elements_text(v_row->'tags');
      else
        v_tags:=string_to_array(coalesce(v_row->>'tags',''),',');
      end if;

      if v_tags is not null then
        foreach v_tag in array v_tags loop
          if nullif(trim(v_tag),'') is not null then
            insert into public.contact_tags(contact_id,tag,source,rule_key,updated_at)
            values(v_contact_id,lower(trim(v_tag)),'csv_import','csv-import',now())
            on conflict (contact_id,tag) do update set updated_at=now();
          end if;
        end loop;
      end if;

      insert into public.contact_activity(
        contact_id,activity_type,title,detail,actor_user_id,metadata
      )
      values(
        v_contact_id,'csv_imported','People record imported',
        coalesce(nullif(trim(p_filename),''),'CSV import'),
        (select auth.uid()),
        jsonb_build_object('batch_id',v_batch_id,'row_number',v_index)
      );

    exception when others then
      v_errors:=v_errors+1;
      v_error_list:=v_error_list||jsonb_build_array(jsonb_build_object(
        'row',v_index,'error',sqlerrm,'data',v_row
      ));
    end;
  end loop;

  update public.people_import_batches
  set created_rows=v_created,
      updated_rows=v_updated,
      skipped_rows=v_skipped,
      error_rows=v_errors,
      errors=v_error_list,
      status=case when v_errors=0 then 'completed' else 'completed_with_errors' end,
      completed_at=now()
  where id=v_batch_id;

  return jsonb_build_object(
    'batch_id',v_batch_id,
    'total_rows',v_total,
    'created_rows',v_created,
    'updated_rows',v_updated,
    'skipped_rows',v_skipped,
    'error_rows',v_errors,
    'errors',v_error_list
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION private.render_agreement_content(p_template text, p_values jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_result text:=coalesce(p_template,'');
  r record;
begin
  for r in
    select key,value
    from jsonb_each_text(coalesce(p_values,'{}'::jsonb))
  loop
    v_result:=replace(v_result,'{{'||r.key||'}}',coalesce(r.value,''));
  end loop;
  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.log_people_export(p_row_count integer, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not private.staff_has_permission((select auth.uid()),'people.export') then
    raise exception 'People export permission required';
  end if;

  insert into public.staff_access_audit(
    staff_user_id,action,actor_user_id,previous_value,new_value,reason
  )
  values(
    (select auth.uid()),
    'people_csv_exported',
    (select auth.uid()),
    '{}'::jsonb,
    jsonb_build_object('row_count',greatest(coalesce(p_row_count,0),0),'filters',coalesce(p_filters,'{}'::jsonb)),
    'People Directory CSV export'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION private.validate_agreement_merge_values(p_schema jsonb, p_values jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_field text;
begin
  for v_field in
    select jsonb_array_elements_text(coalesce(p_schema->'required','[]'::jsonb))
  loop
    if nullif(trim(coalesce(p_values->>v_field,'')),'') is null then
      raise exception 'Required contract field is missing: %',v_field;
    end if;
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_program_challenge_to_existing_members()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_program_code text;
  v_membership_id uuid;
begin
  v_program_code:=coalesce(NEW.program_code,OLD.program_code);

  for v_membership_id in
    select cm.id
    from public.client_memberships cm
    where cm.program_code=v_program_code
  loop
    perform private.reconcile_membership_challenge_access(v_membership_id);
  end loop;

  if TG_OP='UPDATE' and OLD.program_code is distinct from NEW.program_code then
    for v_membership_id in
      select cm.id
      from public.client_memberships cm
      where cm.program_code=OLD.program_code
    loop
      perform private.reconcile_membership_challenge_access(v_membership_id);
    end loop;
  end if;

  return coalesce(NEW,OLD);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.prepare_client_contract(p_contact_id uuid, p_agreement_template_id uuid, p_merge_values jsonb, p_send boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t public.agreement_templates%rowtype;
  m public.client_memberships%rowtype;
  a public.client_agreements%rowtype;
  v_rendered text;
  v_hash text;
  v_user uuid;
  v_required_signatures integer:=1;
begin
  if not private.staff_has_permission((select auth.uid()),'finance.manage') then
    raise exception 'Financial management permission required';
  end if;

  select * into t
  from public.agreement_templates
  where id=p_agreement_template_id
    and status='published'
    and audience='client';

  if t.id is null then raise exception 'Published client agreement template not found'; end if;

  perform private.validate_agreement_merge_values(t.merge_schema,p_merge_values);

  select * into m
  from public.client_memberships
  where primary_contact_id=p_contact_id
  order by created_at desc
  limit 1;

  if m.id is null then raise exception 'Client membership not found'; end if;

  v_rendered:=private.render_agreement_content(t.content_text,p_merge_values);
  v_hash:=encode(extensions.digest(convert_to(v_rendered,'UTF8'),'sha256'),'hex');

  if nullif(trim(coalesce(p_merge_values->>'secondary_client_name','')),'') is not null then
    v_required_signatures:=2;
  end if;

  insert into public.client_agreements(
    contact_id,membership_id,activation_id,agreement_template_id,
    agreement_key,template_version,content_hash,status,sent_at,created_by,
    merge_values,rendered_content_text,rendered_content_hash,
    company_approved_by,company_approved_at,company_approver_name,
    required_client_signatures
  )
  values(
    p_contact_id,m.id,m.activation_id,t.id,t.agreement_key,t.version,t.content_hash,
    case when p_send then 'sent' else 'not_sent' end,
    case when p_send then now() else null end,
    (select auth.uid()),
    coalesce(p_merge_values,'{}'::jsonb),v_rendered,v_hash,
    (select auth.uid()),now(),
    (select display_name from public.staff_access where user_id=(select auth.uid())),
    v_required_signatures
  )
  on conflict (contact_id,agreement_template_id) do update
  set membership_id=excluded.membership_id,
      activation_id=coalesce(excluded.activation_id,public.client_agreements.activation_id),
      merge_values=excluded.merge_values,
      rendered_content_text=excluded.rendered_content_text,
      rendered_content_hash=excluded.rendered_content_hash,
      required_client_signatures=excluded.required_client_signatures,
      company_approved_by=excluded.company_approved_by,
      company_approved_at=excluded.company_approved_at,
      company_approver_name=excluded.company_approver_name,
      status=case
        when public.client_agreements.status in ('signed','waived') then public.client_agreements.status
        when p_send then 'sent'
        else 'not_sent'
      end,
      sent_at=case
        when public.client_agreements.status in ('signed','waived') then public.client_agreements.sent_at
        when p_send then now()
        else null
      end,
      updated_at=now()
  returning * into a;

  if p_send and a.status='sent' then
    select ca.user_id into v_user
    from public.client_access ca
    where ca.contact_id=p_contact_id and ca.status='active' and ca.user_id is not null
    limit 1;

    if v_user is not null then
      insert into public.member_notifications(
        user_id,contact_id,notification_type,title,body,link_url,source_type,source_id
      )
      values(
        v_user,p_contact_id,'program_update',
        'Your ReVitalized Academy contract is ready',
        'Your personalized ReVitalized Academy contract is ready to review and sign.',
        '/member/','client_contract',a.id
      )
      on conflict (user_id,notification_type,source_type,source_id)
        where source_id is not null
      do nothing;
    end if;
  end if;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    p_contact_id,
    case when p_send then 'client_contract_sent' else 'client_contract_prepared' end,
    case when p_send then 'Client contract sent' else 'Client contract prepared' end,
    t.name||' · v'||t.version,
    (select auth.uid()),
    jsonb_build_object(
      'client_agreement_id',a.id,
      'template_id',t.id,
      'merge_values',p_merge_values
    )
  );

  return a.id;
end;
$function$
;

