CREATE OR REPLACE FUNCTION private.notify_client_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user_id uuid;
begin
  if NEW.status<>'assigned' then return NEW; end if;

  if TG_OP='UPDATE'
     and OLD.status='assigned'
     and OLD.title=NEW.title
     and OLD.due_at is not distinct from NEW.due_at then
    return NEW;
  end if;

  select ca.user_id
  into v_user_id
  from public.client_access ca
  where ca.contact_id=NEW.contact_id
    and ca.user_id is not null
  limit 1;

  if v_user_id is null then return NEW; end if;

  insert into public.member_notifications(
    user_id,contact_id,notification_type,title,body,status,source_type,source_id
  )
  values(
    v_user_id,
    NEW.contact_id,
    'assignment_available',
    'New coaching assignment',
    NEW.title,
    'unread',
    'assignment',
    NEW.id
  )
  on conflict (user_id,notification_type,source_type,source_id)
    where source_id is not null
  do update set
    title=excluded.title,
    body=excluded.body,
    status='unread',
    read_at=null,
    created_at=now();

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.staff_can_access_contact(p_user_id uuid, p_contact_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
  select exists(
    select 1
    from public.staff_access sa
    where sa.user_id=p_user_id
      and sa.status='active'
      and private.staff_has_permission(p_user_id,'crm.view')
      and (
        sa.contact_scope='all'
        or (
          sa.contact_scope='assigned'
          and (
            exists(
              select 1 from public.contacts c
              where c.id=p_contact_id and c.assigned_to=p_user_id
            )
            or exists(
              select 1 from public.client_coach_assignments cca
              where cca.contact_id=p_contact_id
                and cca.coach_user_id=p_user_id
                and cca.status='active'
            )
            or exists(
              select 1 from public.follow_up_tasks t
              where t.contact_id=p_contact_id
                and t.assigned_to=p_user_id
                and t.status='open'
            )
          )
        )
      )
  );
$function$
;

