CREATE OR REPLACE FUNCTION private.reconcile_membership_entitlements(p_membership_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_program_code text;
  v_status text;
begin
  select cm.program_code, cm.status
  into v_program_code, v_status
  from public.client_memberships cm
  where cm.id = p_membership_id;

  if v_program_code is null then
    return;
  end if;

  update public.membership_entitlements me
  set status = 'inactive',
      updated_at = now()
  where me.membership_id = p_membership_id
    and (
      v_status not in ('active','pending')
      or not exists (
        select 1
        from public.program_entitlement_templates pet
        where pet.program_code = v_program_code
          and pet.entitlement_key = me.entitlement_key
          and pet.active
      )
    );

  if v_status in ('active','pending') then
    insert into public.membership_entitlements(
      membership_id, entitlement_key, label, status, limit_value,
      reset_cadence, metadata, updated_at
    )
    select
      p_membership_id,
      pet.entitlement_key,
      pet.label,
      'active',
      pet.limit_value,
      pet.reset_cadence,
      pet.metadata,
      now()
    from public.program_entitlement_templates pet
    where pet.program_code = v_program_code
      and pet.active
    on conflict (membership_id, entitlement_key) do update
    set label = excluded.label,
        status = 'active',
        limit_value = excluded.limit_value,
        reset_cadence = excluded.reset_cadence,
        metadata = excluded.metadata,
        updated_at = now();
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_membership_entitlements()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  perform private.reconcile_membership_entitlements(NEW.id);
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_entitlement_template_to_memberships()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_program_code text;
  v_membership_id uuid;
begin
  v_program_code := coalesce(NEW.program_code, OLD.program_code);

  for v_membership_id in
    select cm.id
    from public.client_memberships cm
    where cm.program_code = v_program_code
  loop
    perform private.reconcile_membership_entitlements(v_membership_id);
  end loop;

  return coalesce(NEW, OLD);
end;
$function$
;

CREATE OR REPLACE FUNCTION private.reconcile_membership_course_access(p_membership_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_program_code text;
  v_membership_status text;
  v_created_by uuid;
begin
  select cm.primary_contact_id, cm.program_code, cm.status, cm.created_by
  into v_contact_id, v_program_code, v_membership_status, v_created_by
  from public.client_memberships cm
  where cm.id = p_membership_id;

  if v_contact_id is null then
    return;
  end if;

  update public.client_course_enrollments cce
  set status = 'cancelled',
      updated_at = now()
  where cce.membership_id = p_membership_id
    and cce.source = 'program'
    and cce.status in ('active','paused')
    and (
      v_membership_status <> 'active'
      or not exists (
        select 1
        from public.program_course_access pca
        join public.learning_courses lc
          on lc.id = pca.course_id
         and lc.status = 'published'
        where pca.program_code = v_program_code
          and pca.course_id = cce.course_id
          and pca.active
      )
    );

  if v_membership_status = 'active' then
    insert into public.client_course_enrollments(
      contact_id,membership_id,course_id,source,status,assigned_by,updated_at
    )
    select
      v_contact_id,
      p_membership_id,
      pca.course_id,
      'program',
      'active',
      v_created_by,
      now()
    from public.program_course_access pca
    join public.learning_courses lc
      on lc.id = pca.course_id
     and lc.status = 'published'
    where pca.program_code = v_program_code
      and pca.active
    on conflict (contact_id,course_id) do update
    set membership_id = excluded.membership_id,
        status = case
          when public.client_course_enrollments.status='completed' then 'completed'
          else 'active'
        end,
        source = case
          when public.client_course_enrollments.source in ('coach','manual') then public.client_course_enrollments.source
          else 'program'
        end,
        updated_at = now();
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.notify_member_course_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user_id uuid;
  v_title text;
begin
  if NEW.status <> 'active' then
    return NEW;
  end if;

  if TG_OP='UPDATE'
     and OLD.status='active'
     and OLD.course_id=NEW.course_id
     and OLD.membership_id is not distinct from NEW.membership_id then
    return NEW;
  end if;

  select ca.user_id
  into v_user_id
  from public.client_access ca
  where ca.contact_id=NEW.contact_id
    and ca.user_id is not null
  limit 1;

  if v_user_id is null then
    return NEW;
  end if;

  select lc.title
  into v_title
  from public.learning_courses lc
  where lc.id=NEW.course_id;

  insert into public.member_notifications(
    user_id,contact_id,notification_type,title,body,status,source_type,source_id
  )
  values(
    v_user_id,
    NEW.contact_id,
    'course_available',
    'New course available',
    coalesce(v_title,'A new ReVitalized course is ready for you.'),
    'unread',
    'course',
    NEW.course_id
  )
  on conflict do nothing;

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.notify_member_access_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_program_name text;
begin
  if NEW.status <> 'active' or NEW.user_id is null then
    return NEW;
  end if;

  if TG_OP='UPDATE'
     and OLD.status='active'
     and OLD.user_id is not distinct from NEW.user_id then
