  )
  values(
    NEW.user_id,
    NEW.contact_id,
    'account_active',
    'Welcome to ReVitalized Academy',
    case
      when v_program_name is not null then 'Your '||v_program_name||' access is active.'
      else 'Your ReVitalized Academy access is active.'
    end,
    'unread',
    'membership',
    NEW.membership_id
  )
  on conflict do nothing;

  return NEW;
end;
$function$
;

