CREATE OR REPLACE FUNCTION private.notify_member_appointment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user_id uuid;
  v_title text;
  v_body text;
begin
  if NEW.status <> 'scheduled' or NEW.scheduled_start is null then
    return NEW;
  end if;

  select ca.user_id
  into v_user_id
  from public.client_access ca
  where ca.contact_id=NEW.contact_id
    and ca.user_id is not null
  limit 1;

  if v_user_id is null then
    return NEW;
  end if;

  v_title := case NEW.appointment_type
    when 'coaching_session' then 'Coaching session scheduled'
    when 'consultation' then 'Consultation scheduled'
    when 'application_interview' then 'Interview scheduled'
    else 'Appointment scheduled'
  end;

  v_body := 'Your appointment is scheduled for ' ||
            to_char(NEW.scheduled_start at time zone coalesce(NEW.time_zone,'UTC'),
                    'Mon FMDD, YYYY at FMHH12:MI AM');

  insert into public.member_notifications(
    user_id,contact_id,notification_type,title,body,link_url,status,source_type,source_id
  )
  values(
    v_user_id,
    NEW.contact_id,
    'appointment_scheduled',
    v_title,
    v_body,
    NEW.location_url,
    'unread',
    'appointment',
    NEW.id
  )
  on conflict (user_id,notification_type,source_type,source_id)
    where source_id is not null
  do update set
    title=excluded.title,
    body=excluded.body,
    link_url=excluded.link_url,
    status='unread',
    read_at=null,
    created_at=now();

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.notify_program_resource_members(p_resource_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_title text;
begin
  select rl.title
  into v_title
  from public.resource_library rl
  where rl.id=p_resource_id
    and rl.status='published';

  if v_title is null then
    return;
  end if;

  insert into public.member_notifications(
    user_id,contact_id,notification_type,title,body,status,source_type,source_id
  )
  select distinct
    ca.user_id,
    ca.contact_id,
    'resource_available',
    'New resource available',
    v_title,
    'unread',
    'resource',
    p_resource_id
  from public.program_resource_access pra
  join public.client_memberships cm
    on cm.program_code=pra.program_code
   and cm.status='active'
  join public.client_access ca
    on ca.membership_id=cm.id
   and ca.status='active'
   and ca.user_id is not null
  where pra.resource_id=p_resource_id
    and pra.active
  on conflict (user_id,notification_type,source_type,source_id)
    where source_id is not null
  do nothing;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.notify_program_resource_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if NEW.active then
    perform private.notify_program_resource_members(NEW.resource_id);
  end if;
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.notify_resource_publish()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if NEW.status='published'
     and (TG_OP='INSERT' or OLD.status is distinct from NEW.status) then
