CREATE OR REPLACE FUNCTION private.notify_billing_invoice_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user_id uuid;
  v_title text;
  v_body text;
  v_amount text;
begin
  if NEW.status not in ('open','paid','uncollectible','refunded') then
    return NEW;
  end if;

  if TG_OP='UPDATE' and OLD.status=NEW.status then
    return NEW;
