  where ca.contact_id=NEW.contact_id
    and ca.user_id is not null
  limit 1;

  if v_user_id is null then
    return NEW;
  end if;

  v_amount := trim(to_char((NEW.amount_due_cents::numeric/100),'FM999999990.00')) || ' ' || NEW.currency;

  v_title := case NEW.status
    when 'open' then 'Payment due'
