;

CREATE OR REPLACE FUNCTION private.notification_scheduled_for(p_user_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_enabled boolean;
  v_start time;
  v_end time;
  v_tz text;
  v_local_now timestamp;
  v_local_date date;
  v_local_time time;
  v_target_local timestamp;
begin
  select
    np.quiet_hours_enabled,
    np.quiet_hours_start,
    np.quiet_hours_end,
    case
      when np.time_zone is not null
       and exists(select 1 from pg_timezone_names where name=np.time_zone)
      then np.time_zone
      else 'UTC'
    end
  into v_enabled,v_start,v_end,v_tz
  from public.notification_preferences np
  where np.user_id=p_user_id;

  if not coalesce(v_enabled,false) or v_start is null or v_end is null or v_start=v_end then
    return now();
  end if;

  v_local_now := now() at time zone v_tz;
  v_local_date := v_local_now::date;
  v_local_time := v_local_now::time;

  if v_start < v_end then
    if v_local_time >= v_start and v_local_time < v_end then
      v_target_local := v_local_date + v_end;
      return v_target_local at time zone v_tz;
    end if;
  else
    if v_local_time >= v_start then
      v_target_local := (v_local_date + 1) + v_end;
      return v_target_local at time zone v_tz;
    elsif v_local_time < v_end then
      v_target_local := v_local_date + v_end;
      return v_target_local at time zone v_tz;
    end if;
  end if;

  return now();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_my_goal(p_title text, p_description text DEFAULT NULL::text, p_target_value numeric DEFAULT NULL::numeric, p_target_unit text DEFAULT NULL::text, p_target_date date DEFAULT NULL::date, p_priority integer DEFAULT 3)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_contact_id uuid;
  v_membership_id uuid;
  v_id uuid;
begin
  if coalesce(trim(p_title),'')='' then
    raise exception 'Goal title is required';
  end if;

  if p_priority not between 1 and 5 then
    raise exception 'Priority must be between 1 and 5';
  end if;

  select ca.contact_id,ca.membership_id
  into v_contact_id,v_membership_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access is required';
  end if;

  insert into public.client_goals(
    contact_id,membership_id,scope,title,description,target_value,target_unit,
    target_date,priority,status,created_by_user_id,created_by_type
  )
  values(
    v_contact_id,v_membership_id,'individual',trim(p_title),nullif(trim(p_description),''),
    p_target_value,nullif(trim(p_target_unit),''),p_target_date,p_priority,'active',
    (select auth.uid()),'member'
  )
  returning id into v_id;

  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_my_goal_status(p_goal_id uuid, p_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if p_status not in ('active','completed','paused','cancelled') then
    raise exception 'Unsupported goal status';
  end if;

  update public.client_goals cg
  set status=p_status,
      completed_at=case when p_status='completed' then coalesce(cg.completed_at,now()) else null end,
      updated_at=now()
  where cg.id=p_goal_id
    and cg.contact_id in (
      select ca.contact_id
      from public.client_access ca
      where ca.user_id=(select auth.uid())
    );

  return found;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_my_habit(p_title text, p_category text DEFAULT NULL::text, p_frequency text DEFAULT 'daily'::text, p_target_per_period numeric DEFAULT 1, p_unit text DEFAULT NULL::text, p_starts_on date DEFAULT CURRENT_DATE)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_contact_id uuid;
  v_membership_id uuid;
  v_id uuid;
begin
  if coalesce(trim(p_title),'')='' then
    raise exception 'Habit title is required';
  end if;

  if p_frequency not in ('daily','weekly','custom') then
    raise exception 'Unsupported habit frequency';
  end if;

  if coalesce(p_target_per_period,0)<=0 then
    raise exception 'Habit target must be greater than zero';
  end if;

  select ca.contact_id,ca.membership_id
  into v_contact_id,v_membership_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access is required';
  end if;

  insert into public.client_habits(
    contact_id,membership_id,title,category,frequency,target_per_period,unit,
    status,starts_on,created_by
  )
  values(
    v_contact_id,v_membership_id,trim(p_title),nullif(trim(p_category),''),
    p_frequency,p_target_per_period,nullif(trim(p_unit),''),'active',
    coalesce(p_starts_on,current_date),(select auth.uid())
  )
  returning id into v_id;

  return v_id;
end;
$function$
;

