CREATE OR REPLACE FUNCTION private.log_companion_source_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_event text;
begin
  if tg_op='INSERT' then
    v_event := 'created';
  elsif old.content_checksum is distinct from new.content_checksum then
    v_event := 'content_changed';
  elsif old.status is distinct from new.status and new.status='approved' then
    v_event := 'approved';
  elsif old.status is distinct from new.status and new.status='retired' then
    v_event := 'retired';
  elsif old.status='approved' and new.status='draft' then
    v_event := 'approval_revoked';
  else
    return new;
  end if;

  insert into public.coach_companion_source_events(
    source_id,event_type,actor_user_id,detail
  )
  values(
    new.id,
    v_event,
    auth.uid(),
    jsonb_build_object(
      'status',new.status,
      'version',new.version,
      'ingestion_status',new.ingestion_status,
      'content_checksum',new.content_checksum
    )
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.build_companion_context_snapshot(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_request public.coach_companion_requests%rowtype;
  v_type_allows_personal boolean := false;
  v_pref public.ai_advisor_personalization_preferences%rowtype;
  v_personal_enabled boolean := false;
  v_payload jsonb := '{}'::jsonb;
begin
  select * into v_request
  from public.coach_companion_requests
  where id=p_request_id;

  if v_request.id is null then
    raise exception 'Companion request not found';
  end if;

  select coalesce(qt.allow_personal_context,false)
    into v_type_allows_personal
  from public.coach_companion_question_types qt
  where qt.question_type=v_request.question_type;

  select * into v_pref
  from public.ai_advisor_personalization_preferences p
  where p.user_id=v_request.requested_by_user_id;

  v_personal_enabled :=
    v_type_allows_personal
    and coalesce(v_pref.personalization_enabled,false);

  v_payload := jsonb_build_object(
    'request_id',v_request.id,
    'question_type',v_request.question_type,
    'captured_at',now(),
    'question_type_allows_personal_context',v_type_allows_personal,
    'member_personalization_enabled',coalesce(v_pref.personalization_enabled,false),
    'personal_context_used',v_personal_enabled
  );

  if v_personal_enabled then
    if coalesce(v_pref.allow_program_context,true) then
      v_payload := v_payload || jsonb_build_object(
        'member',
        coalesce((
          select jsonb_build_object(
            'contact_id',c.id,
            'first_name',c.first_name,
            'program_code',cm.program_code,
            'program_name',pc.name,
            'membership_status',cm.status,
            'assigned_coach_name',sd.display_name
          )
          from public.contacts c
          left join public.client_memberships cm on cm.id=v_request.membership_id
          left join public.program_catalog pc on pc.program_code=cm.program_code
          left join public.staff_directory sd on sd.user_id=cm.assigned_coach_id
          where c.id=v_request.contact_id
          limit 1
        ),'{}'::jsonb)
      );
    end if;

    if coalesce(v_pref.allow_daily_plan,true) then
      v_payload := v_payload || jsonb_build_object(
        'daily_plan',
        coalesce((
          select jsonb_build_object(
            'action_date',dac.action_date,
            'habits',dac.habits,
            'meals',dac.meals,
            'workouts',dac.workouts,
            'challenges',dac.challenges,
            'continue_course',dac.continue_course,
            'habit_count',dac.habit_count,
            'habits_completed_today',dac.habits_completed_today,
            'meal_count',dac.meal_count,
            'workout_count',dac.workout_count
          )
          from public.my_daily_action_center dac
          where dac.contact_id=v_request.contact_id
          limit 1
        ),'{}'::jsonb),
        'consistency',
        coalesce((
          select to_jsonb(cs.*)
          from public.my_consistency_summary cs
          limit 1
        ),'{}'::jsonb)
      );
    end if;

    if coalesce(v_pref.allow_goals,true) then
      v_payload := v_payload || jsonb_build_object(
        'goals',
        coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'goal_id',gp.goal_id,
              'goal_key',gp.goal_key,
              'title',gp.title,
              'target_value',gp.target_value,
              'target_unit',gp.target_unit,
              'target_date',gp.target_date,
              'current_value',gp.current_value,
              'completion_percent',gp.completion_percent,
              'progress_state',gp.progress_state
            )
            order by gp.priority,gp.title
          )
          from public.my_goal_progress gp
          where gp.contact_id=v_request.contact_id
            and gp.status in ('active','paused')
        ),'[]'::jsonb)
      );
    end if;

    if coalesce(v_pref.allow_course_progress,true) then
      v_payload := v_payload || jsonb_build_object(
        'courses',
        coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'course_id',mc.course_id,
              'title',mc.title,
              'status',mc.status,
              'progress_percent',mc.progress_percent,
              'last_activity_at',mc.last_activity_at
            )
            order by mc.last_activity_at desc nulls last
          )
          from public.my_courses mc
          where mc.status in ('active','completed')
        ),'[]'::jsonb)
      );
    end if;

    if coalesce(v_pref.allow_coaching_momentum,true) then
      v_payload := v_payload || jsonb_build_object(
        'coaching_momentum',
        coalesce((
          select to_jsonb(cm.*)
          from public.my_coaching_momentum cm
          where cm.contact_id=v_request.contact_id
          limit 1
        ),'{}'::jsonb)
      );
    end if;

    if coalesce(v_pref.allow_health_summary,false) then
      v_payload := v_payload || jsonb_build_object(
        'health_summary',
        coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'metric_key',hd.metric_key,
              'metric_label',hd.metric_label,
              'unit',hd.unit,
              'current_value',hd.current_value,
              'percent_change_30d',hd.percent_change_30d,
              'current_recorded_at',hd.current_recorded_at
            )
            order by hd.category,hd.metric_key
          )
          from public.my_health_dashboard_cards_30d hd
          where hd.contact_id=v_request.contact_id
        ),'[]'::jsonb)
      );
    end if;
  end if;

  insert into public.coach_companion_context_snapshots(
    request_id,contact_id,membership_id,question_type,
    personal_context_allowed,context_version,context_payload
  )
  values(
    v_request.id,v_request.contact_id,v_request.membership_id,v_request.question_type,
    v_personal_enabled,'v2',v_payload
  )
  on conflict(request_id) do update
  set personal_context_allowed=excluded.personal_context_allowed,
      context_version=excluded.context_version,
      context_payload=excluded.context_payload,
      generated_at=now();

  return v_payload;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.retire_companion_source(p_source_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if not private.staff_has_permission((select auth.uid()),'companion.manage') then
    raise exception 'Coach Companion management permission is required';
  end if;

  update public.coach_companion_knowledge_sources
  set status='retired',
      updated_at=now()
  where id=p_source_id;

  if not found then
    raise exception 'Knowledge source not found';
  end if;

  update public.coach_companion_knowledge_chunks
  set active=false,
      updated_at=now()
  where source_id=p_source_id
    and active=true;

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.reset_entitlement_period_if_needed(p_entitlement_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_row public.membership_entitlements%rowtype;
  v_reset boolean := false;
begin
  select * into v_row
  from public.membership_entitlements
  where id=p_entitlement_id
  for update;

  if v_row.id is null then
    return;
  end if;

  if v_row.period_started_at is null then
    update public.membership_entitlements
    set period_started_at=now(),
        used_value=coalesce(used_value,0),
        updated_at=now()
    where id=v_row.id;
    return;
  end if;

  v_reset := case lower(coalesce(v_row.reset_cadence,''))
    when 'daily' then v_row.period_started_at < date_trunc('day',now())
    when 'weekly' then v_row.period_started_at < date_trunc('week',now())
    when 'monthly' then v_row.period_started_at < date_trunc('month',now())
    when 'yearly' then v_row.period_started_at < date_trunc('year',now())
    else false
  end;

  if v_reset then
    update public.membership_entitlements
    set used_value=0,
        period_started_at=now(),
        updated_at=now()
    where id=v_row.id;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.consume_ai_advisor_entitlement(p_membership_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_ent public.membership_entitlements%rowtype;
begin
  select *
    into v_ent
  from public.membership_entitlements
  where membership_id=p_membership_id
    and entitlement_key='ai_advisor'
    and status='active'
  order by created_at desc
  limit 1
  for update;

  if v_ent.id is null then
    raise exception 'Ask ReVitalized is not included with this membership';
  end if;

  perform private.reset_entitlement_period_if_needed(v_ent.id);

  select *
    into v_ent
  from public.membership_entitlements
  where id=v_ent.id
  for update;

  if v_ent.limit_value is not null
     and coalesce(v_ent.used_value,0)>=v_ent.limit_value then
    raise exception 'Ask ReVitalized usage allowance has been reached for the current period';
  end if;

  update public.membership_entitlements
  set used_value=coalesce(used_value,0)+1,
      period_started_at=coalesce(period_started_at,now()),
      updated_at=now()
  where id=v_ent.id
  returning * into v_ent;

  return jsonb_build_object(
    'entitlement_id',v_ent.id,
    'used_value',v_ent.used_value,
    'limit_value',v_ent.limit_value,
    'reset_cadence',v_ent.reset_cadence,
    'period_started_at',v_ent.period_started_at
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION private.refresh_companion_source_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_old_checksum text;
  v_new_checksum text;
begin
  v_new_checksum := md5(coalesce(new.content_text,''));
  v_old_checksum := case when tg_op='UPDATE' then md5(coalesce(old.content_text,'')) else null end;

  if tg_op='INSERT' then
    new.content_checksum := v_new_checksum;
    if coalesce(length(trim(new.content_text)),0)>0 then
      new.ingestion_status := 'queued';
    end if;
    return new;
  end if;

  if v_old_checksum is distinct from v_new_checksum then
    new.content_checksum := v_new_checksum;
    new.ingestion_status := case
      when coalesce(length(trim(new.content_text)),0)>0 then 'queued'
      else 'not_started'
    end;
    new.last_ingested_at := null;

    if old.status='approved' then
      new.status := 'draft';
      new.approved_by := null;
      new.approved_at := null;
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.queue_companion_source_ingestion(p_source_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_job_id uuid;
  v_source public.coach_companion_knowledge_sources%rowtype;
begin
  if not private.staff_has_permission((select auth.uid()),'companion.manage') then
    raise exception 'Coach Companion management permission is required';
  end if;

  select * into v_source
  from public.coach_companion_knowledge_sources
  where id=p_source_id;

  if v_source.id is null then
    raise exception 'Knowledge source not found';
  end if;

  if coalesce(length(trim(v_source.content_text)),0)=0 then
    raise exception 'Knowledge source content is required before ingestion';
  end if;

  update public.coach_companion_knowledge_sources
  set ingestion_status='queued',
      updated_at=now()
  where id=p_source_id;

  insert into public.coach_companion_ingestion_jobs(
    source_id,job_type,status,requested_by
  )
  values(p_source_id,'full_ingest','queued',(select auth.uid()))
  returning id into v_job_id;

  insert into public.coach_companion_source_events(
    source_id,event_type,actor_user_id,detail
  )
  values(
    p_source_id,'ingestion_queued',(select auth.uid()),
    jsonb_build_object('job_id',v_job_id)
  );

  return v_job_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.approve_companion_source(p_source_id uuid, p_version text DEFAULT NULL::text, p_review_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_source public.coach_companion_knowledge_sources%rowtype;
  v_chunk_count integer;
  v_embedded_count integer;
begin
  if not private.staff_has_permission((select auth.uid()),'companion.manage') then
    raise exception 'Coach Companion management permission is required';
  end if;

  select * into v_source
  from public.coach_companion_knowledge_sources
  where id=p_source_id;

  if v_source.id is null then
    raise exception 'Knowledge source not found';
  end if;

  if coalesce(length(trim(v_source.content_text)),0)=0 then
    raise exception 'Knowledge source content is required';
  end if;

  select
    count(*) filter(where ch.active)::integer,
    count(*) filter(where ch.active and ch.embedding is not null)::integer
  into v_chunk_count,v_embedded_count
  from public.coach_companion_knowledge_chunks ch
  where ch.source_id=p_source_id;

  if coalesce(v_chunk_count,0)=0 then
    raise exception 'Knowledge source has no active chunks';
  end if;

  if v_embedded_count<>v_chunk_count then
    raise exception 'All active knowledge chunks must have embeddings before approval';
  end if;

  update public.coach_companion_knowledge_sources
  set status='approved',
      version=coalesce(nullif(trim(p_version),''),version,'1.0'),
      ingestion_status='ready',
      approved_by=(select auth.uid()),
      approved_at=now(),
      review_due_at=p_review_due_at,
      updated_at=now()
  where id=p_source_id;

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.emit_notification_sync_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_household_id uuid;
  v_entity_id uuid;
begin
  if tg_op='DELETE' then
    v_contact_id:=old.contact_id;
    v_entity_id:=old.id;
  else
    v_contact_id:=new.contact_id;
    v_entity_id:=new.id;
  end if;

  if v_contact_id is null then
    return coalesce(new,old);
  end if;

  select hm.household_id
    into v_household_id
  from public.household_members hm
  where hm.contact_id=v_contact_id
    and hm.status='active'
  order by hm.is_primary desc,hm.created_at
  limit 1;

  insert into public.member_sync_events(
    contact_id,household_id,entity_type,entity_id,change_type,metadata
  )
  values(
    v_contact_id,
    v_household_id,
    'notification',
    v_entity_id,
    lower(tg_op),
    jsonb_build_object('table','member_notifications')
  );

  return coalesce(new,old);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_my_companion_feedback(p_request_id uuid, p_helpful boolean, p_feedback_reason text DEFAULT NULL::text, p_comment text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_feedback_id uuid;
begin
  if p_feedback_reason is not null
     and p_feedback_reason not in (
       'not_relevant','unclear','incorrect','missing_context',
       'too_generic','needs_coach','other'
     ) then
    raise exception 'Invalid feedback reason';
  end if;

  if p_comment is not null and length(p_comment)>2000 then
    raise exception 'Feedback comment must be 2000 characters or fewer';
  end if;

  select r.contact_id into v_contact_id
  from public.coach_companion_requests r
  where r.id=p_request_id
    and r.requested_by_user_id=(select auth.uid())
    and r.status in ('answered','resolved');

  if v_contact_id is null then
    raise exception 'Answered Ask ReVitalized request not found';
  end if;

  insert into public.coach_companion_answer_feedback(
    request_id,contact_id,user_id,helpful,feedback_reason,comment
  )
  values(
    p_request_id,v_contact_id,(select auth.uid()),p_helpful,p_feedback_reason,nullif(trim(p_comment),'')
  )
  on conflict(request_id) do update
  set helpful=excluded.helpful,
      feedback_reason=excluded.feedback_reason,
      comment=excluded.comment,
      updated_at=now()
  returning id into v_feedback_id;

  return v_feedback_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_my_ai_advisor_personalization(p_personalization_enabled boolean, p_allow_program_context boolean DEFAULT true, p_allow_daily_plan boolean DEFAULT true, p_allow_goals boolean DEFAULT true, p_allow_course_progress boolean DEFAULT true, p_allow_coaching_momentum boolean DEFAULT true, p_allow_health_summary boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
begin
  select ca.contact_id into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access is required';
  end if;

  insert into public.ai_advisor_personalization_preferences(
    user_id,contact_id,personalization_enabled,
    allow_program_context,allow_daily_plan,allow_goals,
    allow_course_progress,allow_coaching_momentum,allow_health_summary,
    consented_at,revoked_at,updated_at
  )
  values(
    (select auth.uid()),v_contact_id,p_personalization_enabled,
    p_allow_program_context,p_allow_daily_plan,p_allow_goals,
    p_allow_course_progress,p_allow_coaching_momentum,p_allow_health_summary,
    case when p_personalization_enabled then now() else null end,
    case when not p_personalization_enabled then now() else null end,
    now()
  )
  on conflict(user_id) do update
  set contact_id=excluded.contact_id,
      personalization_enabled=excluded.personalization_enabled,
      allow_program_context=excluded.allow_program_context,
      allow_daily_plan=excluded.allow_daily_plan,
      allow_goals=excluded.allow_goals,
      allow_course_progress=excluded.allow_course_progress,
      allow_coaching_momentum=excluded.allow_coaching_momentum,
      allow_health_summary=excluded.allow_health_summary,
      consented_at=case
        when excluded.personalization_enabled
          and not ai_advisor_personalization_preferences.personalization_enabled
        then now()
        else ai_advisor_personalization_preferences.consented_at
      end,
      revoked_at=case
        when not excluded.personalization_enabled then now()
        else null
      end,
      updated_at=now();

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.route_negative_companion_feedback()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_request public.coach_companion_requests%rowtype;
begin
  if new.helpful=true then
    return new;
  end if;

  select * into v_request
  from public.coach_companion_requests
  where id=new.request_id;

  if v_request.id is null then
    return new;
  end if;

  if v_request.answered_by_type='companion'
     or new.feedback_reason in ('incorrect','needs_coach','missing_context') then
    perform private.create_companion_review(
      new.request_id,
      'Member marked the Ask ReVitalized response as not helpful'
      || case
           when new.feedback_reason is not null
           then ' (' || new.feedback_reason || ').'
           else '.'
         end
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_my_mobile_health_batch(p_provider_key text, p_idempotency_key text, p_records jsonb, p_device_id uuid DEFAULT NULL::uuid, p_source_cursor text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_membership_id uuid;
  v_connection_id uuid;
  v_existing public.health_mobile_sync_batches%rowtype;
  v_batch_id uuid;
  v_sync_job_id uuid;
  v_received integer := 0;
  v_imported integer := 0;
  v_blocked integer := 0;
  v_duplicate integer := 0;
  v_record jsonb;
  v_metric_key text;
  v_external_record_id text;
  v_value_numeric numeric;
  v_value_boolean boolean;
  v_unit text;
  v_observed_at timestamptz;
  v_observed_end_at timestamptz;
  v_source_hash text;
  v_allowed boolean;
  v_supported boolean;
  v_inserted_id uuid;
  v_status text;
  v_record_error text;
begin
  if p_provider_key not in ('apple_health','health_connect') then
    raise exception 'Provider must be Apple Health or Android Health Connect';
  end if;

  if coalesce(length(trim(p_idempotency_key)),0)<8 then
    raise exception 'A valid idempotency key is required';
  end if;

  if jsonb_typeof(p_records) is distinct from 'array' then
    raise exception 'Health sync records must be a JSON array';
  end if;

  if jsonb_array_length(p_records)>1000 then
    raise exception 'Health sync batch cannot exceed 1000 records';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    (select auth.uid())::text || ':health:' || p_idempotency_key,0
  ));

  select * into v_existing
  from public.health_mobile_sync_batches b
  where b.user_id=(select auth.uid())
    and b.idempotency_key=p_idempotency_key
  limit 1;

  if v_existing.id is not null then
    if v_existing.provider_key is distinct from p_provider_key then
      raise exception 'Idempotency key has already been used for another provider';
    end if;

    return jsonb_build_object(
      'batch_id',v_existing.id,
      'status',v_existing.status,
      'records_received',v_existing.records_received,
      'records_imported',v_existing.records_imported,
      'records_blocked',v_existing.records_blocked,
      'records_duplicate',v_existing.records_duplicate,
      'source_cursor',v_existing.source_cursor,
      'replayed',true
    );
  end if;

  select ca.contact_id,ca.membership_id
    into v_contact_id,v_membership_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access is required';
  end if;

  if p_device_id is not null
     and not exists (
       select 1 from public.member_devices d
       where d.id=p_device_id
         and d.user_id=(select auth.uid())
         and d.revoked_at is null
     ) then
    raise exception 'Device is not available to the current member';
  end if;

  v_connection_id:=public.ensure_my_mobile_health_connection(
    p_provider_key,p_device_id
  );

  insert into public.health_mobile_sync_batches(
    user_id,contact_id,membership_id,device_id,connection_id,provider_key,
    idempotency_key,source_cursor,records_received,status,metadata
  )
  values(
    (select auth.uid()),v_contact_id,v_membership_id,p_device_id,v_connection_id,
    p_provider_key,p_idempotency_key,p_source_cursor,jsonb_array_length(p_records),
    'processing',
    jsonb_build_object('connection_mode','mobile_bridge')
  )
  returning id into v_batch_id;

  insert into public.health_sync_jobs(
    connection_id,contact_id,provider_key,job_type,status,scheduled_for,
    started_at,records_received,records_imported
  )
  values(
    v_connection_id,v_contact_id,p_provider_key,'incremental','processing',
    now(),now(),jsonb_array_length(p_records),0
  )
  returning id into v_sync_job_id;

  for v_record in
    select value from jsonb_array_elements(p_records)
  loop
    v_received:=v_received+1;
    v_record_error:=null;

    begin
      v_metric_key:=nullif(trim(v_record->>'metric_key'),'');
      v_external_record_id:=nullif(trim(v_record->>'external_record_id'),'');
      v_unit:=nullif(trim(v_record->>'unit'),'');
      v_value_numeric:=case
        when v_record ? 'value_numeric' and nullif(v_record->>'value_numeric','') is not null
          then (v_record->>'value_numeric')::numeric
        else null
      end;
      v_value_boolean:=case
        when v_record ? 'value_boolean' and nullif(v_record->>'value_boolean','') is not null
          then (v_record->>'value_boolean')::boolean
        else null
      end;
      v_observed_at:=case
        when nullif(v_record->>'observed_at','') is not null
          then (v_record->>'observed_at')::timestamptz
        else null
      end;
      v_observed_end_at:=case
        when nullif(v_record->>'observed_end_at','') is not null
          then (v_record->>'observed_end_at')::timestamptz
        else null
      end;
    exception
      when others then
        v_record_error:=left(sqlerrm,500);
    end;

    if v_record_error is not null
       or v_metric_key is null
       or v_observed_at is null
       or ((v_value_numeric is null and v_value_boolean is null)
           or (v_value_numeric is not null and v_value_boolean is not null)) then
      v_blocked:=v_blocked+1;
      continue;
    end if;

    select p.supported_metrics ? v_metric_key
      into v_supported
    from public.health_integration_providers p
    where p.provider_key=p_provider_key
      and p.active
      and p.connection_mode='mobile_bridge';

    if not coalesce(v_supported,false) then
      v_blocked:=v_blocked+1;
      continue;
    end if;

    select coalesce(c.allowed,false)
      into v_allowed
    from public.health_metric_consents c
    where c.user_id=(select auth.uid())
      and c.contact_id=v_contact_id
      and c.provider_key=p_provider_key
      and c.metric_key=v_metric_key
    order by c.updated_at desc
    limit 1;

    if not coalesce(v_allowed,false) then
      v_blocked:=v_blocked+1;
      continue;
    end if;

    v_source_hash:=md5(
      concat_ws('|',
        p_provider_key,
        v_metric_key,
        coalesce(v_external_record_id,''),
        v_observed_at::text,
        coalesce(v_observed_end_at::text,''),
        coalesce(v_value_numeric::text,''),
        coalesce(v_value_boolean::text,''),
        coalesce(v_unit,'')
      )
    );

    v_inserted_id:=null;

    insert into public.health_observations(
      contact_id,membership_id,connection_id,provider_key,metric_key,
      value_numeric,value_boolean,unit,observed_at,observed_end_at,
      external_record_id,source_payload_hash,imported_at,metadata
    )
    values(
      v_contact_id,v_membership_id,v_connection_id,p_provider_key,v_metric_key,
      v_value_numeric,v_value_boolean,v_unit,v_observed_at,v_observed_end_at,
      v_external_record_id,v_source_hash,now(),
      coalesce(v_record->'metadata','{}'::jsonb)
        || jsonb_build_object(
          'mobile_batch_id',v_batch_id,
          'device_id',p_device_id
        )
    )
    on conflict do nothing
    returning id into v_inserted_id;

    if v_inserted_id is null then
      v_duplicate:=v_duplicate+1;
    else
      v_imported:=v_imported+1;
    end if;
  end loop;

  v_status:=case
    when v_blocked>0 then 'partial'
    else 'completed'
  end;

  update public.health_mobile_sync_batches
  set records_received=v_received,
      records_imported=v_imported,
      records_blocked=v_blocked,
      records_duplicate=v_duplicate,
      status=v_status,
      completed_at=now()
  where id=v_batch_id;

  update public.health_integration_connections
  set status='connected',
      last_sync_at=now(),
      last_successful_sync_at=case
        when v_imported>0 or v_duplicate>0 then now()
        else last_successful_sync_at
      end,
      last_error=case
        when v_blocked>0 then v_blocked::text || ' record(s) blocked during last sync'
        else null
      end,
      sync_cursor=coalesce(p_source_cursor,sync_cursor),
      metadata=coalesce(metadata,'{}'::jsonb)
        || jsonb_build_object(
          'last_device_id',p_device_id,
          'last_mobile_batch_id',v_batch_id
        ),
      updated_at=now()
  where id=v_connection_id;

  update public.health_sync_jobs
  set status='completed',
      completed_at=now(),
      records_received=v_received,
      records_imported=v_imported,
      error_message=case
        when v_blocked>0 then v_blocked::text || ' record(s) blocked'
        else null
      end,
      updated_at=now()
  where id=v_sync_job_id;

  perform private.touch_member_device(p_device_id);

  return jsonb_build_object(
    'batch_id',v_batch_id,
    'status',v_status,
    'records_received',v_received,
    'records_imported',v_imported,
    'records_blocked',v_blocked,
    'records_duplicate',v_duplicate,
    'source_cursor',p_source_cursor,
    'replayed',false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.register_my_device(p_device_key text, p_platform text, p_push_provider text DEFAULT 'native'::text, p_push_token text DEFAULT NULL::text, p_push_enabled boolean DEFAULT true, p_app_version text DEFAULT NULL::text, p_os_version text DEFAULT NULL::text, p_device_model text DEFAULT NULL::text, p_locale text DEFAULT NULL::text, p_time_zone text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_device_id uuid;
begin
  if coalesce(length(trim(p_device_key)),0)<3 or length(trim(p_device_key))>255 then
    raise exception 'A valid device key is required';
  end if;

  if p_platform not in ('ios','android','web') then
    raise exception 'Invalid device platform';
  end if;

  if p_push_provider not in ('native','firebase','apns','goodbarber','webpush','other') then
    raise exception 'Invalid push provider';
  end if;

  select ca.contact_id into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  insert into public.member_devices(
    user_id,contact_id,device_key,platform,push_provider,push_token,push_enabled,
    app_version,os_version,device_model,locale,time_zone,last_seen_at,
    push_token_updated_at,revoked_at,metadata
  )
  values(
    (select auth.uid()),v_contact_id,trim(p_device_key),p_platform,p_push_provider,
    nullif(trim(p_push_token),''),p_push_enabled,
    nullif(trim(p_app_version),''),nullif(trim(p_os_version),''),
    nullif(trim(p_device_model),''),nullif(trim(p_locale),''),
    nullif(trim(p_time_zone),''),now(),
    case when nullif(trim(p_push_token),'') is not null then now() else null end,
    null,coalesce(p_metadata,'{}'::jsonb)
  )
  on conflict(user_id,device_key) do update
  set contact_id=excluded.contact_id,
      platform=excluded.platform,
      push_provider=excluded.push_provider,
      push_token=excluded.push_token,
      push_enabled=excluded.push_enabled,
      app_version=excluded.app_version,
      os_version=excluded.os_version,
      device_model=excluded.device_model,
      locale=excluded.locale,
      time_zone=excluded.time_zone,
      last_seen_at=now(),
      push_token_updated_at=case
        when public.member_devices.push_token is distinct from excluded.push_token then now()
        else public.member_devices.push_token_updated_at
      end,
      revoked_at=null,
      metadata=excluded.metadata
  returning id into v_device_id;

  return v_device_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.revoke_my_device(p_device_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  update public.member_devices
  set push_enabled=false,
      push_token=null,
      revoked_at=now(),
      last_seen_at=now()
  where id=p_device_id
    and user_id=(select auth.uid());

  return found;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.queue_push_delivery()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_prefs public.notification_preferences%rowtype;
  v_wants_push boolean := true;
  v_scheduled_for timestamptz;
begin
  select * into v_prefs
  from public.notification_preferences
  where user_id=new.user_id;

  if v_prefs.user_id is null then
    insert into public.notification_preferences(user_id)
    values(new.user_id)
    on conflict(user_id) do nothing;

    select * into v_prefs
    from public.notification_preferences
    where user_id=new.user_id;
  end if;

  if new.notification_type='new_message' then
    v_wants_push:=coalesce(v_prefs.push_messages,true);
  elsif new.notification_type in (
    'appointment_reminder','appointment_scheduled','coaching_reminder',
    'coaching_session','assignment_available','assignment_completed',
    'companion_answer_ready'
  ) then
    v_wants_push:=coalesce(v_prefs.push_coaching_reminders,true);
  elsif new.notification_type in (
    'program_update','account_active','course_assigned','course_available',
    'course_completed','resource_assigned','resource_available',
    'challenge_available','challenge_completed','goal_completed',
    'achievement_unlocked','agreement_sent','agreement_viewed',
    'agreement_signed','agreement_declined','referral_engaged',
    'referral_applicant','referral_converted','referral_reward_approved',
    'referral_reward_issued','family_request_in_review',
    'family_request_approved','family_request_completed',
    'family_request_declined'
  ) then
    v_wants_push:=coalesce(v_prefs.push_program_updates,true);
  elsif new.notification_type='billing_alert'
     or new.notification_type like 'billing_%' then
    v_wants_push:=coalesce(v_prefs.push_billing_alerts,true);
  else
    v_wants_push:=true;
  end if;

  if not v_wants_push then
    return new;
  end if;

  v_scheduled_for:=private.notification_scheduled_for(new.user_id);

  insert into public.push_delivery_jobs(
    notification_id,device_id,user_id,contact_id,provider,push_token,
    title,body,link_url,status,block_reason,scheduled_for
  )
  select
    new.id,
    d.id,
    new.user_id,
    new.contact_id,
    d.push_provider,
    d.push_token,
    new.title,
    new.body,
    new.link_url,
    case
      when d.push_enabled=false then 'blocked'
      when d.revoked_at is not null then 'blocked'
      when d.push_token is null then 'blocked'
      else 'queued'
    end,
    case
      when d.push_enabled=false then 'device_push_disabled'
      when d.revoked_at is not null then 'device_revoked'
      when d.push_token is null then 'missing_push_token'
      else null
    end,
    v_scheduled_for
  from public.member_devices d
  where d.user_id=new.user_id
    and d.revoked_at is null
  on conflict(notification_id,device_id) do nothing;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_app_runtime_config(p_config_key text, p_config_value jsonb, p_description text DEFAULT NULL::text, p_member_visible boolean DEFAULT true, p_active boolean DEFAULT true)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if not private.staff_has_permission((select auth.uid()),'staff.manage') then
    raise exception 'Staff management permission is required';
  end if;

  update public.app_runtime_config
  set config_value=p_config_value,
      description=coalesce(p_description,description),
      member_visible=p_member_visible,
      active=p_active,
      updated_by=(select auth.uid()),
      updated_at=now()
  where config_key=p_config_key;

  if not found then
    raise exception 'Runtime config key not found';
  end if;

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.touch_member_device(p_device_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if p_device_id is null then
    return;
  end if;

  update public.member_devices
  set last_seen_at=now()
  where id=p_device_id
    and user_id=(select auth.uid())
    and revoked_at is null;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.existing_mutation_response(p_idempotency_key text, p_mutation_type text, p_request_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_row public.member_mutation_receipts%rowtype;
begin
  select * into v_row
  from public.member_mutation_receipts
  where user_id=(select auth.uid())
    and idempotency_key=p_idempotency_key
  limit 1;

  if v_row.id is null then
    return null;
  end if;

  if v_row.mutation_type is distinct from p_mutation_type
     or v_row.request_hash is distinct from p_request_hash then
    raise exception 'Idempotency key has already been used for a different request';
  end if;

  return v_row.response_payload;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_my_habit_checkin(p_idempotency_key text, p_habit_id uuid, p_checkin_date date, p_value numeric, p_note text DEFAULT NULL::text, p_device_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_hash text;
  v_existing jsonb;
  v_id uuid;
  v_response jsonb;
begin
  if coalesce(length(trim(p_idempotency_key)),0)<8 then
    raise exception 'A valid idempotency key is required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    (select auth.uid())::text || ':' || p_idempotency_key,0
  ));

  v_hash:=md5(concat_ws('|',p_habit_id::text,p_checkin_date::text,p_value::text,coalesce(p_note,'')));
  v_existing:=private.existing_mutation_response(
    p_idempotency_key,'habit_checkin',v_hash
  );
  if v_existing is not null then
    return v_existing;
  end if;

  select ca.contact_id into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
    and exists (
      select 1 from public.client_habits h
      where h.id=p_habit_id
        and h.contact_id=ca.contact_id
    )
  order by ca.updated_at desc
  limit 1;

  if v_contact_id is null then
    raise exception 'Habit is not available to the current member';
  end if;

  insert into public.habit_checkins(
    habit_id,contact_id,checkin_date,value,note,source,created_by
  )
  values(
    p_habit_id,v_contact_id,p_checkin_date,p_value,
    nullif(trim(p_note),''),'member',(select auth.uid())
  )
  on conflict(habit_id,contact_id,checkin_date) do update
  set value=excluded.value,
      note=excluded.note,
      source='member',
      created_by=(select auth.uid())
  returning id into v_id;

  v_response:=jsonb_build_object(
    'status','ok',
    'mutation_type','habit_checkin',
    'record_id',v_id,
    'contact_id',v_contact_id,
    'checkin_date',p_checkin_date
  );

  insert into public.member_mutation_receipts(
    user_id,contact_id,device_id,idempotency_key,mutation_type,request_hash,response_payload
  )
  values(
    (select auth.uid()),v_contact_id,p_device_id,p_idempotency_key,
    'habit_checkin',v_hash,v_response
  );

  perform private.touch_member_device(p_device_id);
  return v_response;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_my_progress_entry(p_idempotency_key text, p_metric_key text, p_value_numeric numeric DEFAULT NULL::numeric, p_value_boolean boolean DEFAULT NULL::boolean, p_recorded_at timestamp with time zone DEFAULT now(), p_note text DEFAULT NULL::text, p_device_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_membership_id uuid;
  v_hash text;
  v_existing jsonb;
  v_id uuid;
  v_response jsonb;
begin
  if coalesce(length(trim(p_idempotency_key)),0)<8 then
    raise exception 'A valid idempotency key is required';
  end if;

  if (p_value_numeric is null and p_value_boolean is null)
     or (p_value_numeric is not null and p_value_boolean is not null) then
    raise exception 'Provide exactly one progress value';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    (select auth.uid())::text || ':' || p_idempotency_key,0
  ));

  v_hash:=md5(concat_ws('|',p_metric_key,coalesce(p_value_numeric::text,''),
    coalesce(p_value_boolean::text,''),p_recorded_at::text,coalesce(p_note,'')));

  v_existing:=private.existing_mutation_response(
    p_idempotency_key,'progress_entry',v_hash
  );
  if v_existing is not null then
    return v_existing;
  end if;

  select ca.contact_id,ca.membership_id
  into v_contact_id,v_membership_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access is required';
  end if;

  if not exists (
    select 1 from public.progress_metric_catalog pmc
    where pmc.metric_key=p_metric_key
      and pmc.active
      and pmc.member_trackable
  ) then
    raise exception 'Metric is not available for member tracking';
  end if;

  insert into public.progress_entries(
    contact_id,membership_id,metric_key,value_numeric,value_boolean,
    recorded_at,source,created_by,note,metadata
  )
  values(
    v_contact_id,v_membership_id,p_metric_key,p_value_numeric,p_value_boolean,
    coalesce(p_recorded_at,now()),'member',(select auth.uid()),
    nullif(trim(p_note),''),
    jsonb_build_object(
      'idempotency_key',p_idempotency_key,
      'device_id',p_device_id
    )
  )
  returning id into v_id;

  v_response:=jsonb_build_object(
    'status','ok',
    'mutation_type','progress_entry',
    'record_id',v_id,
    'contact_id',v_contact_id,
    'metric_key',p_metric_key,
    'recorded_at',coalesce(p_recorded_at,now())
  );

  insert into public.member_mutation_receipts(
    user_id,contact_id,device_id,idempotency_key,mutation_type,request_hash,response_payload
  )
  values(
    (select auth.uid()),v_contact_id,p_device_id,p_idempotency_key,
    'progress_entry',v_hash,v_response
  );

  perform private.touch_member_device(p_device_id);
  return v_response;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_my_workout_status(p_idempotency_key text, p_assignment_id uuid, p_status text, p_device_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_hash text;
  v_existing jsonb;
  v_response jsonb;
begin
  if p_status not in ('assigned','completed','skipped') then
    raise exception 'Invalid workout status';
  end if;

  if coalesce(length(trim(p_idempotency_key)),0)<8 then
    raise exception 'A valid idempotency key is required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    (select auth.uid())::text || ':' || p_idempotency_key,0
  ));

  v_hash:=md5(concat_ws('|',p_assignment_id::text,p_status));
  v_existing:=private.existing_mutation_response(
    p_idempotency_key,'workout_status',v_hash
  );
  if v_existing is not null then
    return v_existing;
  end if;

  select wa.contact_id into v_contact_id
  from public.client_workout_assignments wa
  join public.client_access ca on ca.contact_id=wa.contact_id
  where wa.id=p_assignment_id
    and ca.user_id=(select auth.uid())
    and ca.status='active'
  limit 1;

  if v_contact_id is null then
    raise exception 'Workout assignment is not available to the current member';
  end if;

  update public.client_workout_assignments
  set status=p_status,
      updated_at=now()
  where id=p_assignment_id;

  v_response:=jsonb_build_object(
    'status','ok',
    'mutation_type','workout_status',
    'record_id',p_assignment_id,
    'contact_id',v_contact_id,
    'workout_status',p_status
  );

  insert into public.member_mutation_receipts(
    user_id,contact_id,device_id,idempotency_key,mutation_type,request_hash,response_payload
  )
  values(
    (select auth.uid()),v_contact_id,p_device_id,p_idempotency_key,
    'workout_status',v_hash,v_response
  );

  perform private.touch_member_device(p_device_id);
  return v_response;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_my_meal_status(p_idempotency_key text, p_meal_item_id uuid, p_status text, p_adherence_percent numeric DEFAULT NULL::numeric, p_device_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_hash text;
  v_existing jsonb;
  v_response jsonb;
begin
  if p_status not in ('planned','completed','skipped','substituted') then
    raise exception 'Invalid meal status';
  end if;

  if p_adherence_percent is not null
     and (p_adherence_percent<0 or p_adherence_percent>100) then
    raise exception 'Adherence percent must be between 0 and 100';
  end if;

  if coalesce(length(trim(p_idempotency_key)),0)<8 then
    raise exception 'A valid idempotency key is required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    (select auth.uid())::text || ':' || p_idempotency_key,0
  ));

  v_hash:=md5(concat_ws('|',p_meal_item_id::text,p_status,coalesce(p_adherence_percent::text,'')));
  v_existing:=private.existing_mutation_response(
    p_idempotency_key,'meal_status',v_hash
  );
  if v_existing is not null then
    return v_existing;
  end if;

  select mi.contact_id into v_contact_id
  from public.client_meal_plan_items mi
  join public.client_access ca on ca.contact_id=mi.contact_id
  where mi.id=p_meal_item_id
    and ca.user_id=(select auth.uid())
    and ca.status='active'
  limit 1;

  if v_contact_id is null then
    raise exception 'Meal item is not available to the current member';
  end if;

  update public.client_meal_plan_items
  set status=p_status,
      adherence_percent=p_adherence_percent,
      completed_at=case when p_status='completed' then coalesce(completed_at,now()) else null end
  where id=p_meal_item_id;

  v_response:=jsonb_build_object(
    'status','ok',
    'mutation_type','meal_status',
    'record_id',p_meal_item_id,
    'contact_id',v_contact_id,
    'meal_status',p_status,
    'adherence_percent',p_adherence_percent
  );

  insert into public.member_mutation_receipts(
    user_id,contact_id,device_id,idempotency_key,mutation_type,request_hash,response_payload
  )
  values(
    (select auth.uid()),v_contact_id,p_device_id,p_idempotency_key,
    'meal_status',v_hash,v_response
  );

  perform private.touch_member_device(p_device_id);
  return v_response;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.emit_member_sync_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_household_id uuid;
  v_entity_id uuid;
  v_change text;
begin
  v_change:=lower(tg_op);

  if tg_op='DELETE' then
    v_contact_id:=old.contact_id;
    v_entity_id:=old.id;
  else
    v_contact_id:=new.contact_id;
    v_entity_id:=new.id;
  end if;

  if v_contact_id is null then
    return coalesce(new,old);
  end if;

  select hm.household_id
    into v_household_id
  from public.household_members hm
  where hm.contact_id=v_contact_id
    and hm.status='active'
  order by hm.is_primary desc,hm.created_at
  limit 1;

  insert into public.member_sync_events(
    contact_id,household_id,entity_type,entity_id,change_type,metadata
  )
  values(
    v_contact_id,
    v_household_id,
    tg_argv[0],
    v_entity_id,
    v_change,
    jsonb_build_object('table',tg_table_name)
  );

  return coalesce(new,old);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_sync_events(p_after_event_id bigint DEFAULT 0, p_limit integer DEFAULT 200)
 RETURNS TABLE(event_id bigint, contact_id uuid, household_id uuid, entity_type text, entity_id uuid, change_type text, changed_at timestamp with time zone, metadata jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select
    e.event_id,
    e.contact_id,
    e.household_id,
    e.entity_type,
    e.entity_id,
    e.change_type,
    e.changed_at,
    e.metadata
  from public.member_sync_events e
  where e.event_id>greatest(coalesce(p_after_event_id,0),0)
  order by e.event_id
  limit greatest(1,least(coalesce(p_limit,200),500));
$function$
;

CREATE OR REPLACE FUNCTION public.start_my_app_session(p_session_key text, p_device_id uuid DEFAULT NULL::uuid, p_platform text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_session_id uuid;
begin
  if coalesce(length(trim(p_session_key)),0)<8 then
    raise exception 'A valid session key is required';
  end if;

  select ca.contact_id into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if p_device_id is not null
     and not exists (
       select 1 from public.member_devices d
       where d.id=p_device_id
         and d.user_id=(select auth.uid())
         and d.revoked_at is null
     ) then
    raise exception 'Device is not available to the current member';
  end if;

  insert into public.member_app_sessions(
    user_id,contact_id,device_id,session_key,platform,app_version,
    started_at,last_seen_at,ended_at
  )
  values(
    (select auth.uid()),v_contact_id,p_device_id,trim(p_session_key),
    nullif(trim(p_platform),''),nullif(trim(p_app_version),''),
    now(),now(),null
  )
  on conflict(user_id,session_key) do update
  set contact_id=excluded.contact_id,
      device_id=coalesce(excluded.device_id,public.member_app_sessions.device_id),
      platform=coalesce(excluded.platform,public.member_app_sessions.platform),
      app_version=coalesce(excluded.app_version,public.member_app_sessions.app_version),
      last_seen_at=now(),
      ended_at=null
  returning id into v_session_id;

  perform private.touch_member_device(p_device_id);
  return v_session_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.disconnect_my_health_provider(p_provider_key text, p_revoke_all_metric_consents boolean DEFAULT true)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
begin
  select ca.contact_id into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access is required';
  end if;

  update public.health_integration_connections
  set status='disconnected',
      last_error=null,
      credential_reference=null,
      granted_scopes='{}'::jsonb,
      updated_at=now()
  where contact_id=v_contact_id
    and user_id=(select auth.uid())
    and provider_key=p_provider_key;

  if p_revoke_all_metric_consents then
    update public.health_metric_consents
    set allowed=false,
        revoked_at=now(),
        updated_at=now()
    where user_id=(select auth.uid())
      and contact_id=v_contact_id
      and provider_key=p_provider_key
      and allowed=true;
  end if;

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.track_my_app_event(p_event_key text, p_session_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid, p_route_key text DEFAULT NULL::text, p_feature_key text DEFAULT NULL::text, p_properties jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_event_id bigint;
begin
  if coalesce(length(trim(p_event_key)),0)<2 or length(trim(p_event_key))>100 then
    raise exception 'A valid event key is required';
  end if;

  select ca.contact_id into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if p_session_id is not null
     and not exists (
       select 1 from public.member_app_sessions s
       where s.id=p_session_id
         and s.user_id=(select auth.uid())
     ) then
    raise exception 'Session is not available to the current member';
  end if;

  if p_device_id is not null
     and not exists (
       select 1 from public.member_devices d
       where d.id=p_device_id
         and d.user_id=(select auth.uid())
         and d.revoked_at is null
     ) then
    raise exception 'Device is not available to the current member';
  end if;

  if p_route_key is not null
     and not exists (
       select 1 from public.app_route_registry r
       where r.route_key=p_route_key
         and r.active
     ) then
    raise exception 'Unknown app route';
  end if;

  insert into public.member_app_events(
    user_id,contact_id,device_id,session_id,event_key,route_key,
    feature_key,properties
  )
  values(
    (select auth.uid()),v_contact_id,p_device_id,p_session_id,
    trim(p_event_key),p_route_key,p_feature_key,coalesce(p_properties,'{}'::jsonb)
  )
  returning id into v_event_id;

  if p_session_id is not null then
    update public.member_app_sessions
    set last_seen_at=now()
    where id=p_session_id
      and user_id=(select auth.uid());
  end if;

  perform private.touch_member_device(p_device_id);
  return v_event_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.end_my_app_session(p_session_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  update public.member_app_sessions
  set last_seen_at=now(),
      ended_at=now()
  where id=p_session_id
    and user_id=(select auth.uid());

  return found;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ensure_my_mobile_health_connection(p_provider_key text, p_device_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_membership_id uuid;
  v_connection_id uuid;
begin
  if p_provider_key not in ('apple_health','health_connect') then
    raise exception 'Provider must be Apple Health or Android Health Connect';
  end if;

  if not exists (
    select 1
    from public.health_integration_providers p
    where p.provider_key=p_provider_key
      and p.active
      and p.connection_mode='mobile_bridge'
  ) then
    raise exception 'Mobile health provider is not currently available';
  end if;

  select ca.contact_id,ca.membership_id
    into v_contact_id,v_membership_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access is required';
  end if;

  if p_device_id is not null
     and not exists (
       select 1
       from public.member_devices d
       where d.id=p_device_id
         and d.user_id=(select auth.uid())
         and d.revoked_at is null
     ) then
    raise exception 'Device is not available to the current member';
  end if;

  insert into public.health_integration_connections(
    contact_id,membership_id,user_id,provider_key,status,
    connected_at,metadata
  )
  values(
    v_contact_id,v_membership_id,(select auth.uid()),p_provider_key,
    'connected',now(),
    jsonb_build_object(
      'connection_mode','mobile_bridge',
      'device_id',p_device_id
    )
  )
  on conflict(contact_id,provider_key) do update
  set membership_id=excluded.membership_id,
      user_id=(select auth.uid()),
      status=case
        when public.health_integration_connections.status in ('revoked','disconnected')
          then 'connected'
        else public.health_integration_connections.status
      end,
      connected_at=coalesce(public.health_integration_connections.connected_at,now()),
      metadata=coalesce(public.health_integration_connections.metadata,'{}'::jsonb)
        || jsonb_build_object('device_id',p_device_id,'connection_mode','mobile_bridge'),
      updated_at=now()
  returning id into v_connection_id;

  perform private.touch_member_device(p_device_id);
  return v_connection_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.prepare_privacy_export(p_request_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_req public.member_privacy_requests%rowtype;
  v_export_id uuid;
  v_manifest jsonb;
begin
  if not private.staff_has_permission((select auth.uid()),'staff.manage') then
    raise exception 'Staff management permission is required';
  end if;

  select * into v_req
  from public.member_privacy_requests
  where id=p_request_id
  for update;

  if v_req.id is null then
    raise exception 'Privacy request not found';
  end if;

  if v_req.request_type<>'data_export' then
    raise exception 'Privacy request is not a data export request';
  end if;

  if v_req.status not in ('submitted','in_review','approved','processing') then
    raise exception 'Privacy request is not eligible for export preparation';
  end if;

  v_manifest:=jsonb_build_object(
    'contact_id',v_req.contact_id,
    'requested_at',v_req.requested_at,
    'scope',v_req.scope,
    'sections',jsonb_build_array(
      'profile',
      'membership',
      'coaching',
      'goals_habits_progress',
      'health_connections_consents_observations',
      'courses',
      'notifications',
      'devices',
      'privacy_requests'
    )
  );

  insert into public.member_privacy_exports(
    privacy_request_id,user_id,contact_id,status,export_scope,manifest,created_by
  )
  values(
    v_req.id,v_req.user_id,v_req.contact_id,'queued',v_req.scope,v_manifest,(select auth.uid())
  )
  on conflict(privacy_request_id) do update
  set status=case
        when public.member_privacy_exports.status in ('ready','processing') then public.member_privacy_exports.status
        else 'queued'
      end,
      export_scope=excluded.export_scope,
      manifest=excluded.manifest,
      error_message=null,
      updated_at=now()
  returning id into v_export_id;

  update public.member_privacy_requests
  set status='processing',
      assigned_to=coalesce(assigned_to,(select auth.uid())),
      reviewed_at=coalesce(reviewed_at,now()),
      updated_at=now()
  where id=v_req.id;

  insert into public.member_privacy_actions(
    privacy_request_id,action_type,actor_user_id,detail
  )
  values(
    v_req.id,'export_queued',(select auth.uid()),
    jsonb_build_object('export_id',v_export_id)
  );

  return v_export_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_my_privacy_request(p_request_type text, p_scope jsonb DEFAULT '{}'::jsonb, p_member_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_contact_id uuid;
  v_request_id uuid;
begin
  if p_request_type not in (
    'data_export','health_data_delete','account_delete','correction','other'
  ) then
    raise exception 'Invalid privacy request type';
  end if;

  if p_member_note is not null and length(p_member_note)>4000 then
    raise exception 'Privacy request note must be 4000 characters or fewer';
  end if;

  select ca.contact_id into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access is required';
  end if;

  insert into public.member_privacy_requests(
    user_id,contact_id,request_type,scope,status,member_note
  )
  values(
    (select auth.uid()),v_contact_id,p_request_type,coalesce(p_scope,'{}'::jsonb),
    'submitted',nullif(trim(p_member_note),'')
  )
  returning id into v_request_id;

  return v_request_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.complete_privacy_export(p_export_id uuid, p_storage_path text, p_file_size_bytes bigint, p_checksum text, p_manifest jsonb DEFAULT NULL::jsonb, p_expires_at timestamp with time zone DEFAULT (now() + '7 days'::interval))
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_export public.member_privacy_exports%rowtype;
begin
  if not private.staff_has_permission((select auth.uid()),'staff.manage') then
    raise exception 'Staff management permission is required';
  end if;

  select * into v_export
  from public.member_privacy_exports
  where id=p_export_id
  for update;

  if v_export.id is null then
    raise exception 'Privacy export not found';
  end if;

  if coalesce(length(trim(p_storage_path)),0)<3 then
    raise exception 'A valid storage path is required';
  end if;

  update public.member_privacy_exports
  set status='ready',
      storage_path=trim(p_storage_path),
      file_size_bytes=p_file_size_bytes,
      checksum=nullif(trim(p_checksum),''),
      manifest=coalesce(p_manifest,manifest),
      expires_at=p_expires_at,
      ready_at=now(),
      error_message=null,
      updated_at=now()
  where id=p_export_id;

  update public.member_privacy_requests
  set status='completed',
      completed_at=now(),
      updated_at=now()
  where id=v_export.privacy_request_id;

  insert into public.member_privacy_actions(
    privacy_request_id,action_type,actor_user_id,detail
  )
  values(
    v_export.privacy_request_id,'export_ready',(select auth.uid()),
    jsonb_build_object(
      'export_id',p_export_id,
      'storage_path',trim(p_storage_path),
      'expires_at',p_expires_at
    )
  );

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.approve_health_data_delete_request(p_request_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_req public.member_privacy_requests%rowtype;
begin
  if not private.staff_has_permission((select auth.uid()),'staff.manage') then
    raise exception 'Staff management permission is required';
  end if;

  select * into v_req
  from public.member_privacy_requests
  where id=p_request_id
  for update;

  if v_req.id is null or v_req.request_type<>'health_data_delete' then
    raise exception 'Health-data deletion request not found';
  end if;

  update public.member_privacy_requests
  set status='approved',
      assigned_to=coalesce(assigned_to,(select auth.uid())),
      reviewed_at=coalesce(reviewed_at,now()),
      updated_at=now()
  where id=v_req.id;

  insert into public.member_privacy_actions(
    privacy_request_id,action_type,actor_user_id,detail
  )
  values(
    v_req.id,'health_delete_approved',(select auth.uid()),
    jsonb_build_object('scope',v_req.scope)
  );

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.execute_health_data_delete_request(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_req public.member_privacy_requests%rowtype;
  v_provider text;
  v_deleted_observations integer := 0;
  v_deleted_batches integer := 0;
begin
  if not private.staff_has_permission((select auth.uid()),'staff.manage') then
    raise exception 'Staff management permission is required';
  end if;

  select * into v_req
  from public.member_privacy_requests
  where id=p_request_id
  for update;

  if v_req.id is null or v_req.request_type<>'health_data_delete' then
    raise exception 'Health-data deletion request not found';
  end if;

  if v_req.status<>'approved' then
    raise exception 'Health-data deletion request must be approved first';
  end if;

  v_provider:=nullif(v_req.scope->>'provider_key','');

  update public.health_integration_connections
  set status='disconnected',
      credential_reference=null,
      granted_scopes='{}'::jsonb,
      last_error=null,
      updated_at=now()
  where contact_id=v_req.contact_id
    and (v_provider is null or provider_key=v_provider);

  update public.health_metric_consents
  set allowed=false,
      revoked_at=now(),
      updated_at=now()
  where contact_id=v_req.contact_id
    and (v_provider is null or provider_key=v_provider);

  delete from public.health_observations
  where contact_id=v_req.contact_id
    and (v_provider is null or provider_key=v_provider);
  get diagnostics v_deleted_observations=row_count;

  delete from public.health_mobile_sync_batches
  where contact_id=v_req.contact_id
    and (v_provider is null or provider_key=v_provider);
  get diagnostics v_deleted_batches=row_count;

  update public.member_privacy_requests
  set status='completed',
      completed_at=now(),
      updated_at=now()
  where id=v_req.id;

  insert into public.member_privacy_actions(
    privacy_request_id,action_type,actor_user_id,detail
  )
  values(
    v_req.id,'health_delete_executed',(select auth.uid()),
    jsonb_build_object(
      'provider_key',v_provider,
      'deleted_health_observations',v_deleted_observations,
      'deleted_mobile_sync_batches',v_deleted_batches
    )
  );

  return jsonb_build_object(
    'status','completed',
    'provider_key',v_provider,
    'deleted_health_observations',v_deleted_observations,
    'deleted_mobile_sync_batches',v_deleted_batches
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_payment_record_to_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_paid_total bigint;
  v_refund_total bigint;
  v_net_total bigint;
  v_activation public.journey_enrollment_activations%rowtype;
begin
  if coalesce(new.activation_id,old.activation_id) is null then
    return coalesce(new,old);
  end if;

  select * into v_activation
  from public.journey_enrollment_activations
  where id=coalesce(new.activation_id,old.activation_id);

  if v_activation.id is null then
    return coalesce(new,old);
  end if;

  select
    coalesce(sum(amount_cents) filter(
      where transaction_type in ('payment','adjustment')
        and status='recorded'
    ),0),
    coalesce(sum(amount_cents) filter(
      where transaction_type in ('refund','reversal')
        and status='recorded'
    ),0)
  into v_paid_total,v_refund_total
  from public.payment_records
  where activation_id=v_activation.id;

  v_net_total:=v_paid_total-v_refund_total;

  update public.journey_enrollment_activations
  set payment_status=case
        when v_activation.payment_status='waived' then 'waived'
        when v_activation.amount_cents is not null and v_net_total>=v_activation.amount_cents then 'paid'
        when v_net_total>0 then 'authorized'
        when v_refund_total>0 and v_net_total<=0 then 'refunded'
        else 'pending'
      end,
      paid_at=case
        when v_activation.payment_status='waived' then paid_at
        when v_activation.amount_cents is not null and v_net_total>=v_activation.amount_cents
          then coalesce(paid_at,now())
        else null
      end,
      payment_completion_method=case
        when v_activation.payment_status='waived' then payment_completion_method
        when v_activation.amount_cents is not null and v_net_total>=v_activation.amount_cents
          then coalesce(payment_completion_method,'payment_records_reconciled')
        else payment_completion_method
      end,
      payment_reference=case
        when tg_op<>'DELETE' and new.reference_number is not null then new.reference_number
        else payment_reference
      end,
      updated_at=now()
  where id=v_activation.id;

  return coalesce(new,old);
end;
$function$
;

CREATE OR REPLACE FUNCTION private.sync_staff_onboarding_from_agreements()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_staff_user_id uuid;
  v_required integer;
  v_incomplete integer;
  v_declined integer;
begin
  v_staff_user_id:=case
    when tg_table_name='staff_agreements' then coalesce(new.staff_user_id,old.staff_user_id)
    else (
      select sa.staff_user_id
      from public.staff_agreements sa
      where sa.id=coalesce(new.staff_agreement_id,old.staff_agreement_id)
    )
  end;

  if v_staff_user_id is null then
    return coalesce(new,old);
  end if;

  select
    count(*) filter(where sa.required)::integer,
    count(*) filter(where sa.required and sa.status not in ('signed','waived'))::integer,
    count(*) filter(where sa.required and sa.status='declined')::integer
  into v_required,v_incomplete,v_declined
  from public.staff_agreements sa
  where sa.staff_user_id=v_staff_user_id;

  update public.staff_access
  set onboarding_status=case
        when status<>'active' then onboarding_status
        when coalesce(v_declined,0)>0 then 'blocked'
        when coalesce(v_required,0)=0 then 'complete'
        when coalesce(v_incomplete,0)=0 then 'complete'
        else 'pending'
      end,
      updated_at=now()
  where user_id=v_staff_user_id;

  return coalesce(new,old);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_my_client_agreement_viewed(p_client_agreement_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  update public.client_agreements ca
  set status=case when ca.status='sent' then 'viewed' else ca.status end,
      viewed_at=coalesce(ca.viewed_at,now()),
      updated_at=now()
  where ca.id=p_client_agreement_id
    and ca.contact_id in (
      select access.contact_id
      from public.client_access access
      where access.user_id=(select auth.uid())
        and access.status='active'
    )
    and ca.status in ('sent','viewed');

  return found;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sign_my_client_agreement(p_client_agreement_id uuid, p_signer_name text, p_signature_type text DEFAULT 'typed'::text, p_user_agent text DEFAULT NULL::text, p_expected_content_hash text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_agreement public.client_agreements%rowtype;
  v_contact public.contacts%rowtype;
  v_acceptance_id uuid;
  v_signature_count integer;
  v_effective_hash text;
begin
  if p_signature_type<>'typed' then
    raise exception 'Self-service agreement signing supports typed signatures only';
  end if;

  if coalesce(length(trim(p_signer_name)),0)<2 then
    raise exception 'Signer name is required';
  end if;

  select ca.* into v_agreement
  from public.client_agreements ca
  where ca.id=p_client_agreement_id
    and ca.contact_id in (
      select access.contact_id
      from public.client_access access
      where access.user_id=(select auth.uid())
        and access.status='active'
    )
  for update;

  if v_agreement.id is null then
    raise exception 'Client agreement not found';
  end if;

  if v_agreement.status in ('waived','declined') then
    raise exception 'This agreement cannot be signed in its current status';
  end if;

  if v_agreement.status='signed' then
    select aa.id into v_acceptance_id
    from public.agreement_acceptances aa
    where aa.client_agreement_id=v_agreement.id
      and aa.signer_role='primary_client'
    limit 1;

    if v_acceptance_id is not null then
      return v_acceptance_id;
    end if;
  end if;

  v_effective_hash:=coalesce(v_agreement.rendered_content_hash,v_agreement.content_hash);

  if p_expected_content_hash is not null
     and p_expected_content_hash is distinct from v_effective_hash then
    raise exception 'Agreement content changed. Reload the agreement before signing';
  end if;

  select c.* into v_contact
  from public.contacts c
  where c.id=v_agreement.contact_id;

  insert into public.agreement_acceptances(
    client_agreement_id,
    contact_id,
    signed_by_user_id,
    signer_name,
    signer_email,
    signature_type,
    accepted_terms,
    content_hash,
    signed_at,
    user_agent,
    metadata,
    signer_role
  )
  values(
    v_agreement.id,
    v_agreement.contact_id,
    (select auth.uid()),
    trim(p_signer_name),
    v_contact.email,
    'typed',
    true,
    v_effective_hash,
    now(),
    nullif(trim(p_user_agent),''),
    jsonb_build_object(
      'source','member_app',
      'agreement_key',v_agreement.agreement_key,
      'template_version',v_agreement.template_version
    ),
    'primary_client'
  )
  on conflict(client_agreement_id,signer_role) do update
  set signer_name=excluded.signer_name,
      signer_email=excluded.signer_email,
      signed_by_user_id=excluded.signed_by_user_id,
      signature_type=excluded.signature_type,
      accepted_terms=true,
      content_hash=excluded.content_hash,
      signed_at=now(),
      user_agent=excluded.user_agent,
      metadata=excluded.metadata
  returning id into v_acceptance_id;

  select count(*)::integer into v_signature_count
  from public.agreement_acceptances aa
  where aa.client_agreement_id=v_agreement.id
    and aa.signer_role in ('primary_client','secondary_client');

  update public.client_agreements
  set status=case
        when v_signature_count>=greatest(coalesce(required_client_signatures,1),1)
          then 'signed'
        else 'viewed'
      end,
      viewed_at=coalesce(viewed_at,now()),
      signed_at=case
        when v_signature_count>=greatest(coalesce(required_client_signatures,1),1)
          then coalesce(signed_at,now())
        else signed_at
      end,
      updated_at=now()
  where id=v_agreement.id;

  return v_acceptance_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_my_staff_agreement_viewed(p_staff_agreement_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
