  set status=case when sa.status='sent' then 'viewed' else sa.status end,
      viewed_at=coalesce(sa.viewed_at,now()),
      updated_at=now()
  where sa.id=p_staff_agreement_id
    and sa.staff_user_id=(select auth.uid())
    and sa.status in ('sent','viewed');

