CREATE VIEW "public"."admin_app_runtime_config" WITH (security_invoker=true) AS
 SELECT c.config_key,
    c.config_type,
    c.config_value,
    c.description,
    c.member_visible,
    c.active,
    c.updated_by,
    sd.display_name AS updated_by_name,
    c.updated_at
   FROM app_runtime_config c
     LEFT JOIN staff_directory sd ON sd.user_id = c.updated_by
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'staff.manage'::text)
  ORDER BY c.config_key;

CREATE VIEW "public"."admin_billing_overview" WITH (security_invoker=true) AS
 SELECT ms.id AS subscription_id,
    ms.membership_id,
    ms.contact_id,
    TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)) AS client_name,
    c.email,
    cm.program_code,
    pc.name AS program_name,
    bp.name AS billing_plan_name,
    bp.billing_interval,
    bp.interval_count,
    bp.amount_cents,
    bp.currency,
    bp.commitment_months,
    ms.provider,
    ms.provider_customer_id,
    ms.provider_subscription_id,
    ms.status,
    ms.started_at,
    ms.next_charge_at,
    ms.commitment_ends_at,
    ms.grace_period_ends_at,
    ms.failed_payment_count,
    ms.last_payment_at,
    ms.last_payment_amount_cents,
    ms.last_failure_at,
    ms.cancel_at_period_end,
    ms.cancelled_at,
    ms.ended_at
   FROM membership_subscriptions ms
     JOIN contacts c ON c.id = ms.contact_id
     JOIN client_memberships cm ON cm.id = ms.membership_id
     LEFT JOIN program_catalog pc ON pc.program_code = cm.program_code
     LEFT JOIN billing_plans bp ON bp.id = ms.billing_plan_id;

CREATE VIEW "public"."admin_client_agreements" WITH (security_invoker=true) AS
 SELECT ca.id,
    ca.contact_id,
    ca.membership_id,
    ca.activation_id,
    ca.agreement_template_id,
    ca.agreement_key,
    ca.template_version,
    ca.content_hash,
    ca.status,
    ca.sent_at,
    ca.viewed_at,
    ca.signed_at,
    ca.declined_at,
    ca.waived_at,
    ca.waived_by,
    ca.waiver_reason,
    ca.created_by,
    ca.created_at,
    ca.updated_at,
    ca.merge_values,
    ca.rendered_content_text,
    ca.rendered_content_hash,
    ca.company_approved_by,
    ca.company_approved_at,
    ca.company_approver_name,
    ca.required_client_signatures,
    at.name AS agreement_name,
    at.description AS agreement_description,
    at.document_type,
    at.audience,
    ( SELECT count(*) AS count
           FROM agreement_acceptances aa
          WHERE aa.client_agreement_id = ca.id AND (aa.signer_role = ANY (ARRAY['primary_client'::text, 'secondary_client'::text]))) AS signature_count,
    ( SELECT jsonb_agg(jsonb_build_object('signer_role', aa.signer_role, 'signer_name', aa.signer_name, 'signer_email', aa.signer_email, 'signed_at', aa.signed_at) ORDER BY aa.signed_at) AS jsonb_agg
           FROM agreement_acceptances aa
          WHERE aa.client_agreement_id = ca.id) AS signatures
   FROM client_agreements ca
     JOIN agreement_templates at ON at.id = ca.agreement_template_id;

CREATE VIEW "public"."admin_client_attention_center" WITH (security_invoker=true) AS
 WITH base AS (
         SELECT c.id AS contact_id,
            c.first_name,
            c.last_name,
            cm.id AS membership_id,
            cm.program_code,
            pc.name AS program_name,
            cca.coach_user_id,
            sd.display_name AS coach_name,
            ( SELECT max(ch.submitted_at) AS max
                   FROM client_checkins ch
                  WHERE ch.contact_id = c.id AND (ch.status = ANY (ARRAY['submitted'::text, 'reviewed'::text]))) AS last_checkin_at,
            ( SELECT max(pe.recorded_at) AS max
                   FROM progress_entries pe
                  WHERE pe.contact_id = c.id) AS last_manual_progress_at,
            ( SELECT max(ho.observed_at) AS max
                   FROM health_observations ho
                  WHERE ho.contact_id = c.id) AS last_synced_health_at,
            ( SELECT count(*)::integer AS count
                   FROM client_goals g
                  WHERE g.contact_id = c.id AND g.status = 'active'::text) AS active_goals,
            ( SELECT count(*)::integer AS count
                   FROM client_goals g
                  WHERE g.contact_id = c.id AND g.status = 'active'::text AND g.target_date IS NOT NULL AND g.target_date < CURRENT_DATE) AS overdue_goals,
            ( SELECT count(*)::integer AS count
                   FROM client_assignments a
                  WHERE a.contact_id = c.id AND (a.status = ANY (ARRAY['assigned'::text, 'in_progress'::text])) AND a.due_at IS NOT NULL AND a.due_at < now()) AS overdue_assignments,
            ( SELECT count(*)::integer AS count
                   FROM follow_up_tasks t
                  WHERE t.contact_id = c.id AND t.status = 'open'::text AND t.due_at IS NOT NULL AND t.due_at < now()) AS overdue_staff_tasks
           FROM contacts c
             JOIN client_access ca ON ca.contact_id = c.id AND ca.status = 'active'::text
             LEFT JOIN client_memberships cm ON cm.id = ca.membership_id
             LEFT JOIN program_catalog pc ON pc.program_code = cm.program_code
             LEFT JOIN client_coach_assignments cca ON cca.contact_id = c.id AND cca.role = 'primary'::text AND cca.status = 'active'::text
             LEFT JOIN staff_directory sd ON sd.user_id = cca.coach_user_id
          WHERE private.staff_can_access_contact(( SELECT auth.uid() AS uid), c.id)
        ), signals AS (
         SELECT b.contact_id,
            b.first_name,
            b.last_name,
            b.membership_id,
            b.program_code,
            b.program_name,
            b.coach_user_id,
            b.coach_name,
            b.last_checkin_at,
            b.last_manual_progress_at,
            b.last_synced_health_at,
            b.active_goals,
            b.overdue_goals,
            b.overdue_assignments,
            b.overdue_staff_tasks,
            GREATEST(COALESCE(b.last_manual_progress_at, '1970-01-01 00:00:00+00'::timestamp with time zone), COALESCE(b.last_synced_health_at, '1970-01-01 00:00:00+00'::timestamp with time zone)) AS last_progress_at,
            array_remove(ARRAY[
                CASE
                    WHEN b.overdue_staff_tasks > 0 THEN 'overdue_staff_tasks'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN b.overdue_assignments > 0 THEN 'overdue_client_assignments'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN b.overdue_goals > 0 THEN 'overdue_goals'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN b.last_checkin_at IS NULL THEN 'no_checkin_yet'::text
                    WHEN b.last_checkin_at < (now() - '14 days'::interval) THEN 'checkin_stale'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN GREATEST(COALESCE(b.last_manual_progress_at, '1970-01-01 00:00:00+00'::timestamp with time zone), COALESCE(b.last_synced_health_at, '1970-01-01 00:00:00+00'::timestamp with time zone)) = '1970-01-01 00:00:00+00'::timestamp with time zone THEN 'no_progress_yet'::text
                    WHEN GREATEST(COALESCE(b.last_manual_progress_at, '1970-01-01 00:00:00+00'::timestamp with time zone), COALESCE(b.last_synced_health_at, '1970-01-01 00:00:00+00'::timestamp with time zone)) < (now() - '14 days'::interval) THEN 'progress_stale'::text
                    ELSE NULL::text
                END], NULL::text) AS attention_signals
           FROM base b
        )
 SELECT contact_id,
    first_name,
    last_name,
    membership_id,
    program_code,
    program_name,
    coach_user_id,
    coach_name,
    last_checkin_at,
    last_manual_progress_at,
    last_synced_health_at,
    active_goals,
    overdue_goals,
    overdue_assignments,
    overdue_staff_tasks,
    last_progress_at,
    attention_signals,
    cardinality(attention_signals) AS attention_signal_count,
        CASE
            WHEN overdue_staff_tasks > 0 THEN 'urgent'::text
            WHEN overdue_assignments > 0 OR overdue_goals > 0 THEN 'high'::text
            WHEN ('checkin_stale'::text = ANY (attention_signals)) OR ('progress_stale'::text = ANY (attention_signals)) OR ('no_checkin_yet'::text = ANY (attention_signals)) OR ('no_progress_yet'::text = ANY (attention_signals)) THEN 'normal'::text
            ELSE 'low'::text
        END AS attention_priority
   FROM signals s;

CREATE VIEW "public"."admin_client_challenge_summary" WITH (security_invoker=true) AS
 SELECT id AS contact_id,
    ( SELECT count(*) AS count
           FROM challenge_enrollments ce
          WHERE ce.status = 'active'::text AND (ce.contact_id = c.id OR (ce.household_id IN ( SELECT hm.household_id
                   FROM household_members hm
                  WHERE hm.contact_id = c.id AND hm.status = 'active'::text)))) AS active_challenges,
    ( SELECT count(*) AS count
           FROM challenge_enrollments ce
          WHERE ce.status = 'completed'::text AND (ce.contact_id = c.id OR (ce.household_id IN ( SELECT hm.household_id
                   FROM household_members hm
                  WHERE hm.contact_id = c.id AND hm.status = 'active'::text)))) AS completed_challenges,
    ( SELECT COALESCE(sum(ce.points_earned), 0::bigint) AS "coalesce"
           FROM challenge_enrollments ce
          WHERE (ce.status = ANY (ARRAY['active'::text, 'completed'::text, 'paused'::text])) AND (ce.contact_id = c.id OR (ce.household_id IN ( SELECT hm.household_id
                   FROM household_members hm
                  WHERE hm.contact_id = c.id AND hm.status = 'active'::text)))) AS challenge_points
   FROM contacts c
  WHERE (EXISTS ( SELECT 1
           FROM client_access ca
          WHERE ca.contact_id = c.id));

CREATE VIEW "public"."admin_client_coaching_entitlements" WITH (security_invoker=true) AS
 SELECT cm.id AS membership_id,
    cm.primary_contact_id AS contact_id,
    me.id AS entitlement_id,
    me.entitlement_key,
    me.label,
    me.status,
    me.limit_value,
    me.used_value,
        CASE
            WHEN me.limit_value IS NULL THEN NULL::integer
            ELSE GREATEST(0, me.limit_value - me.used_value)
        END AS remaining_value,
    me.reset_cadence,
    ( SELECT count(*) AS count
           FROM coaching_entitlement_usage ceu
          WHERE ceu.membership_id = cm.id AND ceu.entitlement_key = me.entitlement_key AND ceu.status = 'reserved'::text) AS reserved_sessions,
    ( SELECT count(*) AS count
           FROM coaching_entitlement_usage ceu
          WHERE ceu.membership_id = cm.id AND ceu.entitlement_key = me.entitlement_key AND ceu.status = 'review'::text) AS review_sessions
   FROM client_memberships cm
     JOIN membership_entitlements me ON me.membership_id = cm.id
  WHERE me.entitlement_key = ANY (ARRAY['private_coaching'::text, 'group_coaching'::text]);

CREATE VIEW "public"."admin_client_coaching_summary" WITH (security_invoker=true) AS
 SELECT c.id AS contact_id,
    c.first_name,
    c.last_name,
    ca.status AS access_status,
    cm.id AS membership_id,
    cm.program_code,
    pc.name AS program_name,
    cca.coach_user_id,
    sd.display_name AS coach_name,
    ( SELECT count(*) AS count
           FROM client_goals g
          WHERE g.contact_id = c.id AND g.status = 'active'::text) AS active_goals,
    ( SELECT count(*) AS count
           FROM client_habits h
          WHERE h.contact_id = c.id AND h.status = 'active'::text) AS active_habits,
    ( SELECT max(ch.submitted_at) AS max
           FROM client_checkins ch
          WHERE ch.contact_id = c.id AND (ch.status = ANY (ARRAY['submitted'::text, 'reviewed'::text]))) AS last_checkin_at,
    ( SELECT count(*) AS count
           FROM client_assignments a
          WHERE a.contact_id = c.id AND (a.status = ANY (ARRAY['assigned'::text, 'in_progress'::text]))) AS open_assignments,
    ( SELECT max(pe.recorded_at) AS max
           FROM progress_entries pe
          WHERE pe.contact_id = c.id) AS last_progress_at
   FROM contacts c
     JOIN client_access ca ON ca.contact_id = c.id
     LEFT JOIN client_memberships cm ON cm.id = ca.membership_id
     LEFT JOIN program_catalog pc ON pc.program_code = cm.program_code
     LEFT JOIN client_coach_assignments cca ON cca.contact_id = c.id AND cca.role = 'primary'::text AND cca.status = 'active'::text
     LEFT JOIN staff_directory sd ON sd.user_id = cca.coach_user_id;

CREATE VIEW "public"."admin_client_documents" WITH (security_invoker=true) AS
 SELECT d.id,
    d.contact_id,
    d.membership_id,
    d.category,
    d.title,
    d.description,
    d.storage_path,
    d.original_filename,
    d.content_type,
    d.size_bytes,
    d.member_visible,
    d.status,
    d.uploaded_by_user_id,
    d.uploaded_by_contact_id,
    d.created_at,
    d.updated_at,
    sd.display_name AS uploaded_by_name
   FROM client_documents d
     LEFT JOIN staff_directory sd ON sd.user_id = d.uploaded_by_user_id
  WHERE d.status = 'active'::text;

CREATE VIEW "public"."admin_client_health_integration_summary" WITH (security_invoker=true) AS
 SELECT c.id AS contact_id,
    count(hc.id) FILTER (WHERE hc.status = 'connected'::text) AS connected_providers,
    max(hc.last_successful_sync_at) AS last_successful_sync_at,
    count(hc.id) FILTER (WHERE hc.status = 'attention_needed'::text) AS connections_needing_attention,
    ( SELECT count(*) AS count
           FROM health_observations ho
          WHERE ho.contact_id = c.id AND ho.observed_at >= (now() - '24:00:00'::interval)) AS observations_24h
   FROM contacts c
     LEFT JOIN health_integration_connections hc ON hc.contact_id = c.id
  WHERE (EXISTS ( SELECT 1
           FROM client_access ca
          WHERE ca.contact_id = c.id))
  GROUP BY c.id;

CREATE VIEW "public"."admin_client_learning_detail" WITH (security_invoker=true) AS
 SELECT e.id AS enrollment_id,
    e.contact_id,
    e.membership_id,
    e.course_id,
    c.title AS course_title,
    c.status AS course_status,
    e.source,
    e.status AS enrollment_status,
    e.progress_percent,
    e.started_at,
    e.completed_at,
    e.last_activity_at,
    ( SELECT count(*) AS count
           FROM learning_lessons l
             JOIN learning_modules m ON m.id = l.module_id
          WHERE m.course_id = e.course_id AND m.active AND l.status = 'published'::text AND l.requires_completion) AS required_lessons,
    ( SELECT count(*) AS count
           FROM lesson_progress lp
          WHERE lp.enrollment_id = e.id AND lp.status = 'completed'::text) AS completed_lessons
   FROM client_course_enrollments e
     JOIN learning_courses c ON c.id = e.course_id;

CREATE VIEW "public"."admin_client_learning_summary" WITH (security_invoker=true) AS
 SELECT id AS contact_id,
    ( SELECT count(*) AS count
           FROM client_course_enrollments e
          WHERE e.contact_id = c.id AND e.status = 'active'::text) AS active_courses,
    ( SELECT count(*) AS count
           FROM client_course_enrollments e
          WHERE e.contact_id = c.id AND e.status = 'completed'::text) AS completed_courses,
    ( SELECT round(avg(e.progress_percent))::integer AS round
           FROM client_course_enrollments e
          WHERE e.contact_id = c.id AND (e.status = ANY (ARRAY['active'::text, 'completed'::text]))) AS average_course_progress,
    ( SELECT count(*) AS count
           FROM client_resource_assignments r
          WHERE r.contact_id = c.id AND r.status = 'assigned'::text) AS assigned_resources
   FROM contacts c
  WHERE (EXISTS ( SELECT 1
           FROM client_access ca
          WHERE ca.contact_id = c.id));

CREATE VIEW "public"."admin_client_wellness_summary" WITH (security_invoker=true) AS
 SELECT id AS contact_id,
    ( SELECT count(*) AS count
           FROM client_meal_plans mp
          WHERE mp.contact_id = c.id AND mp.status = 'active'::text) AS active_meal_plans,
    ( SELECT count(*) AS count
           FROM client_fitness_plans fp
          WHERE fp.contact_id = c.id AND fp.status = 'active'::text) AS active_fitness_plans,
    ( SELECT count(*) AS count
           FROM client_workout_assignments wa
          WHERE wa.contact_id = c.id AND wa.status = 'assigned'::text AND wa.scheduled_date >= CURRENT_DATE AND wa.scheduled_date <= (CURRENT_DATE + 7)) AS upcoming_workouts,
    ( SELECT count(*) AS count
           FROM client_meal_plan_items mi
          WHERE mi.contact_id = c.id AND mi.status = 'planned'::text AND mi.scheduled_date >= CURRENT_DATE AND mi.scheduled_date <= (CURRENT_DATE + 7)) AS upcoming_meals,
    ( SELECT avg(nl.adherence_percent) AS avg
           FROM nutrition_logs nl
          WHERE nl.contact_id = c.id AND nl.log_date >= (CURRENT_DATE - 6) AND nl.adherence_percent IS NOT NULL) AS nutrition_adherence_7d
   FROM contacts c
  WHERE (EXISTS ( SELECT 1
           FROM client_access ca
          WHERE ca.contact_id = c.id));

CREATE VIEW "public"."admin_coach_capacity" WITH (security_invoker=true) AS
 SELECT sa.user_id,
    sa.display_name,
    sa.role,
    COALESCE(scs.accepts_new_clients, true) AS accepts_new_clients,
    scs.max_active_clients,
    scs.max_sessions_per_day,
    scs.max_sessions_per_week,
    COALESCE(scs.session_buffer_minutes, 15) AS session_buffer_minutes,
    COALESCE(scs.default_session_minutes, 60) AS default_session_minutes,
    scs.time_zone,
    ( SELECT count(*) AS count
           FROM client_coach_assignments cca
          WHERE cca.coach_user_id = sa.user_id AND cca.role = 'primary'::text AND cca.status = 'active'::text) AS active_clients,
    ( SELECT count(*) AS count
           FROM coaching_sessions cs
          WHERE cs.coach_user_id = sa.user_id AND cs.status = 'scheduled'::text AND cs.scheduled_start >= date_trunc('week'::text, now()) AND cs.scheduled_start < (date_trunc('week'::text, now()) + '7 days'::interval)) AS scheduled_sessions_this_week,
        CASE
            WHEN scs.max_active_clients IS NULL THEN NULL::bigint
            ELSE GREATEST(0::bigint, scs.max_active_clients - (( SELECT count(*) AS count
               FROM client_coach_assignments cca
              WHERE cca.coach_user_id = sa.user_id AND cca.role = 'primary'::text AND cca.status = 'active'::text)))
        END AS remaining_client_capacity
   FROM staff_access sa
     LEFT JOIN staff_capacity_settings scs ON scs.user_id = sa.user_id
  WHERE sa.status = 'active'::text AND (sa.role = ANY (ARRAY['owner'::text, 'admin'::text, 'coach'::text]));

CREATE VIEW "public"."admin_community_feed" WITH (security_invoker=true) AS
 SELECT p.id AS post_id,
    p.space_id,
    s.name AS space_name,
    s.space_type,
    p.author_user_id,
    p.author_contact_id,
    COALESCE(sa.display_name, c.first_name, 'ReVitalized Member'::text) AS author_name,
    p.post_type,
    p.title,
    p.body,
    p.status,
    p.pinned,
    p.created_at,
    p.updated_at,
    ( SELECT count(*) AS count
           FROM community_comments cc
          WHERE cc.post_id = p.id AND cc.status = 'published'::text) AS comment_count,
    ( SELECT count(*) AS count
           FROM community_reactions cr
          WHERE cr.post_id = p.id) AS reaction_count
   FROM community_posts p
     JOIN community_spaces s ON s.id = p.space_id
     LEFT JOIN staff_access sa ON sa.user_id = p.author_user_id
     LEFT JOIN contacts c ON c.id = p.author_contact_id
  ORDER BY p.pinned DESC, p.created_at DESC;

CREATE VIEW "public"."admin_community_metrics" WITH (security_invoker=true) AS
 SELECT ( SELECT count(*) AS count
           FROM community_spaces
          WHERE community_spaces.status = 'active'::text) AS active_spaces,
    ( SELECT count(*) AS count
           FROM community_posts
          WHERE community_posts.status = 'published'::text AND community_posts.created_at >= (now() - '7 days'::interval)) AS posts_7d,
    ( SELECT count(*) AS count
           FROM community_comments
          WHERE community_comments.status = 'published'::text AND community_comments.created_at >= (now() - '7 days'::interval)) AS comments_7d,
    ( SELECT count(*) AS count
           FROM community_reactions
          WHERE community_reactions.created_at >= (now() - '7 days'::interval)) AS reactions_7d,
    ( SELECT count(*) AS count
           FROM community_memberships
          WHERE community_memberships.status = 'active'::text) AS active_space_memberships;

CREATE VIEW "public"."admin_community_spaces" WITH (security_invoker=true) AS
 SELECT id AS space_id,
    space_key,
    name,
    description,
    space_type,
    program_code,
    household_id,
    challenge_id,
    status,
    posting_mode,
    ( SELECT count(*) AS count
           FROM community_memberships cm
          WHERE cm.space_id = s.id AND cm.status = 'active'::text) AS active_members,
    ( SELECT count(*) AS count
           FROM community_posts p
          WHERE p.space_id = s.id AND p.status = 'published'::text) AS published_posts,
    ( SELECT max(p.created_at) AS max
           FROM community_posts p
          WHERE p.space_id = s.id AND p.status = 'published'::text) AS last_post_at
   FROM community_spaces s
  ORDER BY (
        CASE space_type
            WHEN 'program'::text THEN 1
            WHEN 'household'::text THEN 2
            WHEN 'challenge'::text THEN 3
            ELSE 4
        END), name;

CREATE VIEW "public"."admin_companion_ingestion_queue" WITH (security_invoker=true) AS
 SELECT j.id AS job_id,
    j.source_id,
    s.source_key,
    s.title,
    s.version,
    s.status AS source_status,
    s.ingestion_status AS source_ingestion_status,
    j.job_type,
    j.status AS job_status,
    j.requested_by,
    sd.display_name AS requested_by_name,
    j.started_at,
    j.completed_at,
    j.chunk_count,
    j.embedded_chunk_count,
    j.error_message,
    j.created_at,
    j.updated_at
   FROM coach_companion_ingestion_jobs j
     JOIN coach_companion_knowledge_sources s ON s.id = j.source_id
     LEFT JOIN staff_directory sd ON sd.user_id = j.requested_by
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'companion.manage'::text)
  ORDER BY (
        CASE j.status
            WHEN 'failed'::text THEN 1
            WHEN 'processing'::text THEN 2
            WHEN 'queued'::text THEN 3
            ELSE 4
        END), j.created_at;

CREATE VIEW "public"."admin_companion_knowledge_readiness" WITH (security_invoker=true) AS
 SELECT count(*)::integer AS total_sources,
    count(*) FILTER (WHERE status = 'approved'::text)::integer AS approved_sources,
    count(*) FILTER (WHERE status <> 'approved'::text)::integer AS nonapproved_sources,
    count(*) FILTER (WHERE status = 'approved'::text AND approved_at IS NULL)::integer AS approved_missing_timestamp,
    count(*) FILTER (WHERE status = 'approved'::text AND COALESCE(length(TRIM(BOTH FROM content_text)), 0) = 0)::integer AS approved_missing_content,
    count(*) FILTER (WHERE status = 'approved'::text AND (EXISTS ( SELECT 1
           FROM coach_companion_knowledge_chunks ch
          WHERE ch.source_id = coach_companion_knowledge_sources.id AND ch.active AND ch.embedding IS NOT NULL)))::integer AS approved_sources_with_embeddings,
    count(*) FILTER (WHERE status = 'approved'::text AND NOT (EXISTS ( SELECT 1
           FROM coach_companion_knowledge_chunks ch
          WHERE ch.source_id = coach_companion_knowledge_sources.id AND ch.active AND ch.embedding IS NOT NULL)))::integer AS approved_sources_without_embeddings
   FROM coach_companion_knowledge_sources
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'companion.manage'::text);

CREATE VIEW "public"."admin_companion_operations_summary" WITH (security_invoker=true) AS
 SELECT count(*)::integer AS total_requests,
    count(*) FILTER (WHERE created_at >= (now() - '24:00:00'::interval))::integer AS requests_24h,
    count(*) FILTER (WHERE created_at >= (now() - '7 days'::interval))::integer AS requests_7d,
    count(*) FILTER (WHERE created_at >= (now() - '30 days'::interval))::integer AS requests_30d,
    count(*) FILTER (WHERE status = ANY (ARRAY['queued'::text, 'retrieving'::text, 'draft_ready'::text]))::integer AS processing_requests,
    count(*) FILTER (WHERE status = ANY (ARRAY['coach_review'::text, 'escalated'::text]))::integer AS review_backlog,
    count(*) FILTER (WHERE status = ANY (ARRAY['answered'::text, 'resolved'::text]))::integer AS answered_requests,
    count(*) FILTER (WHERE handling_mode = 'block_and_escalate'::text)::integer AS blocked_or_escalated_requests,
    round(avg(retrieval_confidence) FILTER (WHERE retrieval_confidence IS NOT NULL), 3) AS avg_retrieval_confidence,
    round(avg(answer_confidence) FILTER (WHERE answer_confidence IS NOT NULL), 3) AS avg_answer_confidence,
    round(avg(EXTRACT(epoch FROM answered_at - created_at) / 60::numeric) FILTER (WHERE answered_at IS NOT NULL), 1) AS avg_minutes_to_answer,
    count(*) FILTER (WHERE answered_by_type = 'companion'::text)::integer AS ai_answered,
    count(*) FILTER (WHERE answered_by_type = ANY (ARRAY['coach'::text, 'staff'::text]))::integer AS human_answered
   FROM coach_companion_requests
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'companion.manage'::text);

CREATE VIEW "public"."admin_companion_quality_queue" WITH (security_invoker=true) AS
 SELECT f.id AS feedback_id,
    f.request_id,
    f.contact_id,
    c.first_name,
    c.last_name,
    r.question_type,
    r.question,
    r.final_answer,
    r.answered_by_type,
    r.retrieval_confidence,
    r.answer_confidence,
    f.helpful,
    f.feedback_reason,
    f.comment,
    f.created_at AS feedback_created_at,
    cr.id AS review_id,
    cr.status AS review_status,
    cr.assigned_to
   FROM coach_companion_answer_feedback f
     JOIN coach_companion_requests r ON r.id = f.request_id
     JOIN contacts c ON c.id = f.contact_id
     LEFT JOIN coach_companion_reviews cr ON cr.request_id = f.request_id
  WHERE f.helpful = false AND private.staff_has_permission(( SELECT auth.uid() AS uid), 'companion.manage'::text)
  ORDER BY f.created_at DESC;

CREATE VIEW "public"."admin_companion_quality_summary" WITH (security_invoker=true) AS
 SELECT count(*)::integer AS feedback_count,
    count(*) FILTER (WHERE helpful = true)::integer AS helpful_count,
    count(*) FILTER (WHERE helpful = false)::integer AS not_helpful_count,
    round(100::numeric * count(*) FILTER (WHERE helpful = true)::numeric / NULLIF(count(*), 0)::numeric, 1) AS helpful_percent,
    count(*) FILTER (WHERE feedback_reason = 'incorrect'::text)::integer AS incorrect_count,
    count(*) FILTER (WHERE feedback_reason = 'not_relevant'::text)::integer AS not_relevant_count,
    count(*) FILTER (WHERE feedback_reason = 'unclear'::text)::integer AS unclear_count,
    count(*) FILTER (WHERE feedback_reason = 'missing_context'::text)::integer AS missing_context_count,
    count(*) FILTER (WHERE feedback_reason = 'too_generic'::text)::integer AS too_generic_count,
    count(*) FILTER (WHERE feedback_reason = 'needs_coach'::text)::integer AS needs_coach_count
   FROM coach_companion_answer_feedback
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'companion.manage'::text);

CREATE VIEW "public"."admin_companion_review_queue" WITH (security_invoker=true) AS
 SELECT cr.id AS review_id,
    cr.request_id,
    cr.contact_id,
    c.first_name,
    c.last_name,
    c.email,
    r.question_type,
    qt.label AS question_type_label,
    r.question,
    r.handling_mode,
    r.status AS request_status,
    r.retrieval_confidence,
    r.answer_confidence,
    r.draft_answer,
    r.escalation_reason,
    cr.assigned_to,
    sd.display_name AS assigned_name,
    cr.status AS review_status,
    cr.review_reason,
    cr.created_at
   FROM coach_companion_reviews cr
     JOIN coach_companion_requests r ON r.id = cr.request_id
     JOIN contacts c ON c.id = cr.contact_id
     LEFT JOIN coach_companion_question_types qt ON qt.question_type = r.question_type
     LEFT JOIN staff_directory sd ON sd.user_id = cr.assigned_to
  WHERE cr.status = ANY (ARRAY['open'::text, 'in_review'::text]);

CREATE VIEW "public"."admin_companion_source_health" WITH (security_invoker=true) AS
 SELECT s.id AS source_id,
    s.source_key,
    s.title,
    s.source_type,
    s.version,
    s.status,
    s.approved_at,
    count(ch.id)::integer AS total_chunks,
    count(ch.id) FILTER (WHERE ch.active)::integer AS active_chunks,
    count(ch.id) FILTER (WHERE ch.active AND ch.embedding IS NOT NULL)::integer AS embedded_chunks,
    count(ch.id) FILTER (WHERE ch.active AND ch.embedding IS NULL)::integer AS missing_embeddings,
    max(ch.embedding_updated_at) AS last_embedding_at,
    max(r.captured_at) AS last_revision_at
   FROM coach_companion_knowledge_sources s
     LEFT JOIN coach_companion_knowledge_chunks ch ON ch.source_id = s.id
     LEFT JOIN coach_companion_source_revisions r ON r.source_id = s.id
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'companion.manage'::text)
  GROUP BY s.id, s.source_key, s.title, s.source_type, s.version, s.status, s.approved_at
  ORDER BY (
        CASE s.status
            WHEN 'approved'::text THEN 1
            ELSE 2
        END), s.title;

CREATE VIEW "public"."admin_companion_sources_needing_review" WITH (security_invoker=true) AS
 SELECT id AS source_id,
    source_key,
    title,
    source_type,
    version,
    status,
    ingestion_status,
    approved_at,
    review_due_at,
        CASE
            WHEN status = 'approved'::text AND review_due_at IS NOT NULL AND review_due_at < now() THEN 'review_overdue'::text
            WHEN ingestion_status = 'failed'::text THEN 'ingestion_failed'::text
            WHEN status = 'draft'::text AND ingestion_status = 'ready'::text THEN 'ready_for_approval'::text
            WHEN status = 'draft'::text AND ingestion_status = 'queued'::text THEN 'awaiting_ingestion'::text
            WHEN ingestion_status = 'stale'::text THEN 'stale'::text
            ELSE 'other'::text
        END AS attention_reason
   FROM coach_companion_knowledge_sources s
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'companion.manage'::text) AND (status = 'approved'::text AND review_due_at IS NOT NULL AND review_due_at < now() OR (ingestion_status = ANY (ARRAY['failed'::text, 'stale'::text])) OR status = 'draft'::text AND (ingestion_status = ANY (ARRAY['ready'::text, 'queued'::text])))
  ORDER BY (
        CASE
            WHEN status = 'approved'::text AND review_due_at IS NOT NULL AND review_due_at < now() THEN 1
            WHEN ingestion_status = 'failed'::text THEN 2
            WHEN ingestion_status = 'stale'::text THEN 3
            WHEN status = 'draft'::text AND ingestion_status = 'ready'::text THEN 4
            ELSE 5
        END), updated_at;

CREATE VIEW "public"."admin_companion_usage_summary_30d" WITH (security_invoker=true) AS
 SELECT count(*)::integer AS total_events_30d,
    count(*) FILTER (WHERE event_type = 'question_submitted'::text)::integer AS questions_30d,
    count(*) FILTER (WHERE event_type = 'answer_generated'::text)::integer AS generated_answers_30d,
    count(*) FILTER (WHERE event_type = 'answer_delivered'::text)::integer AS delivered_answers_30d,
    count(*) FILTER (WHERE event_type = 'escalated'::text)::integer AS escalations_30d,
    count(*) FILTER (WHERE event_type = 'coach_reviewed'::text)::integer AS coach_reviews_30d,
    COALESCE(sum(input_tokens), 0::bigint) AS input_tokens_30d,
    COALESCE(sum(output_tokens), 0::bigint) AS output_tokens_30d,
    COALESCE(sum(estimated_cost_micros), 0::numeric)::bigint AS estimated_cost_micros_30d
   FROM coach_companion_usage_events
  WHERE occurred_at >= (now() - '30 days'::interval) AND private.staff_has_permission(( SELECT auth.uid() AS uid), 'companion.manage'::text);

CREATE VIEW "public"."admin_contact_conversations" WITH (security_invoker=true) AS
 SELECT id AS conversation_id,
    conversation_type,
    contact_id,
    household_id,
    membership_id,
    title,
    status,
    last_message_at,
    ( SELECT "left"(m.body, 220) AS "left"
           FROM member_messages m
          WHERE m.conversation_id = c.id AND m.deleted_at IS NULL
          ORDER BY m.created_at DESC
         LIMIT 1) AS last_message_preview
   FROM member_conversations c
  WHERE status = 'active'::text;

CREATE VIEW "public"."admin_contact_journey_summary" WITH (security_invoker=true) AS
 SELECT cj.contact_id,
    cj.id AS journey_id,
    cj.journey_key,
    jd.name AS journey_name,
    cj.status AS journey_status,
    cj.current_step_key,
    s.name AS current_step_name,
    s.status AS current_step_status,
    s.due_at AS current_step_due_at,
    cj.progress_percent,
    cj.assigned_to,
    cj.last_activity_at,
    cj.next_action_at,
    COALESCE(ce.intent_score, 0) AS intent_score,
    COALESCE(ce.temperature, 'cold'::text) AS temperature,
    ( SELECT count(*) AS count
           FROM contact_journey_steps x
          WHERE x.journey_id = cj.id AND (x.status = ANY (ARRAY['completed'::text, 'skipped'::text, 'waived'::text]))) AS completed_steps,
    ( SELECT count(*) AS count
           FROM contact_journey_steps x
          WHERE x.journey_id = cj.id) AS total_steps
   FROM contact_journeys cj
     JOIN journey_definitions jd ON jd.journey_key = cj.journey_key
     LEFT JOIN contact_journey_steps s ON s.journey_id = cj.id AND s.step_key = cj.current_step_key
     LEFT JOIN contact_engagement ce ON ce.contact_id = cj.contact_id
  WHERE cj.status = ANY (ARRAY['active'::text, 'paused'::text, 'nurture'::text]);

CREATE VIEW "public"."admin_contact_next_step" WITH (security_invoker=true) AS
 SELECT c.id AS contact_id,
    cj.id AS journey_id,
    cj.journey_key,
    jd.name AS journey_name,
    cj.status AS journey_status,
    cj.current_step_key,
    s.id AS step_id,
    s.name AS current_step_name,
    s.step_type,
    s.status AS current_step_status,
    s.due_at,
    cj.progress_percent,
    ce.temperature,
    ce.intent_score,
    a.id AS appointment_id,
    a.appointment_type,
    a.status AS appointment_status,
    a.scheduled_start,
    a.time_zone AS appointment_time_zone,
    a.format AS appointment_format,
    ea.id AS activation_id,
    ea.program_code,
    ea.program_name,
    ea.payment_status,
    ea.agreement_status,
    ea.access_status,
    ea.payment_url,
    ea.agreement_url
   FROM contacts c
     JOIN contact_journeys cj ON cj.contact_id = c.id AND (cj.status = ANY (ARRAY['active'::text, 'paused'::text, 'nurture'::text]))
     JOIN journey_definitions jd ON jd.journey_key = cj.journey_key
     LEFT JOIN contact_journey_steps s ON s.journey_id = cj.id AND s.step_key = cj.current_step_key
     LEFT JOIN LATERAL ( SELECT x.id,
            x.contact_id,
            x.journey_id,
            x.journey_step_id,
            x.appointment_type,
            x.status,
            x.provider,
            x.provider_event_id,
            x.scheduled_start,
            x.scheduled_end,
            x.time_zone,
            x.format,
            x.location_url,
            x.requested_availability,
            x.client_notes,
            x.staff_notes,
            x.assigned_to,
            x.created_by,
            x.created_at,
            x.updated_at,
            x.completed_at
           FROM journey_appointments x
          WHERE x.journey_id = cj.id AND (x.status = ANY (ARRAY['requested'::text, 'scheduled'::text]))
          ORDER BY x.created_at DESC
         LIMIT 1) a ON true
     LEFT JOIN LATERAL ( SELECT x.id,
            x.contact_id,
            x.journey_id,
            x.journey_step_id,
            x.program_code,
            x.program_name,
            x.billing_choice,
            x.commitment_months,
            x.amount_cents,
            x.currency,
            x.payment_provider,
            x.provider_customer_id,
            x.provider_subscription_id,
            x.provider_payment_id,
            x.payment_url,
            x.payment_status,
            x.agreement_status,
            x.agreement_url,
            x.agreement_signed_at,
            x.access_status,
            x.metadata,
            x.created_by,
            x.created_at,
            x.updated_at,
            x.paid_at
           FROM journey_enrollment_activations x
          WHERE x.journey_id = cj.id
          ORDER BY x.created_at DESC
         LIMIT 1) ea ON true
     LEFT JOIN contact_engagement ce ON ce.contact_id = c.id;

CREATE VIEW "public"."admin_contact_overview" WITH (security_invoker=true) AS
 SELECT c.id,
    c.first_name,
    c.last_name,
    c.email,
    c.phone,
    c.city,
    c.state,
    c.country,
    c.lifecycle_stage,
    c.follow_up_status,
    c.consultation_status,
    c.assigned_to,
    c.next_follow_up_at,
    c.first_source,
    c.last_source,
    c.created_at,
    c.updated_at,
    va.status AS vitality_status,
    va.completion_percent AS vitality_completion,
    va.current_step AS vitality_step,
    en.status AS enrollment_status,
    en.completion_percent AS enrollment_completion,
    en.current_step AS enrollment_step,
    wr.status AS webinar_status,
    wr.payment_status AS webinar_payment_status,
    wr.registered_at AS webinar_registered_at,
    wr.primary_goal AS webinar_primary_goal,
    ri.status AS refuel_status,
    ri.created_at AS refuel_joined_at,
    ( SELECT max(n.created_at) AS max
           FROM contact_notes n
          WHERE n.contact_id = c.id) AS last_note_at,
    ( SELECT count(*) AS count
           FROM follow_up_tasks t
          WHERE t.contact_id = c.id AND t.status = 'open'::text) AS open_tasks,
    ( SELECT max(a.created_at) AS max
           FROM contact_activity a
          WHERE a.contact_id = c.id) AS last_activity_at
   FROM contacts c
     LEFT JOIN workflow_records va ON va.contact_id = c.id AND va.workflow_type = 'vitality_assessment'::text AND va.status <> 'abandoned'::text
     LEFT JOIN workflow_records en ON en.contact_id = c.id AND en.workflow_type = 'enrollment'::text AND en.status <> 'abandoned'::text
     LEFT JOIN webinar_registrations wr ON wr.contact_id = c.id
     LEFT JOIN refuel_interest ri ON ri.contact_id = c.id;

CREATE VIEW "public"."admin_conversion_funnel" WITH (security_invoker=true) AS
 SELECT stage_order,
    stage_name,
    stage_count
   FROM ( VALUES (1,'Total Contacts'::text,( SELECT count(*) AS count
                   FROM contacts)), (2,'Assessment Leads'::text,( SELECT count(*) AS count
                   FROM contacts
                  WHERE contacts.lifecycle_stage = 'assessment_lead'::text)), (3,'Applicants'::text,( SELECT count(*) AS count
                   FROM contacts
                  WHERE contacts.lifecycle_stage = 'applicant'::text)), (4,'Paid Enrollments'::text,( SELECT count(DISTINCT journey_enrollment_activations.contact_id) AS count
                   FROM journey_enrollment_activations
                  WHERE journey_enrollment_activations.payment_status = 'paid'::text)), (5,'Active Members'::text,( SELECT count(DISTINCT client_memberships.primary_contact_id) AS count
                   FROM client_memberships
                  WHERE client_memberships.status = 'active'::text))) funnel(stage_order, stage_name, stage_count);

CREATE VIEW "public"."admin_dashboard_metrics" WITH (security_invoker=true) AS
 SELECT count(*) AS total_contacts,
    count(*) FILTER (WHERE lifecycle_stage = 'assessment_lead'::text) AS assessment_leads,
    count(*) FILTER (WHERE lifecycle_stage = 'webinar_lead'::text) AS webinar_leads,
    count(*) FILTER (WHERE lifecycle_stage = 'applicant'::text) AS applicants,
    count(*) FILTER (WHERE lifecycle_stage = 'client'::text) AS clients,
    count(*) FILTER (WHERE follow_up_status = 'needs_follow_up'::text) AS needs_follow_up,
    count(*) FILTER (WHERE consultation_status = 'scheduled'::text) AS consultations_scheduled,
    count(*) FILTER (WHERE next_follow_up_at IS NOT NULL AND next_follow_up_at <= (now() + '24:00:00'::interval) AND follow_up_status <> 'closed'::text) AS followups_due_24h,
    count(*) FILTER (WHERE (EXISTS ( SELECT 1
           FROM workflow_records w
          WHERE w.contact_id = contacts.id AND w.workflow_type = 'vitality_assessment'::text AND w.status = 'completed'::text))) AS completed_assessments,
    count(*) FILTER (WHERE (EXISTS ( SELECT 1
           FROM workflow_records w
          WHERE w.contact_id = contacts.id AND w.workflow_type = 'enrollment'::text AND w.status = 'completed'::text))) AS completed_enrollments,
    count(*) FILTER (WHERE (EXISTS ( SELECT 1
           FROM webinar_registrations r
          WHERE r.contact_id = contacts.id AND r.status <> 'cancelled'::text))) AS webinar_registrations,
    count(*) FILTER (WHERE (EXISTS ( SELECT 1
           FROM webinar_registrations r
          WHERE r.contact_id = contacts.id AND (r.status = ANY (ARRAY['seat_reserved'::text, 'confirmed'::text, 'attended'::text]))))) AS webinar_confirmed,
    count(*) FILTER (WHERE (EXISTS ( SELECT 1
           FROM refuel_interest r
          WHERE r.contact_id = contacts.id AND r.status <> 'unsubscribed'::text))) AS refuel_interest
   FROM contacts;

CREATE VIEW "public"."admin_due_tasks" WITH (security_invoker=true) AS
 SELECT t.id,
    t.contact_id,
    t.title,
    t.due_at,
    t.status,
    t.priority,
    t.assigned_to,
    c.first_name,
    c.last_name,
    c.email,
    c.phone
   FROM follow_up_tasks t
     JOIN contacts c ON c.id = t.contact_id
  WHERE t.status = 'open'::text
  ORDER BY (
        CASE t.priority
            WHEN 'urgent'::text THEN 1
            WHEN 'high'::text THEN 2
            WHEN 'normal'::text THEN 3
            ELSE 4
        END), t.due_at, t.created_at DESC;

CREATE VIEW "public"."admin_enrollment_readiness" WITH (security_invoker=true) AS
 WITH payment_totals AS (
         SELECT pr.activation_id,
            COALESCE(sum(pr.amount_cents) FILTER (WHERE (pr.transaction_type = ANY (ARRAY['payment'::text, 'adjustment'::text])) AND pr.status = 'recorded'::text), 0::bigint) AS gross_paid_cents,
            COALESCE(sum(pr.amount_cents) FILTER (WHERE (pr.transaction_type = ANY (ARRAY['refund'::text, 'reversal'::text])) AND pr.status = 'recorded'::text), 0::bigint) AS refunded_cents
           FROM payment_records pr
          WHERE pr.activation_id IS NOT NULL
          GROUP BY pr.activation_id
        ), agreement_rollup AS (
         SELECT ca.activation_id,
            count(*)::integer AS agreement_count,
            count(*) FILTER (WHERE ca.status = 'signed'::text)::integer AS signed_agreements,
            count(*) FILTER (WHERE ca.status = 'waived'::text)::integer AS waived_agreements,
            count(*) FILTER (WHERE ca.status = 'declined'::text)::integer AS declined_agreements,
            count(*) FILTER (WHERE ca.status <> ALL (ARRAY['signed'::text, 'waived'::text]))::integer AS incomplete_agreements,
            COALESCE(sum(ca.required_client_signatures), 0::bigint)::integer AS required_signatures,
            COALESCE(sum(( SELECT count(*) AS count
                   FROM agreement_acceptances aa
                  WHERE aa.client_agreement_id = ca.id AND (aa.signer_role = ANY (ARRAY['primary_client'::text, 'secondary_client'::text])))), 0::numeric)::integer AS collected_signatures
           FROM client_agreements ca
          WHERE ca.activation_id IS NOT NULL
          GROUP BY ca.activation_id
        )
 SELECT a.id AS activation_id,
    a.contact_id,
    c.first_name,
    c.last_name,
    c.email,
    a.program_code,
    a.program_name,
    a.billing_choice,
    a.amount_cents AS agreed_amount_cents,
    a.currency,
    a.payment_status,
    COALESCE(pt.gross_paid_cents, 0::bigint) AS gross_paid_cents,
    COALESCE(pt.refunded_cents, 0::bigint) AS refunded_cents,
    GREATEST(COALESCE(pt.gross_paid_cents, 0::bigint) - COALESCE(pt.refunded_cents, 0::bigint), 0::bigint) AS net_paid_cents,
    GREATEST(COALESCE(a.amount_cents, 0) - GREATEST(COALESCE(pt.gross_paid_cents, 0::bigint) - COALESCE(pt.refunded_cents, 0::bigint), 0::bigint), 0::bigint) AS remaining_balance_cents,
    a.agreement_status,
    COALESCE(ar.agreement_count, 0) AS agreement_count,
    COALESCE(ar.signed_agreements, 0) AS signed_agreements,
    COALESCE(ar.waived_agreements, 0) AS waived_agreements,
    COALESCE(ar.declined_agreements, 0) AS declined_agreements,
    COALESCE(ar.incomplete_agreements, 0) AS incomplete_agreements,
    COALESCE(ar.required_signatures, 0) AS required_signatures,
    COALESCE(ar.collected_signatures, 0) AS collected_signatures,
    a.access_status,
    array_remove(ARRAY[
        CASE
            WHEN a.payment_status <> ALL (ARRAY['paid'::text, 'waived'::text]) THEN 'payment_incomplete'::text
            ELSE NULL::text
        END,
        CASE
            WHEN a.payment_status <> 'waived'::text AND a.amount_cents IS NOT NULL AND GREATEST(COALESCE(pt.gross_paid_cents, 0::bigint) - COALESCE(pt.refunded_cents, 0::bigint), 0::bigint) < a.amount_cents THEN 'payment_amount_short'::text
            ELSE NULL::text
        END,
        CASE
            WHEN COALESCE(ar.declined_agreements, 0) > 0 THEN 'agreement_declined'::text
            ELSE NULL::text
        END,
        CASE
            WHEN a.agreement_status <> ALL (ARRAY['signed'::text, 'waived'::text]) THEN 'agreement_incomplete'::text
            ELSE NULL::text
        END,
        CASE
            WHEN COALESCE(ar.collected_signatures, 0) < COALESCE(ar.required_signatures, 0) THEN 'required_signatures_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (a.payment_status = ANY (ARRAY['paid'::text, 'waived'::text])) AND (a.agreement_status = ANY (ARRAY['signed'::text, 'waived'::text])) AND (a.access_status <> ALL (ARRAY['ready'::text, 'active'::text])) THEN 'access_not_ready'::text
            ELSE NULL::text
        END], NULL::text) AS blockers,
    (a.payment_status = ANY (ARRAY['paid'::text, 'waived'::text])) AND (a.agreement_status = ANY (ARRAY['signed'::text, 'waived'::text])) AND COALESCE(ar.declined_agreements, 0) = 0 AND COALESCE(ar.collected_signatures, 0) >= COALESCE(ar.required_signatures, 0) AS ready_for_access,
    a.created_at,
    a.updated_at
   FROM journey_enrollment_activations a
     JOIN contacts c ON c.id = a.contact_id
     LEFT JOIN payment_totals pt ON pt.activation_id = a.id
     LEFT JOIN agreement_rollup ar ON ar.activation_id = a.id
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'finance.view'::text) AND private.staff_can_access_contact(( SELECT auth.uid() AS uid), a.contact_id);

CREATE VIEW "public"."admin_family_requests" WITH (security_invoker=true) AS
 SELECT fcr.id AS request_id,
    fcr.contact_id,
    TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)) AS member_name,
    c.email AS member_email,
    fcr.household_id,
    h.household_name,
    fcr.membership_id,
    cm.program_code,
    pc.name AS program_name,
    fcr.request_type,
    fcr.target_household_member_id,
    fcr.first_name,
    fcr.last_name,
    fcr.relationship_type,
    fcr.sex,
    fcr.date_of_birth,
    fcr.email,
    fcr.notes,
    fcr.status,
    fcr.staff_notes,
    fcr.reviewed_by,
    sa.display_name AS reviewed_by_name,
    fcr.reviewed_at,
    fcr.created_at,
    fcr.updated_at
   FROM family_change_requests fcr
     JOIN contacts c ON c.id = fcr.contact_id
     LEFT JOIN households h ON h.id = fcr.household_id
     LEFT JOIN client_memberships cm ON cm.id = fcr.membership_id
     LEFT JOIN program_catalog pc ON pc.program_code = cm.program_code
     LEFT JOIN staff_access sa ON sa.user_id = fcr.reviewed_by
  WHERE ( SELECT private.staff_has_permission(( SELECT auth.uid() AS uid), 'crm.view'::text) AS staff_has_permission) AND private.staff_can_access_contact(( SELECT auth.uid() AS uid), fcr.contact_id)
  ORDER BY (
        CASE fcr.status
            WHEN 'submitted'::text THEN 1
            WHEN 'in_review'::text THEN 2
            WHEN 'approved'::text THEN 3
            WHEN 'completed'::text THEN 4
            WHEN 'declined'::text THEN 5
            ELSE 6
        END), fcr.created_at;

CREATE VIEW "public"."admin_followup_queue" WITH (security_invoker=true) AS
 SELECT id,
    first_name,
    last_name,
    email,
    phone,
    lifecycle_stage,
    follow_up_status,
    consultation_status,
    next_follow_up_at,
    updated_at,
    COALESCE(( SELECT count(*) AS count
           FROM follow_up_tasks t
          WHERE t.contact_id = c.id AND t.status = 'open'::text), 0::bigint) AS open_tasks
   FROM contacts c
  WHERE (follow_up_status = ANY (ARRAY['new'::text, 'needs_follow_up'::text, 'contacted'::text, 'consultation_scheduled'::text])) OR next_follow_up_at IS NOT NULL
  ORDER BY next_follow_up_at, updated_at DESC;

CREATE VIEW "public"."admin_journey_pipeline" WITH (security_invoker=true) AS
 SELECT cj.id AS journey_id,
    cj.contact_id,
    c.first_name,
    c.last_name,
    c.email,
    c.phone,
    jd.name AS journey_name,
    cj.journey_key,
    cj.status AS journey_status,
    cj.current_step_key,
    s.name AS current_step_name,
    s.status AS current_step_status,
    s.due_at AS current_step_due_at,
    s.due_at IS NOT NULL AND s.due_at < now() AND (s.status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'blocked'::text])) AS stalled,
    cj.progress_percent,
    ce.intent_score,
    ce.temperature,
    cj.assigned_to,
    cj.last_activity_at,
    cj.next_action_at,
    cj.started_at
   FROM contact_journeys cj
     JOIN contacts c ON c.id = cj.contact_id
     JOIN journey_definitions jd ON jd.journey_key = cj.journey_key
     LEFT JOIN contact_journey_steps s ON s.journey_id = cj.id AND s.step_key = cj.current_step_key
     LEFT JOIN contact_engagement ce ON ce.contact_id = cj.contact_id;

CREATE VIEW "public"."admin_manual_override_history" WITH (security_invoker=true) AS
 SELECT a.id,
    a.contact_id,
    a.journey_id,
    a.journey_step_id,
    a.entity_type,
    a.entity_id,
    a.action,
    a.permission_key,
    a.actor_user_id,
    COALESCE(sa.display_name, a.actor_user_id::text) AS actor_name,
    a.actor_role,
    a.previous_value,
    a.new_value,
    a.completion_method,
    a.reason,
    a.notes,
    a.metadata,
    a.created_at
   FROM manual_override_audit a
     LEFT JOIN staff_access sa ON sa.user_id = a.actor_user_id;

CREATE VIEW "public"."admin_mobile_adoption_summary" WITH (security_invoker=true) AS
 SELECT count(DISTINCT user_id) FILTER (WHERE last_seen_at >= (now() - '1 day'::interval))::integer AS dau,
    count(DISTINCT user_id) FILTER (WHERE last_seen_at >= (now() - '7 days'::interval))::integer AS wau,
    count(DISTINCT user_id) FILTER (WHERE last_seen_at >= (now() - '30 days'::interval))::integer AS mau,
    count(*) FILTER (WHERE started_at >= (now() - '24:00:00'::interval))::integer AS sessions_24h,
    count(*) FILTER (WHERE started_at >= (now() - '7 days'::interval))::integer AS sessions_7d,
    round(avg(EXTRACT(epoch FROM COALESCE(ended_at, last_seen_at) - started_at) / 60::numeric) FILTER (WHERE started_at >= (now() - '30 days'::interval)), 1) AS avg_session_minutes_30d
   FROM member_app_sessions s
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'analytics.view'::text);

CREATE VIEW "public"."admin_mobile_feature_usage_30d" WITH (security_invoker=true) AS
 SELECT COALESCE(feature_key, route_key, event_key) AS usage_key,
    count(*)::integer AS event_count,
    count(DISTINCT user_id)::integer AS unique_members,
    max(occurred_at) AS last_event_at
   FROM member_app_events e
  WHERE occurred_at >= (now() - '30 days'::interval) AND private.staff_has_permission(( SELECT auth.uid() AS uid), 'analytics.view'::text)
  GROUP BY (COALESCE(feature_key, route_key, event_key))
  ORDER BY (count(DISTINCT user_id)::integer) DESC, (count(*)::integer) DESC, (COALESCE(feature_key, route_key, event_key));

CREATE VIEW "public"."admin_mobile_health_connections" WITH (security_invoker=true) AS
 SELECT hc.id AS connection_id,
    hc.contact_id,
    c.first_name,
    c.last_name,
    hc.provider_key,
    p.name AS provider_name,
    hc.status,
    hc.connected_at,
    hc.last_sync_at,
    hc.last_successful_sync_at,
    hc.last_error,
    hc.sync_cursor,
    count(b.id)::integer AS batch_count,
    max(b.started_at) AS latest_batch_at
   FROM health_integration_connections hc
     JOIN contacts c ON c.id = hc.contact_id
     JOIN health_integration_providers p ON p.provider_key = hc.provider_key
     LEFT JOIN health_mobile_sync_batches b ON b.connection_id = hc.id
  WHERE (hc.provider_key = ANY (ARRAY['apple_health'::text, 'health_connect'::text])) AND private.staff_has_permission(( SELECT auth.uid() AS uid), 'health.private.view'::text) AND private.staff_can_access_contact(( SELECT auth.uid() AS uid), hc.contact_id)
  GROUP BY hc.id, hc.contact_id, c.first_name, c.last_name, hc.provider_key, p.name, hc.status, hc.connected_at, hc.last_sync_at, hc.last_successful_sync_at, hc.last_error, hc.sync_cursor
  ORDER BY hc.last_sync_at DESC NULLS LAST, c.last_name, c.first_name;

CREATE VIEW "public"."admin_mobile_health_sync_summary" WITH (security_invoker=true) AS
 SELECT count(*) FILTER (WHERE started_at >= (now() - '24:00:00'::interval))::integer AS batches_24h,
    count(*) FILTER (WHERE started_at >= (now() - '7 days'::interval))::integer AS batches_7d,
    count(*) FILTER (WHERE status = 'failed'::text)::integer AS failed_batches,
    count(*) FILTER (WHERE status = 'partial'::text)::integer AS partial_batches,
    COALESCE(sum(records_received) FILTER (WHERE started_at >= (now() - '7 days'::interval)), 0::bigint) AS records_received_7d,
    COALESCE(sum(records_imported) FILTER (WHERE started_at >= (now() - '7 days'::interval)), 0::bigint) AS records_imported_7d,
    COALESCE(sum(records_blocked) FILTER (WHERE started_at >= (now() - '7 days'::interval)), 0::bigint) AS records_blocked_7d,
    COALESCE(sum(records_duplicate) FILTER (WHERE started_at >= (now() - '7 days'::interval)), 0::bigint) AS records_duplicate_7d
   FROM health_mobile_sync_batches
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'health.private.view'::text);

CREATE VIEW "public"."admin_mobile_versions" WITH (security_invoker=true) AS
 SELECT COALESCE(platform, 'unknown'::text) AS platform,
    COALESCE(app_version, 'unknown'::text) AS app_version,
    count(*) FILTER (WHERE revoked_at IS NULL)::integer AS active_devices,
    count(*) FILTER (WHERE revoked_at IS NULL AND last_seen_at >= (now() - '30 days'::interval))::integer AS active_devices_30d,
    max(last_seen_at) AS last_seen_at
   FROM member_devices d
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'analytics.view'::text)
  GROUP BY (COALESCE(platform, 'unknown'::text)), (COALESCE(app_version, 'unknown'::text))
  ORDER BY (COALESCE(platform, 'unknown'::text)), (count(*) FILTER (WHERE revoked_at IS NULL AND last_seen_at >= (now() - '30 days'::interval))::integer) DESC, (COALESCE(app_version, 'unknown'::text));

CREATE VIEW "public"."admin_notification_delivery_queue" WITH (security_invoker=true) AS
 SELECT j.id AS job_id,
    j.notification_id,
    j.user_id,
    j.contact_id,
    c.first_name,
    c.last_name,
    c.email AS contact_email,
    c.phone,
    j.channel,
    j.provider,
    j.recipient,
    j.subject,
    j.body,
    j.status,
    j.block_reason,
    j.scheduled_for,
    j.attempt_count,
    j.last_attempt_at,
    j.provider_message_id,
    j.error_message,
    j.sent_at,
    j.created_at
   FROM notification_delivery_jobs j
     LEFT JOIN contacts c ON c.id = j.contact_id;

CREATE VIEW "public"."admin_people_directory" WITH (security_invoker=true) AS
 SELECT c.id,
    c.first_name,
    c.last_name,
    c.email,
    c.phone,
    c.city,
    c.state,
    c.country,
    c.lifecycle_stage,
    c.follow_up_status,
    c.consultation_status,
    c.assigned_to,
    sd.display_name AS assigned_name,
    c.next_follow_up_at,
    c.first_source,
    c.last_source,
    c.created_at,
    c.updated_at,
    ( SELECT min(COALESCE(cm.starts_at, cm.created_at)) AS min
           FROM client_memberships cm
          WHERE cm.primary_contact_id = c.id) AS enrolled_at,
    COALESCE(( SELECT max(a.created_at) AS max
           FROM contact_activity a
          WHERE a.contact_id = c.id), c.updated_at) AS last_activity_at,
    ( SELECT w.status
           FROM workflow_records w
          WHERE w.contact_id = c.id AND w.workflow_type = 'vitality_assessment'::text AND w.status <> 'abandoned'::text
          ORDER BY w.updated_at DESC
         LIMIT 1) AS vitality_status,
    ( SELECT w.status
           FROM workflow_records w
          WHERE w.contact_id = c.id AND w.workflow_type = 'enrollment'::text AND w.status <> 'abandoned'::text
          ORDER BY w.updated_at DESC
         LIMIT 1) AS enrollment_status,
    ( SELECT wr.status
           FROM webinar_registrations wr
          WHERE wr.contact_id = c.id
          ORDER BY wr.registered_at DESC
         LIMIT 1) AS webinar_status,
    c.record_kind
   FROM contacts c
     LEFT JOIN staff_directory sd ON sd.user_id = c.assigned_to;

CREATE VIEW "public"."admin_platform_health_metrics" WITH (security_invoker=true) AS
 SELECT ( SELECT count(*) AS count
           FROM contacts) AS total_contacts,
    ( SELECT count(*) AS count
           FROM contacts
          WHERE contacts.lifecycle_stage = 'assessment_lead'::text) AS assessment_leads,
    ( SELECT count(*) AS count
           FROM contacts
          WHERE contacts.lifecycle_stage = 'applicant'::text) AS applicants,
    ( SELECT count(*) AS count
           FROM contacts
          WHERE contacts.lifecycle_stage = 'client'::text) AS clients,
    ( SELECT count(*) AS count
           FROM contact_journeys
          WHERE contact_journeys.status = 'active'::text) AS active_journeys,
    ( SELECT count(*) AS count
           FROM contact_journeys cj
             JOIN contact_journey_steps s ON s.journey_id = cj.id AND s.step_key = cj.current_step_key
          WHERE cj.status = 'active'::text AND s.due_at IS NOT NULL AND s.due_at < now() AND (s.status <> ALL (ARRAY['completed'::text, 'skipped'::text, 'waived'::text]))) AS stalled_journeys,
    ( SELECT count(*) AS count
           FROM journey_enrollment_activations
          WHERE journey_enrollment_activations.payment_status = 'paid'::text) AS paid_enrollments,
    ( SELECT count(*) AS count
           FROM client_memberships
          WHERE client_memberships.status = 'active'::text) AS active_memberships,
    ( SELECT count(*) AS count
           FROM client_access
          WHERE client_access.status = 'active'::text) AS active_member_logins,
    ( SELECT count(DISTINCT client_coach_assignments.contact_id) AS count
           FROM client_coach_assignments
          WHERE client_coach_assignments.role = 'primary'::text AND client_coach_assignments.status = 'active'::text) AS clients_with_primary_coach,
    ( SELECT count(*) AS count
           FROM client_checkins
          WHERE client_checkins.submitted_at >= (now() - '7 days'::interval)) AS checkins_7d,
    ( SELECT count(*) AS count
           FROM client_assignments
          WHERE client_assignments.status = ANY (ARRAY['assigned'::text, 'in_progress'::text])) AS open_client_assignments,
    ( SELECT count(*) AS count
           FROM coaching_sessions
          WHERE coaching_sessions.status = 'scheduled'::text AND coaching_sessions.scheduled_start >= now()) AS upcoming_coaching_sessions,
    ( SELECT count(*) AS count
           FROM client_course_enrollments
          WHERE client_course_enrollments.status = 'active'::text) AS active_course_enrollments,
    ( SELECT COALESCE(round(avg(client_course_enrollments.progress_percent)), 0::numeric) AS "coalesce"
           FROM client_course_enrollments
          WHERE client_course_enrollments.status = ANY (ARRAY['active'::text, 'completed'::text])) AS average_course_progress,
    ( SELECT count(*) AS count
           FROM challenge_enrollments
          WHERE challenge_enrollments.status = 'active'::text) AS active_challenge_enrollments,
    ( SELECT count(*) AS count
           FROM challenge_enrollments
          WHERE challenge_enrollments.status = 'completed'::text) AS completed_challenge_enrollments,
    ( SELECT count(*) AS count
           FROM health_integration_connections
          WHERE health_integration_connections.status = 'connected'::text) AS connected_health_sources,
    ( SELECT count(*) AS count
           FROM health_integration_connections
          WHERE health_integration_connections.status = 'attention_needed'::text) AS health_connections_needing_attention,
    ( SELECT count(*) AS count
           FROM member_messages
          WHERE member_messages.created_at >= (now() - '7 days'::interval) AND member_messages.deleted_at IS NULL) AS private_messages_7d,
    ( SELECT count(*) AS count
           FROM coach_companion_reviews
          WHERE coach_companion_reviews.status = ANY (ARRAY['open'::text, 'in_review'::text])) AS companion_reviews_open,
    ( SELECT count(*) AS count
           FROM notification_delivery_jobs
          WHERE notification_delivery_jobs.status = 'blocked'::text) AS blocked_notification_deliveries;

CREATE VIEW "public"."admin_privacy_operations_summary" WITH (security_invoker=true) AS
 SELECT count(*) FILTER (WHERE status = 'submitted'::text)::integer AS submitted_requests,
    count(*) FILTER (WHERE status = 'in_review'::text)::integer AS in_review_requests,
    count(*) FILTER (WHERE status = 'approved'::text)::integer AS approved_requests,
    count(*) FILTER (WHERE status = 'processing'::text)::integer AS processing_requests,
    count(*) FILTER (WHERE request_type = 'data_export'::text AND (status <> ALL (ARRAY['completed'::text, 'cancelled'::text, 'declined'::text])))::integer AS open_export_requests,
    count(*) FILTER (WHERE request_type = 'health_data_delete'::text AND (status <> ALL (ARRAY['completed'::text, 'cancelled'::text, 'declined'::text])))::integer AS open_health_delete_requests,
    count(*) FILTER (WHERE request_type = 'account_delete'::text AND (status <> ALL (ARRAY['completed'::text, 'cancelled'::text, 'declined'::text])))::integer AS open_account_delete_requests
   FROM member_privacy_requests r
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'staff.manage'::text);

CREATE VIEW "public"."admin_privacy_request_queue" WITH (security_invoker=true) AS
 SELECT r.id AS request_id,
    r.contact_id,
    c.first_name,
    c.last_name,
    c.email,
    r.request_type,
    r.scope,
    r.status,
    r.member_note,
    r.staff_note,
    r.assigned_to,
    sd.display_name AS assigned_to_name,
    r.requested_at,
    r.reviewed_at,
    r.completed_at,
    r.updated_at
   FROM member_privacy_requests r
     JOIN contacts c ON c.id = r.contact_id
     LEFT JOIN staff_directory sd ON sd.user_id = r.assigned_to
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'staff.manage'::text)
  ORDER BY (
        CASE r.status
            WHEN 'submitted'::text THEN 1
            WHEN 'in_review'::text THEN 2
            WHEN 'approved'::text THEN 3
            WHEN 'processing'::text THEN 4
            ELSE 5
        END), r.requested_at;

CREATE VIEW "public"."admin_program_performance" WITH (security_invoker=true) AS
 SELECT pc.program_code,
    pc.name AS program_name,
    count(cm.id) FILTER (WHERE cm.status = 'active'::text) AS active_members,
    count(cm.id) FILTER (WHERE cm.status = 'completed'::text) AS completed_members,
    COALESCE(round(avg(( SELECT avg(e.progress_percent) AS avg
           FROM client_course_enrollments e
          WHERE e.membership_id = cm.id AND (e.status = ANY (ARRAY['active'::text, 'completed'::text]))))), 0::numeric) AS average_course_progress,
    count(DISTINCT cs.id) FILTER (WHERE cs.status = 'completed'::text AND cs.completed_at >= (now() - '30 days'::interval)) AS coaching_sessions_30d,
    count(DISTINCT cc.id) FILTER (WHERE cc.submitted_at >= (now() - '30 days'::interval)) AS checkins_30d
   FROM program_catalog pc
     LEFT JOIN client_memberships cm ON cm.program_code = pc.program_code
     LEFT JOIN coaching_sessions cs ON cs.membership_id = cm.id
     LEFT JOIN client_checkins cc ON cc.membership_id = cm.id
  WHERE pc.active
  GROUP BY pc.program_code, pc.name
  ORDER BY pc.name;

CREATE VIEW "public"."admin_referral_metrics" WITH (security_invoker=true) AS
 SELECT ( SELECT count(*) AS count
           FROM referrals) AS total_referrals,
    ( SELECT count(*) AS count
           FROM referrals
          WHERE referrals.status = 'converted'::text) AS converted_referrals,
    ( SELECT count(*) AS count
           FROM referral_rewards
          WHERE referral_rewards.status = 'pending'::text) AS pending_rewards,
    ( SELECT count(*) AS count
           FROM referral_rewards
          WHERE referral_rewards.status = 'issued'::text) AS issued_rewards,
    ( SELECT count(*) AS count
           FROM referral_profiles
          WHERE referral_profiles.status = 'active'::text) AS active_ambassadors;

CREATE VIEW "public"."admin_referral_pipeline" WITH (security_invoker=true) AS
 SELECT r.id AS referral_id,
    r.referral_program_id,
    rp.name AS referral_program_name,
    r.referrer_contact_id,
    TRIM(BOTH FROM concat_ws(' '::text, referrer.first_name, referrer.last_name)) AS referrer_name,
    referrer.email AS referrer_email,
    r.referred_contact_id,
    TRIM(BOTH FROM concat_ws(' '::text, referred.first_name, referred.last_name)) AS referred_name,
    referred.email AS referred_email,
    referred.phone AS referred_phone,
    referred.lifecycle_stage,
    r.referral_code,
    r.source_channel,
    r.status,
    r.first_touch_at,
    r.converted_at,
    r.notes
   FROM referrals r
     LEFT JOIN referral_programs rp ON rp.id = r.referral_program_id
     LEFT JOIN contacts referrer ON referrer.id = r.referrer_contact_id
     JOIN contacts referred ON referred.id = r.referred_contact_id
  ORDER BY r.created_at DESC;

CREATE VIEW "public"."admin_referral_rewards" WITH (security_invoker=true) AS
 SELECT rr.id AS reward_id,
    rr.referral_id,
    rr.referrer_contact_id,
    TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)) AS referrer_name,
    c.email AS referrer_email,
    rr.reward_type,
    rr.reward_value,
    rr.currency,
    rr.status,
    rr.approved_at,
    rr.issued_at,
    rr.notes,
    rr.created_at
   FROM referral_rewards rr
     JOIN contacts c ON c.id = rr.referrer_contact_id
  ORDER BY rr.created_at DESC;

CREATE VIEW "public"."admin_referral_summary" WITH (security_invoker=true) AS
 SELECT c.id AS contact_id,
    c.first_name,
    c.last_name,
    c.email,
    rp.referral_code,
    count(DISTINCT r.id) AS total_referrals,
    count(DISTINCT r.id) FILTER (WHERE r.status = 'converted'::text) AS converted_referrals,
    count(DISTINCT rr.id) FILTER (WHERE rr.status = 'pending'::text) AS pending_rewards,
    count(DISTINCT rr.id) FILTER (WHERE rr.status = 'issued'::text) AS issued_rewards
   FROM contacts c
     LEFT JOIN referral_profiles rp ON rp.contact_id = c.id
     LEFT JOIN referrals r ON r.referrer_contact_id = c.id
     LEFT JOIN referral_rewards rr ON rr.referrer_contact_id = c.id
  GROUP BY c.id, c.first_name, c.last_name, c.email, rp.referral_code
 HAVING count(DISTINCT r.id) > 0 OR count(DISTINCT rp.id) > 0;

CREATE VIEW "public"."admin_refuel_interest" WITH (security_invoker=true) AS
 SELECT r.id,
    r.contact_id,
    r.email,
    r.first_name,
    r.source,
    r.status,
    r.created_at,
    r.updated_at,
    c.last_name,
    c.phone,
    c.lifecycle_stage
   FROM refuel_interest r
     JOIN contacts c ON c.id = r.contact_id
  ORDER BY r.created_at DESC;

CREATE VIEW "public"."admin_refuel_metrics" WITH (security_invoker=true) AS
 SELECT ( SELECT count(*) AS count
           FROM refuel_interest
          WHERE refuel_interest.status = 'interested'::text) AS interested,
    ( SELECT count(*) AS count
           FROM refuel_invitations
          WHERE refuel_invitations.status = ANY (ARRAY['queued'::text, 'sent'::text, 'opened'::text])) AS invited_open,
    ( SELECT count(*) AS count
           FROM refuel_enrollments
          WHERE refuel_enrollments.status = 'active'::text) AS active_enrollments,
    ( SELECT count(*) AS count
           FROM refuel_enrollments
          WHERE refuel_enrollments.payment_status = 'paid'::text) AS paid_enrollments,
    ( SELECT count(*) AS count
           FROM refuel_offers
          WHERE refuel_offers.status = 'published'::text) AS published_offers;

CREATE VIEW "public"."admin_refuel_pipeline" WITH (security_invoker=true) AS
 SELECT c.id AS contact_id,
    c.first_name,
    c.last_name,
    c.email,
    ri.status AS interest_status,
    ri.created_at AS interest_created_at,
    inv.id AS invitation_id,
    inv.status AS invitation_status,
    inv.invited_at,
    o.id AS offer_id,
    o.name AS offer_name,
    o.status AS offer_status,
    re.id AS enrollment_id,
    re.status AS enrollment_status,
    re.payment_status,
    re.activated_at
   FROM refuel_interest ri
     JOIN contacts c ON c.id = ri.contact_id
     LEFT JOIN refuel_invitations inv ON inv.contact_id = c.id
     LEFT JOIN refuel_offers o ON o.id = inv.offer_id
     LEFT JOIN refuel_enrollments re ON re.contact_id = c.id AND re.offer_id = o.id;

CREATE VIEW "public"."admin_staff_access_directory" WITH (security_invoker=true) AS
 SELECT sa.user_id,
    sa.role,
    sa.display_name,
    sa.status,
    sa.onboarding_status,
    sa.created_at,
    sa.updated_at,
    sa.updated_by,
    c.id AS contact_id,
    c.email,
    c.phone,
    c.first_name,
    c.last_name,
    ( SELECT jsonb_object_agg(pc.permission_key, private.staff_has_permission(sa.user_id, pc.permission_key)) AS jsonb_object_agg
           FROM staff_permission_catalog pc
          WHERE pc.active) AS effective_permissions,
    ( SELECT count(*) AS count
           FROM staff_agreements ag
          WHERE ag.staff_user_id = sa.user_id AND ag.required AND (ag.status <> ALL (ARRAY['signed'::text, 'waived'::text]))) AS pending_required_agreements,
    ( SELECT max(ag.signed_at) AS max
           FROM staff_agreements ag
          WHERE ag.staff_user_id = sa.user_id AND ag.status = 'signed'::text) AS last_staff_agreement_signed_at,
    sa.contact_scope
   FROM staff_access sa
     LEFT JOIN profiles p ON p.user_id = sa.user_id
     LEFT JOIN contacts c ON c.id = p.contact_id;

CREATE VIEW "public"."admin_staff_agreements" WITH (security_invoker=true) AS
 SELECT sa.id,
    sa.staff_user_id,
    sa.agreement_template_id,
    sa.agreement_key,
    sa.template_version,
    sa.content_hash,
    sa.rendered_content_text,
    sa.rendered_content_hash,
    sa.merge_values,
    sa.status,
    sa.required,
    sa.sent_at,
    sa.viewed_at,
    sa.signed_at,
    sa.waived_at,
    sa.waived_by,
    sa.waiver_reason,
    sa.created_by,
    sa.created_at,
    sa.updated_at,
    at.name AS agreement_name,
    at.document_type,
    s.display_name,
    c.email,
    acc.signer_name,
    acc.signed_at AS acceptance_signed_at
   FROM staff_agreements sa
     JOIN agreement_templates at ON at.id = sa.agreement_template_id
     LEFT JOIN staff_access s ON s.user_id = sa.staff_user_id
     LEFT JOIN profiles p ON p.user_id = sa.staff_user_id
     LEFT JOIN contacts c ON c.id = p.contact_id
     LEFT JOIN staff_agreement_acceptances acc ON acc.staff_agreement_id = sa.id;

CREATE VIEW "public"."admin_staff_inbox" WITH (security_invoker=true) AS
 SELECT p.user_id AS staff_user_id,
    c.id AS conversation_id,
    c.conversation_type,
    c.contact_id,
    c.household_id,
    c.membership_id,
    c.title,
    c.status,
    c.last_message_at,
    p.last_read_at,
    ct.first_name,
    ct.last_name,
    ct.email,
    ( SELECT count(*) AS count
           FROM member_messages m
          WHERE m.conversation_id = c.id AND m.deleted_at IS NULL AND m.sender_user_id <> p.user_id AND (p.last_read_at IS NULL OR m.created_at > p.last_read_at)) AS unread_count,
    ( SELECT "left"(m.body, 220) AS "left"
           FROM member_messages m
          WHERE m.conversation_id = c.id AND m.deleted_at IS NULL
          ORDER BY m.created_at DESC
         LIMIT 1) AS last_message_preview,
    ( SELECT m.sender_user_id
           FROM member_messages m
          WHERE m.conversation_id = c.id AND m.deleted_at IS NULL
          ORDER BY m.created_at DESC
         LIMIT 1) AS last_sender_user_id
   FROM member_conversation_participants p
     JOIN member_conversations c ON c.id = p.conversation_id
     LEFT JOIN contacts ct ON ct.id = c.contact_id
  WHERE (p.user_id IN ( SELECT staff_access.user_id
           FROM staff_access)) AND p.left_at IS NULL AND c.status = 'active'::text;

CREATE VIEW "public"."admin_staff_onboarding_readiness" WITH (security_invoker=true) AS
 SELECT s.user_id,
    s.display_name,
    s.role,
    s.status,
    s.onboarding_status,
    s.phone,
    c.email,
    count(sa.id) FILTER (WHERE sa.required)::integer AS required_agreements,
    count(sa.id) FILTER (WHERE sa.required AND sa.status = 'signed'::text)::integer AS signed_required_agreements,
    count(sa.id) FILTER (WHERE sa.required AND sa.status = 'waived'::text)::integer AS waived_required_agreements,
    count(sa.id) FILTER (WHERE sa.required AND (sa.status <> ALL (ARRAY['signed'::text, 'waived'::text])))::integer AS incomplete_required_agreements,
    count(sa.id) FILTER (WHERE sa.required AND sa.status = 'declined'::text)::integer AS declined_required_agreements,
    bool_or(sa.agreement_key = 'revitalized-nation-coach-nda'::text AND sa.status = 'signed'::text) AS coach_nda_signed,
    max(sa.signed_at) FILTER (WHERE sa.agreement_key = 'revitalized-nation-coach-nda'::text) AS coach_nda_signed_at,
    array_remove(ARRAY[
        CASE
            WHEN s.status <> 'active'::text THEN 'staff_inactive'::text
            ELSE NULL::text
        END,
        CASE
            WHEN s.role = 'coach'::text AND NOT COALESCE(bool_or(sa.agreement_key = 'revitalized-nation-coach-nda'::text AND (sa.status = ANY (ARRAY['signed'::text, 'waived'::text]))), false) THEN 'coach_nda_incomplete'::text
            ELSE NULL::text
        END,
        CASE
            WHEN count(sa.id) FILTER (WHERE sa.required AND (sa.status <> ALL (ARRAY['signed'::text, 'waived'::text]))) > 0 THEN 'required_agreement_incomplete'::text
            ELSE NULL::text
        END,
        CASE
            WHEN count(sa.id) FILTER (WHERE sa.required AND sa.status = 'declined'::text) > 0 THEN 'required_agreement_declined'::text
            ELSE NULL::text
        END], NULL::text) AS blockers,
    s.status = 'active'::text AND count(sa.id) FILTER (WHERE sa.required AND (sa.status <> ALL (ARRAY['signed'::text, 'waived'::text]))) = 0 AS onboarding_ready
   FROM staff_access s
     LEFT JOIN profiles p ON p.user_id = s.user_id
     LEFT JOIN contacts c ON c.id = p.contact_id
     LEFT JOIN staff_agreements sa ON sa.staff_user_id = s.user_id
  WHERE private.staff_has_permission(( SELECT auth.uid() AS uid), 'staff.view'::text)
  GROUP BY s.user_id, s.display_name, s.role, s.status, s.onboarding_status, s.phone, c.email
  ORDER BY (
        CASE s.onboarding_status
            WHEN 'blocked'::text THEN 1
            WHEN 'pending'::text THEN 2
            WHEN 'complete'::text THEN 3
            ELSE 4
        END), s.display_name;

CREATE VIEW "public"."admin_staff_permission_matrix" WITH (security_invoker=true) AS
 SELECT sa.user_id,
    sa.display_name,
    sa.role,
    sa.status,
    pc.permission_key,
    pc.label,
    pc.category,
    pc.description,
    pc.sensitive,
    pc.sort_order,
    srpd.allowed AS role_default_allowed,
    spo.allowed AS override_allowed,
    COALESCE(spo.allowed, srpd.allowed, false) AS effective_allowed,
    spo.reason AS override_reason,
    spo.updated_at AS override_updated_at
   FROM staff_access sa
     CROSS JOIN staff_permission_catalog pc
     LEFT JOIN staff_role_permission_defaults srpd ON srpd.role = sa.role AND srpd.permission_key = pc.permission_key
     LEFT JOIN staff_permission_overrides spo ON spo.user_id = sa.user_id AND spo.permission_key = pc.permission_key
  WHERE pc.active;

CREATE VIEW "public"."admin_team_calendar" WITH (security_invoker=true) AS
 SELECT 'journey_appointment'::text AS item_type,
    ja.id AS item_id,
    ja.contact_id,
    TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)) AS person_name,
    c.email,
    ja.appointment_type,
    ja.status,
    ja.scheduled_start,
    ja.scheduled_end,
    ja.time_zone,
    ja.format,
    ja.location_url,
    ja.assigned_to AS staff_user_id,
    sd.display_name AS staff_name,
    ja.journey_id,
    ja.journey_step_id,
    ja.client_notes,
    ja.staff_notes,
    ja.created_at,
    ja.updated_at
   FROM journey_appointments ja
     JOIN contacts c ON c.id = ja.contact_id
     LEFT JOIN staff_directory sd ON sd.user_id = ja.assigned_to
UNION ALL
 SELECT 'coaching_session'::text AS item_type,
    cs.id AS item_id,
    cs.contact_id,
    TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)) AS person_name,
    c.email,
    'coaching_session'::text AS appointment_type,
    cs.status,
    cs.scheduled_start,
    cs.scheduled_end,
    NULL::text AS time_zone,
    cs.format,
    cs.location_url,
    cs.coach_user_id AS staff_user_id,
    sd.display_name AS staff_name,
    NULL::uuid AS journey_id,
    cs.appointment_id AS journey_step_id,
    cs.client_agenda AS client_notes,
    NULL::text AS staff_notes,
    cs.created_at,
    cs.updated_at
   FROM coaching_sessions cs
     JOIN contacts c ON c.id = cs.contact_id
     LEFT JOIN staff_directory sd ON sd.user_id = cs.coach_user_id;

CREATE VIEW "public"."admin_work_queue" WITH (security_invoker=true) AS
 SELECT t.id AS task_id,
    t.contact_id,
    t.title,
    t.due_at,
    t.status,
    t.priority,
    t.assigned_to,
    sd.display_name AS assigned_name,
    sd.role AS assigned_role,
    t.task_type,
    t.instructions,
    t.journey_id,
    t.journey_step_id,
    t.journey_action_id,
    c.first_name,
    c.last_name,
    c.email,
    c.phone,
    c.lifecycle_stage,
    cj.journey_key,
    jd.name AS journey_name,
    s.step_key,
    s.name AS journey_step_name,
        CASE
            WHEN lower(t.title) ~~ '%vitality report%'::text OR s.step_key = 'report_review'::text THEN 'Report Review'::text
            WHEN lower(t.title) ~~ '%weekly check-in%'::text OR t.task_type = 'review'::text AND COALESCE(s.step_key, ''::text) <> 'report_review'::text THEN 'Check-In Review'::text
            WHEN lower(t.title) ~~ '%coaching session%'::text THEN 'Coaching'::text
            WHEN t.task_type = 'scheduling'::text OR lower(t.title) ~~ '%schedule%'::text THEN 'Scheduling'::text
            WHEN t.task_type = 'call'::text OR lower(t.title) ~~ 'call:%'::text OR lower(t.title) ~~ '%follow-up call%'::text THEN 'Calls'::text
            WHEN t.task_type = 'email'::text OR lower(t.title) ~~ 'email:%'::text THEN 'Email'::text
            WHEN t.task_type = 'sms'::text OR lower(t.title) ~~ 'text:%'::text THEN 'Text'::text
            WHEN s.step_key = 'payment_agreement'::text OR lower(t.title) ~~ '%payment%'::text OR lower(t.title) ~~ '%enrollment%'::text THEN 'Enrollment'::text
            WHEN (s.step_key = ANY (ARRAY['onboarding_health_questionnaire'::text, 'backend_activation'::text, 'coach_setup'::text])) OR lower(t.title) ~~ '%onboarding%'::text OR lower(t.title) ~~ '%member access%'::text THEN 'Onboarding'::text
            WHEN lower(t.title) ~~ '%reminder%'::text THEN 'Reminders'::text
            ELSE 'Follow-Up'::text
        END AS work_category,
        CASE
            WHEN t.due_at IS NOT NULL AND t.due_at < now() THEN 'overdue'::text
            WHEN t.due_at IS NOT NULL AND t.due_at < (date_trunc('day'::text, now()) + '1 day'::interval) THEN 'today'::text
            WHEN t.due_at IS NOT NULL AND t.due_at < (now() + '72:00:00'::interval) THEN 'soon'::text
            ELSE 'upcoming'::text
        END AS due_bucket,
    t.due_at IS NOT NULL AND t.due_at < now() AS overdue,
    t.created_at
   FROM follow_up_tasks t
     JOIN contacts c ON c.id = t.contact_id
     LEFT JOIN staff_directory sd ON sd.user_id = t.assigned_to
     LEFT JOIN contact_journeys cj ON cj.id = t.journey_id
     LEFT JOIN journey_definitions jd ON jd.journey_key = cj.journey_key
     LEFT JOIN contact_journey_steps s ON s.id = t.journey_step_id
  WHERE t.status = 'open'::text;

CREATE VIEW "public"."my_achievements" WITH (security_invoker=true) AS
 SELECT ma.id,
    ma.contact_id,
    ma.membership_id,
    ma.achievement_key,
    ac.title,
    ac.description,
    ac.category,
    ac.icon_key,
    ma.unlocked_at,
    ma.source_type,
    ma.source_id,
    ma.metadata
   FROM member_achievements ma
     JOIN achievement_catalog ac ON ac.achievement_key = ma.achievement_key
  WHERE (EXISTS ( SELECT 1
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.contact_id = ma.contact_id AND ca.status = 'active'::text))
  ORDER BY ma.unlocked_at DESC, ac.display_order;

CREATE VIEW "public"."my_active_app_routes" WITH (security_invoker=true) AS
 SELECT route_key,
    route_path,
    screen_name,
    feature_key,
    requires_auth,
    requires_feature_access,
    metadata
   FROM app_route_registry
  WHERE active
  ORDER BY route_key;

CREATE VIEW "public"."my_active_fitness_plan" WITH (security_invoker=true) AS
 SELECT fp.id AS fitness_plan_id,
    fp.title,
    fp.starts_on,
    fp.status,
    fp.notes,
    p.title AS program_title,
    p.difficulty,
    p.environment,
    p.weeks
   FROM client_access ca
     JOIN client_fitness_plans fp ON fp.contact_id = ca.contact_id
     LEFT JOIN fitness_programs p ON p.id = fp.program_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND fp.status = 'active'::text
  ORDER BY fp.starts_on DESC
 LIMIT 1;

CREATE VIEW "public"."my_active_meal_plan" WITH (security_invoker=true) AS
 SELECT mp.id AS meal_plan_id,
    mp.title,
    mp.starts_on,
    mp.ends_on,
    mp.notes,
    mp.status,
    t.title AS template_title,
    p.name AS phase_name
   FROM client_access ca
     JOIN client_meal_plans mp ON mp.contact_id = ca.contact_id
     LEFT JOIN meal_plan_templates t ON t.id = mp.template_id
     LEFT JOIN nutrition_phases p ON p.id = t.phase_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND mp.status = 'active'::text
  ORDER BY mp.starts_on DESC
 LIMIT 1;

CREATE VIEW "public"."my_agreements" WITH (security_invoker=true) AS
 SELECT ca.id AS client_agreement_id,
    ca.agreement_key,
    at.name,
    at.document_type,
    ca.template_version,
    at.description,
    COALESCE(ca.rendered_content_text, at.content_text) AS content_text,
    ca.merge_values,
    ca.status,
    ca.required_client_signatures,
    ca.sent_at,
    ca.viewed_at,
    ca.signed_at,
    ( SELECT count(*) AS count
           FROM agreement_acceptances aa
          WHERE aa.client_agreement_id = ca.id AND (aa.signer_role = ANY (ARRAY['primary_client'::text, 'secondary_client'::text]))) AS signature_count,
    ( SELECT aa.signer_name
           FROM agreement_acceptances aa
          WHERE aa.client_agreement_id = ca.id AND aa.signer_role = 'primary_client'::text
         LIMIT 1) AS primary_signer_name,
    ( SELECT aa.signer_name
           FROM agreement_acceptances aa
          WHERE aa.client_agreement_id = ca.id AND aa.signer_role = 'secondary_client'::text
         LIMIT 1) AS secondary_signer_name,
    ( SELECT max(aa.signed_at) AS max
           FROM agreement_acceptances aa
          WHERE aa.client_agreement_id = ca.id AND (aa.signer_role = ANY (ARRAY['primary_client'::text, 'secondary_client'::text]))) AS acceptance_signed_at
   FROM client_access access
     JOIN client_agreements ca ON ca.contact_id = access.contact_id
     JOIN agreement_templates at ON at.id = ca.agreement_template_id
  WHERE access.user_id = (( SELECT auth.uid() AS uid))
  ORDER BY ca.created_at;

CREATE VIEW "public"."my_ai_advisor_personalization" WITH (security_invoker=true) AS
 SELECT ca.user_id,
    ca.contact_id,
    COALESCE(p.personalization_enabled, false) AS personalization_enabled,
    COALESCE(p.allow_program_context, true) AS allow_program_context,
    COALESCE(p.allow_daily_plan, true) AS allow_daily_plan,
    COALESCE(p.allow_goals, true) AS allow_goals,
    COALESCE(p.allow_course_progress, true) AS allow_course_progress,
    COALESCE(p.allow_coaching_momentum, true) AS allow_coaching_momentum,
    COALESCE(p.allow_health_summary, false) AS allow_health_summary,
    p.consented_at,
    p.revoked_at,
    p.updated_at
   FROM client_access ca
     LEFT JOIN ai_advisor_personalization_preferences p ON p.user_id = ca.user_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.status = 'active'::text
  ORDER BY ca.updated_at DESC
 LIMIT 1;

CREATE VIEW "public"."my_ai_advisor_usage" WITH (security_invoker=true) AS
 SELECT me.id AS entitlement_id,
    me.membership_id,
    me.status,
    me.limit_value,
    COALESCE(me.used_value, 0) AS used_value,
    me.reset_cadence,
    me.period_started_at,
        CASE
            WHEN me.limit_value IS NULL THEN NULL::integer
            ELSE GREATEST(me.limit_value - COALESCE(me.used_value, 0), 0)
        END AS remaining_value,
        CASE
            WHEN me.limit_value IS NULL OR me.limit_value = 0 THEN NULL::numeric
            ELSE round(COALESCE(me.used_value, 0)::numeric / me.limit_value::numeric * 100::numeric, 1)
        END AS percent_used
   FROM membership_entitlements me
     JOIN client_access ca ON ca.membership_id = me.membership_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.status = 'active'::text AND me.entitlement_key = 'ai_advisor'::text
  ORDER BY me.created_at DESC
 LIMIT 1;

CREATE VIEW "public"."my_ambassador_center" WITH (security_invoker=true) AS
 SELECT ca.user_id,
    ca.contact_id,
    rp.referral_code,
    rp.status AS referral_profile_status,
    rp.display_name,
    count(DISTINCT r.id) AS total_referrals,
    count(DISTINCT r.id) FILTER (WHERE r.status = 'converted'::text) AS converted_referrals,
    count(DISTINCT rr.id) FILTER (WHERE rr.status = ANY (ARRAY['pending'::text, 'approved'::text])) AS pending_rewards,
    count(DISTINCT rr.id) FILTER (WHERE rr.status = 'issued'::text) AS issued_rewards,
    COALESCE(sum(rr.reward_value) FILTER (WHERE rr.status = ANY (ARRAY['pending'::text, 'approved'::text])), 0::numeric) AS pending_reward_value,
    COALESCE(sum(rr.reward_value) FILTER (WHERE rr.status = 'issued'::text), 0::numeric) AS issued_reward_value,
    max(rr.currency) FILTER (WHERE rr.reward_value IS NOT NULL) AS reward_currency,
    count(DISTINCT r.id) FILTER (WHERE r.status = 'referred'::text) AS referred_count,
    count(DISTINCT r.id) FILTER (WHERE r.status = 'engaged'::text) AS engaged_count,
    count(DISTINCT r.id) FILTER (WHERE r.status = 'applicant'::text) AS applicant_count,
    count(DISTINCT rr.id) FILTER (WHERE rr.status = 'approved'::text) AS approved_reward_count,
        CASE
            WHEN rp.referral_code IS NOT NULL THEN 'https://revitalizedacademy.com/enroll?ref='::text || rp.referral_code
            ELSE NULL::text
        END AS share_url,
        CASE
            WHEN rp.referral_code IS NOT NULL THEN 'I wanted to share ReVitalized Academy with you. You can learn more and get started here: https://revitalizedacademy.com/enroll?ref='::text || rp.referral_code
            ELSE NULL::text
        END AS share_message
   FROM client_access ca
     LEFT JOIN referral_profiles rp ON rp.contact_id = ca.contact_id
     LEFT JOIN referrals r ON r.referrer_contact_id = ca.contact_id
     LEFT JOIN referral_rewards rr ON rr.referrer_contact_id = ca.contact_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
  GROUP BY ca.user_id, ca.contact_id, rp.referral_code, rp.status, rp.display_name;

CREATE VIEW "public"."my_app_runtime" WITH (security_invoker=true) AS
 SELECT jsonb_object_agg(config_key, config_value ORDER BY config_key) AS config,
    max(updated_at) AS last_updated_at
   FROM app_runtime_config
  WHERE active AND member_visible;

CREATE VIEW "public"."my_assignment_summary" WITH (security_invoker=true) AS
 SELECT ca.user_id,
    ca.contact_id,
    count(a.id) FILTER (WHERE a.status = 'assigned'::text) AS assigned_count,
    count(a.id) FILTER (WHERE a.status = 'in_progress'::text) AS in_progress_count,
    count(a.id) FILTER (WHERE a.status = 'completed'::text) AS completed_count,
    count(a.id) FILTER (WHERE (a.status = ANY (ARRAY['assigned'::text, 'in_progress'::text])) AND a.due_at IS NOT NULL AND a.due_at < now()) AS overdue_count,
    count(a.id) FILTER (WHERE (a.status = ANY (ARRAY['assigned'::text, 'in_progress'::text])) AND a.due_at IS NOT NULL AND a.due_at >= now() AND a.due_at < (now() + '7 days'::interval)) AS due_next_7_days,
    min(a.due_at) FILTER (WHERE (a.status = ANY (ARRAY['assigned'::text, 'in_progress'::text])) AND a.due_at IS NOT NULL AND a.due_at >= now()) AS next_due_at
   FROM client_access ca
     LEFT JOIN client_assignments a ON a.contact_id = ca.contact_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
  GROUP BY ca.user_id, ca.contact_id;

CREATE VIEW "public"."my_billing_summary" WITH (security_invoker=true) AS
 SELECT ms.id AS subscription_id,
    bp.name AS billing_plan_name,
    bp.billing_interval,
    bp.interval_count,
    bp.amount_cents,
    bp.currency,
    bp.commitment_months,
    ms.status,
    ms.started_at,
    ms.next_charge_at,
    ms.commitment_ends_at,
    ms.grace_period_ends_at,
    ms.failed_payment_count,
    ms.last_payment_at,
    ms.cancel_at_period_end
   FROM client_access ca
     JOIN membership_subscriptions ms ON ms.contact_id = ca.contact_id
     LEFT JOIN billing_plans bp ON bp.id = ms.billing_plan_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid));

CREATE VIEW "public"."my_calendar_feed_60d" WITH (security_invoker=true) AS
 WITH access_rows AS (
         SELECT ca.user_id,
            ca.contact_id,
            ca.household_id,
            ca.membership_id
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.status = 'active'::text
        ), appointments AS (
         SELECT a.contact_id,
            ca.household_id,
            a.id AS source_id,
            'appointment'::text AS item_type,
            COALESCE(a.appointment_type, 'Appointment'::text) AS title,
            a.status,
            a.scheduled_start AS starts_at,
            a.scheduled_end AS ends_at,
            a.scheduled_start::date AS item_date,
            false AS all_day,
            a.location_url,
            jsonb_build_object('source', 'journey_appointment', 'format', a.format, 'assigned_to', a.assigned_to) AS metadata
           FROM journey_appointments a
             JOIN access_rows ca ON ca.contact_id = a.contact_id
          WHERE a.scheduled_start >= (now() - '7 days'::interval) AND a.scheduled_start < (now() + '60 days'::interval) AND a.status <> 'cancelled'::text
        UNION ALL
         SELECT cs.contact_id,
            ca.household_id,
            cs.id,
            'coaching_session'::text AS text,
            'Coaching Session'::text AS text,
            cs.status,
            cs.scheduled_start,
            cs.scheduled_end,
            cs.scheduled_start::date AS scheduled_start,
            false,
            cs.location_url,
            jsonb_build_object('source', 'coaching_session', 'session_number', cs.session_number, 'format', cs.format, 'coach_user_id', cs.coach_user_id) AS jsonb_build_object
           FROM coaching_sessions cs
             JOIN access_rows ca ON ca.contact_id = cs.contact_id
          WHERE cs.scheduled_start >= (now() - '7 days'::interval) AND cs.scheduled_start < (now() + '60 days'::interval) AND cs.status <> 'cancelled'::text
        ), workouts AS (
         SELECT wa.contact_id,
            ca.household_id,
            wa.id AS source_id,
            'workout'::text AS item_type,
            wt.title,
            wa.status,
            NULL::timestamp with time zone AS starts_at,
            NULL::timestamp with time zone AS ends_at,
            wa.scheduled_date AS item_date,
            true AS all_day,
            NULL::text AS location_url,
            jsonb_build_object('source', 'workout_assignment', 'workout_id', wa.workout_id, 'category', wt.category, 'difficulty', wt.difficulty, 'duration_minutes', wt.duration_minutes) AS metadata
           FROM client_workout_assignments wa
             JOIN access_rows ca ON ca.contact_id = wa.contact_id
             JOIN workout_templates wt ON wt.id = wa.workout_id
          WHERE wa.scheduled_date >= (CURRENT_DATE - 7) AND wa.scheduled_date <= (CURRENT_DATE + 60) AND wa.status <> 'cancelled'::text
        ), meals AS (
         SELECT mi.contact_id,
            ca.household_id,
            mi.id AS source_id,
            'meal'::text AS item_type,
            COALESCE(r.title, mi.custom_title, 'Meal'::text) AS title,
            mi.status,
            NULL::timestamp with time zone AS starts_at,
            NULL::timestamp with time zone AS ends_at,
            mi.scheduled_date AS item_date,
            true AS all_day,
            NULL::text AS location_url,
            jsonb_build_object('source', 'meal_plan_item', 'meal_slot', mi.meal_slot, 'recipe_id', mi.recipe_id, 'adherence_percent', mi.adherence_percent) AS metadata
           FROM client_meal_plan_items mi
             JOIN access_rows ca ON ca.contact_id = mi.contact_id
             LEFT JOIN recipes r ON r.id = mi.recipe_id
          WHERE mi.scheduled_date >= (CURRENT_DATE - 7) AND mi.scheduled_date <= (CURRENT_DATE + 60)
        ), goals AS (
         SELECT g.contact_id,
            COALESCE(g.household_id, ca.household_id) AS household_id,
            g.id AS source_id,
            'goal_due'::text AS item_type,
            g.title,
            g.status,
            NULL::timestamp with time zone AS starts_at,
            NULL::timestamp with time zone AS ends_at,
            g.target_date AS item_date,
            true AS all_day,
            NULL::text AS location_url,
            jsonb_build_object('source', 'client_goal', 'scope', g.scope, 'goal_key', g.goal_key, 'priority', g.priority, 'target_value', g.target_value, 'target_unit', g.target_unit) AS metadata
           FROM client_goals g
             JOIN access_rows ca ON ca.contact_id = g.contact_id
          WHERE g.target_date >= (CURRENT_DATE - 7) AND g.target_date <= (CURRENT_DATE + 60) AND (g.status = ANY (ARRAY['active'::text, 'paused'::text]))
        ), challenges AS (
         SELECT ce.contact_id,
            COALESCE(ce.household_id, ca.household_id) AS household_id,
            ce.id AS source_id,
            'challenge_end'::text AS item_type,
            wc.title,
            ce.status,
            NULL::timestamp with time zone AS starts_at,
            NULL::timestamp with time zone AS ends_at,
            wc.ends_on AS item_date,
            true AS all_day,
            NULL::text AS location_url,
            jsonb_build_object('source', 'challenge_enrollment', 'challenge_id', wc.id, 'scope', ce.scope, 'completion_percent', ce.completion_percent, 'points_earned', ce.points_earned, 'target_value', wc.target_value, 'unit', wc.unit) AS metadata
           FROM challenge_enrollments ce
             JOIN access_rows ca ON ca.contact_id = ce.contact_id OR ca.household_id IS NOT NULL AND ca.household_id = ce.household_id
             JOIN wellness_challenges wc ON wc.id = ce.challenge_id
          WHERE wc.ends_on >= (CURRENT_DATE - 7) AND wc.ends_on <= (CURRENT_DATE + 60) AND (ce.status = ANY (ARRAY['active'::text, 'paused'::text]))
        )
 SELECT appointments.contact_id,
    appointments.household_id,
    appointments.source_id,
    appointments.item_type,
    appointments.title,
    appointments.status,
    appointments.starts_at,
    appointments.ends_at,
    appointments.item_date,
    appointments.all_day,
    appointments.location_url,
    appointments.metadata
   FROM appointments
UNION ALL
 SELECT workouts.contact_id,
    workouts.household_id,
    workouts.source_id,
    workouts.item_type,
    workouts.title,
    workouts.status,
    workouts.starts_at,
    workouts.ends_at,
    workouts.item_date,
    workouts.all_day,
    workouts.location_url,
    workouts.metadata
   FROM workouts
UNION ALL
 SELECT meals.contact_id,
    meals.household_id,
    meals.source_id,
    meals.item_type,
    meals.title,
    meals.status,
    meals.starts_at,
    meals.ends_at,
    meals.item_date,
    meals.all_day,
    meals.location_url,
    meals.metadata
   FROM meals
UNION ALL
 SELECT goals.contact_id,
    goals.household_id,
    goals.source_id,
    goals.item_type,
    goals.title,
    goals.status,
    goals.starts_at,
    goals.ends_at,
    goals.item_date,
    goals.all_day,
    goals.location_url,
    goals.metadata
   FROM goals
UNION ALL
 SELECT challenges.contact_id,
    challenges.household_id,
    challenges.source_id,
    challenges.item_type,
    challenges.title,
    challenges.status,
    challenges.starts_at,
    challenges.ends_at,
    challenges.item_date,
    challenges.all_day,
    challenges.location_url,
    challenges.metadata
   FROM challenges;

CREATE VIEW "public"."my_challenges" WITH (security_invoker=true) AS
 SELECT ce.id AS enrollment_id,
    ce.scope,
    ce.status AS enrollment_status,
    ce.current_value,
    ce.completion_percent,
    ce.points_earned,
    wc.id AS challenge_id,
    wc.challenge_key,
    wc.title,
    wc.description,
    wc.target_key,
    wc.aggregation,
    wc.target_value,
    wc.unit,
    wc.starts_on,
    wc.ends_on,
    wc.points_available
   FROM client_access ca
     JOIN challenge_enrollments ce ON ce.contact_id = ca.contact_id OR ca.household_id IS NOT NULL AND ce.household_id = ca.household_id
     JOIN wellness_challenges wc ON wc.id = ce.challenge_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND (ce.status = ANY (ARRAY['active'::text, 'completed'::text, 'paused'::text]))
  ORDER BY (
        CASE ce.status
            WHEN 'active'::text THEN 1
            WHEN 'paused'::text THEN 2
            ELSE 3
        END), wc.ends_on;

CREATE VIEW "public"."my_client_assignments" WITH (security_invoker=true) AS
 SELECT a.id,
    a.title,
    a.instructions,
    a.assignment_type,
    a.due_at,
    a.status,
    a.completed_at,
    a.member_note,
    a.created_at,
    sd.display_name AS assigned_by_name
   FROM client_assignments a
     LEFT JOIN staff_directory sd ON sd.user_id = a.assigned_by
     JOIN client_access ca ON ca.contact_id = a.contact_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND a.status <> 'cancelled'::text
  ORDER BY (
        CASE a.status
            WHEN 'assigned'::text THEN 1
            WHEN 'in_progress'::text THEN 2
            WHEN 'completed'::text THEN 3
            ELSE 4
        END), a.due_at, a.created_at DESC;

CREATE VIEW "public"."my_coach" WITH (security_invoker=true) AS
 SELECT cca.contact_id,
    cca.coach_user_id,
    cca.role,
    cca.status,
    sd.display_name AS coach_name
   FROM client_coach_assignments cca
     JOIN client_access ca ON ca.contact_id = cca.contact_id
     LEFT JOIN staff_directory sd ON sd.user_id = cca.coach_user_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND cca.status = 'active'::text;

CREATE VIEW "public"."my_coaching_requests" WITH (security_invoker=true) AS
 SELECT ja.id AS appointment_id,
    ja.status,
    ja.requested_availability,
    ja.client_notes,
    ja.scheduled_start,
    ja.scheduled_end,
    ja.time_zone,
    ja.format,
    ja.location_url,
    ja.assigned_to,
    sd.display_name AS assigned_coach_name,
    ja.created_at,
    ja.updated_at
   FROM client_access ca
     JOIN journey_appointments ja ON ja.contact_id = ca.contact_id
     LEFT JOIN staff_directory sd ON sd.user_id = ja.assigned_to
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ja.appointment_type = 'coaching_session'::text
  ORDER BY ja.created_at DESC;

CREATE VIEW "public"."my_coaching_sessions" WITH (security_invoker=true) AS
 SELECT cs.id AS session_id,
    cs.contact_id,
    cs.membership_id,
    cs.coach_user_id,
    sd.display_name AS coach_name,
    cs.appointment_id,
    cs.session_number,
    cs.status,
    cs.scheduled_start,
    cs.scheduled_end,
    cs.format,
    cs.location_url,
    cs.client_agenda,
    cs.completed_at,
    cs.created_at
   FROM client_access ca
     JOIN coaching_sessions cs ON cs.contact_id = ca.contact_id
     LEFT JOIN staff_directory sd ON sd.user_id = cs.coach_user_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
  ORDER BY cs.scheduled_start DESC NULLS LAST, cs.created_at DESC;

CREATE VIEW "public"."my_community_feed" WITH (security_invoker=true) AS
 SELECT p.id AS post_id,
    p.space_id,
    s.name AS space_name,
    s.space_type,
    p.post_type,
    p.title,
    p.body,
    p.pinned,
    p.created_at,
    p.author_user_id,
    COALESCE(sa.display_name, c.first_name, 'ReVitalized Member'::text) AS author_name,
    ( SELECT count(*) AS count
           FROM community_comments cc
          WHERE cc.post_id = p.id AND cc.status = 'published'::text) AS comment_count,
    ( SELECT count(*) AS count
           FROM community_reactions cr
          WHERE cr.post_id = p.id) AS reaction_count
   FROM community_posts p
     JOIN community_spaces s ON s.id = p.space_id
     JOIN community_memberships cm ON cm.space_id = p.space_id AND cm.user_id = (( SELECT auth.uid() AS uid)) AND (cm.status = ANY (ARRAY['active'::text, 'muted'::text]))
     LEFT JOIN staff_access sa ON sa.user_id = p.author_user_id
     LEFT JOIN contacts c ON c.id = p.author_contact_id
  WHERE p.status = 'published'::text AND s.status = 'active'::text
  ORDER BY p.pinned DESC, p.created_at DESC
 LIMIT 100;

CREATE VIEW "public"."my_community_spaces" WITH (security_invoker=true) AS
 SELECT s.id AS space_id,
    s.space_key,
    s.name,
    s.description,
    s.space_type,
    s.program_code,
    s.household_id,
    s.challenge_id,
    s.posting_mode,
    cm.membership_role,
    cm.status AS membership_status
   FROM community_memberships cm
     JOIN community_spaces s ON s.id = cm.space_id
  WHERE cm.user_id = (( SELECT auth.uid() AS uid)) AND (cm.status = ANY (ARRAY['active'::text, 'muted'::text])) AND s.status = 'active'::text
  ORDER BY (
        CASE s.space_type
            WHEN 'household'::text THEN 1
            WHEN 'program'::text THEN 2
            WHEN 'challenge'::text THEN 3
            ELSE 4
        END), s.name;

CREATE VIEW "public"."my_companion_answer_sources" WITH (security_invoker=true) AS
 SELECT rs.request_id,
    rs.rank,
    rs.similarity,
    rs.used_in_answer,
    s.source_key,
    s.title AS source_title,
    s.source_type,
    s.version AS source_version,
    ch.heading,
    s.approved_at
   FROM coach_companion_request_sources rs
     JOIN coach_companion_requests r ON r.id = rs.request_id
     JOIN coach_companion_knowledge_chunks ch ON ch.id = rs.chunk_id
     JOIN coach_companion_knowledge_sources s ON s.id = ch.source_id
  WHERE r.requested_by_user_id = (( SELECT auth.uid() AS uid)) AND (r.status = ANY (ARRAY['answered'::text, 'resolved'::text])) AND s.status = 'approved'::text
  ORDER BY rs.request_id, rs.rank;

CREATE VIEW "public"."my_companion_feedback" WITH (security_invoker=true) AS
 SELECT request_id,
    helpful,
    feedback_reason,
    comment,
    created_at,
    updated_at
   FROM coach_companion_answer_feedback f
  WHERE user_id = (( SELECT auth.uid() AS uid))
  ORDER BY updated_at DESC;

CREATE VIEW "public"."my_companion_question_types" WITH (security_invoker=true) AS
 SELECT question_type,
    label,
    description,
    handling_mode,
    requires_coach_assignment,
    sort_order
   FROM coach_companion_question_types qt
  WHERE active AND member_visible
  ORDER BY sort_order, label;

CREATE VIEW "public"."my_companion_request_context" WITH (security_invoker=true) AS
 SELECT cs.request_id,
    cs.question_type,
    cs.personal_context_allowed,
    cs.context_version,
    cs.context_payload,
    cs.generated_at
   FROM coach_companion_context_snapshots cs
     JOIN coach_companion_requests r ON r.id = cs.request_id
  WHERE r.requested_by_user_id = (( SELECT auth.uid() AS uid))
  ORDER BY cs.generated_at DESC;

CREATE VIEW "public"."my_companion_requests" WITH (security_invoker=true) AS
 SELECT r.id AS request_id,
    r.question_type,
    qt.label AS question_type_label,
    r.question,
    r.handling_mode,
    r.status,
    r.final_answer,
    r.escalation_reason,
    r.assigned_coach_id,
    sd.display_name AS assigned_coach_name,
    r.answered_by_type,
    r.created_at,
    r.answered_at,
    r.updated_at
   FROM coach_companion_requests r
     LEFT JOIN coach_companion_question_types qt ON qt.question_type = r.question_type
     LEFT JOIN staff_directory sd ON sd.user_id = r.assigned_coach_id
  WHERE r.requested_by_user_id = (( SELECT auth.uid() AS uid))
  ORDER BY r.created_at DESC;

CREATE VIEW "public"."my_companion_summary" WITH (security_invoker=true) AS
 SELECT ca.user_id,
    ca.contact_id,
    ca.membership_id,
    count(r.id) AS total_questions,
    count(r.id) FILTER (WHERE r.status = ANY (ARRAY['queued'::text, 'retrieving'::text, 'draft_ready'::text])) AS processing_count,
    count(r.id) FILTER (WHERE r.status = ANY (ARRAY['coach_review'::text, 'escalated'::text])) AS coach_review_count,
    count(r.id) FILTER (WHERE r.status = ANY (ARRAY['answered'::text, 'resolved'::text])) AS answered_count,
    max(r.created_at) AS last_question_at,
    max(r.answered_at) AS last_answered_at
   FROM client_access ca
     LEFT JOIN coach_companion_requests r ON r.requested_by_user_id = ca.user_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
  GROUP BY ca.user_id, ca.contact_id, ca.membership_id;

CREATE VIEW "public"."my_conversations" WITH (security_invoker=true) AS
 SELECT c.id AS conversation_id,
    c.conversation_type,
    c.title,
    c.status,
    c.last_message_at,
    p.last_read_at,
    ( SELECT count(*) AS count
           FROM member_messages m
          WHERE m.conversation_id = c.id AND m.deleted_at IS NULL AND m.sender_user_id <> (( SELECT auth.uid() AS uid)) AND (p.last_read_at IS NULL OR m.created_at > p.last_read_at)) AS unread_count,
    ( SELECT "left"(m.body, 180) AS "left"
           FROM member_messages m
          WHERE m.conversation_id = c.id AND m.deleted_at IS NULL
          ORDER BY m.created_at DESC
         LIMIT 1) AS last_message_preview
   FROM member_conversation_participants p
     JOIN member_conversations c ON c.id = p.conversation_id
  WHERE p.user_id = (( SELECT auth.uid() AS uid)) AND p.left_at IS NULL AND c.status = 'active'::text
  ORDER BY c.last_message_at DESC NULLS LAST, c.created_at DESC;

CREATE VIEW "public"."my_course_lessons" WITH (security_invoker=true) AS
 SELECT ca.user_id,
    e.id AS enrollment_id,
    c.id AS course_id,
    m.id AS module_id,
    m.title AS module_title,
    m.module_order,
    l.id AS lesson_id,
    l.title AS lesson_title,
    l.description AS lesson_description,
    l.lesson_order,
    l.lesson_type,
    l.media_url,
    l.duration_seconds,
    l.requires_completion,
    COALESCE(lp.status, 'not_started'::text) AS progress_status,
    COALESCE(lp.progress_seconds, 0) AS progress_seconds,
    COALESCE(lp.completion_percent, 0) AS completion_percent,
    lp.completed_at
   FROM client_access ca
     JOIN client_course_enrollments e ON e.contact_id = ca.contact_id
     JOIN learning_courses c ON c.id = e.course_id AND c.status = 'published'::text
     JOIN learning_modules m ON m.course_id = c.id AND m.active
     JOIN learning_lessons l ON l.module_id = m.id AND l.status = 'published'::text
     LEFT JOIN lesson_progress lp ON lp.enrollment_id = e.id AND lp.lesson_id = l.id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND e.status <> 'cancelled'::text
  ORDER BY c.title, m.module_order, l.lesson_order;

CREATE VIEW "public"."my_course_progress_summary" WITH (security_invoker=true) AS
 SELECT cce.id AS enrollment_id,
    cce.course_id,
    lc.title AS course_title,
    cce.status,
    cce.progress_percent,
    cce.started_at,
    cce.completed_at,
    count(ll.id) FILTER (WHERE ll.requires_completion AND ll.status = 'published'::text) AS required_lessons,
    count(lp.id) FILTER (WHERE lp.status = 'completed'::text) AS completed_lessons,
    max(lp.last_activity_at) AS last_lesson_activity_at
   FROM client_access ca
     JOIN client_course_enrollments cce ON cce.contact_id = ca.contact_id
     JOIN learning_courses lc ON lc.id = cce.course_id
     LEFT JOIN learning_modules lm ON lm.course_id = lc.id AND lm.active
     LEFT JOIN learning_lessons ll ON ll.module_id = lm.id AND ll.status = 'published'::text
     LEFT JOIN lesson_progress lp ON lp.enrollment_id = cce.id AND lp.lesson_id = ll.id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND cce.status <> 'cancelled'::text
  GROUP BY cce.id, cce.course_id, lc.title, cce.status, cce.progress_percent, cce.started_at, cce.completed_at
  ORDER BY (
        CASE cce.status
            WHEN 'active'::text THEN 1
            WHEN 'paused'::text THEN 2
            WHEN 'completed'::text THEN 3
            ELSE 4
        END), lc.title;

CREATE VIEW "public"."my_courses" WITH (security_invoker=true) AS
 SELECT e.id AS enrollment_id,
    e.course_id,
    c.title,
    c.description,
    c.estimated_minutes,
    c.thumbnail_url,
    e.status,
    e.progress_percent,
    e.last_lesson_id,
    e.last_activity_at,
    e.started_at,
    e.completed_at
   FROM client_access ca
     JOIN client_course_enrollments e ON e.contact_id = ca.contact_id
     JOIN learning_courses c ON c.id = e.course_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND e.status <> 'cancelled'::text AND c.status = 'published'::text
  ORDER BY (
        CASE e.status
            WHEN 'active'::text THEN 1
            WHEN 'paused'::text THEN 2
            WHEN 'completed'::text THEN 3
            ELSE 4
        END), c.title;

CREATE VIEW "public"."my_daily_plan_history_30d" WITH (security_invoker=true) AS
 WITH me AS (
         SELECT ca.contact_id
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.status = 'active'::text
          ORDER BY ca.updated_at DESC
         LIMIT 1
        ), days AS (
         SELECT generate_series((CURRENT_DATE - 29)::timestamp with time zone, CURRENT_DATE::timestamp with time zone, '1 day'::interval)::date AS action_date
        ), habit_daily AS (
         SELECT d_1.action_date,
            count(h_1.id)::integer AS assigned,
            count(h_1.id) FILTER (WHERE COALESCE(hc.value, 0::numeric) >= h_1.target_per_period)::integer AS completed
           FROM days d_1
             CROSS JOIN me
             LEFT JOIN client_habits h_1 ON h_1.contact_id = me.contact_id AND h_1.status = 'active'::text AND h_1.starts_on <= d_1.action_date AND (h_1.ends_on IS NULL OR h_1.ends_on >= d_1.action_date)
             LEFT JOIN habit_checkins hc ON hc.habit_id = h_1.id AND hc.contact_id = me.contact_id AND hc.checkin_date = d_1.action_date
          GROUP BY d_1.action_date
        ), meal_daily AS (
         SELECT d_1.action_date,
            count(mi.id)::integer AS assigned,
            count(mi.id) FILTER (WHERE mi.status = 'completed'::text)::integer AS completed
           FROM days d_1
             CROSS JOIN me
             LEFT JOIN client_meal_plan_items mi ON mi.contact_id = me.contact_id AND mi.scheduled_date = d_1.action_date
          GROUP BY d_1.action_date
        ), workout_daily AS (
         SELECT d_1.action_date,
            count(wa.id)::integer AS assigned,
            count(wa.id) FILTER (WHERE wa.status = 'completed'::text)::integer AS completed
           FROM days d_1
             CROSS JOIN me
             LEFT JOIN client_workout_assignments wa ON wa.contact_id = me.contact_id AND wa.scheduled_date = d_1.action_date
          GROUP BY d_1.action_date
        )
 SELECT d.action_date,
    COALESCE(h.assigned, 0) AS habits_assigned,
    COALESCE(h.completed, 0) AS habits_completed,
    COALESCE(m.assigned, 0) AS meals_assigned,
    COALESCE(m.completed, 0) AS meals_completed,
    COALESCE(w.assigned, 0) AS workouts_assigned,
    COALESCE(w.completed, 0) AS workouts_completed,
    COALESCE(h.assigned, 0) + COALESCE(m.assigned, 0) + COALESCE(w.assigned, 0) AS total_actions,
    COALESCE(h.completed, 0) + COALESCE(m.completed, 0) + COALESCE(w.completed, 0) AS completed_actions,
        CASE
            WHEN (COALESCE(h.assigned, 0) + COALESCE(m.assigned, 0) + COALESCE(w.assigned, 0)) = 0 THEN NULL::numeric
            ELSE round((COALESCE(h.completed, 0) + COALESCE(m.completed, 0) + COALESCE(w.completed, 0))::numeric / (COALESCE(h.assigned, 0) + COALESCE(m.assigned, 0) + COALESCE(w.assigned, 0))::numeric * 100::numeric, 1)
        END AS completion_percent,
    (COALESCE(h.assigned, 0) + COALESCE(m.assigned, 0) + COALESCE(w.assigned, 0)) > 0 AND (COALESCE(h.completed, 0) + COALESCE(m.completed, 0) + COALESCE(w.completed, 0)) >= (COALESCE(h.assigned, 0) + COALESCE(m.assigned, 0) + COALESCE(w.assigned, 0)) AS fully_completed
   FROM days d
     LEFT JOIN habit_daily h ON h.action_date = d.action_date
     LEFT JOIN meal_daily m ON m.action_date = d.action_date
     LEFT JOIN workout_daily w ON w.action_date = d.action_date
  ORDER BY d.action_date;

CREATE VIEW "public"."my_device_summary" WITH (security_invoker=true) AS
 SELECT count(*) FILTER (WHERE revoked_at IS NULL)::integer AS active_devices,
    count(*) FILTER (WHERE revoked_at IS NULL AND push_enabled AND push_token IS NOT NULL)::integer AS push_ready_devices,
    max(last_seen_at) AS last_device_seen_at,
    max(app_version) FILTER (WHERE revoked_at IS NULL) AS latest_app_version_seen
   FROM member_devices
  WHERE user_id = (( SELECT auth.uid() AS uid));

CREATE VIEW "public"."my_devices" WITH (security_invoker=true) AS
 SELECT id AS device_id,
    device_key,
    platform,
    push_provider,
    push_enabled,
    app_version,
    os_version,
    device_model,
    locale,
    time_zone,
    last_seen_at,
    registered_at,
    push_token_updated_at,
    revoked_at,
    push_token IS NOT NULL AS has_push_token
   FROM member_devices
  WHERE user_id = (( SELECT auth.uid() AS uid))
  ORDER BY revoked_at NULLS FIRST, last_seen_at DESC;

CREATE VIEW "public"."my_documents" WITH (security_invoker=true) AS
 SELECT d.id AS document_id,
    d.category,
    d.title,
    d.description,
    d.storage_path,
    d.original_filename,
    d.content_type,
    d.size_bytes,
    d.created_at,
    d.updated_at
   FROM client_access ca
     JOIN client_documents d ON d.contact_id = ca.contact_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND d.status = 'active'::text AND d.member_visible
  ORDER BY d.created_at DESC;

CREATE VIEW "public"."my_enrollment_readiness" WITH (security_invoker=true) AS
 SELECT a.id AS activation_id,
    a.program_code,
    a.program_name,
    a.amount_cents AS agreed_amount_cents,
    a.currency,
    a.payment_status,
    a.agreement_status,
    a.access_status,
    COALESCE(( SELECT count(*)::integer AS count
           FROM client_agreements ca_1
          WHERE ca_1.activation_id = a.id AND (ca_1.status <> ALL (ARRAY['signed'::text, 'waived'::text]))), 0) AS incomplete_agreements,
    COALESCE(( SELECT sum(ca_1.required_client_signatures)::integer AS sum
           FROM client_agreements ca_1
          WHERE ca_1.activation_id = a.id), 0) AS required_signatures,
    COALESCE(( SELECT count(*)::integer AS count
           FROM agreement_acceptances aa
             JOIN client_agreements ca_1 ON ca_1.id = aa.client_agreement_id
          WHERE ca_1.activation_id = a.id AND (aa.signer_role = ANY (ARRAY['primary_client'::text, 'secondary_client'::text]))), 0) AS collected_signatures,
    (a.payment_status = ANY (ARRAY['paid'::text, 'waived'::text])) AND (a.agreement_status = ANY (ARRAY['signed'::text, 'waived'::text])) AS enrollment_requirements_complete
   FROM journey_enrollment_activations a
     JOIN client_access ca ON ca.contact_id = a.contact_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.status = 'active'::text
  ORDER BY a.created_at DESC
 LIMIT 1;

CREATE VIEW "public"."my_family_hub_summary" WITH (security_invoker=true) AS
 SELECT ca.user_id,
    ca.contact_id,
    ca.household_id,
    h.household_name,
    h.household_type,
    h.status AS household_status,
    count(hm.id) FILTER (WHERE hm.status = 'active'::text) AS active_members,
    count(hm.id) FILTER (WHERE hm.status = 'active'::text AND hm.is_primary = false) AS additional_members,
    count(hm.id) FILTER (WHERE hm.status = 'active'::text AND hm.date_of_birth IS NOT NULL AND hm.date_of_birth > (CURRENT_DATE - '18 years'::interval)) AS minors,
    ( SELECT count(*) AS count
           FROM client_goals cg
          WHERE cg.household_id = ca.household_id AND cg.scope = 'household'::text AND cg.status = 'active'::text) AS active_family_goals
   FROM client_access ca
     JOIN households h ON h.id = ca.household_id
     LEFT JOIN household_members hm ON hm.household_id = h.id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
  GROUP BY ca.user_id, ca.contact_id, ca.household_id, h.household_name, h.household_type, h.status;

CREATE VIEW "public"."my_family_progress_dashboard" WITH (security_invoker=true) AS
 WITH access_rows AS (
         SELECT DISTINCT ca.user_id,
            ca.household_id
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.status = 'active'::text AND ca.household_id IS NOT NULL
        ), family_members AS (
         SELECT hm.household_id,
            hm.id AS household_member_id,
            hm.contact_id,
            hm.relationship_type,
            hm.is_primary,
            hm.date_of_birth,
            c.first_name,
            c.last_name
           FROM household_members hm
             JOIN access_rows ar ON ar.household_id = hm.household_id
             JOIN contacts c ON c.id = hm.contact_id
          WHERE hm.status = 'active'::text
        ), latest_score AS (
         SELECT DISTINCT ON (ws.contact_id, ws.score_type) ws.contact_id,
            ws.score_type,
            ws.score,
            ws.methodology_version,
            ws.calculated_at
           FROM wellness_score_snapshots ws
             JOIN family_members fm_1 ON fm_1.contact_id = ws.contact_id
          ORDER BY ws.contact_id, ws.score_type, ws.calculated_at DESC
        ), achievement_counts AS (
         SELECT ma.contact_id,
            count(*)::integer AS achievement_count,
            max(ma.unlocked_at) AS latest_achievement_at
           FROM member_achievements ma
             JOIN family_members fm_1 ON fm_1.contact_id = ma.contact_id
          GROUP BY ma.contact_id
        ), goal_counts AS (
         SELECT g.contact_id,
            count(*) FILTER (WHERE g.status = 'active'::text)::integer AS active_goals,
            count(*) FILTER (WHERE g.status = 'completed'::text)::integer AS completed_goals
           FROM client_goals g
             JOIN family_members fm_1 ON fm_1.contact_id = g.contact_id
          GROUP BY g.contact_id
        ), challenge_counts AS (
         SELECT ce.contact_id,
            count(*) FILTER (WHERE ce.status = 'active'::text)::integer AS active_challenges,
            count(*) FILTER (WHERE ce.status = 'completed'::text)::integer AS completed_challenges,
            COALESCE(sum(ce.points_earned), 0::bigint)::integer AS challenge_points
           FROM challenge_enrollments ce
             JOIN family_members fm_1 ON fm_1.contact_id = ce.contact_id
          GROUP BY ce.contact_id
        )
 SELECT fm.household_id,
    fm.household_member_id,
    fm.contact_id,
    fm.first_name,
    fm.last_name,
    fm.relationship_type,
    fm.is_primary,
    fm.date_of_birth,
    ls.score_type,
    ls.score AS health_score,
    ls.methodology_version AS health_score_methodology_version,
    ls.calculated_at AS health_score_calculated_at,
    COALESCE(gc.active_goals, 0) AS active_goals,
    COALESCE(gc.completed_goals, 0) AS completed_goals,
    COALESCE(cc.active_challenges, 0) AS active_challenges,
    COALESCE(cc.completed_challenges, 0) AS completed_challenges,
    COALESCE(cc.challenge_points, 0) AS challenge_points,
    COALESCE(ac.achievement_count, 0) AS achievement_count,
    ac.latest_achievement_at,
    round(avg(ls.score) OVER (PARTITION BY fm.household_id, ls.score_type), 2) AS household_average_health_score
   FROM family_members fm
     LEFT JOIN latest_score ls ON ls.contact_id = fm.contact_id
     LEFT JOIN achievement_counts ac ON ac.contact_id = fm.contact_id
     LEFT JOIN goal_counts gc ON gc.contact_id = fm.contact_id
     LEFT JOIN challenge_counts cc ON cc.contact_id = fm.contact_id
  ORDER BY fm.is_primary DESC, fm.first_name, fm.last_name;

CREATE VIEW "public"."my_family_requests" WITH (security_invoker=true) AS
 SELECT id AS request_id,
    request_type,
    target_household_member_id,
    first_name,
    last_name,
    relationship_type,
    sex,
    date_of_birth,
    email,
    notes,
    status,
    staff_notes,
    reviewed_at,
    created_at,
    updated_at
   FROM family_change_requests fcr
  WHERE user_id = (( SELECT auth.uid() AS uid))
  ORDER BY created_at DESC;

CREATE VIEW "public"."my_family_wellness_summary" WITH (security_invoker=true) AS
 WITH accessible_households AS (
         SELECT DISTINCT ca.household_id
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.status = 'active'::text AND ca.household_id IS NOT NULL
        ), latest_scores AS (
         SELECT DISTINCT ON (ws.contact_id, ws.score_type) ws.contact_id,
            ws.household_id,
            ws.score_type,
            ws.score,
            ws.methodology_version,
            ws.components,
            ws.calculated_at
           FROM wellness_score_snapshots ws
             JOIN accessible_households ah_1 ON ah_1.household_id = ws.household_id
          ORDER BY ws.contact_id, ws.score_type, ws.calculated_at DESC
        )
 SELECT hm.household_id,
    hm.id AS household_member_id,
    hm.contact_id,
    c.first_name,
    c.last_name,
    hm.relationship_type,
    hm.is_primary,
    ls.score_type,
    ls.score,
    ls.methodology_version,
    ls.components,
    ls.calculated_at,
    round(avg(ls.score) OVER (PARTITION BY hm.household_id, ls.score_type), 2) AS household_average_score
   FROM household_members hm
     JOIN accessible_households ah ON ah.household_id = hm.household_id
     JOIN contacts c ON c.id = hm.contact_id
     LEFT JOIN latest_scores ls ON ls.contact_id = hm.contact_id
  WHERE hm.status = 'active'::text
  ORDER BY hm.is_primary DESC, c.first_name, c.last_name;

CREATE VIEW "public"."my_goals" WITH (security_invoker=true) AS
 SELECT g.id,
    g.contact_id,
    g.household_id,
    g.membership_id,
    g.scope,
    g.goal_key,
    g.title,
    g.description,
    g.target_value,
    g.target_unit,
    g.baseline_value,
    g.target_date,
    g.priority,
    g.status,
    g.created_by_user_id,
    g.created_by_type,
    g.completed_at,
    g.created_at,
    g.updated_at
   FROM client_goals g
     JOIN client_access ca ON ca.contact_id = g.contact_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
  ORDER BY (
        CASE g.status
            WHEN 'active'::text THEN 1
            WHEN 'paused'::text THEN 2
            WHEN 'completed'::text THEN 3
            ELSE 4
        END), g.priority, g.created_at DESC;

CREATE VIEW "public"."my_grocery_list" WITH (security_invoker=true) AS
 SELECT gl.id AS grocery_list_id,
    gl.title,
    gl.status,
    gi.id AS item_id,
    gi.item,
    gi.quantity,
    gi.unit,
    gi.category,
    gi.checked,
    gi.sort_order
   FROM client_access ca
     JOIN client_grocery_lists gl ON gl.contact_id = ca.contact_id
     JOIN grocery_list_items gi ON gi.grocery_list_id = gl.id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND gl.status = 'active'::text
  ORDER BY gl.created_at DESC, gi.checked, gi.sort_order;

CREATE VIEW "public"."my_habits" WITH (security_invoker=true) AS
 SELECT h.id,
    h.contact_id,
    h.membership_id,
    h.title,
    h.category,
    h.frequency,
    h.target_per_period,
    h.unit,
    h.status,
    h.starts_on,
    h.ends_on,
    h.created_by,
    h.metadata,
    h.created_at,
    h.updated_at,
    COALESCE(( SELECT sum(hc.value) AS sum
           FROM habit_checkins hc
          WHERE hc.habit_id = h.id AND hc.checkin_date >= (CURRENT_DATE - '6 days'::interval)), 0::numeric) AS last_7_day_value,
    COALESCE(( SELECT sum(hc.value) AS sum
           FROM habit_checkins hc
          WHERE hc.habit_id = h.id AND hc.checkin_date = CURRENT_DATE), 0::numeric) AS today_value
   FROM client_habits h
     JOIN client_access ca ON ca.contact_id = h.contact_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
  ORDER BY h.status, h.created_at DESC;

CREATE VIEW "public"."my_health_connection_center" WITH (security_invoker=true) AS
 SELECT p.provider_key,
    p.name AS provider_name,
    p.provider_type,
    p.connection_mode,
    p.supported_metrics,
    hc.id AS connection_id,
    COALESCE(hc.status, 'not_connected'::text) AS status,
    hc.connected_at,
    hc.last_sync_at,
    hc.last_successful_sync_at,
    hc.last_error,
    COALESCE(( SELECT count(*)::integer AS count
           FROM health_metric_consents c
          WHERE c.user_id = (( SELECT auth.uid() AS uid)) AND c.provider_key = p.provider_key AND c.allowed = true), 0) AS allowed_metric_count
   FROM health_integration_providers p
     LEFT JOIN LATERAL ( SELECT h.id,
            h.contact_id,
            h.membership_id,
            h.user_id,
            h.provider_key,
            h.status,
            h.external_account_reference,
            h.credential_reference,
            h.granted_scopes,
            h.connected_at,
            h.last_sync_at,
            h.last_successful_sync_at,
            h.last_error,
            h.sync_cursor,
            h.metadata,
            h.created_at,
            h.updated_at
           FROM health_integration_connections h
          WHERE h.provider_key = p.provider_key AND (h.user_id = (( SELECT auth.uid() AS uid)) OR (h.contact_id IN ( SELECT ca.contact_id
                   FROM client_access ca
                  WHERE ca.user_id = (( SELECT auth.uid() AS uid)))))
          ORDER BY h.updated_at DESC
         LIMIT 1) hc ON true
  WHERE p.active = true;

CREATE VIEW "public"."my_health_connections" WITH (security_invoker=true) AS
 SELECT hc.id AS connection_id,
    hc.provider_key,
    p.name AS provider_name,
    p.provider_type,
    p.connection_mode,
    hc.status,
    hc.connected_at,
    hc.last_sync_at,
    hc.last_successful_sync_at,
    hc.last_error
   FROM health_integration_connections hc
     JOIN health_integration_providers p ON p.provider_key = hc.provider_key
  WHERE hc.user_id = (( SELECT auth.uid() AS uid)) OR (hc.contact_id IN ( SELECT ca.contact_id
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid))));

CREATE VIEW "public"."my_health_data_snapshot" WITH (security_invoker=true) AS
 SELECT DISTINCT ON (o.metric_key) o.metric_key,
    COALESCE(m.label, o.metric_key) AS label,
    m.category,
    o.value_numeric,
    o.value_boolean,
    COALESCE(o.unit, m.unit) AS unit,
    o.observed_at,
    o.provider_key,
    p.name AS provider_name
   FROM health_observations o
     LEFT JOIN health_metric_catalog m ON m.metric_key = o.metric_key
     LEFT JOIN health_integration_providers p ON p.provider_key = o.provider_key
  WHERE (o.contact_id IN ( SELECT ca.contact_id
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.status = 'active'::text))
  ORDER BY o.metric_key, o.observed_at DESC;

CREATE VIEW "public"."my_health_metric_permissions" WITH (security_invoker=true) AS
 SELECT p.provider_key,
    p.name AS provider_name,
    p.provider_type,
    p.connection_mode,
    m.metric_key,
    m.label,
    m.category,
    m.unit,
    m.coaching_use,
    m.display_order,
    COALESCE(c.allowed, false) AS allowed,
    c.consented_at,
    c.revoked_at
   FROM health_integration_providers p
     JOIN health_metric_catalog m ON p.supported_metrics ? m.metric_key
     LEFT JOIN health_metric_consents c ON c.provider_key = p.provider_key AND c.metric_key = m.metric_key AND c.user_id = (( SELECT auth.uid() AS uid))
  WHERE p.active = true AND m.active = true;

CREATE VIEW "public"."my_health_metric_timeline" WITH (security_invoker=true) AS
 SELECT ho.contact_id,
    ho.membership_id,
    ho.metric_key,
    hmc.label AS metric_label,
    hmc.category,
    COALESCE(ho.unit, hmc.unit) AS unit,
    ho.value_numeric,
    ho.value_boolean,
    ho.observed_at AS recorded_at,
    'wearable'::text AS origin,
    ho.provider_key AS source_key,
    ho.connection_id,
    ho.metadata
   FROM health_observations ho
     LEFT JOIN health_metric_catalog hmc ON hmc.metric_key = ho.metric_key
  WHERE (EXISTS ( SELECT 1
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.contact_id = ho.contact_id AND ca.status = 'active'::text))
UNION ALL
 SELECT pe.contact_id,
    pe.membership_id,
    pe.metric_key,
    pmc.label AS metric_label,
    pmc.category,
    pmc.unit,
    pe.value_numeric,
    pe.value_boolean,
    pe.recorded_at,
    'manual'::text AS origin,
    pe.source AS source_key,
    NULL::uuid AS connection_id,
    pe.metadata
   FROM progress_entries pe
     LEFT JOIN progress_metric_catalog pmc ON pmc.metric_key = pe.metric_key
  WHERE (EXISTS ( SELECT 1
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.contact_id = pe.contact_id AND ca.status = 'active'::text));

CREATE VIEW "public"."my_household" WITH (security_invoker=true) AS
 SELECT ca.user_id,
    hm.household_id,
    hm.id AS household_member_id,
    hm.contact_id,
    hm.relationship_type,
    hm.sex,
    hm.is_primary,
    hm.date_of_birth,
    hm.status,
    c.first_name,
    c.last_name,
    c.email
   FROM client_access ca
     JOIN household_members hm ON hm.household_id = ca.household_id
     JOIN contacts c ON c.id = hm.contact_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND hm.status = 'active'::text;

CREATE VIEW "public"."my_invoices" WITH (security_invoker=true) AS
 SELECT bi.id AS invoice_id,
    bi.invoice_number,
    bi.status,
    bi.amount_due_cents,
    bi.amount_paid_cents,
    bi.currency,
    bi.due_at,
    bi.paid_at,
    bi.hosted_invoice_url,
    bi.created_at
   FROM client_access ca
     JOIN billing_invoices bi ON bi.contact_id = ca.contact_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
  ORDER BY bi.created_at DESC;

CREATE VIEW "public"."my_journey_status" WITH (security_invoker=true) AS
 SELECT p.user_id,
    c.id AS contact_id,
    c.first_name,
    c.last_name,
    c.email,
    c.lifecycle_stage,
    va.status AS vitality_status,
    va.completion_percent AS vitality_completion,
    en.status AS enrollment_status,
    en.completion_percent AS enrollment_completion,
    wr.status AS webinar_status,
    wr.payment_status AS webinar_payment_status
   FROM profiles p
     JOIN contacts c ON c.id = p.contact_id
     LEFT JOIN workflow_records va ON va.contact_id = c.id AND va.workflow_type = 'vitality_assessment'::text AND va.status <> 'abandoned'::text
     LEFT JOIN workflow_records en ON en.contact_id = c.id AND en.workflow_type = 'enrollment'::text AND en.status <> 'abandoned'::text
     LEFT JOIN webinar_registrations wr ON wr.contact_id = c.id
  WHERE p.user_id = auth.uid();

CREATE VIEW "public"."my_latest_wellness_scores" WITH (security_invoker=true) AS
 SELECT DISTINCT ON (contact_id, score_type) id,
    contact_id,
    household_id,
    membership_id,
    score_type,
    score,
    methodology_version,
    components,
    source,
    calculated_at
   FROM wellness_score_snapshots ws
  WHERE (EXISTS ( SELECT 1
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.contact_id = ws.contact_id AND ca.status = 'active'::text))
  ORDER BY contact_id, score_type, calculated_at DESC;

CREATE VIEW "public"."my_member_dashboard" WITH (security_invoker=true) AS
 SELECT ca.user_id,
    ca.contact_id,
    ca.status AS access_status,
    ca.ready_at,
    ca.activated_at,
    c.first_name,
    c.last_name,
    c.email,
    h.id AS household_id,
    h.household_type,
    h.household_name,
    h.status AS household_status,
    cm.id AS membership_id,
    cm.status AS membership_status,
    cm.program_code,
    pc.name AS program_name,
    cm.billing_choice,
    cm.amount_cents,
    cm.currency,
    cm.commitment_months,
    cm.starts_at,
    cm.commitment_ends_at,
    cm.assigned_coach_id,
    sd.display_name AS assigned_coach_name
   FROM client_access ca
     JOIN contacts c ON c.id = ca.contact_id
     LEFT JOIN households h ON h.id = ca.household_id
     LEFT JOIN client_memberships cm ON cm.id = ca.membership_id
     LEFT JOIN program_catalog pc ON pc.program_code = cm.program_code
     LEFT JOIN staff_directory sd ON sd.user_id = cm.assigned_coach_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid));

CREATE VIEW "public"."my_member_entitlements" WITH (security_invoker=true) AS
 SELECT ca.user_id,
    me.membership_id,
    me.entitlement_key,
    me.label,
    me.status,
    me.limit_value,
    me.used_value,
    me.reset_cadence,
    me.metadata
   FROM client_access ca
     JOIN membership_entitlements me ON me.membership_id = ca.membership_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND me.status = 'active'::text;

CREATE VIEW "public"."my_member_journey" WITH (security_invoker=true) AS
 SELECT ca.user_id,
    cj.id AS journey_id,
    cj.journey_key,
    jd.name AS journey_name,
    cj.status AS journey_status,
    cj.current_step_key,
    s.name AS current_step_name,
    s.step_type,
    s.status AS current_step_status,
    s.due_at AS current_step_due_at,
    cj.progress_percent,
    cj.last_activity_at,
    cj.next_action_at
   FROM client_access ca
     JOIN contact_journeys cj ON cj.contact_id = ca.contact_id AND (cj.status = ANY (ARRAY['active'::text, 'paused'::text, 'nurture'::text]))
     JOIN journey_definitions jd ON jd.journey_key = cj.journey_key
     LEFT JOIN contact_journey_steps s ON s.journey_id = cj.id AND s.step_key = cj.current_step_key
  WHERE ca.user_id = (( SELECT auth.uid() AS uid));

CREATE VIEW "public"."my_member_profile" WITH (security_invoker=true) AS
 SELECT p.user_id,
    c.id AS contact_id,
    c.first_name,
    c.last_name,
    c.email,
    c.phone,
    c.city,
    c.state,
    c.country,
    c.updated_at
   FROM profiles p
     JOIN contacts c ON c.id = p.contact_id
  WHERE p.user_id = (( SELECT auth.uid() AS uid));

CREATE VIEW "public"."my_member_upcoming_appointment" WITH (security_invoker=true) AS
 SELECT user_id,
    appointment_id,
    appointment_type,
    status,
    scheduled_start,
    scheduled_end,
    time_zone,
    format,
    location_url,
    assigned_to,
    assigned_coach_name,
    source
   FROM ( SELECT ca.user_id,
            a.id AS appointment_id,
            a.appointment_type,
            a.status,
            a.scheduled_start,
            a.scheduled_end,
            a.time_zone,
            a.format,
            a.location_url,
            a.assigned_to,
            sd.display_name AS assigned_coach_name,
            'journey'::text AS source
           FROM client_access ca
             JOIN journey_appointments a ON a.contact_id = ca.contact_id
             LEFT JOIN staff_directory sd ON sd.user_id = a.assigned_to
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND a.status = 'scheduled'::text AND a.scheduled_start >= now()
        UNION ALL
         SELECT ca.user_id,
            cs.id AS appointment_id,
            'coaching_session'::text AS appointment_type,
            cs.status,
            cs.scheduled_start,
            cs.scheduled_end,
            NULL::text AS time_zone,
            cs.format,
            cs.location_url,
            cs.coach_user_id AS assigned_to,
            sd.display_name AS assigned_coach_name,
            'coaching'::text AS source
           FROM client_access ca
             JOIN coaching_sessions cs ON cs.contact_id = ca.contact_id
             LEFT JOIN staff_directory sd ON sd.user_id = cs.coach_user_id
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND cs.status = 'scheduled'::text AND cs.scheduled_start >= now()) x
  ORDER BY scheduled_start
 LIMIT 1;

CREATE VIEW "public"."my_membership_overview" WITH (security_invoker=true) AS
 SELECT ca.contact_id,
    ca.household_id,
    ca.membership_id,
    ca.status AS access_status,
    cm.program_code,
    pc.name AS program_name,
    pc.program_type,
    pc.default_commitment_months,
    pc.pricing,
    pc.metadata AS program_metadata,
    cm.status AS membership_status,
    cm.billing_choice,
    cm.amount_cents,
    cm.currency,
    cm.starts_at,
    cm.commitment_ends_at,
    cm.assigned_coach_id,
    sa.display_name AS assigned_coach_name,
    ( SELECT count(*) AS count
           FROM membership_entitlements me
          WHERE me.membership_id = cm.id AND me.status = 'active'::text) AS active_entitlements,
    ( SELECT count(*) AS count
           FROM client_course_enrollments cce
          WHERE cce.membership_id = cm.id AND (cce.status = ANY (ARRAY['active'::text, 'paused'::text, 'completed'::text]))) AS course_count,
    ( SELECT count(*) AS count
           FROM program_resource_access pra
             JOIN resource_library rl ON rl.id = pra.resource_id AND rl.status = 'published'::text
          WHERE pra.program_code = cm.program_code AND pra.active) AS resource_count
   FROM client_access ca
     JOIN client_memberships cm ON cm.id = ca.membership_id
     JOIN program_catalog pc ON pc.program_code = cm.program_code
     LEFT JOIN staff_access sa ON sa.user_id = cm.assigned_coach_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
 LIMIT 1;

CREATE VIEW "public"."my_message_attachments" WITH (security_invoker=true) AS
 SELECT a.id AS attachment_id,
    a.message_id,
    m.conversation_id,
    a.storage_path,
    a.original_filename,
    a.content_type,
    a.size_bytes,
    a.created_at
   FROM member_message_attachments a
     JOIN member_messages m ON m.id = a.message_id
     JOIN member_conversation_participants p ON p.conversation_id = m.conversation_id AND p.user_id = (( SELECT auth.uid() AS uid)) AND p.left_at IS NULL;

CREATE VIEW "public"."my_mobile_health_sync_status" WITH (security_invoker=true) AS
 SELECT b.id AS batch_id,
    b.provider_key,
    p.name AS provider_name,
    b.device_id,
    b.status,
    b.source_cursor,
    b.records_received,
    b.records_imported,
    b.records_blocked,
    b.records_duplicate,
    b.started_at,
    b.completed_at,
    b.error_message
   FROM health_mobile_sync_batches b
     JOIN health_integration_providers p ON p.provider_key = b.provider_key
  WHERE b.user_id = (( SELECT auth.uid() AS uid))
  ORDER BY b.started_at DESC
 LIMIT 25;

CREATE VIEW "public"."my_notification_preferences" WITH (security_invoker=true) AS
 SELECT user_id,
    in_app_messages,
    email_messages,
    sms_messages,
    email_coaching_reminders,
    sms_coaching_reminders,
    email_program_updates,
    sms_program_updates,
    email_billing_alerts,
    sms_billing_alerts,
    quiet_hours_enabled,
    quiet_hours_start,
    quiet_hours_end,
    time_zone,
    updated_at
   FROM notification_preferences np
  WHERE user_id = (( SELECT auth.uid() AS uid));

CREATE VIEW "public"."my_notification_preferences_v2" WITH (security_invoker=true) AS
 SELECT user_id,
    in_app_messages,
    email_messages,
    sms_messages,
    push_messages,
    email_coaching_reminders,
    sms_coaching_reminders,
    push_coaching_reminders,
    email_program_updates,
    sms_program_updates,
    push_program_updates,
    email_billing_alerts,
    sms_billing_alerts,
    push_billing_alerts,
    quiet_hours_enabled,
    quiet_hours_start,
    quiet_hours_end,
    time_zone,
    updated_at
   FROM notification_preferences np
  WHERE user_id = (( SELECT auth.uid() AS uid));

CREATE VIEW "public"."my_notification_routes" WITH (security_invoker=true) AS
 SELECT n.id AS notification_id,
    n.notification_type,
    n.title,
    n.body,
    n.status,
    n.created_at,
    COALESCE(n.link_url, r.route_path, '/app/notifications'::text) AS resolved_link_url,
    rr.route_key,
    r.screen_name,
    r.feature_key
   FROM member_notifications n
     LEFT JOIN notification_route_rules rr ON rr.notification_type = n.notification_type
     LEFT JOIN app_route_registry r ON r.route_key = rr.route_key AND r.active
  WHERE n.user_id = (( SELECT auth.uid() AS uid)) AND n.status <> 'dismissed'::text
  ORDER BY n.created_at DESC
 LIMIT 100;

CREATE VIEW "public"."my_notifications" WITH (security_invoker=true) AS
 SELECT id,
    notification_type,
    title,
    body,
    link_url,
    status,
    created_at,
    read_at
   FROM member_notifications
  WHERE user_id = (( SELECT auth.uid() AS uid)) AND status <> 'dismissed'::text
  ORDER BY created_at DESC
 LIMIT 100;

CREATE VIEW "public"."my_payment_history" WITH (security_invoker=true) AS
 SELECT be.id AS event_id,
    be.event_type,
    be.provider,
    be.amount_cents,
    be.currency,
    be.status,
    be.occurred_at
   FROM client_access ca
     JOIN billing_events be ON be.contact_id = ca.contact_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND (be.event_type = ANY (ARRAY['payment_succeeded'::text, 'payment_failed'::text, 'refund'::text, 'manual_adjustment'::text]))
  ORDER BY be.occurred_at DESC;

CREATE VIEW "public"."my_prefill_facts" WITH (security_invoker=true) AS
 SELECT f.field_key,
    f.value,
    f.source_workflow,
    f.source_question_key,
    f.last_confirmed_at
   FROM canonical_facts f
     JOIN profiles p ON p.contact_id = f.contact_id
  WHERE p.user_id = (( SELECT auth.uid() AS uid));

CREATE VIEW "public"."my_privacy_center" WITH (security_invoker=true) AS
 SELECT user_id,
    contact_id,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('provider_key', hc.provider_key, 'provider_name', p.name, 'status', hc.status, 'connected_at', hc.connected_at, 'last_sync_at', hc.last_sync_at, 'last_successful_sync_at', hc.last_successful_sync_at) ORDER BY p.name) AS jsonb_agg
           FROM health_integration_connections hc
             JOIN health_integration_providers p ON p.provider_key = hc.provider_key
          WHERE hc.contact_id = ca.contact_id AND hc.user_id = (( SELECT auth.uid() AS uid))), '[]'::jsonb) AS health_connections,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('request_id', r.id, 'request_type', r.request_type, 'scope', r.scope, 'status', r.status, 'requested_at', r.requested_at, 'reviewed_at', r.reviewed_at, 'completed_at', r.completed_at) ORDER BY r.requested_at DESC) AS jsonb_agg
           FROM member_privacy_requests r
          WHERE r.user_id = (( SELECT auth.uid() AS uid))), '[]'::jsonb) AS privacy_requests,
    ( SELECT count(*)::integer AS count
           FROM health_observations ho
          WHERE ho.contact_id = ca.contact_id) AS stored_health_observation_count,
    ( SELECT max(ho.observed_at) AS max
           FROM health_observations ho
          WHERE ho.contact_id = ca.contact_id) AS latest_health_observation_at
   FROM client_access ca
  WHERE user_id = (( SELECT auth.uid() AS uid)) AND status = 'active'::text
  ORDER BY updated_at DESC
 LIMIT 1;

CREATE VIEW "public"."my_privacy_exports" WITH (security_invoker=true) AS
 SELECT id AS export_id,
    privacy_request_id,
    status,
    manifest,
    file_size_bytes,
    checksum,
    expires_at,
    created_at,
    ready_at,
        CASE
            WHEN status = 'ready'::text AND storage_path IS NOT NULL AND (expires_at IS NULL OR expires_at > now()) THEN storage_path
            ELSE NULL::text
        END AS available_storage_path
   FROM member_privacy_exports e
  WHERE user_id = (( SELECT auth.uid() AS uid))
  ORDER BY created_at DESC;

CREATE VIEW "public"."my_progress_photo_sets" WITH (security_invoker=true) AS
 SELECT s.id AS set_id,
    s.contact_id,
    s.membership_id,
    s.label,
    s.captured_on,
    s.notes,
    s.created_at,
    count(p.id)::integer AS photo_count,
    max(p.created_at) AS last_photo_created_at
   FROM progress_photo_sets s
     LEFT JOIN progress_photos p ON p.set_id = s.id
  WHERE (EXISTS ( SELECT 1
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.contact_id = s.contact_id AND ca.status = 'active'::text))
  GROUP BY s.id, s.contact_id, s.membership_id, s.label, s.captured_on, s.notes, s.created_at
  ORDER BY s.captured_on DESC, s.created_at DESC;

CREATE VIEW "public"."my_progress_photos" WITH (security_invoker=true) AS
 SELECT id AS photo_id,
    set_id,
    contact_id,
    membership_id,
    angle,
    storage_path,
    mime_type,
    file_size_bytes,
    captured_at,
    note,
    created_at
   FROM progress_photos p
  WHERE (EXISTS ( SELECT 1
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.contact_id = p.contact_id AND ca.status = 'active'::text))
  ORDER BY captured_at DESC NULLS LAST, created_at DESC;

CREATE VIEW "public"."my_progress_snapshot" WITH (security_invoker=true) AS
 SELECT user_id,
    contact_id,
    ( SELECT count(*) AS count
           FROM client_goals g
          WHERE g.contact_id = ca.contact_id AND g.status = 'active'::text) AS active_goals,
    ( SELECT count(*) AS count
           FROM client_goals g
          WHERE g.contact_id = ca.contact_id AND g.status = 'completed'::text) AS completed_goals,
    ( SELECT count(*) AS count
           FROM client_habits h
          WHERE h.contact_id = ca.contact_id AND h.status = 'active'::text) AS active_habits,
    ( SELECT count(*) AS count
           FROM habit_checkins hc
          WHERE hc.contact_id = ca.contact_id AND hc.checkin_date >= (CURRENT_DATE - 6)) AS habit_checkins_last_7_days,
    ( SELECT count(*) AS count
           FROM challenge_enrollments ce
          WHERE ce.contact_id = ca.contact_id AND ce.status = 'active'::text) AS active_challenges,
    ( SELECT count(*) AS count
           FROM challenge_enrollments ce
          WHERE ce.contact_id = ca.contact_id AND ce.status = 'completed'::text) AS completed_challenges,
    ( SELECT COALESCE(sum(ce.points_earned), 0::bigint) AS "coalesce"
           FROM challenge_enrollments ce
          WHERE ce.contact_id = ca.contact_id) AS challenge_points,
    ( SELECT count(*) AS count
           FROM client_workout_assignments wa
          WHERE wa.contact_id = ca.contact_id AND wa.status = 'completed'::text AND wa.scheduled_date >= (CURRENT_DATE - 29)) AS workouts_completed_30d,
    ( SELECT count(*) AS count
           FROM client_meal_plan_items mi
          WHERE mi.contact_id = ca.contact_id AND mi.status = 'completed'::text AND mi.scheduled_date >= (CURRENT_DATE - 29)) AS meals_completed_30d,
    ( SELECT round(avg(mi.adherence_percent), 1) AS round
           FROM client_meal_plan_items mi
          WHERE mi.contact_id = ca.contact_id AND mi.adherence_percent IS NOT NULL AND mi.scheduled_date >= (CURRENT_DATE - 29)) AS meal_adherence_30d,
    ( SELECT max(pe.recorded_at) AS max
           FROM progress_entries pe
          WHERE pe.contact_id = ca.contact_id) AS last_progress_at
   FROM client_access ca
  WHERE user_id = (( SELECT auth.uid() AS uid))
 LIMIT 1;

CREATE VIEW "public"."my_recent_progress" WITH (security_invoker=true) AS
 SELECT pe.id,
    pe.contact_id,
    pe.metric_key,
    mc.label,
    mc.category,
    mc.unit,
    mc.value_type,
    pe.value_numeric,
    pe.value_boolean,
    pe.recorded_at,
    pe.source,
    pe.note
   FROM progress_entries pe
     JOIN progress_metric_catalog mc ON mc.metric_key = pe.metric_key
     JOIN client_access ca ON ca.contact_id = pe.contact_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
  ORDER BY pe.recorded_at DESC
 LIMIT 100;

CREATE VIEW "public"."my_referral_activity" WITH (security_invoker=true) AS
 SELECT r.id AS referral_id,
    r.status,
    r.source_channel,
    r.first_touch_at,
    r.converted_at,
    c.first_name AS referred_first_name,
        CASE
            WHEN c.last_name IS NULL OR TRIM(BOTH FROM c.last_name) = ''::text THEN NULL::text
            ELSE "left"(c.last_name, 1) || '.'::text
        END AS referred_last_initial,
    rr.status AS reward_status,
    rr.reward_type,
    rr.reward_value,
    rr.currency,
    rr.approved_at,
    rr.issued_at
   FROM client_access ca
     JOIN referrals r ON r.referrer_contact_id = ca.contact_id
     JOIN contacts c ON c.id = r.referred_contact_id
     LEFT JOIN referral_rewards rr ON rr.referral_id = r.id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
  ORDER BY r.first_touch_at DESC;

CREATE VIEW "public"."my_referral_summary" WITH (security_invoker=true) AS
 SELECT rp.referral_code,
    count(DISTINCT r.id) AS total_referrals,
    count(DISTINCT r.id) FILTER (WHERE r.status = 'converted'::text) AS converted_referrals,
    count(DISTINCT rr.id) FILTER (WHERE rr.status = 'pending'::text) AS pending_rewards,
    count(DISTINCT rr.id) FILTER (WHERE rr.status = 'issued'::text) AS issued_rewards
   FROM client_access ca
     JOIN referral_profiles rp ON rp.contact_id = ca.contact_id
     LEFT JOIN referrals r ON r.referrer_contact_id = rp.contact_id
     LEFT JOIN referral_rewards rr ON rr.referrer_contact_id = rp.contact_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
  GROUP BY rp.referral_code;

CREATE VIEW "public"."my_refuel_access" WITH (security_invoker=true) AS
 SELECT re.id AS enrollment_id,
    re.status AS enrollment_status,
    re.payment_status,
    o.id AS offer_id,
    o.offer_key,
    o.name AS offer_name,
    o.description,
    o.starts_at,
    o.ends_at,
    o.price_cents,
    o.currency,
    o.billing_type
   FROM client_access ca
     JOIN refuel_enrollments re ON re.contact_id = ca.contact_id
     JOIN refuel_offers o ON o.id = re.offer_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND (re.status = ANY (ARRAY['pending'::text, 'active'::text, 'completed'::text]))
  ORDER BY re.enrolled_at DESC;

CREATE VIEW "public"."my_resources" WITH (security_invoker=true) AS
 SELECT DISTINCT r.id AS resource_id,
    r.title,
    r.description,
    r.resource_type,
    r.resource_url,
    r.category,
    r.tags,
    COALESCE(cra.status, 'available'::text) AS assignment_status,
    cra.note AS assignment_note
   FROM client_access ca
     JOIN client_memberships cm ON cm.id = ca.membership_id
     JOIN resource_library r ON r.status = 'published'::text
     LEFT JOIN program_resource_access pra ON pra.resource_id = r.id AND pra.program_code = cm.program_code AND pra.active
     LEFT JOIN client_resource_assignments cra ON cra.resource_id = r.id AND cra.contact_id = ca.contact_id AND cra.status <> 'cancelled'::text
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.status = 'active'::text AND cm.status = 'active'::text AND (pra.id IS NOT NULL OR cra.id IS NOT NULL)
  ORDER BY r.category, r.title;

CREATE VIEW "public"."my_staff_agreements" WITH (security_invoker=true) AS
 SELECT sa.id AS staff_agreement_id,
    sa.agreement_key,
    at.name,
    sa.template_version,
    at.description,
    sa.rendered_content_text AS content_text,
    sa.status,
    sa.required,
    sa.sent_at,
    sa.viewed_at,
    sa.signed_at,
    acc.signer_name,
    acc.signed_at AS acceptance_signed_at
   FROM staff_agreements sa
     JOIN agreement_templates at ON at.id = sa.agreement_template_id
     LEFT JOIN staff_agreement_acceptances acc ON acc.staff_agreement_id = sa.id
  WHERE sa.staff_user_id = (( SELECT auth.uid() AS uid))
  ORDER BY sa.created_at;

CREATE VIEW "public"."my_staff_onboarding_readiness" WITH (security_invoker=true) AS
 SELECT s.user_id,
    s.display_name,
    s.role,
    s.status,
    s.onboarding_status,
    count(sa.id) FILTER (WHERE sa.required)::integer AS required_agreements,
    count(sa.id) FILTER (WHERE sa.required AND sa.status = 'signed'::text)::integer AS signed_required_agreements,
    count(sa.id) FILTER (WHERE sa.required AND sa.status = 'waived'::text)::integer AS waived_required_agreements,
    count(sa.id) FILTER (WHERE sa.required AND (sa.status <> ALL (ARRAY['signed'::text, 'waived'::text])))::integer AS incomplete_required_agreements,
    bool_or(sa.agreement_key = 'revitalized-nation-coach-nda'::text AND sa.status = 'signed'::text) AS coach_nda_signed,
    max(sa.signed_at) FILTER (WHERE sa.agreement_key = 'revitalized-nation-coach-nda'::text) AS coach_nda_signed_at,
    s.status = 'active'::text AND count(sa.id) FILTER (WHERE sa.required AND (sa.status <> ALL (ARRAY['signed'::text, 'waived'::text]))) = 0 AS onboarding_ready
   FROM staff_access s
     LEFT JOIN staff_agreements sa ON sa.staff_user_id = s.user_id
  WHERE s.user_id = (( SELECT auth.uid() AS uid))
  GROUP BY s.user_id, s.display_name, s.role, s.status, s.onboarding_status;

CREATE VIEW "public"."my_staff_permissions_view" WITH (security_invoker=true) AS
 SELECT pc.permission_key,
    COALESCE(spo.allowed, srpd.allowed, false) AS allowed
   FROM staff_access sa
     CROSS JOIN staff_permission_catalog pc
     LEFT JOIN staff_role_permission_defaults srpd ON srpd.role = sa.role AND srpd.permission_key = pc.permission_key
     LEFT JOIN staff_permission_overrides spo ON spo.user_id = sa.user_id AND spo.permission_key = pc.permission_key
  WHERE sa.user_id = (( SELECT auth.uid() AS uid)) AND sa.status = 'active'::text AND pc.active;

CREATE VIEW "public"."my_sync_cursor" WITH (security_invoker=true) AS
 SELECT COALESCE(max(event_id), 0::bigint) AS latest_event_id,
    max(changed_at) AS latest_change_at,
    now() AS server_time
   FROM member_sync_events e;

CREATE VIEW "public"."my_sync_status" WITH (security_invoker=true) AS
 SELECT now() AS server_time,
    count(*) FILTER (WHERE created_at >= (now() - '24:00:00'::interval))::integer AS mutations_24h,
    max(created_at) AS last_successful_mutation_at,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('idempotency_key', r.idempotency_key, 'mutation_type', r.mutation_type, 'response_payload', r.response_payload, 'created_at', r.created_at) ORDER BY r.created_at DESC) AS jsonb_agg
           FROM ( SELECT member_mutation_receipts_1.id,
                    member_mutation_receipts_1.user_id,
                    member_mutation_receipts_1.contact_id,
                    member_mutation_receipts_1.device_id,
                    member_mutation_receipts_1.idempotency_key,
                    member_mutation_receipts_1.mutation_type,
                    member_mutation_receipts_1.request_hash,
                    member_mutation_receipts_1.response_payload,
                    member_mutation_receipts_1.created_at
                   FROM member_mutation_receipts member_mutation_receipts_1
                  WHERE member_mutation_receipts_1.user_id = (( SELECT auth.uid() AS uid))
                  ORDER BY member_mutation_receipts_1.created_at DESC
                 LIMIT 20) r), '[]'::jsonb) AS recent_mutations
   FROM member_mutation_receipts
  WHERE user_id = (( SELECT auth.uid() AS uid));

CREATE VIEW "public"."my_upcoming_meals" WITH (security_invoker=true) AS
 SELECT i.id AS meal_item_id,
    i.meal_plan_id,
    i.scheduled_date,
    i.meal_slot,
    i.status,
    i.adherence_percent,
    COALESCE(r.title, i.custom_title) AS title,
    r.id AS recipe_id,
    r.prep_minutes,
    r.cook_minutes
   FROM client_access ca
     JOIN client_meal_plan_items i ON i.contact_id = ca.contact_id
     LEFT JOIN recipes r ON r.id = i.recipe_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND i.scheduled_date >= CURRENT_DATE AND i.scheduled_date <= (CURRENT_DATE + 6)
  ORDER BY i.scheduled_date, i.sort_order;

CREATE VIEW "public"."my_upcoming_workouts" WITH (security_invoker=true) AS
 SELECT a.id AS workout_assignment_id,
    a.fitness_plan_id,
    a.scheduled_date,
    a.status,
    a.notes,
    w.id AS workout_id,
    w.title,
    w.description,
    w.category,
    w.difficulty,
    w.environment,
    w.duration_minutes
   FROM client_access ca
     JOIN client_workout_assignments a ON a.contact_id = ca.contact_id
     JOIN workout_templates w ON w.id = a.workout_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND a.scheduled_date >= CURRENT_DATE AND a.scheduled_date <= (CURRENT_DATE + 6) AND a.status <> 'cancelled'::text
  ORDER BY a.scheduled_date, w.title;

CREATE VIEW "public"."my_weekly_summary" WITH (security_invoker=true) AS
 SELECT user_id,
    contact_id,
    CURRENT_DATE - 6 AS period_start,
    CURRENT_DATE AS period_end,
    ( SELECT count(*) AS count
           FROM habit_checkins hc
          WHERE hc.contact_id = ca.contact_id AND hc.checkin_date >= (CURRENT_DATE - 6) AND hc.checkin_date <= CURRENT_DATE) AS habit_checkins,
    ( SELECT count(DISTINCT hc.checkin_date) AS count
           FROM habit_checkins hc
          WHERE hc.contact_id = ca.contact_id AND hc.checkin_date >= (CURRENT_DATE - 6) AND hc.checkin_date <= CURRENT_DATE) AS active_habit_days,
    ( SELECT count(*) AS count
           FROM client_workout_assignments wa
          WHERE wa.contact_id = ca.contact_id AND wa.status = 'completed'::text AND wa.scheduled_date >= (CURRENT_DATE - 6) AND wa.scheduled_date <= CURRENT_DATE) AS workouts_completed,
    ( SELECT count(*) AS count
           FROM client_meal_plan_items mi
          WHERE mi.contact_id = ca.contact_id AND mi.status = 'completed'::text AND mi.scheduled_date >= (CURRENT_DATE - 6) AND mi.scheduled_date <= CURRENT_DATE) AS meals_completed,
    ( SELECT round(avg(mi.adherence_percent), 1) AS round
           FROM client_meal_plan_items mi
          WHERE mi.contact_id = ca.contact_id AND mi.adherence_percent IS NOT NULL AND mi.scheduled_date >= (CURRENT_DATE - 6) AND mi.scheduled_date <= CURRENT_DATE) AS meal_adherence,
    ( SELECT count(*) AS count
           FROM progress_entries pe
          WHERE pe.contact_id = ca.contact_id AND pe.recorded_at::date >= (CURRENT_DATE - 6) AND pe.recorded_at::date <= CURRENT_DATE) AS progress_entries,
    ( SELECT count(*) AS count
           FROM client_goals g
          WHERE g.contact_id = ca.contact_id AND g.status = 'completed'::text AND g.completed_at::date >= (CURRENT_DATE - 6) AND g.completed_at::date <= CURRENT_DATE) AS goals_completed,
    ( SELECT count(*) AS count
           FROM challenge_enrollments ce
          WHERE ce.contact_id = ca.contact_id AND ce.status = 'completed'::text AND ce.completed_at::date >= (CURRENT_DATE - 6) AND ce.completed_at::date <= CURRENT_DATE) AS challenges_completed,
    ( SELECT COALESCE(sum(ce.points_earned), 0::bigint) AS "coalesce"
           FROM challenge_enrollments ce
          WHERE ce.contact_id = ca.contact_id AND ce.completed_at::date >= (CURRENT_DATE - 6) AND ce.completed_at::date <= CURRENT_DATE) AS challenge_points_earned,
    ( SELECT count(*) AS count
           FROM client_course_enrollments cce
          WHERE cce.contact_id = ca.contact_id AND cce.status = 'completed'::text AND cce.completed_at::date >= (CURRENT_DATE - 6) AND cce.completed_at::date <= CURRENT_DATE) AS courses_completed
   FROM client_access ca
  WHERE user_id = (( SELECT auth.uid() AS uid))
 LIMIT 1;

CREATE VIEW "public"."admin_coach_attention_by_owner" WITH (security_invoker=true) AS
 SELECT coach_user_id,
    coach_name,
    count(*)::integer AS client_count,
    count(*) FILTER (WHERE attention_priority = 'urgent'::text)::integer AS urgent_clients,
    count(*) FILTER (WHERE attention_priority = 'high'::text)::integer AS high_priority_clients,
    count(*) FILTER (WHERE attention_priority = 'normal'::text)::integer AS normal_priority_clients,
    count(*) FILTER (WHERE attention_priority = 'low'::text)::integer AS low_priority_clients,
    COALESCE(sum(attention_signal_count), 0::bigint)::integer AS total_attention_signals,
    COALESCE(sum(overdue_goals), 0::bigint)::integer AS overdue_goals,
    COALESCE(sum(overdue_assignments), 0::bigint)::integer AS overdue_assignments,
    COALESCE(sum(overdue_staff_tasks), 0::bigint)::integer AS overdue_staff_tasks
   FROM admin_client_attention_center
  GROUP BY coach_user_id, coach_name
  ORDER BY (count(*) FILTER (WHERE attention_priority = 'urgent'::text)) DESC, (count(*) FILTER (WHERE attention_priority = 'high'::text)) DESC, (COALESCE(sum(attention_signal_count), 0::bigint)::integer) DESC, coach_name;

CREATE VIEW "public"."admin_coaching_attention_summary" WITH (security_invoker=true) AS
 SELECT count(*)::integer AS visible_clients,
    count(*) FILTER (WHERE attention_priority = 'urgent'::text)::integer AS urgent_clients,
    count(*) FILTER (WHERE attention_priority = 'high'::text)::integer AS high_priority_clients,
    count(*) FILTER (WHERE attention_priority = 'normal'::text)::integer AS normal_priority_clients,
    count(*) FILTER (WHERE attention_priority = 'low'::text)::integer AS low_priority_clients,
    count(*) FILTER (WHERE 'no_checkin_yet'::text = ANY (attention_signals))::integer AS clients_without_checkin,
    count(*) FILTER (WHERE 'checkin_stale'::text = ANY (attention_signals))::integer AS stale_checkins,
    count(*) FILTER (WHERE 'no_progress_yet'::text = ANY (attention_signals))::integer AS clients_without_progress,
    count(*) FILTER (WHERE 'progress_stale'::text = ANY (attention_signals))::integer AS stale_progress,
    COALESCE(sum(overdue_goals), 0::bigint)::integer AS overdue_goals,
    COALESCE(sum(overdue_assignments), 0::bigint)::integer AS overdue_client_assignments,
    COALESCE(sum(overdue_staff_tasks), 0::bigint)::integer AS overdue_staff_tasks
   FROM admin_client_attention_center;

CREATE VIEW "public"."admin_companion_control_center" WITH (security_invoker=true) AS
 SELECT ( SELECT to_jsonb(k.*) AS to_jsonb
           FROM admin_companion_knowledge_readiness k
         LIMIT 1) AS knowledge_readiness,
    ( SELECT to_jsonb(o.*) AS to_jsonb
           FROM admin_companion_operations_summary o
         LIMIT 1) AS operations,
    ( SELECT to_jsonb(u.*) AS to_jsonb
           FROM admin_companion_usage_summary_30d u
         LIMIT 1) AS usage_30d,
    COALESCE(( SELECT jsonb_agg(to_jsonb(s.*) ORDER BY s.title) AS jsonb_agg
           FROM admin_companion_source_health s), '[]'::jsonb) AS source_health,
    COALESCE(( SELECT jsonb_agg(to_jsonb(q.*) ORDER BY q.created_at) AS jsonb_agg
           FROM ( SELECT admin_companion_review_queue.review_id,
                    admin_companion_review_queue.request_id,
                    admin_companion_review_queue.contact_id,
                    admin_companion_review_queue.first_name,
                    admin_companion_review_queue.last_name,
                    admin_companion_review_queue.email,
                    admin_companion_review_queue.question_type,
                    admin_companion_review_queue.question_type_label,
                    admin_companion_review_queue.question,
                    admin_companion_review_queue.handling_mode,
                    admin_companion_review_queue.request_status,
                    admin_companion_review_queue.retrieval_confidence,
                    admin_companion_review_queue.answer_confidence,
                    admin_companion_review_queue.draft_answer,
                    admin_companion_review_queue.escalation_reason,
                    admin_companion_review_queue.assigned_to,
                    admin_companion_review_queue.assigned_name,
                    admin_companion_review_queue.review_status,
                    admin_companion_review_queue.review_reason,
                    admin_companion_review_queue.created_at
                   FROM admin_companion_review_queue
                  ORDER BY admin_companion_review_queue.created_at
                 LIMIT 50) q), '[]'::jsonb) AS review_queue;

CREATE VIEW "public"."admin_enrollment_readiness_summary" WITH (security_invoker=true) AS
 SELECT count(*)::integer AS visible_enrollments,
    count(*) FILTER (WHERE ready_for_access)::integer AS ready_for_access,
    count(*) FILTER (WHERE NOT ready_for_access)::integer AS blocked_enrollments,
    count(*) FILTER (WHERE 'payment_incomplete'::text = ANY (blockers))::integer AS payment_incomplete,
    count(*) FILTER (WHERE 'payment_amount_short'::text = ANY (blockers))::integer AS payment_amount_short,
    count(*) FILTER (WHERE 'agreement_incomplete'::text = ANY (blockers))::integer AS agreement_incomplete,
    count(*) FILTER (WHERE 'required_signatures_missing'::text = ANY (blockers))::integer AS signatures_missing,
    count(*) FILTER (WHERE 'agreement_declined'::text = ANY (blockers))::integer AS agreement_declined,
    count(*) FILTER (WHERE 'access_not_ready'::text = ANY (blockers))::integer AS access_not_ready
   FROM admin_enrollment_readiness;

CREATE VIEW "public"."admin_mobile_operations_center" WITH (security_invoker=true) AS
 SELECT ( SELECT to_jsonb(a.*) AS to_jsonb
           FROM admin_mobile_adoption_summary a
         LIMIT 1) AS adoption,
    COALESCE(( SELECT jsonb_agg(to_jsonb(v.*) ORDER BY v.platform, v.active_devices_30d DESC) AS jsonb_agg
           FROM admin_mobile_versions v), '[]'::jsonb) AS versions,
    COALESCE(( SELECT jsonb_agg(to_jsonb(f.*) ORDER BY f.unique_members DESC, f.event_count DESC) AS jsonb_agg
           FROM ( SELECT admin_mobile_feature_usage_30d.usage_key,
                    admin_mobile_feature_usage_30d.event_count,
                    admin_mobile_feature_usage_30d.unique_members,
                    admin_mobile_feature_usage_30d.last_event_at
                   FROM admin_mobile_feature_usage_30d
                 LIMIT 50) f), '[]'::jsonb) AS feature_usage_30d;

CREATE VIEW "public"."admin_schedule_availability_issues" WITH (security_invoker=true) AS
 WITH scheduled AS (
         SELECT admin_team_calendar.item_type,
            admin_team_calendar.item_id,
            admin_team_calendar.contact_id,
            admin_team_calendar.person_name,
            admin_team_calendar.email,
            admin_team_calendar.appointment_type,
            admin_team_calendar.status,
            admin_team_calendar.scheduled_start,
            admin_team_calendar.scheduled_end,
            admin_team_calendar.time_zone,
            admin_team_calendar.format,
            admin_team_calendar.location_url,
            admin_team_calendar.staff_user_id,
            admin_team_calendar.staff_name,
            admin_team_calendar.journey_id,
            admin_team_calendar.journey_step_id,
            admin_team_calendar.client_notes,
            admin_team_calendar.staff_notes,
            admin_team_calendar.created_at,
            admin_team_calendar.updated_at
           FROM admin_team_calendar
          WHERE admin_team_calendar.status = 'scheduled'::text AND admin_team_calendar.staff_user_id IS NOT NULL AND admin_team_calendar.scheduled_start IS NOT NULL
        ), availability AS (
         SELECT s_1.item_id,
            (EXISTS ( SELECT 1
                   FROM staff_availability_rules ar
                  WHERE ar.user_id = s_1.staff_user_id AND ar.active AND ar.day_of_week = EXTRACT(dow FROM (s_1.scheduled_start AT TIME ZONE ar.time_zone))::integer AND (s_1.scheduled_start AT TIME ZONE ar.time_zone)::time without time zone >= ar.start_time AND (COALESCE(s_1.scheduled_end, s_1.scheduled_start + '01:00:00'::interval) AT TIME ZONE ar.time_zone) <= (date((s_1.scheduled_start AT TIME ZONE ar.time_zone)) + ar.end_time))) AS within_recurring_availability,
            (EXISTS ( SELECT 1
                   FROM staff_availability_exceptions ex
                  WHERE ex.user_id = s_1.staff_user_id AND ex.exception_type = 'unavailable'::text AND ex.starts_at < COALESCE(s_1.scheduled_end, s_1.scheduled_start + '01:00:00'::interval) AND ex.ends_at > s_1.scheduled_start)) AS hits_unavailable_exception,
            (EXISTS ( SELECT 1
                   FROM staff_availability_rules ar
                  WHERE ar.user_id = s_1.staff_user_id AND ar.active)) AS has_availability_rules
           FROM scheduled s_1
        ), daily_counts AS (
         SELECT s_1.staff_user_id,
            date(s_1.scheduled_start) AS schedule_day,
            count(*) AS day_count
           FROM scheduled s_1
          GROUP BY s_1.staff_user_id, (date(s_1.scheduled_start))
        ), weekly_counts AS (
         SELECT s_1.staff_user_id,
            date_trunc('week'::text, s_1.scheduled_start) AS week_start,
            count(*) AS week_count
           FROM scheduled s_1
          GROUP BY s_1.staff_user_id, (date_trunc('week'::text, s_1.scheduled_start))
        )
 SELECT s.item_id,
    s.item_type,
    s.staff_user_id,
    s.staff_name,
    s.person_name,
    s.scheduled_start,
    s.scheduled_end,
        CASE
            WHEN a.hits_unavailable_exception THEN 'unavailable_exception'::text
            WHEN a.has_availability_rules AND NOT a.within_recurring_availability THEN 'outside_recurring_availability'::text
            WHEN scs.max_sessions_per_day IS NOT NULL AND dc.day_count > scs.max_sessions_per_day THEN 'daily_capacity_exceeded'::text
            WHEN scs.max_sessions_per_week IS NOT NULL AND wc.week_count > scs.max_sessions_per_week THEN 'weekly_capacity_exceeded'::text
            ELSE NULL::text
        END AS issue_type,
        CASE
            WHEN a.hits_unavailable_exception THEN 'Scheduled during a staff unavailable exception.'::text
            WHEN a.has_availability_rules AND NOT a.within_recurring_availability THEN 'Scheduled outside configured recurring availability.'::text
            WHEN scs.max_sessions_per_day IS NOT NULL AND dc.day_count > scs.max_sessions_per_day THEN 'Scheduled sessions exceed the configured daily limit.'::text
            WHEN scs.max_sessions_per_week IS NOT NULL AND wc.week_count > scs.max_sessions_per_week THEN 'Scheduled sessions exceed the configured weekly limit.'::text
            ELSE NULL::text
        END AS issue_detail
   FROM scheduled s
     JOIN availability a ON a.item_id = s.item_id
     LEFT JOIN staff_capacity_settings scs ON scs.user_id = s.staff_user_id
     LEFT JOIN daily_counts dc ON dc.staff_user_id = s.staff_user_id AND dc.schedule_day = date(s.scheduled_start)
     LEFT JOIN weekly_counts wc ON wc.staff_user_id = s.staff_user_id AND wc.week_start = date_trunc('week'::text, s.scheduled_start)
  WHERE a.hits_unavailable_exception OR a.has_availability_rules AND NOT a.within_recurring_availability OR scs.max_sessions_per_day IS NOT NULL AND dc.day_count > scs.max_sessions_per_day OR scs.max_sessions_per_week IS NOT NULL AND wc.week_count > scs.max_sessions_per_week;

CREATE VIEW "public"."admin_schedule_conflicts" WITH (security_invoker=true) AS
 SELECT a.staff_user_id,
    a.staff_name,
    a.item_id AS item_a_id,
    b.item_id AS item_b_id,
    a.scheduled_start AS item_a_start,
    a.scheduled_end AS item_a_end,
    b.scheduled_start AS item_b_start,
    b.scheduled_end AS item_b_end,
    a.person_name AS item_a_person,
    b.person_name AS item_b_person
   FROM admin_team_calendar a
     JOIN admin_team_calendar b ON a.staff_user_id = b.staff_user_id AND a.item_id < b.item_id AND a.status = 'scheduled'::text AND b.status = 'scheduled'::text AND a.scheduled_start IS NOT NULL AND b.scheduled_start IS NOT NULL AND COALESCE(a.scheduled_end, a.scheduled_start + '01:00:00'::interval) > b.scheduled_start AND COALESCE(b.scheduled_end, b.scheduled_start + '01:00:00'::interval) > a.scheduled_start;

CREATE VIEW "public"."admin_staff_onboarding_summary" WITH (security_invoker=true) AS
 SELECT count(*)::integer AS visible_staff,
    count(*) FILTER (WHERE onboarding_ready)::integer AS onboarding_ready,
    count(*) FILTER (WHERE NOT onboarding_ready)::integer AS onboarding_blocked_or_pending,
    count(*) FILTER (WHERE 'coach_nda_incomplete'::text = ANY (blockers))::integer AS coach_nda_incomplete,
    count(*) FILTER (WHERE 'required_agreement_incomplete'::text = ANY (blockers))::integer AS required_agreement_incomplete,
    count(*) FILTER (WHERE 'required_agreement_declined'::text = ANY (blockers))::integer AS required_agreement_declined
   FROM admin_staff_onboarding_readiness;

CREATE VIEW "public"."admin_staff_workload" WITH (security_invoker=true) AS
 SELECT user_id,
    display_name,
    role,
    status,
    ( SELECT count(*) AS count
           FROM contacts c
          WHERE c.assigned_to = sa.user_id AND c.lifecycle_stage <> 'inactive'::text) AS assigned_contacts,
    ( SELECT count(*) AS count
           FROM client_coach_assignments cca
          WHERE cca.coach_user_id = sa.user_id AND cca.role = 'primary'::text AND cca.status = 'active'::text) AS active_clients,
    ( SELECT count(*) AS count
           FROM follow_up_tasks t
          WHERE t.assigned_to = sa.user_id AND t.status = 'open'::text) AS open_tasks,
    ( SELECT count(*) AS count
           FROM follow_up_tasks t
          WHERE t.assigned_to = sa.user_id AND t.status = 'open'::text AND t.due_at IS NOT NULL AND t.due_at < now()) AS overdue_tasks,
    ( SELECT count(*) AS count
           FROM coaching_sessions cs
          WHERE cs.coach_user_id = sa.user_id AND cs.status = 'scheduled'::text AND cs.scheduled_start >= now() AND cs.scheduled_start < (now() + '7 days'::interval)) AS coaching_sessions_7d,
    ( SELECT COALESCE(sum(i.unread_count), 0::numeric) AS "coalesce"
           FROM admin_staff_inbox i
          WHERE i.staff_user_id = sa.user_id) AS unread_member_messages,
    ( SELECT count(*) AS count
           FROM coach_companion_reviews cr
          WHERE cr.assigned_to = sa.user_id AND (cr.status = ANY (ARRAY['open'::text, 'in_review'::text]))) AS companion_reviews
   FROM staff_access sa
  WHERE status = 'active'::text
  ORDER BY (
        CASE role
            WHEN 'owner'::text THEN 1
            WHEN 'admin'::text THEN 2
            WHEN 'coach'::text THEN 3
            WHEN 'financial'::text THEN 4
            WHEN 'support'::text THEN 5
            ELSE 6
        END), display_name;

CREATE VIEW "public"."admin_work_queue_summary" WITH (security_invoker=true) AS
 SELECT assigned_to,
    COALESCE(assigned_name, 'Unassigned'::text) AS assigned_name,
    count(*) AS open_count,
    count(*) FILTER (WHERE overdue) AS overdue_count,
    count(*) FILTER (WHERE due_bucket = 'today'::text) AS due_today_count,
    count(*) FILTER (WHERE work_category = 'Report Review'::text) AS report_review_count,
    count(*) FILTER (WHERE work_category = 'Check-In Review'::text) AS checkin_review_count,
    count(*) FILTER (WHERE work_category = 'Scheduling'::text) AS scheduling_count,
    count(*) FILTER (WHERE work_category = 'Calls'::text) AS calls_count,
    count(*) FILTER (WHERE work_category = 'Coaching'::text) AS coaching_count,
    count(*) FILTER (WHERE work_category = 'Enrollment'::text) AS enrollment_count,
    count(*) FILTER (WHERE work_category = 'Onboarding'::text) AS onboarding_count
   FROM admin_work_queue
  GROUP BY assigned_to, assigned_name;

CREATE VIEW "public"."my_activity_timeline" WITH (security_invoker=true) AS
 SELECT occurred_at,
    activity_type,
    title,
    detail,
    activity_key,
    source_type,
    source_id
   FROM ( SELECT mn.created_at AS occurred_at,
            'notification'::text AS activity_type,
            mn.title,
            mn.body AS detail,
            mn.notification_type AS activity_key,
            'notification'::text AS source_type,
            mn.id AS source_id
           FROM my_notifications mn
        UNION ALL
         SELECT g.completed_at AS occurred_at,
            'goal_completed'::text AS activity_type,
            g.title,
            'Goal completed'::text AS detail,
            g.goal_key AS activity_key,
            'goal'::text AS source_type,
            g.id AS source_id
           FROM my_goals g
          WHERE g.status = 'completed'::text AND g.completed_at IS NOT NULL
        UNION ALL
         SELECT cce.completed_at AS occurred_at,
            'course_completed'::text AS activity_type,
            lc.title,
            'Course completed'::text AS detail,
            NULL::text AS activity_key,
            'course'::text AS source_type,
            cce.course_id AS source_id
           FROM client_access ca
             JOIN client_course_enrollments cce ON cce.contact_id = ca.contact_id
             JOIN learning_courses lc ON lc.id = cce.course_id
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND cce.status = 'completed'::text AND cce.completed_at IS NOT NULL
        UNION ALL
         SELECT ce.completed_at AS occurred_at,
            'challenge_completed'::text AS activity_type,
            wc.title,
            ('Challenge completed · '::text || ce.points_earned::text) || ' points'::text AS detail,
            wc.challenge_key AS activity_key,
            'challenge'::text AS source_type,
            ce.challenge_id AS source_id
           FROM client_access ca
             JOIN challenge_enrollments ce ON ce.contact_id = ca.contact_id
             JOIN wellness_challenges wc ON wc.id = ce.challenge_id
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ce.status = 'completed'::text AND ce.completed_at IS NOT NULL
        UNION ALL
         SELECT pe.recorded_at AS occurred_at,
            'progress_logged'::text AS activity_type,
            pmc.label AS title,
                CASE
                    WHEN pe.value_numeric IS NOT NULL THEN TRIM(BOTH FROM to_char(pe.value_numeric, 'FM999999990.99'::text)) ||
                    CASE
                        WHEN pmc.unit IS NOT NULL THEN ' '::text || pmc.unit
                        ELSE ''::text
                    END
                    WHEN pe.value_boolean IS NOT NULL THEN
                    CASE
                        WHEN pe.value_boolean THEN 'Yes'::text
                        ELSE 'No'::text
                    END
                    ELSE NULL::text
                END AS detail,
            pe.metric_key AS activity_key,
            'progress'::text AS source_type,
            pe.id AS source_id
           FROM client_access ca
             JOIN progress_entries pe ON pe.contact_id = ca.contact_id
             JOIN progress_metric_catalog pmc ON pmc.metric_key = pe.metric_key
          WHERE ca.user_id = (( SELECT auth.uid() AS uid))) activity
  WHERE occurred_at IS NOT NULL
  ORDER BY occurred_at DESC;

CREATE VIEW "public"."my_app_access" WITH (security_invoker=true) AS
 SELECT ca.user_id,
    ca.contact_id,
    ca.membership_id,
    cm.program_code,
    pc.name AS program_name,
    (EXISTS ( SELECT 1
           FROM membership_entitlements me
          WHERE me.membership_id = cm.id AND me.status = 'active'::text AND me.entitlement_key = 'community'::text)) AS community_enabled,
    (EXISTS ( SELECT 1
           FROM client_course_enrollments cce
          WHERE cce.membership_id = cm.id AND cce.status <> 'cancelled'::text)) AS courses_enabled,
    (EXISTS ( SELECT 1
           FROM membership_entitlements me
          WHERE me.membership_id = cm.id AND me.status = 'active'::text AND (me.entitlement_key = ANY (ARRAY['nutrition_plans'::text, 'tracking'::text])))) AS nutrition_enabled,
    (EXISTS ( SELECT 1
           FROM membership_entitlements me
          WHERE me.membership_id = cm.id AND me.status = 'active'::text AND (me.entitlement_key = ANY (ARRAY['fitness_plans'::text, 'tracking'::text])))) AS fitness_enabled,
    (EXISTS ( SELECT 1
           FROM membership_entitlements me
          WHERE me.membership_id = cm.id AND me.status = 'active'::text AND me.entitlement_key = 'health_challenges'::text)) AS challenges_enabled,
    (EXISTS ( SELECT 1
           FROM membership_entitlements me
          WHERE me.membership_id = cm.id AND me.status = 'active'::text AND me.entitlement_key = 'ai_advisor'::text)) AS ask_revitalized_enabled,
    (EXISTS ( SELECT 1
           FROM membership_entitlements me
          WHERE me.membership_id = cm.id AND me.status = 'active'::text AND me.entitlement_key = 'family_profiles'::text)) AS family_hub_enabled,
    (EXISTS ( SELECT 1
           FROM membership_entitlements me
          WHERE me.membership_id = cm.id AND me.status = 'active'::text AND me.entitlement_key = 'biometrics'::text)) AS biometrics_enabled,
    (EXISTS ( SELECT 1
           FROM membership_entitlements me
          WHERE me.membership_id = cm.id AND me.status = 'active'::text AND me.entitlement_key = 'group_coaching'::text)) AS group_coaching_enabled,
    (EXISTS ( SELECT 1
           FROM membership_entitlements me
          WHERE me.membership_id = cm.id AND me.status = 'active'::text AND me.entitlement_key = 'private_coaching'::text)) AS private_coaching_enabled,
    (EXISTS ( SELECT 1
           FROM my_refuel_access mra)) AS refuel_enabled,
    ( SELECT me.limit_value
           FROM membership_entitlements me
          WHERE me.membership_id = cm.id AND me.status = 'active'::text AND me.entitlement_key = 'family_profiles'::text
         LIMIT 1) AS family_profile_limit,
    ( SELECT count(*) AS count
           FROM membership_entitlements me
          WHERE me.membership_id = cm.id AND me.status = 'active'::text) AS entitlement_count,
    (EXISTS ( SELECT 1
           FROM referral_profiles rp
          WHERE rp.contact_id = ca.contact_id AND rp.status = 'active'::text)) AS ambassador_center_enabled
   FROM client_access ca
     JOIN client_memberships cm ON cm.id = ca.membership_id
     JOIN program_catalog pc ON pc.program_code = cm.program_code
  WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.status = 'active'::text AND cm.status = 'active'::text
 LIMIT 1;

CREATE VIEW "public"."my_app_home" WITH (security_invoker=true) AS
 SELECT ca.user_id,
    ca.contact_id,
    c.first_name,
    c.last_name,
    ca.membership_id,
    cm.program_code,
    pc.name AS program_name,
    cm.status AS membership_status,
    ca.status AS access_status,
    cm.assigned_coach_id,
    sa.display_name AS assigned_coach_name,
    ( SELECT mj.journey_name
           FROM my_member_journey mj
          ORDER BY mj.last_activity_at DESC NULLS LAST
         LIMIT 1) AS journey_name,
    ( SELECT mj.current_step_name
           FROM my_member_journey mj
          ORDER BY mj.last_activity_at DESC NULLS LAST
         LIMIT 1) AS current_step_name,
    ( SELECT mj.progress_percent
           FROM my_member_journey mj
          ORDER BY mj.last_activity_at DESC NULLS LAST
         LIMIT 1) AS journey_progress_percent,
    ( SELECT count(*) AS count
           FROM my_goals g
          WHERE g.status = 'active'::text) AS active_goals,
    ( SELECT count(*) AS count
           FROM my_habits h
          WHERE h.status = 'active'::text) AS active_habits,
    ( SELECT count(*) AS count
           FROM my_challenges ch
          WHERE ch.enrollment_status = 'active'::text) AS active_challenges,
    ( SELECT count(*) AS count
           FROM my_courses mc
          WHERE mc.status = 'active'::text) AS active_courses,
    (( SELECT COALESCE(round(avg(mc.progress_percent)), 0::numeric) AS "coalesce"
           FROM my_courses mc
          WHERE mc.status = ANY (ARRAY['active'::text, 'completed'::text])))::integer AS average_course_progress,
    ( SELECT count(*) AS count
           FROM my_resources mr) AS available_resources,
    ( SELECT count(*) AS count
           FROM my_notifications mn
          WHERE mn.status = 'unread'::text) AS unread_notifications,
    ( SELECT count(*) AS count
           FROM my_upcoming_meals mum
          WHERE mum.scheduled_date = CURRENT_DATE) AS meals_today,
    ( SELECT count(*) AS count
           FROM my_upcoming_workouts muw
          WHERE muw.scheduled_date = CURRENT_DATE) AS workouts_today,
    ( SELECT mc.title
           FROM my_courses mc
          WHERE mc.status = 'active'::text
          ORDER BY mc.last_activity_at DESC NULLS LAST, mc.title
         LIMIT 1) AS continue_course_title,
    ( SELECT muw.title
           FROM my_upcoming_workouts muw
          WHERE muw.scheduled_date >= CURRENT_DATE
          ORDER BY muw.scheduled_date, muw.title
         LIMIT 1) AS next_workout_title,
    ( SELECT mum.title
           FROM my_upcoming_meals mum
          WHERE mum.scheduled_date >= CURRENT_DATE
          ORDER BY mum.scheduled_date, mum.meal_slot
         LIMIT 1) AS next_meal_title
   FROM client_access ca
     JOIN contacts c ON c.id = ca.contact_id
     JOIN client_memberships cm ON cm.id = ca.membership_id
     JOIN program_catalog pc ON pc.program_code = cm.program_code
     LEFT JOIN staff_access sa ON sa.user_id = cm.assigned_coach_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
 LIMIT 1;

CREATE VIEW "public"."my_coach_attention_queue" WITH (security_invoker=true) AS
 SELECT contact_id,
    first_name,
    last_name,
    membership_id,
    program_code,
    program_name,
    coach_user_id,
    coach_name,
    last_checkin_at,
    last_manual_progress_at,
    last_synced_health_at,
    active_goals,
    overdue_goals,
    overdue_assignments,
    overdue_staff_tasks,
    last_progress_at,
    attention_signals,
    attention_signal_count,
    attention_priority
   FROM admin_client_attention_center
  WHERE coach_user_id = (( SELECT auth.uid() AS uid)) OR private.staff_has_permission(( SELECT auth.uid() AS uid), 'coaching.manage'::text)
  ORDER BY (
        CASE attention_priority
            WHEN 'urgent'::text THEN 1
            WHEN 'high'::text THEN 2
            WHEN 'normal'::text THEN 3
            ELSE 4
        END), attention_signal_count DESC, last_checkin_at NULLS FIRST;

CREATE VIEW "public"."my_coaching_entitlements" WITH (security_invoker=true) AS
 SELECT ace.entitlement_key,
    ace.label,
    ace.limit_value,
    ace.used_value,
    ace.remaining_value,
    ace.reserved_sessions,
    ace.reset_cadence
   FROM client_access ca
     JOIN admin_client_coaching_entitlements ace ON ace.contact_id = ca.contact_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid));

CREATE VIEW "public"."my_coaching_momentum" WITH (security_invoker=true) AS
 WITH me AS (
         SELECT ca.contact_id,
            ca.membership_id
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.status = 'active'::text
          ORDER BY ca.updated_at DESC
         LIMIT 1
        ), recent_plan AS (
         SELECT avg(h.completion_percent) FILTER (WHERE h.completion_percent IS NOT NULL AND h.action_date >= (CURRENT_DATE - 6)) AS avg_7d,
            count(*) FILTER (WHERE h.total_actions > 0 AND h.action_date >= (CURRENT_DATE - 6))::integer AS planned_days_7d,
            count(*) FILTER (WHERE h.fully_completed AND h.action_date >= (CURRENT_DATE - 6))::integer AS full_days_7d
           FROM my_daily_plan_history_30d h
        ), last_checkin AS (
         SELECT max(c.submitted_at) AS submitted_at
           FROM client_checkins c
             JOIN me me_1 ON me_1.contact_id = c.contact_id
          WHERE c.status = ANY (ARRAY['submitted'::text, 'reviewed'::text])
        ), last_progress AS (
         SELECT max(t.recorded_at) AS recorded_at
           FROM my_health_metric_timeline t
             JOIN me me_1 ON me_1.contact_id = t.contact_id
        ), goals AS (
         SELECT count(*) FILTER (WHERE g_1.status = 'active'::text)::integer AS active_goals,
            count(*) FILTER (WHERE g_1.status = 'active'::text AND g_1.target_date < CURRENT_DATE)::integer AS overdue_goals
           FROM client_goals g_1
             JOIN me me_1 ON me_1.contact_id = g_1.contact_id
        )
 SELECT me.contact_id,
    me.membership_id,
    round(rp.avg_7d, 1) AS plan_completion_7d,
    rp.planned_days_7d,
    rp.full_days_7d,
    lc.submitted_at AS last_checkin_at,
    lp.recorded_at AS last_progress_at,
    g.active_goals,
    g.overdue_goals,
        CASE
            WHEN rp.planned_days_7d >= 3 AND COALESCE(rp.avg_7d, 100::numeric) < 50::numeric THEN 'needs_attention'::text
            WHEN lc.submitted_at IS NOT NULL AND lc.submitted_at < (now() - '14 days'::interval) THEN 'checkin_due'::text
            WHEN lp.recorded_at IS NOT NULL AND lp.recorded_at < (now() - '14 days'::interval) THEN 'progress_due'::text
            WHEN g.overdue_goals > 0 THEN 'goal_follow_up'::text
            WHEN rp.planned_days_7d >= 3 AND COALESCE(rp.avg_7d, 0::numeric) >= 80::numeric THEN 'strong_momentum'::text
            ELSE 'steady'::text
        END AS momentum_state
   FROM me
     CROSS JOIN recent_plan rp
     CROSS JOIN last_checkin lc
     CROSS JOIN last_progress lp
     CROSS JOIN goals g;

CREATE VIEW "public"."my_consistency_summary" WITH (security_invoker=true) AS
 WITH hist AS (
         SELECT my_daily_plan_history_30d.action_date,
            my_daily_plan_history_30d.habits_assigned,
            my_daily_plan_history_30d.habits_completed,
            my_daily_plan_history_30d.meals_assigned,
            my_daily_plan_history_30d.meals_completed,
            my_daily_plan_history_30d.workouts_assigned,
            my_daily_plan_history_30d.workouts_completed,
            my_daily_plan_history_30d.total_actions,
            my_daily_plan_history_30d.completed_actions,
            my_daily_plan_history_30d.completion_percent,
            my_daily_plan_history_30d.fully_completed
           FROM my_daily_plan_history_30d
        ), numbered AS (
         SELECT h.action_date,
            h.habits_assigned,
            h.habits_completed,
            h.meals_assigned,
            h.meals_completed,
            h.workouts_assigned,
            h.workouts_completed,
            h.total_actions,
            h.completed_actions,
            h.completion_percent,
            h.fully_completed,
            row_number() OVER (ORDER BY h.action_date DESC) AS recency_rank
           FROM hist h
        ), current_streak AS (
         SELECT count(*)::integer AS streak
           FROM numbered n
          WHERE n.fully_completed = true AND NOT (EXISTS ( SELECT 1
                   FROM numbered newer
                  WHERE newer.action_date > n.action_date AND newer.total_actions > 0 AND newer.fully_completed = false)) AND n.action_date <= CURRENT_DATE
        ), islands AS (
         SELECT hist_1.action_date,
            hist_1.action_date - row_number() OVER (ORDER BY hist_1.action_date)::integer AS grp
           FROM hist hist_1
          WHERE hist_1.fully_completed = true
        ), best_streak AS (
         SELECT COALESCE(max(s.cnt), 0) AS streak
           FROM ( SELECT count(*)::integer AS cnt
                   FROM islands
                  GROUP BY islands.grp) s
        )
 SELECT COALESCE(( SELECT hist_1.completion_percent
           FROM hist hist_1
          WHERE hist_1.action_date = CURRENT_DATE), 0::numeric) AS today_completion_percent,
    ( SELECT hist_1.total_actions
           FROM hist hist_1
          WHERE hist_1.action_date = CURRENT_DATE) AS today_actions,
    ( SELECT hist_1.completed_actions
           FROM hist hist_1
          WHERE hist_1.action_date = CURRENT_DATE) AS today_completed_actions,
    round(avg(completion_percent) FILTER (WHERE completion_percent IS NOT NULL), 1) AS average_completion_30d,
    count(*) FILTER (WHERE fully_completed)::integer AS fully_completed_days_30d,
    count(*) FILTER (WHERE total_actions > 0)::integer AS planned_days_30d,
    ( SELECT current_streak.streak
           FROM current_streak) AS current_full_completion_streak,
    ( SELECT best_streak.streak
           FROM best_streak) AS best_full_completion_streak_30d
   FROM hist;

CREATE VIEW "public"."my_daily_action_center" WITH (security_invoker=true) AS
 SELECT user_id,
    contact_id,
    CURRENT_DATE AS action_date,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('habit_id', h.id, 'title', h.title, 'category', h.category, 'frequency', h.frequency, 'target', h.target_per_period, 'unit', h.unit, 'today_value', COALESCE(( SELECT hc.value
                   FROM habit_checkins hc
                  WHERE hc.habit_id = h.id AND hc.contact_id = ca.contact_id AND hc.checkin_date = CURRENT_DATE
                 LIMIT 1), 0::numeric), 'completed_today', COALESCE(( SELECT hc.value >= h.target_per_period
                   FROM habit_checkins hc
                  WHERE hc.habit_id = h.id AND hc.contact_id = ca.contact_id AND hc.checkin_date = CURRENT_DATE
                 LIMIT 1), false)) ORDER BY h.title) AS jsonb_agg
           FROM client_habits h
          WHERE h.contact_id = ca.contact_id AND h.status = 'active'::text AND h.starts_on <= CURRENT_DATE AND (h.ends_on IS NULL OR h.ends_on >= CURRENT_DATE)), '[]'::jsonb) AS habits,
    COALESCE(( SELECT jsonb_agg(to_jsonb(m.*) ORDER BY m.meal_slot, m.title) AS jsonb_agg
           FROM my_upcoming_meals m
          WHERE m.scheduled_date = CURRENT_DATE), '[]'::jsonb) AS meals,
    COALESCE(( SELECT jsonb_agg(to_jsonb(w.*) ORDER BY w.title) AS jsonb_agg
           FROM my_upcoming_workouts w
          WHERE w.scheduled_date = CURRENT_DATE), '[]'::jsonb) AS workouts,
    COALESCE(( SELECT jsonb_agg(to_jsonb(ch.*) ORDER BY ch.ends_on, ch.title) AS jsonb_agg
           FROM my_challenges ch
          WHERE ch.enrollment_status = 'active'::text), '[]'::jsonb) AS challenges,
    ( SELECT to_jsonb(c.*) AS to_jsonb
           FROM my_courses c
          WHERE c.status = 'active'::text
          ORDER BY c.last_activity_at DESC NULLS LAST, c.title
         LIMIT 1) AS continue_course,
    ( SELECT count(*) AS count
           FROM client_habits h
          WHERE h.contact_id = ca.contact_id AND h.status = 'active'::text AND h.starts_on <= CURRENT_DATE AND (h.ends_on IS NULL OR h.ends_on >= CURRENT_DATE)) AS habit_count,
    ( SELECT count(*) AS count
           FROM habit_checkins hc
             JOIN client_habits h ON h.id = hc.habit_id
          WHERE hc.contact_id = ca.contact_id AND hc.checkin_date = CURRENT_DATE AND h.status = 'active'::text AND hc.value >= h.target_per_period) AS habits_completed_today,
    ( SELECT count(*) AS count
           FROM my_upcoming_meals m
          WHERE m.scheduled_date = CURRENT_DATE) AS meal_count,
    ( SELECT count(*) AS count
           FROM my_upcoming_workouts w
          WHERE w.scheduled_date = CURRENT_DATE) AS workout_count
   FROM client_access ca
  WHERE user_id = (( SELECT auth.uid() AS uid))
 LIMIT 1;

CREATE VIEW "public"."my_family_calendar_summary" WITH (security_invoker=true) AS
 SELECT household_id,
    item_date,
    count(*)::integer AS item_count,
    count(*) FILTER (WHERE item_type = 'coaching_session'::text)::integer AS coaching_sessions,
    count(*) FILTER (WHERE item_type = 'workout'::text)::integer AS workouts,
    count(*) FILTER (WHERE item_type = 'meal'::text)::integer AS meals,
    count(*) FILTER (WHERE item_type = 'goal_due'::text)::integer AS goals_due,
    count(*) FILTER (WHERE item_type = 'challenge_end'::text)::integer AS challenges_ending
   FROM my_calendar_feed_60d
  WHERE household_id IS NOT NULL
  GROUP BY household_id, item_date
  ORDER BY item_date;

CREATE VIEW "public"."my_family_dashboard_summary_v2" WITH (security_invoker=true) AS
 SELECT household_id,
    max(household_average_health_score) AS family_health_score,
    count(*)::integer AS family_member_count,
    sum(active_goals)::integer AS active_goals,
    sum(completed_goals)::integer AS completed_goals,
    sum(active_challenges)::integer AS active_challenges,
    sum(completed_challenges)::integer AS completed_challenges,
    sum(challenge_points)::integer AS challenge_points,
    sum(achievement_count)::integer AS achievements_unlocked,
    max(latest_achievement_at) AS latest_achievement_at
   FROM my_family_progress_dashboard f
  GROUP BY household_id;

CREATE VIEW "public"."my_goal_progress" WITH (security_invoker=true) AS
 WITH latest AS (
         SELECT DISTINCT ON (t.contact_id, t.metric_key) t.contact_id,
            t.metric_key,
            t.value_numeric,
            t.recorded_at,
            t.unit
           FROM my_health_metric_timeline t
          WHERE t.value_numeric IS NOT NULL
          ORDER BY t.contact_id, t.metric_key, t.recorded_at DESC
        )
 SELECT g.id AS goal_id,
    g.contact_id,
    g.household_id,
    g.membership_id,
    g.scope,
    g.goal_key,
    g.title,
    g.description,
    g.baseline_value,
    g.target_value,
    g.target_unit,
    g.target_date,
    g.priority,
    g.status,
    l.value_numeric AS current_value,
    l.recorded_at AS current_recorded_at,
        CASE
            WHEN g.baseline_value IS NULL OR g.target_value IS NULL OR g.target_value = g.baseline_value OR l.value_numeric IS NULL THEN NULL::numeric
            ELSE round(GREATEST(0::numeric, LEAST(100::numeric, (l.value_numeric - g.baseline_value) / (g.target_value - g.baseline_value) * 100::numeric)), 1)
        END AS completion_percent,
        CASE
            WHEN g.status = 'completed'::text THEN 'completed'::text
            WHEN g.target_date IS NOT NULL AND g.target_date < CURRENT_DATE THEN 'past_due'::text
            WHEN l.value_numeric IS NULL THEN 'awaiting_data'::text
            ELSE 'in_progress'::text
        END AS progress_state
   FROM client_goals g
     LEFT JOIN latest l ON l.contact_id = g.contact_id AND l.metric_key = g.goal_key
  WHERE (EXISTS ( SELECT 1
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.contact_id = g.contact_id AND ca.status = 'active'::text))
  ORDER BY (
        CASE g.status
            WHEN 'active'::text THEN 1
            WHEN 'paused'::text THEN 2
            WHEN 'completed'::text THEN 3
            ELSE 4
        END), g.priority, g.created_at DESC;

CREATE VIEW "public"."my_health_dashboard_cards_30d" WITH (security_invoker=true) AS
 WITH ranked AS (
         SELECT t.contact_id,
            t.membership_id,
            t.metric_key,
            t.metric_label,
            t.category,
            t.unit,
            t.value_numeric,
            t.value_boolean,
            t.recorded_at,
            t.origin,
            t.source_key,
            t.connection_id,
            t.metadata,
            row_number() OVER (PARTITION BY t.contact_id, t.metric_key ORDER BY t.recorded_at DESC, t.origin) AS rn_latest,
            row_number() OVER (PARTITION BY t.contact_id, t.metric_key ORDER BY t.recorded_at, t.origin) AS rn_earliest
           FROM my_health_metric_timeline t
          WHERE t.value_numeric IS NOT NULL AND t.recorded_at >= (now() - '30 days'::interval)
        ), agg AS (
         SELECT ranked.contact_id,
            ranked.metric_key,
            max(ranked.metric_label) AS metric_label,
            max(ranked.category) AS category,
            max(ranked.unit) AS unit,
            max(ranked.value_numeric) FILTER (WHERE ranked.rn_latest = 1) AS current_value,
            max(ranked.recorded_at) FILTER (WHERE ranked.rn_latest = 1) AS current_recorded_at,
            max(ranked.value_numeric) FILTER (WHERE ranked.rn_earliest = 1) AS baseline_value,
            max(ranked.recorded_at) FILTER (WHERE ranked.rn_earliest = 1) AS baseline_recorded_at
           FROM ranked
          GROUP BY ranked.contact_id, ranked.metric_key
        )
 SELECT contact_id,
    metric_key,
    metric_label,
    category,
    unit,
    current_value,
    current_recorded_at,
    baseline_value,
    baseline_recorded_at,
    current_value - baseline_value AS absolute_change,
        CASE
            WHEN baseline_value IS NULL OR baseline_value = 0::numeric THEN NULL::numeric
            ELSE round((current_value - baseline_value) / abs(baseline_value) * 100::numeric, 2)
        END AS percent_change_30d
   FROM agg;

CREATE VIEW "public"."my_health_metric_latest" WITH (security_invoker=true) AS
 SELECT DISTINCT ON (contact_id, metric_key) contact_id,
    membership_id,
    metric_key,
    metric_label,
    category,
    unit,
    value_numeric,
    value_boolean,
    recorded_at,
    origin,
    source_key,
    connection_id,
    metadata
   FROM my_health_metric_timeline
  ORDER BY contact_id, metric_key, recorded_at DESC, origin;

CREATE VIEW "public"."my_message_threads" WITH (security_invoker=true) AS
 SELECT conversation_id,
    conversation_type,
    title,
    status,
    last_message_at,
    last_read_at,
    unread_count,
    last_message_preview,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('message_id', m.id, 'sender_user_id', m.sender_user_id, 'sender_contact_id', m.sender_contact_id, 'body', m.body, 'message_type', m.message_type, 'created_at', m.created_at, 'edited_at', m.edited_at) ORDER BY m.created_at) AS jsonb_agg
           FROM ( SELECT mm.id,
                    mm.conversation_id,
                    mm.sender_user_id,
                    mm.sender_contact_id,
                    mm.body,
                    mm.message_type,
                    mm.edited_at,
                    mm.deleted_at,
                    mm.metadata,
                    mm.created_at
                   FROM member_messages mm
                  WHERE mm.conversation_id = c.conversation_id AND mm.deleted_at IS NULL
                  ORDER BY mm.created_at DESC
                 LIMIT 50) m), '[]'::jsonb) AS messages
   FROM my_conversations c;

CREATE VIEW "public"."my_signature_center" WITH (security_invoker=true) AS
 SELECT 'client'::text AS agreement_scope,
    a.client_agreement_id AS agreement_id,
    a.agreement_key,
    a.name,
    a.document_type,
    a.template_version,
    a.status,
    a.required_client_signatures AS required_signatures,
    a.signature_count AS collected_signatures,
    a.required_client_signatures - a.signature_count AS signatures_remaining,
    a.sent_at,
    a.viewed_at,
    a.signed_at
   FROM my_agreements a
UNION ALL
 SELECT 'staff'::text AS agreement_scope,
    s.staff_agreement_id AS agreement_id,
    s.agreement_key,
    s.name,
    at.document_type,
    s.template_version,
    s.status,
    1 AS required_signatures,
        CASE
            WHEN s.acceptance_signed_at IS NOT NULL THEN 1
            ELSE 0
        END AS collected_signatures,
        CASE
            WHEN s.acceptance_signed_at IS NOT NULL THEN 0
            ELSE 1
        END AS signatures_remaining,
    s.sent_at,
    s.viewed_at,
    s.signed_at
   FROM my_staff_agreements s
     JOIN staff_agreements sa ON sa.id = s.staff_agreement_id
     JOIN agreement_templates at ON at.id = sa.agreement_template_id;

CREATE VIEW "public"."my_up_next" WITH (security_invoker=true) AS
 SELECT contact_id,
    household_id,
    source_id,
    item_type,
    title,
    status,
    starts_at,
    ends_at,
    item_date,
    all_day,
    location_url,
    metadata
   FROM my_calendar_feed_60d
  WHERE starts_at IS NOT NULL AND starts_at >= now() OR starts_at IS NULL AND item_date >= CURRENT_DATE
  ORDER BY item_date, starts_at, (
        CASE item_type
            WHEN 'appointment'::text THEN 1
            WHEN 'coaching_session'::text THEN 2
            WHEN 'workout'::text THEN 3
            WHEN 'meal'::text THEN 4
            WHEN 'goal_due'::text THEN 5
            WHEN 'challenge_end'::text THEN 6
            ELSE 7
        END)
 LIMIT 20;

CREATE VIEW "public"."admin_companion_control_center_v2" WITH (security_invoker=true) AS
 SELECT knowledge_readiness,
    operations,
    usage_30d,
    source_health,
    review_queue,
    ( SELECT to_jsonb(q.*) AS to_jsonb
           FROM admin_companion_quality_summary q
         LIMIT 1) AS quality,
    COALESCE(( SELECT jsonb_agg(to_jsonb(n.*) ORDER BY n.feedback_created_at DESC) AS jsonb_agg
           FROM ( SELECT admin_companion_quality_queue.feedback_id,
                    admin_companion_quality_queue.request_id,
                    admin_companion_quality_queue.contact_id,
                    admin_companion_quality_queue.first_name,
                    admin_companion_quality_queue.last_name,
                    admin_companion_quality_queue.question_type,
                    admin_companion_quality_queue.question,
                    admin_companion_quality_queue.final_answer,
                    admin_companion_quality_queue.answered_by_type,
                    admin_companion_quality_queue.retrieval_confidence,
                    admin_companion_quality_queue.answer_confidence,
                    admin_companion_quality_queue.helpful,
                    admin_companion_quality_queue.feedback_reason,
                    admin_companion_quality_queue.comment,
                    admin_companion_quality_queue.feedback_created_at,
                    admin_companion_quality_queue.review_id,
                    admin_companion_quality_queue.review_status,
                    admin_companion_quality_queue.assigned_to
                   FROM admin_companion_quality_queue
                  ORDER BY admin_companion_quality_queue.feedback_created_at DESC
                 LIMIT 30) n), '[]'::jsonb) AS negative_feedback_queue,
    COALESCE(( SELECT jsonb_agg(to_jsonb(i.*) ORDER BY i.created_at) AS jsonb_agg
           FROM ( SELECT admin_companion_ingestion_queue.job_id,
                    admin_companion_ingestion_queue.source_id,
                    admin_companion_ingestion_queue.source_key,
                    admin_companion_ingestion_queue.title,
                    admin_companion_ingestion_queue.version,
                    admin_companion_ingestion_queue.source_status,
                    admin_companion_ingestion_queue.source_ingestion_status,
                    admin_companion_ingestion_queue.job_type,
                    admin_companion_ingestion_queue.job_status,
                    admin_companion_ingestion_queue.requested_by,
                    admin_companion_ingestion_queue.requested_by_name,
                    admin_companion_ingestion_queue.started_at,
                    admin_companion_ingestion_queue.completed_at,
                    admin_companion_ingestion_queue.chunk_count,
                    admin_companion_ingestion_queue.embedded_chunk_count,
                    admin_companion_ingestion_queue.error_message,
                    admin_companion_ingestion_queue.created_at,
                    admin_companion_ingestion_queue.updated_at
                   FROM admin_companion_ingestion_queue
                  WHERE admin_companion_ingestion_queue.job_status = ANY (ARRAY['queued'::text, 'processing'::text, 'failed'::text])
                  ORDER BY admin_companion_ingestion_queue.created_at
                 LIMIT 30) i), '[]'::jsonb) AS ingestion_queue
   FROM admin_companion_control_center c;

CREATE VIEW "public"."my_coach_attention_summary" WITH (security_invoker=true) AS
 SELECT count(*)::integer AS client_count,
    count(*) FILTER (WHERE attention_priority = 'urgent'::text)::integer AS urgent_clients,
    count(*) FILTER (WHERE attention_priority = 'high'::text)::integer AS high_priority_clients,
    count(*) FILTER (WHERE attention_priority = 'normal'::text)::integer AS normal_priority_clients,
    count(*) FILTER (WHERE attention_priority = 'low'::text)::integer AS low_priority_clients,
    COALESCE(sum(attention_signal_count), 0::bigint)::integer AS total_attention_signals,
    COALESCE(sum(overdue_goals), 0::bigint)::integer AS overdue_goals,
    COALESCE(sum(overdue_assignments), 0::bigint)::integer AS overdue_assignments,
    COALESCE(sum(overdue_staff_tasks), 0::bigint)::integer AS overdue_staff_tasks
   FROM my_coach_attention_queue;

CREATE VIEW "public"."my_coaching_hub" WITH (security_invoker=true) AS
 SELECT ca.user_id,
    ca.contact_id,
    ca.membership_id,
    cm.program_code,
    pc.name AS program_name,
    cm.assigned_coach_id,
    sd.display_name AS assigned_coach_name,
    ( SELECT to_jsonb(a.*) AS to_jsonb
           FROM my_member_upcoming_appointment a
         LIMIT 1) AS next_appointment,
    ( SELECT to_jsonb(s.*) AS to_jsonb
           FROM my_assignment_summary s
         LIMIT 1) AS assignment_summary,
    COALESCE(( SELECT jsonb_agg(to_jsonb(a.*) ORDER BY (
                CASE a.status
                    WHEN 'assigned'::text THEN 1
                    WHEN 'in_progress'::text THEN 2
                    ELSE 3
                END), a.due_at, a.created_at DESC) AS jsonb_agg
           FROM ( SELECT my_client_assignments.id,
                    my_client_assignments.title,
                    my_client_assignments.instructions,
                    my_client_assignments.assignment_type,
                    my_client_assignments.due_at,
                    my_client_assignments.status,
                    my_client_assignments.completed_at,
                    my_client_assignments.member_note,
                    my_client_assignments.created_at,
                    my_client_assignments.assigned_by_name
                   FROM my_client_assignments
                  WHERE my_client_assignments.status = ANY (ARRAY['assigned'::text, 'in_progress'::text])
                  ORDER BY (
                        CASE my_client_assignments.status
                            WHEN 'assigned'::text THEN 1
                            WHEN 'in_progress'::text THEN 2
                            ELSE 3
                        END), my_client_assignments.due_at, my_client_assignments.created_at DESC
                 LIMIT 8) a), '[]'::jsonb) AS current_assignments,
    COALESCE(( SELECT jsonb_agg(to_jsonb(cs.*) ORDER BY cs.scheduled_start DESC NULLS LAST) AS jsonb_agg
           FROM ( SELECT my_coaching_sessions.session_id,
                    my_coaching_sessions.contact_id,
                    my_coaching_sessions.membership_id,
                    my_coaching_sessions.coach_user_id,
                    my_coaching_sessions.coach_name,
                    my_coaching_sessions.appointment_id,
                    my_coaching_sessions.session_number,
                    my_coaching_sessions.status,
                    my_coaching_sessions.scheduled_start,
                    my_coaching_sessions.scheduled_end,
                    my_coaching_sessions.format,
                    my_coaching_sessions.location_url,
                    my_coaching_sessions.client_agenda,
                    my_coaching_sessions.completed_at,
                    my_coaching_sessions.created_at
                   FROM my_coaching_sessions
                  ORDER BY my_coaching_sessions.scheduled_start DESC NULLS LAST
                 LIMIT 6) cs), '[]'::jsonb) AS recent_sessions,
    COALESCE(( SELECT jsonb_agg(to_jsonb(mt.*) ORDER BY mt.last_message_at DESC NULLS LAST) AS jsonb_agg
           FROM ( SELECT my_conversations.conversation_id,
                    my_conversations.conversation_type,
                    my_conversations.title,
                    my_conversations.status,
                    my_conversations.last_message_at,
                    my_conversations.last_read_at,
                    my_conversations.unread_count,
                    my_conversations.last_message_preview
                   FROM my_conversations
                  ORDER BY my_conversations.last_message_at DESC NULLS LAST
                 LIMIT 6) mt), '[]'::jsonb) AS conversations,
    ( SELECT COALESCE(sum(mc.unread_count), 0::numeric) AS "coalesce"
           FROM my_conversations mc) AS unread_messages,
    ( SELECT count(*) AS count
           FROM my_coaching_entitlements ce) AS coaching_entitlement_count
   FROM client_access ca
     JOIN client_memberships cm ON cm.id = ca.membership_id
     JOIN program_catalog pc ON pc.program_code = cm.program_code
     LEFT JOIN staff_directory sd ON sd.user_id = cm.assigned_coach_id
  WHERE ca.user_id = (( SELECT auth.uid() AS uid))
 LIMIT 1;

CREATE VIEW "public"."my_next_best_actions" WITH (security_invoker=true) AS
 WITH candidates AS (
         SELECT 10 AS priority_rank,
            'assignment_overdue'::text AS action_type,
            a.id AS source_id,
            a.title,
            COALESCE(a.instructions, 'Complete your overdue coaching assignment.'::text) AS description,
            a.due_at,
            '/app/coaching'::text AS link_url,
            jsonb_build_object('assignment_type', a.assignment_type, 'status', a.status, 'assigned_by_name', a.assigned_by_name) AS metadata
           FROM my_client_assignments a
          WHERE (a.status = ANY (ARRAY['assigned'::text, 'in_progress'::text])) AND a.due_at IS NOT NULL AND a.due_at < now()
        UNION ALL
         SELECT 20,
            'appointment_upcoming'::text,
            ap.appointment_id,
            'Upcoming '::text || replace(COALESCE(ap.appointment_type, 'appointment'::text), '_'::text, ' '::text),
                CASE
                    WHEN ap.assigned_coach_name IS NOT NULL THEN ('Your next session with '::text || ap.assigned_coach_name) || ' is coming up.'::text
                    ELSE 'Your next scheduled session is coming up.'::text
                END AS "case",
            ap.scheduled_start,
            '/app/coaching'::text,
            jsonb_build_object('scheduled_start', ap.scheduled_start, 'scheduled_end', ap.scheduled_end, 'format', ap.format, 'location_url', ap.location_url, 'coach_name', ap.assigned_coach_name) AS jsonb_build_object
           FROM my_member_upcoming_appointment ap
          WHERE ap.scheduled_start <= (now() + '24:00:00'::interval)
        UNION ALL
         SELECT 30,
            'workout_today'::text,
            w.workout_assignment_id,
            w.title,
            COALESCE(w.description, 'Complete today''s assigned workout.'::text) AS "coalesce",
            CURRENT_DATE::timestamp with time zone AS "current_date",
            '/app/workouts'::text,
            jsonb_build_object('workout_id', w.workout_id, 'category', w.category, 'difficulty', w.difficulty, 'duration_minutes', w.duration_minutes, 'status', w.status) AS jsonb_build_object
           FROM my_upcoming_workouts w
          WHERE w.scheduled_date = CURRENT_DATE AND w.status <> 'completed'::text
        UNION ALL
         SELECT 40,
            'meal_today'::text,
            m.meal_item_id,
            m.title,
            ('Review or complete your '::text || COALESCE(m.meal_slot, 'meal'::text)) || ' plan for today.'::text,
            CURRENT_DATE::timestamp with time zone AS "current_date",
            '/app/nutrition'::text,
            jsonb_build_object('meal_slot', m.meal_slot, 'recipe_id', m.recipe_id, 'status', m.status, 'adherence_percent', m.adherence_percent) AS jsonb_build_object
           FROM my_upcoming_meals m
          WHERE m.scheduled_date = CURRENT_DATE AND m.status <> 'completed'::text
        UNION ALL
         SELECT 50,
            'habit_today'::text,
            (h.value ->> 'habit_id'::text)::uuid AS uuid,
            h.value ->> 'title'::text,
            'Complete today''s habit target.'::text,
            CURRENT_DATE::timestamp with time zone AS "current_date",
            '/app/today'::text,
            jsonb_build_object('category', h.value ->> 'category'::text, 'target', h.value ->> 'target'::text, 'unit', h.value ->> 'unit'::text, 'today_value', h.value ->> 'today_value'::text) AS jsonb_build_object
           FROM my_daily_action_center dac,
            LATERAL jsonb_array_elements(dac.habits) h(value)
          WHERE COALESCE((h.value ->> 'completed_today'::text)::boolean, false) = false
        UNION ALL
         SELECT 60,
            'goal_follow_up'::text,
            gp.goal_id,
            gp.title,
                CASE
                    WHEN gp.progress_state = 'past_due'::text THEN 'This goal is past its target date. Review it with your coach or update the plan.'::text
                    WHEN gp.progress_state = 'awaiting_data'::text THEN 'Add progress data so this goal can be tracked.'::text
                    ELSE 'Keep moving toward this active goal.'::text
                END AS "case",
            gp.target_date::timestamp with time zone AS target_date,
            '/app/progress'::text,
            jsonb_build_object('completion_percent', gp.completion_percent, 'progress_state', gp.progress_state, 'target_value', gp.target_value, 'target_unit', gp.target_unit) AS jsonb_build_object
           FROM my_goal_progress gp
          WHERE gp.status = 'active'::text AND (gp.progress_state = ANY (ARRAY['past_due'::text, 'awaiting_data'::text]))
        UNION ALL
         SELECT 70,
            'continue_course'::text,
            c.enrollment_id,
            c.title,
            'Continue your active ReVitalized course.'::text,
            COALESCE(c.last_activity_at, c.started_at, c.created_at) AS "coalesce",
            '/app/courses'::text,
            jsonb_build_object('course_id', c.course_id, 'progress_percent', c.progress_percent, 'last_lesson_id', c.last_lesson_id) AS jsonb_build_object
           FROM ( SELECT mc.enrollment_id,
                    mc.course_id,
                    mc.title,
                    mc.description,
                    mc.estimated_minutes,
                    mc.thumbnail_url,
                    mc.status,
                    mc.progress_percent,
                    mc.last_lesson_id,
                    mc.last_activity_at,
                    mc.started_at,
                    mc.completed_at,
                    now() AS created_at
                   FROM my_courses mc
                  WHERE mc.status = 'active'::text
                  ORDER BY mc.last_activity_at DESC NULLS LAST, mc.title
                 LIMIT 1) c
        UNION ALL
         SELECT 80,
            'ask_revitalized_follow_up'::text,
            r.request_id,
            'Review your Ask ReVitalized answer'::text,
            'A recent Ask ReVitalized response is ready for you.'::text,
            COALESCE(r.answered_at, r.updated_at) AS "coalesce",
            '/app/ask-revitalized'::text,
            jsonb_build_object('question_type', r.question_type, 'status', r.status, 'answered_by_type', r.answered_by_type) AS jsonb_build_object
           FROM my_companion_requests r
          WHERE (r.status = ANY (ARRAY['answered'::text, 'resolved'::text])) AND r.answered_at >= (now() - '7 days'::interval) AND NOT (EXISTS ( SELECT 1
                   FROM my_companion_feedback f
                  WHERE f.request_id = r.request_id))
        )
 SELECT row_number() OVER (ORDER BY priority_rank, due_at, title)::integer AS action_order,
    priority_rank,
    action_type,
    source_id,
    title,
    description,
    due_at,
    link_url,
    metadata
   FROM candidates
  ORDER BY priority_rank, due_at, title
 LIMIT 12;

CREATE VIEW "public"."my_progress_insights" WITH (security_invoker=true) AS
 SELECT contact_id,
    metric_key,
    metric_label,
    category,
    unit,
    current_value,
    current_recorded_at,
    baseline_value,
    baseline_recorded_at,
    absolute_change,
    percent_change_30d,
        CASE
            WHEN absolute_change IS NULL THEN 'insufficient_data'::text
            WHEN absolute_change > 0::numeric THEN 'up'::text
            WHEN absolute_change < 0::numeric THEN 'down'::text
            ELSE 'stable'::text
        END AS direction,
        CASE
            WHEN absolute_change IS NULL THEN 'More data is needed to show a 30-day trend.'::text
            WHEN absolute_change > 0::numeric THEN (((metric_label || ' is up '::text) || TRIM(BOTH FROM to_char(abs(absolute_change), 'FM999999990.99'::text))) ||
            CASE
                WHEN unit IS NOT NULL THEN ' '::text || unit
                ELSE ''::text
            END) || ' across the available 30-day comparison.'::text
            WHEN absolute_change < 0::numeric THEN (((metric_label || ' is down '::text) || TRIM(BOTH FROM to_char(abs(absolute_change), 'FM999999990.99'::text))) ||
            CASE
                WHEN unit IS NOT NULL THEN ' '::text || unit
                ELSE ''::text
            END) || ' across the available 30-day comparison.'::text
            ELSE metric_label || ' is unchanged across the available 30-day comparison.'::text
        END AS insight_text
   FROM my_health_dashboard_cards_30d hd;

CREATE VIEW "public"."my_app_bootstrap" WITH (security_invoker=true) AS
 SELECT ( SELECT to_jsonb(h.*) AS to_jsonb
           FROM my_app_home h
         LIMIT 1) AS home,
    ( SELECT to_jsonb(a.*) AS to_jsonb
           FROM my_app_access a
         LIMIT 1) AS access,
    ( SELECT to_jsonb(c.*) AS to_jsonb
           FROM my_coach c
         LIMIT 1) AS coach,
    ( SELECT to_jsonb(ap.*) AS to_jsonb
           FROM my_member_upcoming_appointment ap
         LIMIT 1) AS upcoming_appointment,
    ( SELECT to_jsonb(b.*) AS to_jsonb
           FROM my_billing_summary b
         LIMIT 1) AS billing,
    COALESCE(( SELECT jsonb_agg(to_jsonb(ag.*) ORDER BY ag.sent_at DESC NULLS LAST) AS jsonb_agg
           FROM my_agreements ag), '[]'::jsonb) AS agreements,
    ( SELECT to_jsonb(f.*) AS to_jsonb
           FROM my_family_hub_summary f
         LIMIT 1) AS family_hub,
    ( SELECT to_jsonb(a.*) AS to_jsonb
           FROM my_ambassador_center a
         LIMIT 1) AS ambassador,
    COALESCE(( SELECT jsonb_agg(to_jsonb(n.*) ORDER BY n.created_at DESC) AS jsonb_agg
           FROM ( SELECT my_notifications.id,
                    my_notifications.notification_type,
                    my_notifications.title,
                    my_notifications.body,
                    my_notifications.link_url,
                    my_notifications.status,
                    my_notifications.created_at,
                    my_notifications.read_at
                   FROM my_notifications
                  ORDER BY my_notifications.created_at DESC
                 LIMIT 10) n), '[]'::jsonb) AS recent_notifications,
    COALESCE(( SELECT jsonb_agg(to_jsonb(c.*) ORDER BY c.last_activity_at DESC NULLS LAST) AS jsonb_agg
           FROM ( SELECT my_courses.enrollment_id,
                    my_courses.course_id,
                    my_courses.title,
                    my_courses.description,
                    my_courses.estimated_minutes,
                    my_courses.thumbnail_url,
                    my_courses.status,
                    my_courses.progress_percent,
                    my_courses.last_lesson_id,
                    my_courses.last_activity_at,
                    my_courses.started_at,
                    my_courses.completed_at
                   FROM my_courses
                  ORDER BY my_courses.last_activity_at DESC NULLS LAST, my_courses.title
                 LIMIT 5) c), '[]'::jsonb) AS courses,
    COALESCE(( SELECT jsonb_agg(to_jsonb(r.*) ORDER BY r.category, r.title) AS jsonb_agg
           FROM ( SELECT my_resources.resource_id,
                    my_resources.title,
                    my_resources.description,
                    my_resources.resource_type,
                    my_resources.resource_url,
                    my_resources.category,
                    my_resources.tags,
                    my_resources.assignment_status,
                    my_resources.assignment_note
                   FROM my_resources
                  ORDER BY my_resources.category, my_resources.title
                 LIMIT 8) r), '[]'::jsonb) AS resources,
    ( SELECT to_jsonb(np.*) AS to_jsonb
           FROM my_notification_preferences np
         LIMIT 1) AS notification_preferences,
    COALESCE(( SELECT jsonb_agg(to_jsonb(cs.*) ORDER BY cs.scheduled_start DESC NULLS LAST) AS jsonb_agg
           FROM ( SELECT my_coaching_sessions.session_id,
                    my_coaching_sessions.contact_id,
                    my_coaching_sessions.membership_id,
                    my_coaching_sessions.coach_user_id,
                    my_coaching_sessions.coach_name,
                    my_coaching_sessions.appointment_id,
                    my_coaching_sessions.session_number,
                    my_coaching_sessions.status,
                    my_coaching_sessions.scheduled_start,
                    my_coaching_sessions.scheduled_end,
                    my_coaching_sessions.format,
                    my_coaching_sessions.location_url,
                    my_coaching_sessions.client_agenda,
                    my_coaching_sessions.completed_at,
                    my_coaching_sessions.created_at
                   FROM my_coaching_sessions
                  ORDER BY my_coaching_sessions.scheduled_start DESC NULLS LAST
                 LIMIT 8) cs), '[]'::jsonb) AS coaching_sessions,
    COALESCE(( SELECT jsonb_agg(to_jsonb(i.*) ORDER BY i.created_at DESC) AS jsonb_agg
           FROM ( SELECT my_invoices.invoice_id,
                    my_invoices.invoice_number,
                    my_invoices.status,
                    my_invoices.amount_due_cents,
                    my_invoices.amount_paid_cents,
                    my_invoices.currency,
                    my_invoices.due_at,
                    my_invoices.paid_at,
                    my_invoices.hosted_invoice_url,
                    my_invoices.created_at
                   FROM my_invoices
                  ORDER BY my_invoices.created_at DESC
                 LIMIT 8) i), '[]'::jsonb) AS invoices,
    COALESCE(( SELECT jsonb_agg(to_jsonb(ph.*) ORDER BY ph.occurred_at DESC) AS jsonb_agg
           FROM ( SELECT my_payment_history.event_id,
                    my_payment_history.event_type,
                    my_payment_history.provider,
                    my_payment_history.amount_cents,
                    my_payment_history.currency,
                    my_payment_history.status,
                    my_payment_history.occurred_at
                   FROM my_payment_history
                  ORDER BY my_payment_history.occurred_at DESC
                 LIMIT 10) ph), '[]'::jsonb) AS payment_history,
    ( SELECT to_jsonb(dac.*) AS to_jsonb
           FROM my_daily_action_center dac
         LIMIT 1) AS daily_actions,
    ( SELECT to_jsonb(ps.*) AS to_jsonb
           FROM my_progress_snapshot ps
         LIMIT 1) AS progress_snapshot,
    COALESCE(( SELECT jsonb_agg(to_jsonb(cps.*) ORDER BY cps.course_title) AS jsonb_agg
           FROM my_course_progress_summary cps), '[]'::jsonb) AS course_progress,
    ( SELECT to_jsonb(ws.*) AS to_jsonb
           FROM my_weekly_summary ws
         LIMIT 1) AS weekly_summary,
    COALESCE(( SELECT jsonb_agg(to_jsonb(at.*) ORDER BY at.occurred_at DESC) AS jsonb_agg
           FROM ( SELECT my_activity_timeline.occurred_at,
                    my_activity_timeline.activity_type,
                    my_activity_timeline.title,
                    my_activity_timeline.detail,
                    my_activity_timeline.activity_key,
                    my_activity_timeline.source_type,
                    my_activity_timeline.source_id
                   FROM my_activity_timeline
                  ORDER BY my_activity_timeline.occurred_at DESC
                 LIMIT 25) at), '[]'::jsonb) AS activity_timeline,
    ( SELECT to_jsonb(ch.*) AS to_jsonb
           FROM my_coaching_hub ch
         LIMIT 1) AS coaching_hub,
    ( SELECT to_jsonb(asum.*) AS to_jsonb
           FROM my_assignment_summary asum
         LIMIT 1) AS assignment_summary,
    COALESCE(( SELECT jsonb_agg(to_jsonb(mt.*) ORDER BY mt.last_message_at DESC NULLS LAST) AS jsonb_agg
           FROM ( SELECT my_message_threads.conversation_id,
                    my_message_threads.conversation_type,
                    my_message_threads.title,
                    my_message_threads.status,
                    my_message_threads.last_message_at,
                    my_message_threads.last_read_at,
                    my_message_threads.unread_count,
                    my_message_threads.last_message_preview,
                    my_message_threads.messages
                   FROM my_message_threads
                  ORDER BY my_message_threads.last_message_at DESC NULLS LAST
                 LIMIT 6) mt), '[]'::jsonb) AS message_threads,
    COALESCE(( SELECT jsonb_agg(to_jsonb(cr.*) ORDER BY cr.created_at DESC) AS jsonb_agg
           FROM ( SELECT my_coaching_requests.appointment_id,
                    my_coaching_requests.status,
                    my_coaching_requests.requested_availability,
                    my_coaching_requests.client_notes,
                    my_coaching_requests.scheduled_start,
                    my_coaching_requests.scheduled_end,
                    my_coaching_requests.time_zone,
                    my_coaching_requests.format,
                    my_coaching_requests.location_url,
                    my_coaching_requests.assigned_to,
                    my_coaching_requests.assigned_coach_name,
                    my_coaching_requests.created_at,
                    my_coaching_requests.updated_at
                   FROM my_coaching_requests
                  ORDER BY my_coaching_requests.created_at DESC
                 LIMIT 6) cr), '[]'::jsonb) AS coaching_requests,
    COALESCE(( SELECT jsonb_agg(to_jsonb(ra.*) ORDER BY ra.first_touch_at DESC) AS jsonb_agg
           FROM ( SELECT my_referral_activity.referral_id,
                    my_referral_activity.status,
                    my_referral_activity.source_channel,
                    my_referral_activity.first_touch_at,
                    my_referral_activity.converted_at,
                    my_referral_activity.referred_first_name,
                    my_referral_activity.referred_last_initial,
                    my_referral_activity.reward_status,
                    my_referral_activity.reward_type,
                    my_referral_activity.reward_value,
                    my_referral_activity.currency,
                    my_referral_activity.approved_at,
                    my_referral_activity.issued_at
                   FROM my_referral_activity
                  ORDER BY my_referral_activity.first_touch_at DESC
                 LIMIT 20) ra), '[]'::jsonb) AS referral_activity,
    COALESCE(( SELECT jsonb_agg(to_jsonb(fr.*) ORDER BY fr.created_at DESC) AS jsonb_agg
           FROM ( SELECT my_family_requests.request_id,
                    my_family_requests.request_type,
                    my_family_requests.target_household_member_id,
                    my_family_requests.first_name,
                    my_family_requests.last_name,
                    my_family_requests.relationship_type,
                    my_family_requests.sex,
                    my_family_requests.date_of_birth,
                    my_family_requests.email,
                    my_family_requests.notes,
                    my_family_requests.status,
                    my_family_requests.staff_notes,
                    my_family_requests.reviewed_at,
                    my_family_requests.created_at,
                    my_family_requests.updated_at
                   FROM my_family_requests
                  ORDER BY my_family_requests.created_at DESC
                 LIMIT 10) fr), '[]'::jsonb) AS family_requests;

CREATE VIEW "public"."my_home_priority_summary" WITH (security_invoker=true) AS
 SELECT count(*)::integer AS action_count,
    count(*) FILTER (WHERE priority_rank <= 20)::integer AS high_priority_count,
    count(*) FILTER (WHERE action_type = 'assignment_overdue'::text)::integer AS overdue_assignments,
    count(*) FILTER (WHERE action_type = 'appointment_upcoming'::text)::integer AS appointments_next_24h,
    count(*) FILTER (WHERE action_type = 'workout_today'::text)::integer AS workouts_remaining_today,
    count(*) FILTER (WHERE action_type = 'meal_today'::text)::integer AS meals_remaining_today,
    count(*) FILTER (WHERE action_type = 'habit_today'::text)::integer AS habits_remaining_today,
    count(*) FILTER (WHERE action_type = 'goal_follow_up'::text)::integer AS goals_needing_follow_up,
    count(*) FILTER (WHERE action_type = 'continue_course'::text)::integer AS courses_to_continue
   FROM my_next_best_actions;

CREATE VIEW "public"."my_weekly_progress_story" WITH (security_invoker=true) AS
 WITH me AS (
         SELECT ca.user_id,
            ca.contact_id,
            ca.membership_id
           FROM client_access ca
          WHERE ca.user_id = (( SELECT auth.uid() AS uid)) AND ca.status = 'active'::text
          ORDER BY ca.updated_at DESC
         LIMIT 1
        ), this_week AS (
         SELECT count(*) FILTER (WHERE h_1.action_date >= (CURRENT_DATE - 6) AND h_1.action_date <= CURRENT_DATE AND h_1.total_actions > 0)::integer AS planned_days,
            count(*) FILTER (WHERE h_1.action_date >= (CURRENT_DATE - 6) AND h_1.action_date <= CURRENT_DATE AND h_1.fully_completed)::integer AS fully_completed_days,
            round(avg(h_1.completion_percent) FILTER (WHERE h_1.action_date >= (CURRENT_DATE - 6) AND h_1.action_date <= CURRENT_DATE AND h_1.completion_percent IS NOT NULL), 1) AS avg_completion
           FROM my_daily_plan_history_30d h_1
        ), prior_week AS (
         SELECT count(*) FILTER (WHERE h_1.action_date >= (CURRENT_DATE - 13) AND h_1.action_date <= (CURRENT_DATE - 7) AND h_1.total_actions > 0)::integer AS planned_days,
            count(*) FILTER (WHERE h_1.action_date >= (CURRENT_DATE - 13) AND h_1.action_date <= (CURRENT_DATE - 7) AND h_1.fully_completed)::integer AS fully_completed_days,
            round(avg(h_1.completion_percent) FILTER (WHERE h_1.action_date >= (CURRENT_DATE - 13) AND h_1.action_date <= (CURRENT_DATE - 7) AND h_1.completion_percent IS NOT NULL), 1) AS avg_completion
           FROM my_daily_plan_history_30d h_1
        ), weekly AS (
         SELECT my_weekly_summary.user_id,
            my_weekly_summary.contact_id,
            my_weekly_summary.period_start,
            my_weekly_summary.period_end,
            my_weekly_summary.habit_checkins,
            my_weekly_summary.active_habit_days,
            my_weekly_summary.workouts_completed,
            my_weekly_summary.meals_completed,
            my_weekly_summary.meal_adherence,
            my_weekly_summary.progress_entries,
            my_weekly_summary.goals_completed,
            my_weekly_summary.challenges_completed,
            my_weekly_summary.challenge_points_earned,
            my_weekly_summary.courses_completed
           FROM my_weekly_summary
        ), achievements AS (
         SELECT count(*)::integer AS unlocked_count,
            COALESCE(jsonb_agg(jsonb_build_object('achievement_key', a_1.achievement_key, 'title', a_1.title, 'description', a_1.description, 'icon_key', a_1.icon_key, 'unlocked_at', a_1.unlocked_at) ORDER BY a_1.unlocked_at DESC) FILTER (WHERE a_1.unlocked_at >= (now() - '7 days'::interval)), '[]'::jsonb) AS items
           FROM my_achievements a_1
        ), goals AS (
         SELECT count(*) FILTER (WHERE gp.status = 'active'::text)::integer AS active_goals,
            count(*) FILTER (WHERE gp.progress_state = 'past_due'::text)::integer AS past_due_goals,
            count(*) FILTER (WHERE gp.completion_percent >= 75::numeric AND gp.status = 'active'::text)::integer AS goals_near_completion,
            COALESCE(jsonb_agg(jsonb_build_object('goal_id', gp.goal_id, 'title', gp.title, 'completion_percent', gp.completion_percent, 'progress_state', gp.progress_state, 'target_date', gp.target_date) ORDER BY gp.priority, gp.title) FILTER (WHERE gp.status = ANY (ARRAY['active'::text, 'paused'::text])), '[]'::jsonb) AS items
           FROM my_goal_progress gp
        ), upcoming AS (
         SELECT COALESCE(jsonb_agg(jsonb_build_object('source_id', u_1.source_id, 'item_type', u_1.item_type, 'title', u_1.title, 'starts_at', u_1.starts_at, 'ends_at', u_1.ends_at, 'item_date', u_1.item_date, 'all_day', u_1.all_day, 'location_url', u_1.location_url, 'metadata', u_1.metadata) ORDER BY u_1.item_date, u_1.starts_at), '[]'::jsonb) AS items
           FROM ( SELECT my_up_next.contact_id,
                    my_up_next.household_id,
                    my_up_next.source_id,
                    my_up_next.item_type,
                    my_up_next.title,
                    my_up_next.status,
                    my_up_next.starts_at,
                    my_up_next.ends_at,
                    my_up_next.item_date,
                    my_up_next.all_day,
                    my_up_next.location_url,
                    my_up_next.metadata
                   FROM my_up_next
                  WHERE my_up_next.item_date >= CURRENT_DATE AND my_up_next.item_date <= (CURRENT_DATE + 7)
                  ORDER BY my_up_next.item_date, my_up_next.starts_at
                 LIMIT 12) u_1
        ), health AS (
         SELECT COALESCE(jsonb_agg(jsonb_build_object('metric_key', i.metric_key, 'metric_label', i.metric_label, 'unit', i.unit, 'current_value', i.current_value, 'absolute_change', i.absolute_change, 'percent_change_30d', i.percent_change_30d, 'direction', i.direction, 'insight_text', i.insight_text) ORDER BY i.category, i.metric_label), '[]'::jsonb) AS items
           FROM my_progress_insights i
          WHERE i.current_recorded_at >= (now() - '14 days'::interval)
        ), momentum AS (
         SELECT my_coaching_momentum.contact_id,
            my_coaching_momentum.membership_id,
            my_coaching_momentum.plan_completion_7d,
            my_coaching_momentum.planned_days_7d,
            my_coaching_momentum.full_days_7d,
            my_coaching_momentum.last_checkin_at,
            my_coaching_momentum.last_progress_at,
            my_coaching_momentum.active_goals,
            my_coaching_momentum.overdue_goals,
            my_coaching_momentum.momentum_state
           FROM my_coaching_momentum
         LIMIT 1
        )
 SELECT me.user_id,
    me.contact_id,
    me.membership_id,
    CURRENT_DATE - 6 AS period_start,
    CURRENT_DATE AS period_end,
    tw.planned_days,
    tw.fully_completed_days,
    tw.avg_completion AS plan_completion_7d,
    pw.avg_completion AS prior_plan_completion_7d,
        CASE
            WHEN tw.avg_completion IS NULL OR pw.avg_completion IS NULL THEN NULL::numeric
            ELSE round(tw.avg_completion - pw.avg_completion, 1)
        END AS completion_change_vs_prior_week,
    w.habit_checkins,
    w.active_habit_days,
    w.workouts_completed,
    w.meals_completed,
    w.meal_adherence,
    w.progress_entries,
    w.goals_completed,
    w.challenges_completed,
    w.challenge_points_earned,
    w.courses_completed,
    a.unlocked_count AS achievements_unlocked,
    a.items AS achievements,
    g.active_goals,
    g.past_due_goals,
    g.goals_near_completion,
    g.items AS goals,
    h.items AS progress_insights,
    u.items AS upcoming_7d,
    m.momentum_state,
    m.last_checkin_at,
    m.last_progress_at,
        CASE
            WHEN tw.avg_completion IS NULL THEN 'Your week is ready to begin.'::text
            WHEN tw.avg_completion >= 90::numeric THEN 'You completed nearly all of your planned actions this week.'::text
            WHEN tw.avg_completion >= 75::numeric THEN 'You completed most of your planned actions this week.'::text
            WHEN tw.avg_completion >= 50::numeric THEN 'You made steady progress on your plan this week.'::text
            ELSE 'There are several opportunities to reconnect with your plan this week.'::text
        END AS summary_headline,
        CASE
            WHEN pw.avg_completion IS NULL OR tw.avg_completion IS NULL THEN NULL::text
            WHEN (tw.avg_completion - pw.avg_completion) >= 10::numeric THEN 'Your plan completion increased compared with the prior week.'::text
            WHEN (tw.avg_completion - pw.avg_completion) <= '-10'::integer::numeric THEN 'Your plan completion decreased compared with the prior week.'::text
            ELSE 'Your plan completion was similar to the prior week.'::text
        END AS comparison_text
   FROM me
     CROSS JOIN this_week tw
     CROSS JOIN prior_week pw
     CROSS JOIN weekly w
     CROSS JOIN achievements a
     CROSS JOIN goals g
     CROSS JOIN upcoming u
     CROSS JOIN health h
     LEFT JOIN momentum m ON m.contact_id = me.contact_id;

