CREATE POLICY "client_document_object_delete" ON "storage"."objects" AS PERMISSIVE FOR DELETE TO "authenticated" USING (((bucket_id = 'client-documents'::text) AND (EXISTS ( SELECT 1
   FROM client_documents d
  WHERE ((d.storage_path = objects.name) AND private.staff_can_manage_document_category(d.category))))));

CREATE POLICY "client_document_object_insert" ON "storage"."objects" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (((bucket_id = 'client-documents'::text) AND (EXISTS ( SELECT 1
   FROM client_documents d
  WHERE ((d.storage_path = objects.name) AND (d.status = 'active'::text) AND (((d.contact_id IN ( SELECT ca.contact_id
           FROM client_access ca
          WHERE (ca.user_id = ( SELECT auth.uid() AS uid)))) AND (d.category = ANY (ARRAY['general'::text, 'progress'::text])) AND d.member_visible AND (d.uploaded_by_user_id = ( SELECT auth.uid() AS uid))) OR private.staff_can_manage_document_category(d.category)))))));

